TRANSLATIONS: dict[str, dict[str, str]] = {'content/hub/scripting/fundamentals/Data Structures/_index.md': {'de': '---\n'
                                                                        'title: "Datenstrukturen"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'In Scheme sind '
                                                                        '**Datenstrukturen** '
                                                                        'wesentliche Werkzeuge zum '
                                                                        'Organisieren, Speichern '
                                                                        'und Bearbeiten von Daten. '
                                                                        'Sie ermöglichen '
                                                                        'Entwicklern die '
                                                                        'Erstellung effizienter, '
                                                                        'lesbarer und '
                                                                        'wiederverwendbarer '
                                                                        'Skripte. Durch die '
                                                                        'Auswahl der richtigen '
                                                                        'Datenstruktur für ein '
                                                                        'bestimmtes Problem können '
                                                                        'Sie sowohl die Leistung '
                                                                        'als auch die Klarheit '
                                                                        'Ihres Codes optimieren.\n'
                                                                        '\n'
                                                                        '## Wichtige '
                                                                        'Datenstrukturen in '
                                                                        'Scheme\n'
                                                                        '\n'
                                                                        'Scheme bietet mehrere '
                                                                        'leistungsstarke und '
                                                                        'vielseitige '
                                                                        'Datenstrukturen, die '
                                                                        'jeweils für bestimmte '
                                                                        'Aufgaben geeignet sind. '
                                                                        'Zu den primären '
                                                                        'Datenstrukturen gehören:\n'
                                                                        '\n'
                                                                        '### Listen\n'
                                                                        '\n'
                                                                        'Listen sind geordnete '
                                                                        'Sammlungen von Elementen, '
                                                                        'die dynamisch wachsen '
                                                                        'oder schrumpfen können. '
                                                                        'Sie eignen sich ideal für '
                                                                        'sequentielle oder '
                                                                        'hierarchische Daten und '
                                                                        'werden häufig in der '
                                                                        'funktionalen '
                                                                        'Programmierung '
                                                                        'verwendet.\n'
                                                                        '\n'
                                                                        'Hauptmerkmale:\n'
                                                                        '- Dynamische Größe.\n'
                                                                        '- Elemente können '
                                                                        'gemischter Art sein.\n'
                                                                        '– Wird häufig für '
                                                                        'rekursive Algorithmen und '
                                                                        'zur Darstellung '
                                                                        'baumartiger Strukturen '
                                                                        'verwendet.\n'
                                                                        '\n'
                                                                        'Anwendungsbeispiele:\n'
                                                                        '- Verwalten von '
                                                                        'Element-Sammlungen.\n'
                                                                        '- Darstellung von '
                                                                        'Abfolgen oder '
                                                                        'Hierarchien.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Vektoren\n'
                                                                        '\n'
                                                                        'Vektoren sind Sammlungen '
                                                                        'von Elementen fester '
                                                                        'Größe, die für einen '
                                                                        'schnellen Zugriff '
                                                                        'indiziert sind. Sie '
                                                                        'eignen sich am besten für '
                                                                        'Szenarien, in denen '
                                                                        'Leistung und '
                                                                        'Positionszugriff von '
                                                                        'entscheidender Bedeutung '
                                                                        'sind.\n'
                                                                        '\n'
                                                                        'Hauptmerkmale:\n'
                                                                        '- Feste Größe bei der '
                                                                        'Erstellung.\n'
                                                                        '- Auf Elemente wird über '
                                                                        'ihren Index zugegriffen.\n'
                                                                        '- Schneller als Listen '
                                                                        'für bestimmte Vorgänge '
                                                                        'wie Direktzugriff.\n'
                                                                        '\n'
                                                                        'Anwendungsbeispiele:\n'
                                                                        '- Speichern von '
                                                                        'Konfigurationen oder '
                                                                        'Daten fester Größe.\n'
                                                                        '- Schnelle Suche und '
                                                                        'Aktualisierung basierend '
                                                                        'auf der Position.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Auswahl der richtigen '
                                                                        'Datenstruktur\n'
                                                                        '\n'
                                                                        'Die Entscheidung, eine '
                                                                        '**Liste** oder einen '
                                                                        '**Vektor** zu verwenden, '
                                                                        'hängt von den '
                                                                        'spezifischen '
                                                                        'Anforderungen Ihres '
                                                                        'Skripts ab. Hier sind '
                                                                        'einige Richtlinien:\n'
                                                                        '\n'
                                                                        '| Funktion | Listen | '
                                                                        'Vektoren |\n'
                                                                        '|-----------|---------------|--------------------------------|\n'
                                                                        '| **Größenflexibilität** '
                                                                        '| Dynamisch | Behoben |\n'
                                                                        '| '
                                                                        '**Zugriffsgeschwindigkeit** '
                                                                        '| Langsamer '
                                                                        '(sequentieller Zugriff) | '
                                                                        'Schneller (indizierter '
                                                                        'Zugriff) |\n'
                                                                        '| **Einfache '
                                                                        'Modifikation**| Einfacher '
                                                                        '| Härter (erfordert '
                                                                        'Neuzuweisung)|\n'
                                                                        '| **Anwendungsfälle** | '
                                                                        'Dynamische Daten, '
                                                                        'Rekursion | Statische '
                                                                        'Daten, schnelle Suche |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'es': '---\n'
                                                                        'title: "Estructuras de '
                                                                        'datos"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'En Scheme, las '
                                                                        '**estructuras de datos** '
                                                                        'son herramientas '
                                                                        'esenciales para '
                                                                        'organizar, almacenar y '
                                                                        'manipular datos. Permiten '
                                                                        'a los desarrolladores '
                                                                        'crear scripts eficientes, '
                                                                        'legibles y reutilizables. '
                                                                        'Al elegir la estructura '
                                                                        'de datos adecuada para un '
                                                                        'problema específico, '
                                                                        'puede optimizar tanto el '
                                                                        'rendimiento como la '
                                                                        'claridad de su código.\n'
                                                                        '\n'
                                                                        '## Estructuras de datos '
                                                                        'clave en el esquema\n'
                                                                        '\n'
                                                                        'Scheme proporciona varias '
                                                                        'estructuras de datos '
                                                                        'potentes y versátiles, '
                                                                        'cada una adecuada para '
                                                                        'tareas específicas. Las '
                                                                        'estructuras de datos '
                                                                        'primarias incluyen:\n'
                                                                        '\n'
                                                                        '### Listas\n'
                                                                        '\n'
                                                                        'Las listas son '
                                                                        'colecciones ordenadas de '
                                                                        'elementos que pueden '
                                                                        'crecer o reducirse '
                                                                        'dinámicamente. Son '
                                                                        'ideales para datos '
                                                                        'secuenciales o '
                                                                        'jerárquicos y se utilizan '
                                                                        'ampliamente en '
                                                                        'programación funcional.\n'
                                                                        '\n'
                                                                        'Características clave:\n'
                                                                        '- Dimensionado '
                                                                        'dinámicamente.\n'
                                                                        '- Los elementos pueden '
                                                                        'ser de tipos mixtos.\n'
                                                                        '- Comúnmente utilizado '
                                                                        'para algoritmos '
                                                                        'recursivos y para '
                                                                        'representar estructuras '
                                                                        'en forma de árbol.\n'
                                                                        '\n'
                                                                        'Ejemplos de uso:\n'
                                                                        '- Gestión de colecciones '
                                                                        'de artículos.\n'
                                                                        '- Representar secuencias '
                                                                        'o jerarquías.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Vectores\n'
                                                                        '\n'
                                                                        'Los vectores son '
                                                                        'colecciones de elementos '
                                                                        'de tamaño fijo, indexados '
                                                                        'para un acceso rápido. '
                                                                        'Son más adecuados para '
                                                                        'escenarios donde el '
                                                                        'rendimiento y el acceso '
                                                                        'posicional son críticos.\n'
                                                                        '\n'
                                                                        'Características clave:\n'
                                                                        '- Tamaño fijo en la '
                                                                        'creación.\n'
                                                                        '- Se accede a los '
                                                                        'elementos por su índice.\n'
                                                                        '- Más rápido que las '
                                                                        'listas para determinadas '
                                                                        'operaciones como el '
                                                                        'acceso aleatorio.\n'
                                                                        '\n'
                                                                        'Ejemplos de uso:\n'
                                                                        '- Almacenamiento de '
                                                                        'configuraciones o datos '
                                                                        'de tamaño fijo.\n'
                                                                        '- Búsquedas rápidas y '
                                                                        'actualizaciones según la '
                                                                        'posición.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Elegir la estructura '
                                                                        'de datos adecuada\n'
                                                                        '\n'
                                                                        'La decisión de utilizar '
                                                                        'una **lista** o un '
                                                                        '**vector** depende de las '
                                                                        'necesidades específicas '
                                                                        'de su script. Aquí hay '
                                                                        'algunas pautas:\n'
                                                                        '\n'
                                                                        '| Característica | Listas '
                                                                        '| Vectores |\n'
                                                                        '|---------------------------------|------------------------------|--------------------------------|\n'
                                                                        '| **Flexibilidad de '
                                                                        'tamaño** | Dinámico | '
                                                                        'Fijo |\n'
                                                                        '| **Velocidad de acceso** '
                                                                        '| Más lento (acceso '
                                                                        'secuencial) | Más rápido '
                                                                        '(acceso indexado) |\n'
                                                                        '| **Facilidad de '
                                                                        'modificación**| Más fácil '
                                                                        '| Más difícil (requiere '
                                                                        'reasignación)|\n'
                                                                        '| **Casos de uso** | '
                                                                        'Datos dinámicos, '
                                                                        'recursividad | Datos '
                                                                        'estáticos, búsquedas '
                                                                        'rápidas |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'fr': '---\n'
                                                                        'title: "Structures de '
                                                                        'données"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'Dans Scheme, les '
                                                                        '**structures de données** '
                                                                        'sont des outils '
                                                                        'essentiels pour '
                                                                        'organiser, stocker et '
                                                                        'manipuler les données. '
                                                                        'Ils permettent aux '
                                                                        'développeurs de créer des '
                                                                        'scripts efficaces, '
                                                                        'lisibles et '
                                                                        'réutilisables. En '
                                                                        'choisissant la bonne '
                                                                        'structure de données pour '
                                                                        'un problème spécifique, '
                                                                        'vous pouvez optimiser à '
                                                                        'la fois les performances '
                                                                        'et la clarté de votre '
                                                                        'code.\n'
                                                                        '\n'
                                                                        '## Structures de données '
                                                                        'clés en Scheme\n'
                                                                        '\n'
                                                                        'Scheme fournit plusieurs '
                                                                        'structures de données '
                                                                        'puissantes et '
                                                                        'polyvalentes, chacune '
                                                                        'adaptée à des tâches '
                                                                        'spécifiques. Les '
                                                                        'structures de données '
                                                                        'principales '
                                                                        'comprennent\xa0:\n'
                                                                        '\n'
                                                                        '### Listes\n'
                                                                        '\n'
                                                                        'Les listes sont des '
                                                                        'collections ordonnées '
                                                                        "d'éléments qui peuvent "
                                                                        "s'agrandir ou se réduire "
                                                                        'de manière dynamique. Ils '
                                                                        'sont idéaux pour les '
                                                                        'données séquentielles ou '
                                                                        'hiérarchiques et sont '
                                                                        'largement utilisés en '
                                                                        'programmation '
                                                                        'fonctionnelle.\n'
                                                                        '\n'
                                                                        'Principales '
                                                                        'caractéristiques\xa0:\n'
                                                                        '- Dimensionné '
                                                                        'dynamiquement.\n'
                                                                        '- Les éléments peuvent '
                                                                        'être de types mixtes.\n'
                                                                        '- Couramment utilisé pour '
                                                                        'les algorithmes récursifs '
                                                                        'et pour représenter des '
                                                                        'structures '
                                                                        'arborescentes.\n'
                                                                        '\n'
                                                                        "Exemples d'utilisation :\n"
                                                                        '- Gestion de collections '
                                                                        "d'éléments.\n"
                                                                        '- Représenter des '
                                                                        'séquences ou des '
                                                                        'hiérarchies.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Vecteurs\n'
                                                                        '\n'
                                                                        'Les vecteurs sont des '
                                                                        "collections d'éléments de "
                                                                        'taille fixe, indexées '
                                                                        'pour un accès rapide. Ils '
                                                                        'conviennent mieux aux '
                                                                        'scénarios dans lesquels '
                                                                        'les performances et '
                                                                        'l’accès positionnel sont '
                                                                        'essentiels.\n'
                                                                        '\n'
                                                                        'Principales '
                                                                        'caractéristiques\xa0:\n'
                                                                        '- Taille fixe à la '
                                                                        'création.\n'
                                                                        '- Les éléments sont '
                                                                        'accessibles par leur '
                                                                        'index.\n'
                                                                        '- Plus rapide que les '
                                                                        'listes pour certaines '
                                                                        "opérations comme l'accès "
                                                                        'aléatoire.\n'
                                                                        '\n'
                                                                        "Exemples d'utilisation :\n"
                                                                        '- Stockage de '
                                                                        'configurations ou de '
                                                                        'données de taille fixe.\n'
                                                                        '- Recherches et mises à '
                                                                        'jour rapides en fonction '
                                                                        'de la position.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Choisir la bonne '
                                                                        'structure de données\n'
                                                                        '\n'
                                                                        "La décision d'utiliser "
                                                                        'une **list** ou un '
                                                                        '**vecteur** dépend des '
                                                                        'besoins spécifiques de '
                                                                        'votre script. Voici '
                                                                        'quelques lignes '
                                                                        'directrices\xa0:\n'
                                                                        '\n'
                                                                        '| Fonctionnalité | Listes '
                                                                        '| Vecteurs |\n'
                                                                        '|------------------------------|------------------------------|--------------------------------|\n'
                                                                        '| **Flexibilité de '
                                                                        'taille** | Dynamique | '
                                                                        'Fixe |\n'
                                                                        "| **Vitesse d'accès** | "
                                                                        'Plus lent (accès '
                                                                        'séquentiel) | Plus rapide '
                                                                        '(accès indexé) |\n'
                                                                        '| **Facilité de '
                                                                        'modification**| Plus '
                                                                        'facile | Plus difficile '
                                                                        '(nécessite une '
                                                                        'réaffectation) |\n'
                                                                        "| **Cas d'utilisation** | "
                                                                        'Données dynamiques, '
                                                                        'récursivité | Données '
                                                                        'statiques, recherches '
                                                                        'rapides |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'it': '---\n'
                                                                        'title: "Strutture dati"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'In Scheme, le **strutture '
                                                                        'dati** sono strumenti '
                                                                        'essenziali per '
                                                                        'organizzare, archiviare e '
                                                                        'manipolare i dati. '
                                                                        'Consentono agli '
                                                                        'sviluppatori di creare '
                                                                        'script efficienti, '
                                                                        'leggibili e '
                                                                        'riutilizzabili. '
                                                                        'Scegliendo la struttura '
                                                                        'dati corretta per un '
                                                                        'problema specifico, puoi '
                                                                        'ottimizzare sia le '
                                                                        'prestazioni che la '
                                                                        'chiarezza del tuo '
                                                                        'codice.\n'
                                                                        '\n'
                                                                        '## Strutture dati chiave '
                                                                        'nello schema\n'
                                                                        '\n'
                                                                        'Scheme fornisce diverse '
                                                                        'strutture dati potenti e '
                                                                        'versatili, ciascuna '
                                                                        'adatta per attività '
                                                                        'specifiche. Le strutture '
                                                                        'dati primarie includono:\n'
                                                                        '\n'
                                                                        '### Elenchi\n'
                                                                        '\n'
                                                                        'Gli elenchi sono raccolte '
                                                                        'ordinate di elementi che '
                                                                        'possono crescere o '
                                                                        'ridursi dinamicamente. '
                                                                        'Sono ideali per dati '
                                                                        'sequenziali o gerarchici '
                                                                        'e sono ampiamente '
                                                                        'utilizzati nella '
                                                                        'programmazione '
                                                                        'funzionale.\n'
                                                                        '\n'
                                                                        'Caratteristiche '
                                                                        'principali:\n'
                                                                        '- Dimensioni dinamiche.\n'
                                                                        '- Gli elementi possono '
                                                                        'essere di tipo misto.\n'
                                                                        '- Comunemente utilizzato '
                                                                        'per algoritmi ricorsivi e '
                                                                        'per rappresentare '
                                                                        'strutture ad albero.\n'
                                                                        '\n'
                                                                        'Esempi di utilizzo:\n'
                                                                        '-Gestione delle '
                                                                        'collezioni di oggetti.\n'
                                                                        '- Rappresentare sequenze '
                                                                        'o gerarchie.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Vettori\n'
                                                                        '\n'
                                                                        'I vettori sono raccolte '
                                                                        'di elementi di dimensione '
                                                                        'fissa, indicizzati per un '
                                                                        'accesso rapido. Sono più '
                                                                        'adatti per scenari in cui '
                                                                        'le prestazioni e '
                                                                        "l'accesso posizionale "
                                                                        'sono fondamentali.\n'
                                                                        '\n'
                                                                        'Caratteristiche '
                                                                        'principali:\n'
                                                                        '- Dimensioni fisse alla '
                                                                        'creazione.\n'
                                                                        '- Si accede agli elementi '
                                                                        'tramite il loro indice.\n'
                                                                        '- Più veloce degli '
                                                                        'elenchi per determinate '
                                                                        "operazioni come l'accesso "
                                                                        'casuale.\n'
                                                                        '\n'
                                                                        'Esempi di utilizzo:\n'
                                                                        '- Memorizzazione di '
                                                                        'configurazioni o dati a '
                                                                        'dimensione fissa.\n'
                                                                        '- Ricerche rapide e '
                                                                        'aggiornamenti in base '
                                                                        'alla posizione.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Scegliere la giusta '
                                                                        'struttura dei dati\n'
                                                                        '\n'
                                                                        'La decisione di '
                                                                        'utilizzare una **lista** '
                                                                        'o un **vettore** dipende '
                                                                        'dalle esigenze specifiche '
                                                                        'del tuo script. Ecco '
                                                                        'alcune linee guida:\n'
                                                                        '\n'
                                                                        '| Caratteristica | '
                                                                        'Elenchi | Vettori |\n'
                                                                        '|-------------------------|------------------------------------|--------------------------------|\n'
                                                                        '| **Flessibilità delle '
                                                                        'dimensioni** | Dinamico | '
                                                                        'Risolto |\n'
                                                                        '| **Velocità di accesso** '
                                                                        '| Più lento (accesso '
                                                                        'sequenziale) | Più veloce '
                                                                        '(accesso indicizzato) |\n'
                                                                        '| **Facilità di '
                                                                        'modifica**| Più facile | '
                                                                        'Più difficile (richiede '
                                                                        'la riallocazione)|\n'
                                                                        "| **Casi d'uso** | Dati "
                                                                        'dinamici, ricorsione | '
                                                                        'Dati statici, ricerche '
                                                                        'veloci |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'ja': '---\n'
                                                                        'title: "データ構造"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'Scheme では、**データ構造** '
                                                                        'はデータを整理、保存、操作するための重要なツールです。これらにより、開発者は効率的で読みやすく、再利用可能なスクリプトを構築できます。特定の問題に対して適切なデータ構造を選択することで、コードのパフォーマンスと明瞭さの両方を最適化できます。\n'
                                                                        '\n'
                                                                        '## Scheme の主要なデータ構造\n'
                                                                        '\n'
                                                                        'Scheme '
                                                                        'は、特定のタスクに適した強力で多用途のデータ構造をいくつか提供します。主なデータ構造には次のものがあります。\n'
                                                                        '\n'
                                                                        '### リスト\n'
                                                                        '\n'
                                                                        'リストは、動的に拡大または縮小できる順序付けされた要素のコレクションです。これらは順次データまたは階層データに最適であり、関数型プログラミングで広く使用されています。\n'
                                                                        '\n'
                                                                        '主な特徴:\n'
                                                                        '- 動的にサイズ変更されます。\n'
                                                                        '- 要素は混合タイプにすることができます。\n'
                                                                        '- '
                                                                        '再帰的アルゴリズムとツリー状構造の表現によく使用されます。\n'
                                                                        '\n'
                                                                        '使用例:\n'
                                                                        '- アイテムのコレクションを管理します。\n'
                                                                        '- シーケンスまたは階層を表現します。\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### ベクトル\n'
                                                                        '\n'
                                                                        'ベクトルは、高速アクセスのためにインデックスが付けられた固定サイズの要素のコレクションです。これらは、パフォーマンスと位置アクセスが重要なシナリオに最適です。\n'
                                                                        '\n'
                                                                        '主な特徴:\n'
                                                                        '- 作成時にサイズを固定しました。\n'
                                                                        '- '
                                                                        '要素にはインデックスによってアクセスされます。\n'
                                                                        '- ランダム '
                                                                        'アクセスなどの特定の操作ではリストよりも高速です。\n'
                                                                        '\n'
                                                                        '使用例：\n'
                                                                        '- 固定サイズの構成またはデータの保存。\n'
                                                                        '- 位置に基づいた素早い検索と更新。\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### 適切なデータ構造の選択\n'
                                                                        '\n'
                                                                        '**リスト**と**ベクター**のどちらを使用するかの決定は、スクリプトの特定のニーズによって異なります。以下にいくつかのガイドラインを示します。\n'
                                                                        '\n'
                                                                        '|特集 |リスト |ベクター |\n'
                                                                        '|----------------------|------------------------------|----------------------------|\n'
                                                                        '| **サイズの柔軟性** |ダイナミック '
                                                                        '|修正済み |\n'
                                                                        '| **アクセス速度** |遅い '
                                                                        '(シーケンシャルアクセス) |高速化 '
                                                                        '(インデックス付きアクセス) |\n'
                                                                        '| **変更の容易さ**|より簡単 |より困難 '
                                                                        '(再割り当てが必要)|\n'
                                                                        '| **使用例** |動的データ、再帰 '
                                                                        '|静的データ、高速検索 |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'ko': '---\n'
                                                                        'title: "데이터 구조"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'Scheme에서 **데이터 구조**는 데이터를 '
                                                                        '구성, 저장 및 조작하는 데 필수적인 '
                                                                        '도구입니다. 이를 통해 개발자는 효율적이고 '
                                                                        '읽기 쉽고 재사용 가능한 스크립트를 작성할 수 '
                                                                        '있습니다. 특정 문제에 적합한 데이터 구조를 '
                                                                        '선택하면 코드의 성능과 명확성을 모두 최적화할 '
                                                                        '수 있습니다.\n'
                                                                        '\n'
                                                                        '## 스키마의 주요 데이터 구조\n'
                                                                        '\n'
                                                                        'Scheme은 각각 특정 작업에 적합한 '
                                                                        '강력하고 다양한 데이터 구조를 제공합니다. '
                                                                        '기본 데이터 구조는 다음과 같습니다.\n'
                                                                        '\n'
                                                                        '### 목록\n'
                                                                        '\n'
                                                                        '목록은 동적으로 늘어나거나 줄어들 수 있는 '
                                                                        '순서가 지정된 요소 모음입니다. 이는 순차적 '
                                                                        '또는 계층적 데이터에 이상적이며 함수형 '
                                                                        '프로그래밍에 널리 사용됩니다.\n'
                                                                        '\n'
                                                                        '주요 기능:\n'
                                                                        '- 동적으로 크기가 조정됩니다.\n'
                                                                        '- 요소는 혼합 유형일 수 있습니다.\n'
                                                                        '- 일반적으로 재귀 알고리즘 및 트리형 구조를 '
                                                                        '나타내는 데 사용됩니다.\n'
                                                                        '\n'
                                                                        '사용 예:\n'
                                                                        '- 아이템 컬렉션을 관리합니다.\n'
                                                                        '- 시퀀스 또는 계층을 나타냅니다.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### 벡터\n'
                                                                        '\n'
                                                                        '벡터는 빠른 액세스를 위해 인덱싱된 고정 크기 '
                                                                        '요소 컬렉션입니다. 성능과 위치 액세스가 '
                                                                        '중요한 시나리오에 가장 적합합니다.\n'
                                                                        '\n'
                                                                        '주요 기능:\n'
                                                                        '- 생성 시 크기가 고정되었습니다.\n'
                                                                        '- 요소는 인덱스로 액세스됩니다.\n'
                                                                        '- 무작위 액세스와 같은 특정 작업의 경우 '
                                                                        '목록보다 빠릅니다.\n'
                                                                        '\n'
                                                                        '사용 예:\n'
                                                                        '- 고정 크기 구성 또는 데이터 저장.\n'
                                                                        '- 위치에 따른 빠른 조회 및 업데이트.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### 올바른 데이터 구조 선택\n'
                                                                        '\n'
                                                                        '**목록** 또는 **벡터** 사용 결정은 '
                                                                        '스크립트의 특정 요구 사항에 따라 다릅니다. '
                                                                        '다음은 몇 가지 지침입니다.\n'
                                                                        '\n'
                                                                        '| 기능 | 목록 | 벡터 |\n'
                                                                        '|------------|------------------|-------------------|\n'
                                                                        '| **크기 유연성** | 동적 | 고정 |\n'
                                                                        '| **액세스 속도** | 더 느림(순차 '
                                                                        '액세스) | 더 빠르게(색인화된 액세스) |\n'
                                                                        '| **수정의 용이성**| 더 쉽게 | 더 '
                                                                        '어려움(재할당 필요)|\n'
                                                                        '| **사용 사례** | 동적 데이터, 재귀 '
                                                                        '| 정적 데이터, 빠른 조회 |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'nl': '---\n'
                                                                        'title: '
                                                                        '"Gegevensstructuren"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'In Scheme zijn '
                                                                        '**datastructuren** '
                                                                        'essentiële hulpmiddelen '
                                                                        'voor het organiseren, '
                                                                        'opslaan en manipuleren '
                                                                        'van gegevens. Ze stellen '
                                                                        'ontwikkelaars in staat '
                                                                        'efficiënte, leesbare en '
                                                                        'herbruikbare scripts te '
                                                                        'bouwen. Door de juiste '
                                                                        'datastructuur voor een '
                                                                        'specifiek probleem te '
                                                                        'kiezen, kunt u zowel de '
                                                                        'prestaties als de '
                                                                        'duidelijkheid van uw code '
                                                                        'optimaliseren.\n'
                                                                        '\n'
                                                                        '## '
                                                                        'Sleutelgegevensstructuren '
                                                                        'in schema\n'
                                                                        '\n'
                                                                        'Scheme biedt '
                                                                        'verschillende krachtige '
                                                                        'en veelzijdige '
                                                                        'datastructuren, elk '
                                                                        'geschikt voor specifieke '
                                                                        'taken. De primaire '
                                                                        'datastructuren omvatten:\n'
                                                                        '\n'
                                                                        '### Lijsten\n'
                                                                        '\n'
                                                                        'Lijsten zijn geordende '
                                                                        'verzamelingen van '
                                                                        'elementen die dynamisch '
                                                                        'kunnen groeien of '
                                                                        'krimpen. Ze zijn ideaal '
                                                                        'voor sequentiële of '
                                                                        'hiërarchische gegevens en '
                                                                        'worden veel gebruikt bij '
                                                                        'functioneel '
                                                                        'programmeren.\n'
                                                                        '\n'
                                                                        'Belangrijkste kenmerken:\n'
                                                                        '- Dynamisch formaat.\n'
                                                                        '- Elementen kunnen van '
                                                                        'gemengde typen zijn.\n'
                                                                        '- Vaak gebruikt voor '
                                                                        'recursieve algoritmen en '
                                                                        'het weergeven van '
                                                                        'boomachtige structuren.\n'
                                                                        '\n'
                                                                        'Voorbeelden van gebruik:\n'
                                                                        '- Beheer van collecties '
                                                                        'van artikelen.\n'
                                                                        '- Vertegenwoordigt '
                                                                        'reeksen of hiërarchieën.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### vectoren\n'
                                                                        '\n'
                                                                        'Vectoren zijn '
                                                                        'verzamelingen elementen '
                                                                        'van vaste grootte, '
                                                                        'geïndexeerd voor snelle '
                                                                        'toegang. Ze zijn het '
                                                                        'meest geschikt voor '
                                                                        "scenario's waarin "
                                                                        'prestaties en positionele '
                                                                        'toegang van cruciaal '
                                                                        'belang zijn.\n'
                                                                        '\n'
                                                                        'Belangrijkste kenmerken:\n'
                                                                        '- Vaste grootte bij '
                                                                        'creatie.\n'
                                                                        '- Elementen zijn '
                                                                        'toegankelijk via hun '
                                                                        'index.\n'
                                                                        '- Sneller dan lijsten '
                                                                        'voor bepaalde bewerkingen '
                                                                        'zoals willekeurige '
                                                                        'toegang.\n'
                                                                        '\n'
                                                                        'Voorbeelden van gebruik:\n'
                                                                        '- Opslaan van '
                                                                        'configuraties of gegevens '
                                                                        'met een vaste grootte.\n'
                                                                        '- Snelle zoekopdrachten '
                                                                        'en updates op basis van '
                                                                        'positie.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### De juiste '
                                                                        'gegevensstructuur kiezen\n'
                                                                        '\n'
                                                                        'De beslissing om een '
                                                                        '**lijst** of een '
                                                                        '**vector** te gebruiken, '
                                                                        'hangt af van de '
                                                                        'specifieke behoeften van '
                                                                        'uw script. Hier zijn '
                                                                        'enkele richtlijnen:\n'
                                                                        '\n'
                                                                        '| Kenmerk | Lijsten | '
                                                                        'Vectoren |\n'
                                                                        '|----------------------|----------------------------|------------------------------|\n'
                                                                        '| **Maatflexibiliteit** | '
                                                                        'Dynamisch | Vast |\n'
                                                                        '| **Toegangssnelheid** | '
                                                                        'Langzamer (sequentiële '
                                                                        'toegang) | Sneller '
                                                                        '(geïndexeerde toegang) |\n'
                                                                        '| **Gemak van '
                                                                        'wijziging**| Makkelijker '
                                                                        '| Moeilijker (vereist '
                                                                        'herverdeling)|\n'
                                                                        "| **Gebruiksscenario's** "
                                                                        '| Dynamische gegevens, '
                                                                        'recursie | Statische '
                                                                        'gegevens, snelle '
                                                                        'zoekopdrachten |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'pl': '---\n'
                                                                        'title: "Struktury '
                                                                        'danych"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'W schemacie **struktury '
                                                                        'danych** są niezbędnymi '
                                                                        'narzędziami do '
                                                                        'organizowania, '
                                                                        'przechowywania i '
                                                                        'manipulowania danymi. '
                                                                        'Umożliwiają programistom '
                                                                        'tworzenie wydajnych, '
                                                                        'czytelnych i nadających '
                                                                        'się do ponownego użycia '
                                                                        'skryptów. Wybierając '
                                                                        'odpowiednią strukturę '
                                                                        'danych dla konkretnego '
                                                                        'problemu, możesz '
                                                                        'zoptymalizować zarówno '
                                                                        'wydajność, jak i '
                                                                        'przejrzystość swojego '
                                                                        'kodu.\n'
                                                                        '\n'
                                                                        '## Kluczowe struktury '
                                                                        'danych w schemacie\n'
                                                                        '\n'
                                                                        'Scheme udostępnia kilka '
                                                                        'potężnych i '
                                                                        'wszechstronnych struktur '
                                                                        'danych, z których każda '
                                                                        'jest dostosowana do '
                                                                        'określonych zadań. '
                                                                        'Podstawowe struktury '
                                                                        'danych obejmują:\n'
                                                                        '\n'
                                                                        '### Listy\n'
                                                                        '\n'
                                                                        'Listy to uporządkowane '
                                                                        'zbiory elementów, które '
                                                                        'mogą dynamicznie rosnąć '
                                                                        'lub kurczyć się. Idealnie '
                                                                        'nadają się do danych '
                                                                        'sekwencyjnych lub '
                                                                        'hierarchicznych i są '
                                                                        'szeroko stosowane w '
                                                                        'programowaniu '
                                                                        'funkcjonalnym.\n'
                                                                        '\n'
                                                                        'Kluczowe cechy:\n'
                                                                        '- Rozmiar dynamiczny.\n'
                                                                        '- Elementy mogą być typów '
                                                                        'mieszanych.\n'
                                                                        '- Powszechnie używane w '
                                                                        'algorytmach '
                                                                        'rekurencyjnych i '
                                                                        'reprezentujących '
                                                                        'struktury drzewiaste.\n'
                                                                        '\n'
                                                                        'Przykłady użycia:\n'
                                                                        '- Zarządzanie zbiorami '
                                                                        'przedmiotów.\n'
                                                                        '- Reprezentowanie '
                                                                        'sekwencji lub '
                                                                        'hierarchii.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Wektory\n'
                                                                        '\n'
                                                                        'Wektory to zbiory '
                                                                        'elementów o stałym '
                                                                        'rozmiarze, indeksowane w '
                                                                        'celu szybkiego dostępu. '
                                                                        'Najlepiej nadają się do '
                                                                        'scenariuszy, w których '
                                                                        'wydajność i dostęp '
                                                                        'pozycyjny mają kluczowe '
                                                                        'znaczenie.\n'
                                                                        '\n'
                                                                        'Kluczowe cechy:\n'
                                                                        '- Naprawiono rozmiar przy '
                                                                        'tworzeniu.\n'
                                                                        '- Dostęp do elementów '
                                                                        'uzyskuje się poprzez ich '
                                                                        'indeks.\n'
                                                                        '- Szybciej niż listy w '
                                                                        'przypadku niektórych '
                                                                        'operacji, takich jak '
                                                                        'dostęp losowy.\n'
                                                                        '\n'
                                                                        'Przykłady użycia:\n'
                                                                        '- Przechowywanie '
                                                                        'konfiguracji lub danych o '
                                                                        'stałym rozmiarze.\n'
                                                                        '- Szybkie wyszukiwania i '
                                                                        'aktualizacje na podstawie '
                                                                        'pozycji.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Wybór właściwej '
                                                                        'struktury danych\n'
                                                                        '\n'
                                                                        'Decyzja o użyciu '
                                                                        '**listy** lub **wektora** '
                                                                        'zależy od konkretnych '
                                                                        'potrzeb Twojego skryptu. '
                                                                        'Oto kilka wskazówek:\n'
                                                                        '\n'
                                                                        '| Funkcja | Listy | '
                                                                        'Wektory |\n'
                                                                        '|-------------------------|--------------------------------------------|--------------------------------|\n'
                                                                        '| **Elastyczność '
                                                                        'rozmiaru** | Dynamiczny | '
                                                                        'Naprawiono |\n'
                                                                        '| **Szybkość dostępu** | '
                                                                        'Wolniejsze (dostęp '
                                                                        'sekwencyjny) | Szybciej '
                                                                        '(dostęp indeksowany) |\n'
                                                                        '| **Łatwość '
                                                                        'modyfikacji**| Łatwiej | '
                                                                        'Trudniejsze (wymaga '
                                                                        'realokacji)|\n'
                                                                        '| **Przypadki użycia** | '
                                                                        'Dane dynamiczne, '
                                                                        'rekurencja | Dane '
                                                                        'statyczne, szybkie '
                                                                        'wyszukiwania |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'pt-br': '---\n'
                                                                           'title: "Estruturas de '
                                                                           'dados"\n'
                                                                           'type: docs\n'
                                                                           'weight: 3\n'
                                                                           '---\n'
                                                                           'No Scheme, '
                                                                           '**estruturas de '
                                                                           'dados** são '
                                                                           'ferramentas essenciais '
                                                                           'para organizar, '
                                                                           'armazenar e manipular '
                                                                           'dados. Eles permitem '
                                                                           'que os desenvolvedores '
                                                                           'criem scripts '
                                                                           'eficientes, legíveis e '
                                                                           'reutilizáveis. Ao '
                                                                           'escolher a estrutura '
                                                                           'de dados certa para um '
                                                                           'problema específico, '
                                                                           'você pode otimizar o '
                                                                           'desempenho e a clareza '
                                                                           'do seu código.\n'
                                                                           '\n'
                                                                           '## Principais '
                                                                           'estruturas de dados no '
                                                                           'esquema\n'
                                                                           '\n'
                                                                           'O Scheme fornece '
                                                                           'diversas estruturas de '
                                                                           'dados poderosas e '
                                                                           'versáteis, cada uma '
                                                                           'adequada para tarefas '
                                                                           'específicas. As '
                                                                           'estruturas de dados '
                                                                           'primárias incluem:\n'
                                                                           '\n'
                                                                           '### Listas\n'
                                                                           '\n'
                                                                           'Listas são coleções '
                                                                           'ordenadas de elementos '
                                                                           'que podem aumentar ou '
                                                                           'diminuir '
                                                                           'dinamicamente. Eles '
                                                                           'são ideais para dados '
                                                                           'sequenciais ou '
                                                                           'hierárquicos e são '
                                                                           'amplamente utilizados '
                                                                           'em programação '
                                                                           'funcional.\n'
                                                                           '\n'
                                                                           'Principais recursos:\n'
                                                                           '- Dimensionado '
                                                                           'dinamicamente.\n'
                                                                           '- Os elementos podem '
                                                                           'ser de tipos mistos.\n'
                                                                           '- Comumente usado para '
                                                                           'algoritmos recursivos '
                                                                           'e representação de '
                                                                           'estruturas semelhantes '
                                                                           'a árvores.\n'
                                                                           '\n'
                                                                           'Exemplos de uso:\n'
                                                                           '- Gerenciar coleções '
                                                                           'de itens.\n'
                                                                           '- Representando '
                                                                           'sequências ou '
                                                                           'hierarquias.\n'
                                                                           '\n'
                                                                           '---\n'
                                                                           '\n'
                                                                           '### Vetores\n'
                                                                           '\n'
                                                                           'Vetores são coleções '
                                                                           'de elementos de '
                                                                           'tamanho fixo, '
                                                                           'indexados para acesso '
                                                                           'rápido. Eles são mais '
                                                                           'adequados para '
                                                                           'cenários onde o '
                                                                           'desempenho e o acesso '
                                                                           'posicional são '
                                                                           'críticos.\n'
                                                                           '\n'
                                                                           'Principais recursos:\n'
                                                                           '- Tamanho fixo na '
                                                                           'criação.\n'
                                                                           '- Os elementos são '
                                                                           'acessados '
                                                                           '\u200b\u200bpelo seu '
                                                                           'índice.\n'
                                                                           '- Mais rápido que '
                                                                           'listas para '
                                                                           'determinadas '
                                                                           'operações, como acesso '
                                                                           'aleatório.\n'
                                                                           '\n'
                                                                           'Exemplos de uso:\n'
                                                                           '- Armazenamento de '
                                                                           'configurações ou dados '
                                                                           'de tamanho fixo.\n'
                                                                           '- Pesquisas e '
                                                                           'atualizações rápidas '
                                                                           'com base na posição.\n'
                                                                           '\n'
                                                                           '---\n'
                                                                           '\n'
                                                                           '### Escolhendo a '
                                                                           'estrutura de dados '
                                                                           'correta\n'
                                                                           '\n'
                                                                           'A decisão de usar uma '
                                                                           '**lista** ou um '
                                                                           '**vetor** depende das '
                                                                           'necessidades '
                                                                           'específicas do seu '
                                                                           'script. Aqui estão '
                                                                           'algumas diretrizes:\n'
                                                                           '\n'
                                                                           '| Recurso | Listas | '
                                                                           'Vetores |\n'
                                                                           '|-------------------------|----------------------------------------|--------------------------------|\n'
                                                                           '| **Flexibilidade de '
                                                                           'tamanho** | Dinâmico | '
                                                                           'Fixo |\n'
                                                                           '| **Velocidade de '
                                                                           'acesso** | Mais lento '
                                                                           '(acesso sequencial) | '
                                                                           'Mais rápido (acesso '
                                                                           'indexado) |\n'
                                                                           '| **Facilidade de '
                                                                           'modificação**| Mais '
                                                                           'fácil | Mais difícil '
                                                                           '(requer realocação)|\n'
                                                                           '| **Casos de uso** | '
                                                                           'Dados dinâmicos, '
                                                                           'recursão | Dados '
                                                                           'estáticos, pesquisas '
                                                                           'rápidas |\n'
                                                                           '\n'
                                                                           '---',
                                                                  'ru': '---\n'
                                                                        'title: "Структуры '
                                                                        'данных"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'В Scheme **структуры '
                                                                        'данных** — это важные '
                                                                        'инструменты для '
                                                                        'организации, хранения и '
                                                                        'управления данными. Они '
                                                                        'позволяют разработчикам '
                                                                        'создавать эффективные, '
                                                                        'читаемые и повторно '
                                                                        'используемые сценарии. '
                                                                        'Выбрав правильную '
                                                                        'структуру данных для '
                                                                        'конкретной задачи, вы '
                                                                        'можете оптимизировать как '
                                                                        'производительность, так и '
                                                                        'ясность вашего кода.\n'
                                                                        '\n'
                                                                        '## Ключевые структуры '
                                                                        'данных в схеме\n'
                                                                        '\n'
                                                                        'Scheme предоставляет '
                                                                        'несколько мощных и '
                                                                        'универсальных структур '
                                                                        'данных, каждая из которых '
                                                                        'подходит для конкретных '
                                                                        'задач. К первичным '
                                                                        'структурам данных '
                                                                        'относятся:\n'
                                                                        '\n'
                                                                        '### Списки\n'
                                                                        '\n'
                                                                        'Списки представляют собой '
                                                                        'упорядоченные коллекции '
                                                                        'элементов, которые могут '
                                                                        'динамически увеличиваться '
                                                                        'или уменьшаться. Они '
                                                                        'идеально подходят для '
                                                                        'последовательных или '
                                                                        'иерархических данных и '
                                                                        'широко используются в '
                                                                        'функциональном '
                                                                        'программировании.\n'
                                                                        '\n'
                                                                        'Ключевые особенности:\n'
                                                                        '- Динамический размер.\n'
                                                                        '- Элементы могут быть '
                                                                        'смешанного типа.\n'
                                                                        '- Обычно используется для '
                                                                        'рекурсивных алгоритмов и '
                                                                        'представления древовидных '
                                                                        'структур.\n'
                                                                        '\n'
                                                                        'Примеры использования:\n'
                                                                        '- Управление коллекциями '
                                                                        'предметов.\n'
                                                                        '- Представление '
                                                                        'последовательностей или '
                                                                        'иерархий.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Векторы\n'
                                                                        '\n'
                                                                        'Векторы — это коллекции '
                                                                        'элементов фиксированного '
                                                                        'размера, '
                                                                        'проиндексированные для '
                                                                        'быстрого доступа. Они '
                                                                        'лучше всего подходят для '
                                                                        'сценариев, где '
                                                                        'производительность и '
                                                                        'позиционный доступ имеют '
                                                                        'решающее значение.\n'
                                                                        '\n'
                                                                        'Ключевые особенности:\n'
                                                                        '- Исправлен размер при '
                                                                        'создании.\n'
                                                                        '- Доступ к элементам '
                                                                        'осуществляется по их '
                                                                        'индексу.\n'
                                                                        '- Быстрее, чем списки для '
                                                                        'определенных операций, '
                                                                        'таких как произвольный '
                                                                        'доступ.\n'
                                                                        '\n'
                                                                        'Примеры использования:\n'
                                                                        '- Хранение конфигураций '
                                                                        'или данных фиксированного '
                                                                        'размера.\n'
                                                                        '- Быстрый поиск и '
                                                                        'обновления в зависимости '
                                                                        'от позиции.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Выбор правильной '
                                                                        'структуры данных\n'
                                                                        '\n'
                                                                        'Решение использовать '
                                                                        '**список** или **вектор** '
                                                                        'зависит от конкретных '
                                                                        'потребностей вашего '
                                                                        'скрипта. Вот несколько '
                                                                        'рекомендаций:\n'
                                                                        '\n'
                                                                        '| Особенность | Списки | '
                                                                        'Векторы |\n'
                                                                        '|-------------------------|----------------------------------------------|--------------------------------|\n'
                                                                        '| **Гибкость размеров** | '
                                                                        'Динамический | Исправлено '
                                                                        '|\n'
                                                                        '| **Скорость доступа** | '
                                                                        'Медленнее '
                                                                        '(последовательный доступ) '
                                                                        '| Быстрее '
                                                                        '(индексированный доступ) '
                                                                        '|\n'
                                                                        '| **Простота '
                                                                        'модификации**| Проще | '
                                                                        'Сложнее (требуется '
                                                                        'перераспределение)|\n'
                                                                        '| **Примеры '
                                                                        'использования** | '
                                                                        'Динамические данные, '
                                                                        'рекурсия | Статические '
                                                                        'данные, быстрый поиск |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'sv': '---\n'
                                                                        'title: "Datastrukturer"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'I Scheme är '
                                                                        '**datastrukturer** '
                                                                        'viktiga verktyg för att '
                                                                        'organisera, lagra och '
                                                                        'manipulera data. De gör '
                                                                        'det möjligt för '
                                                                        'utvecklare att bygga '
                                                                        'effektiva, läsbara och '
                                                                        'återanvändbara skript. '
                                                                        'Genom att välja rätt '
                                                                        'datastruktur för ett '
                                                                        'specifikt problem kan du '
                                                                        'optimera både prestanda '
                                                                        'och tydlighet i din kod.\n'
                                                                        '\n'
                                                                        '## Nyckeldatastrukturer i '
                                                                        'schema\n'
                                                                        '\n'
                                                                        'Scheme tillhandahåller '
                                                                        'flera kraftfulla och '
                                                                        'mångsidiga '
                                                                        'datastrukturer, var och '
                                                                        'en lämpad för specifika '
                                                                        'uppgifter. De primära '
                                                                        'datastrukturerna '
                                                                        'inkluderar:\n'
                                                                        '\n'
                                                                        '### Listor\n'
                                                                        '\n'
                                                                        'Listor är ordnade '
                                                                        'samlingar av element som '
                                                                        'dynamiskt kan växa eller '
                                                                        'krympa. De är idealiska '
                                                                        'för sekventiell eller '
                                                                        'hierarkisk data och '
                                                                        'används ofta i '
                                                                        'funktionell '
                                                                        'programmering.\n'
                                                                        '\n'
                                                                        'Nyckelfunktioner:\n'
                                                                        '- Dynamiskt '
                                                                        'dimensionerad.\n'
                                                                        '– Element kan vara av '
                                                                        'blandade typer.\n'
                                                                        '- Används vanligtvis för '
                                                                        'rekursiva algoritmer och '
                                                                        'representerar '
                                                                        'trädliknande strukturer.\n'
                                                                        '\n'
                                                                        'Exempel på användning:\n'
                                                                        '- Hantera samlingar av '
                                                                        'föremål.\n'
                                                                        '- Representerar sekvenser '
                                                                        'eller hierarkier.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Vektorer\n'
                                                                        '\n'
                                                                        'Vektorer är samlingar av '
                                                                        'element med fast storlek, '
                                                                        'indexerade för snabb '
                                                                        'åtkomst. De är bäst '
                                                                        'lämpade för scenarier där '
                                                                        'prestanda och '
                                                                        'positionsåtkomst är '
                                                                        'avgörande.\n'
                                                                        '\n'
                                                                        'Nyckelfunktioner:\n'
                                                                        '- Fast storlek vid '
                                                                        'skapande.\n'
                                                                        '- Elementen nås av deras '
                                                                        'index.\n'
                                                                        '- Snabbare än listor för '
                                                                        'vissa operationer som '
                                                                        'slumpmässig åtkomst.\n'
                                                                        '\n'
                                                                        'Exempel på användning:\n'
                                                                        '- Lagring av '
                                                                        'konfigurationer eller '
                                                                        'data med fast storlek.\n'
                                                                        '- Snabbsökningar och '
                                                                        'uppdateringar baserat på '
                                                                        'position.\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### Att välja rätt '
                                                                        'datastruktur\n'
                                                                        '\n'
                                                                        'Beslutet att använda en '
                                                                        '**lista** eller en '
                                                                        '**vektor** beror på de '
                                                                        'specifika behoven hos '
                                                                        'ditt manus. Här är några '
                                                                        'riktlinjer:\n'
                                                                        '\n'
                                                                        '| Funktion | Listor | '
                                                                        'Vektorer |\n'
                                                                        '|------------------------|-------------------------------------|--------------------------------|\n'
                                                                        '| '
                                                                        '**Storleksflexibilitet** '
                                                                        '| Dynamisk | Fast |\n'
                                                                        '| **Åtkomsthastighet** | '
                                                                        'Långsammare (sekventiell '
                                                                        'åtkomst) | Snabbare '
                                                                        '(indexerad åtkomst) |\n'
                                                                        '| **Lätt att ändra**| '
                                                                        'Lättare | Svårare (kräver '
                                                                        'omfördelning)|\n'
                                                                        '| **Användningsfall** | '
                                                                        'Dynamisk data, rekursion '
                                                                        '| Statisk data, snabba '
                                                                        'uppslagningar |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'th': '---\n'
                                                                        'title: "โครงสร้างข้อมูล"\n'
                                                                        'type: docs\n'
                                                                        'weight: 3\n'
                                                                        '---\n'
                                                                        'ใน Scheme '
                                                                        '**โครงสร้างข้อมูล** '
                                                                        'เป็นเครื่องมือสำคัญสำหรับการจัดระเบียบ '
                                                                        'จัดเก็บ และจัดการข้อมูล '
                                                                        'ช่วยให้นักพัฒนาสามารถสร้างสคริปต์ที่มีประสิทธิภาพ '
                                                                        'อ่านได้ '
                                                                        'และนำกลับมาใช้ใหม่ได้ '
                                                                        'ด้วยการเลือกโครงสร้างข้อมูลที่เหมาะสมสำหรับปัญหาเฉพาะ '
                                                                        'คุณสามารถเพิ่มประสิทธิภาพทั้งประสิทธิภาพและความชัดเจนของโค้ดของคุณได้\n'
                                                                        '\n'
                                                                        '## '
                                                                        'โครงสร้างข้อมูลสำคัญในโครงการ\n'
                                                                        '\n'
                                                                        'Scheme '
                                                                        'มีโครงสร้างข้อมูลที่ทรงพลังและหลากหลาย '
                                                                        'ซึ่งแต่ละโครงสร้างเหมาะสำหรับงานเฉพาะ '
                                                                        'โครงสร้างข้อมูลหลักประกอบด้วย:\n'
                                                                        '\n'
                                                                        '### รายการ\n'
                                                                        '\n'
                                                                        'รายการคือการเรียงลำดับคอลเลกชันขององค์ประกอบที่สามารถขยายหรือย่อแบบไดนามิกได้ '
                                                                        'เหมาะอย่างยิ่งสำหรับข้อมูลตามลำดับหรือลำดับชั้น '
                                                                        'และมีการใช้กันอย่างแพร่หลายในการเขียนโปรแกรมเชิงฟังก์ชัน\n'
                                                                        '\n'
                                                                        'คุณสมบัติที่สำคัญ:\n'
                                                                        '- ขนาดแบบไดนามิก\n'
                                                                        '- '
                                                                        'องค์ประกอบสามารถเป็นแบบผสมได้\n'
                                                                        '- '
                                                                        'ใช้กันทั่วไปสำหรับอัลกอริธึมแบบเรียกซ้ำและแสดงโครงสร้างคล้ายต้นไม้\n'
                                                                        '\n'
                                                                        'ตัวอย่างการใช้งาน:\n'
                                                                        '- '
                                                                        'การจัดการคอลเลกชันของรายการ\n'
                                                                        '- '
                                                                        'การแสดงลำดับหรือลำดับชั้น\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### เวกเตอร์\n'
                                                                        '\n'
                                                                        'เวกเตอร์คือคอลเลกชันขององค์ประกอบที่มีขนาดคงที่ '
                                                                        'ซึ่งจัดทำดัชนีไว้เพื่อการเข้าถึงที่รวดเร็ว '
                                                                        'เหมาะที่สุดสำหรับสถานการณ์ที่ประสิทธิภาพและการเข้าถึงตำแหน่งมีความสำคัญ\n'
                                                                        '\n'
                                                                        'คุณสมบัติที่สำคัญ:\n'
                                                                        '- ขนาดคงที่ในการสร้าง\n'
                                                                        '- องค์ประกอบต่างๆ '
                                                                        'เข้าถึงได้โดยดัชนี\n'
                                                                        '- '
                                                                        'เร็วกว่ารายการสำหรับการดำเนินการบางอย่าง '
                                                                        'เช่น การเข้าถึงแบบสุ่ม\n'
                                                                        '\n'
                                                                        'ตัวอย่างการใช้งาน:\n'
                                                                        '- '
                                                                        'การจัดเก็บการกำหนดค่าหรือข้อมูลขนาดคงที่\n'
                                                                        '- '
                                                                        'การค้นหาและอัปเดตอย่างรวดเร็วตามตำแหน่ง\n'
                                                                        '\n'
                                                                        '---\n'
                                                                        '\n'
                                                                        '### '
                                                                        'การเลือกโครงสร้างข้อมูลที่เหมาะสม\n'
                                                                        '\n'
                                                                        'การตัดสินใจใช้ **รายการ** '
                                                                        'หรือ **เวกเตอร์** '
                                                                        'ขึ้นอยู่กับความต้องการเฉพาะของสคริปต์ของคุณ '
                                                                        'ต่อไปนี้เป็นแนวทางบางประการ:\n'
                                                                        '\n'
                                                                        '| คุณสมบัติ | รายการ | '
                                                                        'เวกเตอร์ |\n'
                                                                        '|-----------------------------|----------------------------------|--------------------------------|\n'
                                                                        '| **ความยืดหยุ่นของขนาด** '
                                                                        '| ไดนามิก | แก้ไข |\n'
                                                                        '| '
                                                                        '**ความเร็วในการเข้าถึง** '
                                                                        '| ช้าลง (เข้าถึงตามลำดับ) '
                                                                        '| เร็วขึ้น '
                                                                        '(การเข้าถึงที่จัดทำดัชนี) '
                                                                        '|\n'
                                                                        '| '
                                                                        '**ความง่ายในการปรับเปลี่ยน**| '
                                                                        'ง่ายขึ้น | ยากกว่า '
                                                                        '(ต้องจัดสรรใหม่)|\n'
                                                                        '| **กรณีการใช้งาน** | '
                                                                        'ข้อมูลไดนามิก การเรียกซ้ำ '
                                                                        '| ข้อมูลคงที่ '
                                                                        'การค้นหาที่รวดเร็ว |\n'
                                                                        '\n'
                                                                        '---',
                                                                  'zh-cn': '---\n'
                                                                           'title: "数据结构"\n'
                                                                           'type: docs\n'
                                                                           'weight: 3\n'
                                                                           '---\n'
                                                                           '在Scheme中，**数据结构**是组织、存储和操作数据的重要工具。它们使开发人员能够构建高效、可读且可重用的脚本。通过为特定问题选择正确的数据结构，您可以优化代码的性能和清晰度。\n'
                                                                           '\n'
                                                                           '## Scheme中的关键数据结构\n'
                                                                           '\n'
                                                                           'Scheme '
                                                                           '提供了几种强大且通用的数据结构，每种数据结构都适合特定的任务。主要数据结构包括：\n'
                                                                           '\n'
                                                                           '### 列表\n'
                                                                           '\n'
                                                                           '列表是可以动态增长或缩小的元素的有序集合。它们非常适合顺序或分层数据，并广泛用于函数式编程。\n'
                                                                           '\n'
                                                                           '主要特点：\n'
                                                                           '- 动态调整大小。\n'
                                                                           '- 元素可以是混合类型。\n'
                                                                           '- 通常用于递归算法和表示树状结构。\n'
                                                                           '\n'
                                                                           '使用示例：\n'
                                                                           '- 管理项目集合。\n'
                                                                           '- 表示序列或层次结构。\n'
                                                                           '\n'
                                                                           '---\n'
                                                                           '\n'
                                                                           '### 向量\n'
                                                                           '\n'
                                                                           '向量是固定大小的元素集合，具有索引以便快速访问。它们最适合性能和位置访问至关重要的场景。\n'
                                                                           '\n'
                                                                           '主要特点：\n'
                                                                           '- 创建时固定大小。\n'
                                                                           '- 元素通过其索引来访问。\n'
                                                                           '- '
                                                                           '对于某些操作（例如随机访问）比列表更快。\n'
                                                                           '\n'
                                                                           '使用示例：\n'
                                                                           '- 存储固定大小的配置或数据。\n'
                                                                           '- 根据位置快速查找和更新。\n'
                                                                           '\n'
                                                                           '---\n'
                                                                           '\n'
                                                                           '### 选择正确的数据结构\n'
                                                                           '\n'
                                                                           '决定使用 **列表** 还是 **向量** '
                                                                           '取决于脚本的具体需求。以下是一些准则：\n'
                                                                           '\n'
                                                                           '|特色|列表 |向量|\n'
                                                                           '|------------------------------------|----------------------------------------|--------------------------------|\n'
                                                                           '| **尺寸灵活性** |动态 |固定|\n'
                                                                           '| **访问速度** '
                                                                           '|较慢（顺序访问）|更快（索引访问）|\n'
                                                                           '| **易于修改**|更容易 '
                                                                           '|更难（需要重新分配）|\n'
                                                                           '| **使用案例** '
                                                                           '|动态数据，递归|静态数据，快速查找|\n'
                                                                           '\n'
                                                                           '---',
                                                                  'zh-tw': '---\n'
                                                                           'title: "資料結構"\n'
                                                                           'type: docs\n'
                                                                           'weight: 3\n'
                                                                           '---\n'
                                                                           '在Scheme中，**資料結構**是組織、儲存和操作資料的重要工具。它們使開發人員能夠建立高效、可讀且可重複使用的腳本。透過為特定問題選擇正確的資料結構，您可以優化程式碼的效能和清晰度。\n'
                                                                           '\n'
                                                                           '## Scheme中的關鍵資料結構\n'
                                                                           '\n'
                                                                           'Scheme '
                                                                           '提供了幾種強大且通用的資料結構，每種資料結構都適合特定的任務。主要資料結構包括：\n'
                                                                           '\n'
                                                                           '### 列表\n'
                                                                           '\n'
                                                                           '列表是可以動態增長或縮小的元素的有序集合。它們非常適合順序或分層數據，並廣泛用於函數式程式設計。\n'
                                                                           '\n'
                                                                           '主要特點：\n'
                                                                           '- 動態調整大小。\n'
                                                                           '- 元素可以是混合類型。\n'
                                                                           '- 通常用於遞歸演算法和表示樹狀結構。\n'
                                                                           '\n'
                                                                           '使用範例：\n'
                                                                           '- 管理項目集合。\n'
                                                                           '- 表示序列或層次結構。\n'
                                                                           '\n'
                                                                           '---\n'
                                                                           '\n'
                                                                           '### 向量\n'
                                                                           '\n'
                                                                           '向量是固定大小的元素集合，具有索引以便快速存取。它們最適合效能和位置存取至關重要的場景。\n'
                                                                           '\n'
                                                                           '主要特點：\n'
                                                                           '- 創建時固定大小。\n'
                                                                           '- 元素透過其索引來存取。\n'
                                                                           '- '
                                                                           '對於某些操作（例如隨機存取）比清單更快。\n'
                                                                           '\n'
                                                                           '使用範例：\n'
                                                                           '- 儲存固定大小的配置或資料。\n'
                                                                           '- 根據位置快速尋找和更新。\n'
                                                                           '\n'
                                                                           '---\n'
                                                                           '\n'
                                                                           '### 選擇正確的資料結構\n'
                                                                           '\n'
                                                                           '決定使用 **清單** 還是 **向量** '
                                                                           '取決於腳本的特定需求。以下是一些準則：\n'
                                                                           '\n'
                                                                           '|特色|列表 |向量|\n'
                                                                           '|------------------------------------|----------------------------------------|--------------------------------|\n'
                                                                           '| **尺寸彈性** |動態 |固定|\n'
                                                                           '| **存取速度** '
                                                                           '|較慢（順序存取）|更快（索引存取）|\n'
                                                                           '| **易於修改**|更容易 '
                                                                           '|更難（需要重新分配）|\n'
                                                                           '| **使用案例** '
                                                                           '|動態數據，遞歸|靜態數據，快速查找|\n'
                                                                           '\n'
                                                                           '---'},
 'content/hub/scripting/fundamentals/Data Structures/alists.md': {'de': '---\n'
                                                                        'title: '
                                                                        '"Assoziationslisten '
                                                                        '(Alists)"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        'Eine '
                                                                        '**Assoziationsliste** '
                                                                        '(oder **Alist**) ist eine '
                                                                        'grundlegende '
                                                                        'Datenstruktur in Scheme, '
                                                                        'die zur Darstellung von '
                                                                        'Sammlungen von '
                                                                        'Schlüssel-Wert-Paaren '
                                                                        'verwendet wird. Es wird '
                                                                        'als Liste von Paaren '
                                                                        'implementiert, wobei '
                                                                        'jedes Paar einen '
                                                                        'Schlüssel (normalerweise '
                                                                        'ein Symbol) einem Wert '
                                                                        'zuordnet. Alisten sind '
                                                                        'einfach, flexibel und '
                                                                        'eignen sich gut für '
                                                                        'kleine bis mittelgroße '
                                                                        'Datensätze.\n'
                                                                        '\n'
                                                                        '### Aufbau einer '
                                                                        'Assoziationsliste\n'
                                                                        '\n'
                                                                        'Eine Liste ist eine '
                                                                        'Liste, in der jedes '
                                                                        'Element ein **Paar** ist '
                                                                        '(konstruiert mit `cons`). '
                                                                        'Jedes Paar besteht aus:\n'
                                                                        '\n'
                                                                        '- **Schlüssel**: Das '
                                                                        'erste Element '
                                                                        '(normalerweise ein '
                                                                        'Symbol).\n'
                                                                        '- **Wert**: Das zweite '
                                                                        'Element, das einen '
                                                                        'beliebigen Datentyp haben '
                                                                        'kann.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        "- **Schlüssel**: `'name`, "
                                                                        "`'age`, `'city`\n"
                                                                        '- **Wert**: `"Alice"`, '
                                                                        '`30`, `"Paris"`\n'
                                                                        '- **Struktur**: Eine '
                                                                        'Liste von Paaren:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Erstellen einer '
                                                                        'Alist\n'
                                                                        '\n'
                                                                        'Sie können eine Liste '
                                                                        'erstellen, indem Sie '
                                                                        'manuell Paare erstellen '
                                                                        'oder sie '
                                                                        'programmgesteuert mit '
                                                                        '`cons` erstellen.\n'
                                                                        '\n'
                                                                        '#### Verwendung des '
                                                                        'einfachen '
                                                                        "Anführungszeichens (`'`)\n"
                                                                        '\n'
                                                                        'Das einfache '
                                                                        "Anführungszeichen (`'`) "
                                                                        'ist eine Abkürzung für '
                                                                        '**quoting**, was Scheme '
                                                                        'daran hindert, den '
                                                                        'Ausdruck auszuwerten. '
                                                                        'Dies macht es ideal für '
                                                                        'die Erstellung statischer '
                                                                        'Listen, bei denen alle '
                                                                        'Schlüssel und Werte fest '
                                                                        'codiert sind.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Alist manuell '
                                                                        'definieren\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Programmatisch ein '
                                                                        'neues Paar hinzufügen\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Ergebnis**:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### Verwendung des '
                                                                        'Backquotes („` ` ``) and '
                                                                        'Comma (`,`)\n'
                                                                        '\n'
                                                                        'Der Backquote-Operator '
                                                                        '(„` ` ``) is similar to '
                                                                        'the single quote but '
                                                                        'allows you to dynamically '
                                                                        'insert evaluated '
                                                                        'expressions using the '
                                                                        'comma (`,“). Dies ist '
                                                                        'nützlich zum Erstellen '
                                                                        'von Listen, bei denen '
                                                                        'Schlüssel oder Werte zur '
                                                                        'Laufzeit berechnet '
                                                                        'werden.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Ergebnis**:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Beispielvergleich\n'
                                                                        '\n'
                                                                        "Statische Liste mit `'`:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        'Dynamische Liste mit `` ` '
                                                                        '`` and `,`:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Zugriff auf Daten in '
                                                                        'einer Alist\n'
                                                                        '\n'
                                                                        'Um einen Wert aus einer '
                                                                        'Liste abzurufen, können '
                                                                        'Sie die Funktion `assoc` '
                                                                        'verwenden, die ein Paar '
                                                                        'anhand seines Schlüssels '
                                                                        'sucht.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Returns (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Returns #f (key not '
                                                                        'found)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Den Wert extrahieren\n'
                                                                        '\n'
                                                                        'Sobald Sie ein Paar mit '
                                                                        '`assoc` abgerufen haben, '
                                                                        'verwenden Sie `cdr`, um '
                                                                        'den Wert zu extrahieren:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Returns '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Zusammenfassung der '
                                                                        'wichtigsten Funktionen\n'
                                                                        '\n'
                                                                        '- **Einfaches '
                                                                        'Anführungszeichen '
                                                                        "(`'`)**: Erstellt eine "
                                                                        'statische Liste, in der '
                                                                        'alle Elemente '
                                                                        'Literaldaten sind.\n'
                                                                        '- **Backquote (`` ` '
                                                                        '``)**: Allows dynamic '
                                                                        'creation of alists by '
                                                                        'mixing static elements '
                                                                        'with evaluated '
                                                                        'expressions (using `,`).\n'
                                                                        '- **Punktnotation '
                                                                        '(`.`)**: Wird zum '
                                                                        'Erstellen von Paaren '
                                                                        'verwendet, um einen '
                                                                        'Schlüssel einem Wert in '
                                                                        'einer Liste zuzuordnen.',
                                                                  'es': '---\n'
                                                                        'title: "Listas de '
                                                                        'asociación (Alists)"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        'Una **lista de '
                                                                        'asociaciones** (o '
                                                                        '**alista**) es una '
                                                                        'estructura de datos '
                                                                        'fundamental en Scheme que '
                                                                        'se utiliza para '
                                                                        'representar colecciones '
                                                                        'de pares clave-valor. Se '
                                                                        'implementa como una lista '
                                                                        'de pares, donde cada par '
                                                                        'asocia una clave '
                                                                        '(normalmente un símbolo) '
                                                                        'con un valor. Las listas '
                                                                        'Al son simples, flexibles '
                                                                        'y adecuadas para '
                                                                        'conjuntos de datos '
                                                                        'pequeños y medianos.\n'
                                                                        '\n'
                                                                        '### Estructura de una '
                                                                        'lista de asociaciones\n'
                                                                        '\n'
                                                                        'Una lista alista es una '
                                                                        'lista donde cada elemento '
                                                                        'es un **par** (construido '
                                                                        'con `cons`). Cada par '
                                                                        'consta de:\n'
                                                                        '\n'
                                                                        '- **Clave**: el primer '
                                                                        'elemento (normalmente un '
                                                                        'símbolo).\n'
                                                                        '- **Valor**: El segundo '
                                                                        'elemento, que puede ser '
                                                                        'de cualquier tipo de '
                                                                        'datos.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        "- **Clave**: `'name`, "
                                                                        "`'age`, `'city`\n"
                                                                        '- **Valor**: `"Alice"`, '
                                                                        '`30`, `"Paris"`\n'
                                                                        '- **Estructura**: Una '
                                                                        'lista de pares:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Creando una lista Al\n'
                                                                        '\n'
                                                                        'Puede crear una lista al '
                                                                        'construir pares '
                                                                        'manualmente o mediante '
                                                                        'programación usando '
                                                                        '`cons`.\n'
                                                                        '\n'
                                                                        '#### Usando la comilla '
                                                                        "simple (`'`)\n"
                                                                        '\n'
                                                                        "La comilla simple (`'`) "
                                                                        'es una abreviatura de '
                                                                        '**comillas**, lo que '
                                                                        'impide que Scheme evalúe '
                                                                        'la expresión. Esto lo '
                                                                        'hace ideal para crear '
                                                                        'listas estáticas donde '
                                                                        'todas las claves y '
                                                                        'valores están '
                                                                        'codificados.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Alist manuell '
                                                                        'definieren\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Programmatisch ein '
                                                                        'neues Paar hinzufügen\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Resultado**:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### Usando las comillas '
                                                                        'inversas (`` ` ``) and '
                                                                        'Comma (`,`)\n'
                                                                        '\n'
                                                                        'El operador de comillas '
                                                                        'invertidas (`` ` ``) is '
                                                                        'similar to the single '
                                                                        'quote but allows you to '
                                                                        'dynamically insert '
                                                                        'evaluated expressions '
                                                                        'using the comma (`,`). '
                                                                        'Esto es útil para crear '
                                                                        'listas donde las claves o '
                                                                        'valores se calculan en '
                                                                        'tiempo de ejecución.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Resultado**:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Ejemplo de '
                                                                        'comparación\n'
                                                                        '\n'
                                                                        'Lista estática usando '
                                                                        "`'`:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        'Lista dinámica usando `` '
                                                                        '` `` and `,`:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Accediendo a datos en '
                                                                        'una lista Al\n'
                                                                        '\n'
                                                                        'Para recuperar un valor '
                                                                        'de una lista, puede usar '
                                                                        'la función `assoc`, que '
                                                                        'busca un par por su '
                                                                        'clave.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Returns (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Returns #f (key not '
                                                                        'found)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Extrayendo el valor\n'
                                                                        '\n'
                                                                        'Una vez que recupere un '
                                                                        'par usando `assoc`, use '
                                                                        '`cdr` para extraer el '
                                                                        'valor:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Returns '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Resumen de '
                                                                        'características clave\n'
                                                                        '\n'
                                                                        '- **Comilla única '
                                                                        "(`'`)**: crea una lista "
                                                                        'estática donde todos los '
                                                                        'elementos son datos '
                                                                        'literales.\n'
                                                                        '- **Cotización inversa '
                                                                        '(`` ` ``)**: Allows '
                                                                        'dynamic creation of '
                                                                        'alists by mixing static '
                                                                        'elements with evaluated '
                                                                        'expressions (using `,`).\n'
                                                                        '- **Notación de puntos '
                                                                        '(`.`)**: Se utiliza para '
                                                                        'construir pares, '
                                                                        'asociando una clave con '
                                                                        'un valor en una lista '
                                                                        'alista.',
                                                                  'fr': '---\n'
                                                                        'title: "Listes '
                                                                        "d'associations "
                                                                        '(Alists)"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        'Une **liste '
                                                                        "d'associations** (ou "
                                                                        '**alist**) est une '
                                                                        'structure de données '
                                                                        'fondamentale en Scheme '
                                                                        'pour représenter des '
                                                                        'collections de paires '
                                                                        'clé-valeur. Elle est '
                                                                        'implémentée sous la forme '
                                                                        "d'une liste de paires, où "
                                                                        'chaque paire associe une '
                                                                        'clé (généralement un '
                                                                        'symbole) à une valeur. '
                                                                        'Les alists sont simples, '
                                                                        'flexibles et bien '
                                                                        'adaptées aux ensembles de '
                                                                        'données de petite et '
                                                                        'moyenne taille.\n'
                                                                        '\n'
                                                                        "### Structure d'une liste "
                                                                        "d'associations\n"
                                                                        '\n'
                                                                        'Une alist est une liste '
                                                                        'dont chaque élément est '
                                                                        'une **paire** (construite '
                                                                        'avec `cons`). Chaque '
                                                                        'paire est composée de\xa0'
                                                                        ':\n'
                                                                        '\n'
                                                                        '- **Clé**\xa0: Le premier '
                                                                        'élément (généralement un '
                                                                        'symbole).\n'
                                                                        '- **Valeur**\xa0: Le '
                                                                        'deuxième élément, qui '
                                                                        "peut être de n'importe "
                                                                        'quel type de données.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        "- **Clé**\xa0: `'name`, "
                                                                        "`'age`, `'city`\n"
                                                                        '- **Valeur**\xa0: '
                                                                        '`"Alice"`, `30`, '
                                                                        '`"Paris"`\n'
                                                                        '- **Structure**\xa0: Une '
                                                                        'liste de paires\xa0:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Créer une alist\n'
                                                                        '\n'
                                                                        'Vous pouvez créer une '
                                                                        'alist en construisant '
                                                                        'manuellement des paires '
                                                                        'ou en la construisant par '
                                                                        "programme à l'aide de "
                                                                        '`cons`.\n'
                                                                        '\n'
                                                                        '#### Utilisation du '
                                                                        "guillemet unique (`'`)\n"
                                                                        '\n'
                                                                        "Le guillemet simple (`'`) "
                                                                        'est un raccourci pour '
                                                                        '**quoting**, ce qui '
                                                                        "empêche Scheme d'évaluer "
                                                                        "l'expression. Cela "
                                                                        'convient parfaitement '
                                                                        'pour créer des alists '
                                                                        'statiques où toutes les '
                                                                        'clés et valeurs sont '
                                                                        'codées en dur.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Définir une alist '
                                                                        'manuellement\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Ajouter '
                                                                        'programmatiquement une '
                                                                        'nouvelle paire\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Résultat**\xa0:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### Utilisation du '
                                                                        'backquote (`` ` ``) et de '
                                                                        'la virgule (`,`)\n'
                                                                        '\n'
                                                                        'Le backquote (`` ` ``) '
                                                                        'ressemble au guillemet '
                                                                        'simple, mais permet '
                                                                        "d'insérer dynamiquement "
                                                                        'des expressions évaluées '
                                                                        "avec l'opérateur virgule "
                                                                        "(`,`). C'est utile pour "
                                                                        'créer des alists dans '
                                                                        'lesquelles les clés ou '
                                                                        'les valeurs sont '
                                                                        'calculées au moment de '
                                                                        "l'exécution.\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Résultat**\xa0:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Exemple de '
                                                                        'comparaison\n'
                                                                        '\n'
                                                                        'Alist statique avec '
                                                                        "`'`\xa0:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        'Alist dynamique avec `` ` '
                                                                        '`` et `,`\xa0:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Accéder aux données '
                                                                        "d'une alist\n"
                                                                        '\n'
                                                                        'Pour récupérer une valeur '
                                                                        "d'une alist, vous pouvez "
                                                                        'utiliser la fonction '
                                                                        '`assoc`, qui recherche '
                                                                        'une paire par sa clé.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Renvoie (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Renvoie #f (clé '
                                                                        'introuvable)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Extraction de la '
                                                                        'valeur\n'
                                                                        '\n'
                                                                        'Une fois que vous avez '
                                                                        'récupéré une paire à '
                                                                        "l'aide de `assoc`, "
                                                                        'utilisez `cdr` pour '
                                                                        'extraire la valeur\xa0:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Renvoie '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Résumé des '
                                                                        'principales '
                                                                        'fonctionnalités\n'
                                                                        '\n'
                                                                        '- **Single Quote '
                                                                        "(`'`)**\xa0: crée une "
                                                                        'liste statique où tous '
                                                                        'les éléments sont des '
                                                                        'données littérales.\n'
                                                                        '- **Backquote (`` ` ``)** '
                                                                        ': permet de créer des '
                                                                        'alists dynamiques en '
                                                                        'mélangeant éléments '
                                                                        'statiques et expressions '
                                                                        'évaluées (avec `,`).\n'
                                                                        '- **Notation point '
                                                                        '(`.`)** : sert à '
                                                                        'construire des paires, en '
                                                                        'associant une clé à une '
                                                                        'valeur dans une alist.',
                                                                  'it': '---\n'
                                                                        'title: "Liste di '
                                                                        'associazione (Alists)"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        'Una **lista di '
                                                                        'associazioni** (o '
                                                                        '**alist**) è una '
                                                                        'struttura dati '
                                                                        'fondamentale in Scheme '
                                                                        'utilizzata per '
                                                                        'rappresentare raccolte di '
                                                                        'coppie chiave-valore. È '
                                                                        'implementato come un '
                                                                        'elenco di coppie, in cui '
                                                                        'ciascuna coppia associa '
                                                                        'una chiave (tipicamente '
                                                                        'un simbolo) a un valore. '
                                                                        'Gli elenchi sono '
                                                                        'semplici, flessibili e '
                                                                        'adatti a set di dati di '
                                                                        'piccole e medie '
                                                                        'dimensioni.\n'
                                                                        '\n'
                                                                        '### Struttura di una '
                                                                        'lista di associazioni\n'
                                                                        '\n'
                                                                        'Una alist è una lista in '
                                                                        'cui ogni elemento è una '
                                                                        '**coppia** (costruita con '
                                                                        '`cons`). Ogni coppia è '
                                                                        'composta da:\n'
                                                                        '\n'
                                                                        '- **Chiave**: il primo '
                                                                        'elemento (tipicamente un '
                                                                        'simbolo).\n'
                                                                        '- **Valore**: il secondo '
                                                                        'elemento, che può essere '
                                                                        'di qualsiasi tipo di '
                                                                        'dati.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        "- **Chiave**: `'name`, "
                                                                        "`'age`, `'city`\n"
                                                                        '- **Valore**: `"Alice"`, '
                                                                        '`30`, `"Paris"`\n'
                                                                        '- **Struttura**: un '
                                                                        'elenco di coppie:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Creazione di un '
                                                                        'elenco\n'
                                                                        '\n'
                                                                        'È possibile creare un '
                                                                        'elenco costruendo '
                                                                        'manualmente coppie o '
                                                                        'costruendolo a livello di '
                                                                        'codice utilizzando '
                                                                        '`cons`.\n'
                                                                        '\n'
                                                                        '#### Utilizzo della '
                                                                        "virgoletta singola (`'`)\n"
                                                                        '\n'
                                                                        'La virgoletta singola '
                                                                        "(`'`) è una scorciatoia "
                                                                        'per **quoting**, che '
                                                                        'impedisce a Scheme di '
                                                                        "valutare l'espressione. "
                                                                        'Ciò lo rende ideale per '
                                                                        'creare elenchi statici in '
                                                                        'cui tutte le chiavi e i '
                                                                        'valori sono codificati.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Alist manuell '
                                                                        'definieren\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Programmatisch ein '
                                                                        'neues Paar hinzufügen\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Risultato**:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### Utilizzo delle '
                                                                        'virgolette inverse (`` ` '
                                                                        '``) and Comma (`,`)\n'
                                                                        '\n'
                                                                        "L'operatore virgolette "
                                                                        'inverse (`` ` ``) is '
                                                                        'similar to the single '
                                                                        'quote but allows you to '
                                                                        'dynamically insert '
                                                                        'evaluated expressions '
                                                                        'using the comma (`,`). '
                                                                        'Ciò è utile per creare '
                                                                        'elenchi in cui chiavi o '
                                                                        'valori vengono calcolati '
                                                                        'in fase di esecuzione.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Risultato**:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Esempio di confronto\n'
                                                                        '\n'
                                                                        'Elenco statico '
                                                                        "utilizzando `'`:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        'Elenco dinamico '
                                                                        'utilizzando `` ` `` and '
                                                                        '`,`:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Accesso ai dati in un '
                                                                        'elenco\n'
                                                                        '\n'
                                                                        'Per recuperare un valore '
                                                                        'da un elenco, è possibile '
                                                                        'utilizzare la funzione '
                                                                        '`assoc`, che cerca una '
                                                                        'coppia in base alla sua '
                                                                        'chiave.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Returns (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Returns #f (key not '
                                                                        'found)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Estrazione del '
                                                                        'valore\n'
                                                                        '\n'
                                                                        'Una volta recuperata una '
                                                                        'coppia utilizzando '
                                                                        '`assoc`, utilizzare `cdr` '
                                                                        'per estrarre il valore:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Returns '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Riepilogo delle '
                                                                        'caratteristiche '
                                                                        'principali\n'
                                                                        '\n'
                                                                        '- **Citazione singola '
                                                                        "(`'`)**: crea un elenco "
                                                                        'statico in cui tutti gli '
                                                                        'elementi sono dati '
                                                                        'letterali.\n'
                                                                        '- **Citazione inversa (`` '
                                                                        '` ``)**: Allows dynamic '
                                                                        'creation of alists by '
                                                                        'mixing static elements '
                                                                        'with evaluated '
                                                                        'expressions (using `,`).\n'
                                                                        '- **Notazione punto '
                                                                        '(`.`)**: Utilizzato per '
                                                                        'costruire coppie, '
                                                                        'associando una chiave a '
                                                                        'un valore in un elenco.',
                                                                  'ja': '---\n'
                                                                        'title: "連想リスト（Alists）"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        '**アソシエーション リスト** (または '
                                                                        '**アリスト**) '
                                                                        'は、キーと値のペアのコレクションを表すために使用される '
                                                                        'Scheme '
                                                                        'の基本的なデータ構造です。これはペアのリストとして実装され、各ペアがキー '
                                                                        '(通常はシンボル) '
                                                                        'と値を関連付けます。リストはシンプルかつ柔軟で、小規模から中規模のデータセットに適しています。\n'
                                                                        '\n'
                                                                        '### 関連リストの構造\n'
                                                                        '\n'
                                                                        'alist は、各要素が **ペア** '
                                                                        '(`cons` で構築される) '
                                                                        'であるリストです。各ペアは次のもので構成されます。\n'
                                                                        '\n'
                                                                        '- **キー**: 最初の要素 '
                                                                        '(通常はシンボル)。\n'
                                                                        '- **値**: 2 '
                                                                        '番目の要素。任意のデータ型を使用できます。\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '- **キー**: '
                                                                        "`'name`、`'age`、`'city`\n"
                                                                        '- **値**: '
                                                                        '`"Alice"`、`30`、`"Paris"`\n'
                                                                        '- **構造**: ペアのリスト:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### エイリストの作成\n'
                                                                        '\n'
                                                                        '手動でペアを構築するか、`cons` '
                                                                        'を使用してプログラムでペアを構築することで、アリスリストを作成できます。\n'
                                                                        '\n'
                                                                        "#### 一重引用符の使用 (`'`)\n"
                                                                        '\n'
                                                                        "一重引用符 (`'`) は **引用** "
                                                                        'の短縮形であり、Scheme '
                                                                        'による式の評価を防ぎます。これは、すべてのキーと値がハードコーディングされた静的リストの作成に最適です。\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Alist manuell '
                                                                        'definieren\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Programmatisch ein '
                                                                        'neues Paar hinzufügen\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**結果**:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### 逆引用符の使用 (`` ` ``) '
                                                                        'and Comma (`,`)\n'
                                                                        '\n'
                                                                        '逆引用符 (`` ` ``) is similar '
                                                                        'to the single quote but '
                                                                        'allows you to dynamically '
                                                                        'insert evaluated '
                                                                        'expressions using the '
                                                                        'comma (`,`) '
                                                                        '演算子。これは、キーまたは値が実行時に計算されるリストを作成する場合に便利です。\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**結果**:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### 比較例\n'
                                                                        '\n'
                                                                        "`'` を使用した静的 alist:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '`` ` `` and `,` を使用した動的 '
                                                                        'alist:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Alist 内のデータへのアクセス\n'
                                                                        '\n'
                                                                        'アリリストから値を取得するには、キーでペアを検索する '
                                                                        '`assoc` 関数を使用できます。\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Returns (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Returns #f (key not '
                                                                        'found)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### 値の抽出\n'
                                                                        '\n'
                                                                        '`assoc` '
                                                                        'を使用してペアを取得したら、`cdr` '
                                                                        'を使用して値を抽出します。\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Returns '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### 主な機能の概要\n'
                                                                        '\n'
                                                                        "- **一重引用符 (`'`)**: "
                                                                        'すべての要素がリテラル データである静的 '
                                                                        'alist を作成します。\n'
                                                                        '- **バッククォート (`` ` ``)**: '
                                                                        'Allows dynamic creation '
                                                                        'of alists by mixing '
                                                                        'static elements with '
                                                                        'evaluated expressions '
                                                                        '(using `,`)。\n'
                                                                        '- **ドット表記 (`.`)**: '
                                                                        'ペアを構築し、キーを alist '
                                                                        '内の値に関連付けるために使用されます。',
                                                                  'ko': '---\n'
                                                                        'title: "연관 리스트(Alists)"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        '**연관 목록**(또는 **alist**)은 '
                                                                        '키-값 쌍 모음을 나타내는 데 사용되는 '
                                                                        'Scheme의 기본 데이터 구조입니다. 이는 '
                                                                        '쌍 목록으로 구현되며, 각 쌍은 키(일반적으로 '
                                                                        '기호)를 값과 연결합니다. Alist는 '
                                                                        '간단하고 유연하며 중소 규모 데이터세트에 '
                                                                        '적합합니다.\n'
                                                                        '\n'
                                                                        '### 연관 목록의 구조\n'
                                                                        '\n'
                                                                        'alist는 각 요소가 '
                                                                        '**쌍**(`cons`으로 구성됨)인 '
                                                                        '목록입니다. 각 쌍은 다음으로 구성됩니다.\n'
                                                                        '\n'
                                                                        '- **키**: 첫 번째 요소(일반적으로 '
                                                                        '기호)입니다.\n'
                                                                        '- **값**: 모든 데이터 유형이 될 수 '
                                                                        '있는 두 번째 요소입니다.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        "- **키**: `'name`, `'age`, "
                                                                        "`'city`\n"
                                                                        '- **값**: `"Alice"`, `30`, '
                                                                        '`"Paris"`\n'
                                                                        '- **구조**: 쌍 목록:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Alist 만들기\n'
                                                                        '\n'
                                                                        '수동으로 쌍을 구성하거나 `cons`을 '
                                                                        '사용하여 프로그래밍 방식으로 빌드하여 목록을 '
                                                                        '생성할 수 있습니다.\n'
                                                                        '\n'
                                                                        "#### 작은따옴표 사용(`'`)\n"
                                                                        '\n'
                                                                        "작은따옴표(`'`)는 **인용**을 줄여서 "
                                                                        'Scheme이 표현식을 평가하지 못하도록 '
                                                                        '합니다. 이는 모든 키와 값이 하드코딩된 정적 '
                                                                        '목록을 생성하는 데 이상적입니다.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Alist manuell '
                                                                        'definieren\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Programmatisch ein '
                                                                        'neues Paar hinzufügen\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**결과**:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### 역따옴표 사용(`` ```) and '
                                                                        'Comma (`,`)\n'
                                                                        '\n'
                                                                        '역따옴표(`` ` ``) is similar '
                                                                        'to the single quote but '
                                                                        'allows you to dynamically '
                                                                        'insert evaluated '
                                                                        'expressions using the '
                                                                        'comma (`,`) 연산자입니다. 이는 '
                                                                        '런타임에 키나 값이 계산되는 목록을 만드는 데 '
                                                                        '유용합니다.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**결과**:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### 예시 비교\n'
                                                                        '\n'
                                                                        "`'`을 사용하는 정적 목록:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '`` ``` and ``을 사용하는 동적 '
                                                                        '목록:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Alist의 데이터에 액세스\n'
                                                                        '\n'
                                                                        'alist에서 값을 검색하려면 해당 키로 쌍을 '
                                                                        '찾는 `assoc` 함수를 사용할 수 '
                                                                        '있습니다.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Returns (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Returns #f (key not '
                                                                        'found)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### 값 추출\n'
                                                                        '\n'
                                                                        '`assoc`을 사용하여 쌍을 검색한 후 '
                                                                        '`cdr`을 사용하여 값을 추출합니다.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Returns '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### 주요 기능 요약\n'
                                                                        '\n'
                                                                        "- **작은 따옴표(`'`)**: 모든 요소가 "
                                                                        '리터럴 데이터인 정적 alist를 '
                                                                        '생성합니다.\n'
                                                                        '- **역따옴표(`` ```)**: '
                                                                        'Allows dynamic creation '
                                                                        'of alists by mixing '
                                                                        'static elements with '
                                                                        'evaluated expressions '
                                                                        '(using `,`).\n'
                                                                        '- **점 표기법(`.`)**: 목록의 값과 '
                                                                        '키를 연결하여 쌍을 구성하는 데 사용됩니다.',
                                                                  'nl': '---\n'
                                                                        'title: "Associatielijsten '
                                                                        '(Alists)"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        'Een **associatielijst** '
                                                                        '(of **alist**) is een '
                                                                        'fundamentele '
                                                                        'gegevensstructuur in '
                                                                        'Scheme die wordt gebruikt '
                                                                        'om verzamelingen '
                                                                        'sleutel-waardeparen weer '
                                                                        'te geven. Het wordt '
                                                                        'geïmplementeerd als een '
                                                                        'lijst met paren, waarbij '
                                                                        'elk paar een sleutel '
                                                                        '(meestal een symbool) '
                                                                        'associeert met een '
                                                                        'waarde. Alists zijn '
                                                                        'eenvoudig, flexibel en '
                                                                        'zeer geschikt voor kleine '
                                                                        'tot middelgrote '
                                                                        'datasets.\n'
                                                                        '\n'
                                                                        '### Structuur van een '
                                                                        'associatielijst\n'
                                                                        '\n'
                                                                        'Een alist is een lijst '
                                                                        'waarbij elk element een '
                                                                        '**paar** is (opgebouwd '
                                                                        'met `cons`). Elk paar '
                                                                        'bestaat uit:\n'
                                                                        '\n'
                                                                        '- **Sleutel**: het eerste '
                                                                        'element (meestal een '
                                                                        'symbool).\n'
                                                                        '- **Waarde**: het tweede '
                                                                        'element, dat van elk '
                                                                        'gegevenstype kan zijn.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        "- **Sleutel**: `'name`, "
                                                                        "`'age`, `'city`\n"
                                                                        '- **Waarde**: `"Alice"`, '
                                                                        '`30`, `"Paris"`\n'
                                                                        '- **Structuur**: een '
                                                                        'lijst met paren:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Een lijst maken\n'
                                                                        '\n'
                                                                        'U kunt een alist maken '
                                                                        'door handmatig paren te '
                                                                        'construeren of deze '
                                                                        'programmatisch op te '
                                                                        'bouwen met `cons`.\n'
                                                                        '\n'
                                                                        '#### Gebruik van één '
                                                                        "enkel citaat (`'`)\n"
                                                                        '\n'
                                                                        'Het enkele '
                                                                        "aanhalingsteken (`'`) is "
                                                                        'een afkorting voor '
                                                                        '**quoting**, waardoor '
                                                                        'Scheme de expressie niet '
                                                                        'kan evalueren. Dit maakt '
                                                                        'het ideaal voor het maken '
                                                                        'van statische alisten '
                                                                        'waarbij alle sleutels en '
                                                                        'waarden hardgecodeerd '
                                                                        'zijn.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Alist manuell '
                                                                        'definieren\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Programmatisch ein '
                                                                        'neues Paar hinzufügen\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Resultaat**:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### Het aanhalingsteken '
                                                                        'gebruiken ("` ` ``) and '
                                                                        'Comma (`,`)\n'
                                                                        '\n'
                                                                        'De backquote-operator ("` '
                                                                        '` ``) is similar to the '
                                                                        'single quote but allows '
                                                                        'you to dynamically insert '
                                                                        'evaluated expressions '
                                                                        'using the comma (`,`). '
                                                                        'Dit is handig voor het '
                                                                        'maken van alists waarbij '
                                                                        'sleutels of waarden '
                                                                        'tijdens runtime worden '
                                                                        'berekend.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Resultaat**:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### '
                                                                        'Voorbeeldvergelijking\n'
                                                                        '\n'
                                                                        "Statische lijst met `'`:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        'Dynamische lijst met `` ` '
                                                                        '`` and `,`:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Toegang tot gegevens '
                                                                        'in een lijst\n'
                                                                        '\n'
                                                                        'Om een waarde uit een '
                                                                        'lijst op te halen, kunt u '
                                                                        'de functie `assoc` '
                                                                        'gebruiken, die een paar '
                                                                        'opzoekt aan de hand van '
                                                                        'de sleutel.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Returns (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Returns #f (key not '
                                                                        'found)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### De waarde extraheren\n'
                                                                        '\n'
                                                                        'Zodra u een paar heeft '
                                                                        'opgehaald met `assoc`, '
                                                                        'gebruikt u `cdr` om de '
                                                                        'waarde te extraheren:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Returns '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Samenvatting van de '
                                                                        'belangrijkste kenmerken\n'
                                                                        '\n'
                                                                        "- **Enkel citaat (`'`)**: "
                                                                        'Creëert een statische '
                                                                        'lijst waarin alle '
                                                                        'elementen letterlijke '
                                                                        'gegevens zijn.\n'
                                                                        '- **Backquote ("` ` '
                                                                        '``)**: Allows dynamic '
                                                                        'creation of alists by '
                                                                        'mixing static elements '
                                                                        'with evaluated '
                                                                        'expressions (using `,`).\n'
                                                                        '- **Puntnotatie (`.`)**: '
                                                                        'wordt gebruikt om paren '
                                                                        'te construeren, waarbij '
                                                                        'een sleutel wordt '
                                                                        'gekoppeld aan een waarde '
                                                                        'in een lijst.',
                                                                  'pl': '---\n'
                                                                        'title: "Listy asocjacyjne '
                                                                        '(Alists)"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        '**Lista powiązań** (lub '
                                                                        '**alista**) to podstawowa '
                                                                        'struktura danych w '
                                                                        'schemacie używana do '
                                                                        'reprezentowania kolekcji '
                                                                        'par klucz-wartość. Jest '
                                                                        'zaimplementowany jako '
                                                                        'lista par, gdzie każda '
                                                                        'para kojarzy klucz '
                                                                        '(zwykle symbol) z '
                                                                        'wartością. Alisty są '
                                                                        'proste, elastyczne i '
                                                                        'dobrze nadają się do '
                                                                        'małych i średnich zbiorów '
                                                                        'danych.\n'
                                                                        '\n'
                                                                        '### Struktura listy '
                                                                        'stowarzyszeń\n'
                                                                        '\n'
                                                                        'Alista to lista, na '
                                                                        'której każdy element jest '
                                                                        '**parą** (skonstruowaną '
                                                                        'za pomocą `cons`). Każda '
                                                                        'para składa się z:\n'
                                                                        '\n'
                                                                        '- **Klucz**: Pierwszy '
                                                                        'element (zazwyczaj '
                                                                        'symbol).\n'
                                                                        '- **Wartość**: Drugi '
                                                                        'element, który może mieć '
                                                                        'dowolny typ danych.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        "- **Klucz**: `'name`, "
                                                                        "`'age`, `'city`\n"
                                                                        '- **Wartość**: `"Alice"`, '
                                                                        '`30`, `"Paris"`\n'
                                                                        '- **Struktura**: Lista '
                                                                        'par:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Tworzenie listy\n'
                                                                        '\n'
                                                                        'Możesz utworzyć listę, '
                                                                        'ręcznie konstruując pary '
                                                                        'lub budując ją programowo '
                                                                        'za pomocą `cons`.\n'
                                                                        '\n'
                                                                        '#### Używanie '
                                                                        'pojedynczego cudzysłowu '
                                                                        "(`'`)\n"
                                                                        '\n'
                                                                        'Pojedynczy cudzysłów '
                                                                        "(`'`) jest skrótem od "
                                                                        '**cytowania**, co '
                                                                        'uniemożliwia Scheme ocenę '
                                                                        'wyrażenia. Dzięki temu '
                                                                        'idealnie nadaje się do '
                                                                        'tworzenia statycznych '
                                                                        'list, w których wszystkie '
                                                                        'klucze i wartości są '
                                                                        'zakodowane na stałe.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Alist manuell '
                                                                        'definieren\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Programmatisch ein '
                                                                        'neues Paar hinzufügen\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Wynik**:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### Korzystanie z '
                                                                        'cudzysłowu (`` ` ``) and '
                                                                        'Comma (`,`)\n'
                                                                        '\n'
                                                                        'Operator cudzysłowu (`` ` '
                                                                        '``) is similar to the '
                                                                        'single quote but allows '
                                                                        'you to dynamically insert '
                                                                        'evaluated expressions '
                                                                        'using the comma (`,`). '
                                                                        'Jest to przydatne do '
                                                                        'tworzenia list, w których '
                                                                        'klucze lub wartości są '
                                                                        'obliczane w czasie '
                                                                        'wykonywania.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Wynik**:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Przykładowe '
                                                                        'porównanie\n'
                                                                        '\n'
                                                                        'Statyczna lista używająca '
                                                                        "`'`:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        'Dynamiczny alist '
                                                                        'używający `` ` `` and '
                                                                        '`,`:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Dostęp do danych na '
                                                                        'liście\n'
                                                                        '\n'
                                                                        'Aby pobrać wartość z '
                                                                        'listy, możesz użyć '
                                                                        'funkcji `assoc`, która '
                                                                        'wyszukuje parę według jej '
                                                                        'klucza.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Returns (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Returns #f (key not '
                                                                        'found)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Wyodrębnianie '
                                                                        'wartości\n'
                                                                        '\n'
                                                                        'Po odzyskaniu pary za '
                                                                        'pomocą `assoc` użyj '
                                                                        '`cdr`, aby wyodrębnić '
                                                                        'wartość:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Returns '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Podsumowanie '
                                                                        'kluczowych funkcji\n'
                                                                        '\n'
                                                                        '- **Pojedynczy cudzysłów '
                                                                        "(`'`)**: Tworzy statyczną "
                                                                        'listę, w której wszystkie '
                                                                        'elementy są danymi '
                                                                        'dosłownymi.\n'
                                                                        '- **Cytat wsteczny (`` ` '
                                                                        '``)**: Allows dynamic '
                                                                        'creation of alists by '
                                                                        'mixing static elements '
                                                                        'with evaluated '
                                                                        'expressions (using `,`).\n'
                                                                        '- **Zapis kropkowy '
                                                                        '(`.`)**: Używany do '
                                                                        'konstruowania par, '
                                                                        'wiążących klucz z '
                                                                        'wartością na liście.',
                                                                  'pt-br': '---\n'
                                                                           'title: "Listas de '
                                                                           'associação (Alists)"\n'
                                                                           'type: docs\n'
                                                                           'weight: 6\n'
                                                                           '---\n'
                                                                           'Uma **lista de '
                                                                           'associações** (ou '
                                                                           '**alist**) é uma '
                                                                           'estrutura de dados '
                                                                           'fundamental no Scheme '
                                                                           'usada para representar '
                                                                           'coleções de pares '
                                                                           'chave-valor. É '
                                                                           'implementado como uma '
                                                                           'lista de pares, onde '
                                                                           'cada par associa uma '
                                                                           'chave (normalmente um '
                                                                           'símbolo) a um valor. '
                                                                           'As listas são simples, '
                                                                           'flexíveis e adequadas '
                                                                           'para conjuntos de '
                                                                           'dados de pequeno e '
                                                                           'médio porte.\n'
                                                                           '\n'
                                                                           '### Estrutura de uma '
                                                                           'lista de associações\n'
                                                                           '\n'
                                                                           'Uma lista é uma lista '
                                                                           'onde cada elemento é '
                                                                           'um **par** (construído '
                                                                           'com `cons`). Cada par '
                                                                           'consiste em:\n'
                                                                           '\n'
                                                                           '- **Chave**: O '
                                                                           'primeiro elemento '
                                                                           '(normalmente um '
                                                                           'símbolo).\n'
                                                                           '- **Valor**: O segundo '
                                                                           'elemento, que pode ser '
                                                                           'de qualquer tipo de '
                                                                           'dados.\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define alist '((name "
                                                                           '. "Alice") (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           "- **Chave**: `'name`, "
                                                                           "`'age`, `'city`\n"
                                                                           '- **Valor**: '
                                                                           '`"Alice"`, `30`, '
                                                                           '`"Paris"`\n'
                                                                           '- **Estrutura**: uma '
                                                                           'lista de pares:\n'
                                                                           '  `((name . "Alice") '
                                                                           '(age . 30) (city . '
                                                                           '"Paris"))`\n'
                                                                           '\n'
                                                                           '### Criando uma lista\n'
                                                                           '\n'
                                                                           'Você pode criar uma '
                                                                           'lista construindo '
                                                                           'pares manualmente ou '
                                                                           'programaticamente '
                                                                           'usando `cons`.\n'
                                                                           '\n'
                                                                           '#### Usando aspas '
                                                                           "simples (`'`)\n"
                                                                           '\n'
                                                                           "A aspa simples (`'`) é "
                                                                           'uma abreviação para '
                                                                           '**quoting**, o que '
                                                                           'impede que Scheme '
                                                                           'avalie a expressão. '
                                                                           'Isso o torna ideal '
                                                                           'para criar listas '
                                                                           'estáticas onde todas '
                                                                           'as chaves e valores '
                                                                           'são codificados.\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           ';; Alist manuell '
                                                                           'definieren\n'
                                                                           "(define alist '((name "
                                                                           '. "Alice") (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '\n'
                                                                           ';; Programmatisch ein '
                                                                           'neues Paar hinzufügen\n'
                                                                           '(define updated-alist '
                                                                           "(cons '(country . "
                                                                           '"France") alist))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '**Resultado**:\n'
                                                                           '`((country . "France") '
                                                                           '(name . "Alice") (age '
                                                                           '. 30) (city . '
                                                                           '"Paris"))`\n'
                                                                           '\n'
                                                                           '#### Usando as crases '
                                                                           '(`` ` ``) and Comma '
                                                                           '(`,`)\n'
                                                                           '\n'
                                                                           'O operador de crase '
                                                                           '(`` ` ``) is similar '
                                                                           'to the single quote '
                                                                           'but allows you to '
                                                                           'dynamically insert '
                                                                           'evaluated expressions '
                                                                           'using the comma (`,`). '
                                                                           'Isso é útil para criar '
                                                                           'listas onde chaves ou '
                                                                           'valores são calculados '
                                                                           'em tempo de execução.\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define key 'name)\n"
                                                                           '(define value '
                                                                           '"Alice")\n'
                                                                           '\n'
                                                                           '(define alist `((,key '
                                                                           '. ,value) (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '**Resultado**:\n'
                                                                           '`((name . "Alice") '
                                                                           '(age . 30) (city . '
                                                                           '"Paris"))`\n'
                                                                           '\n'
                                                                           '### Exemplo de '
                                                                           'comparação\n'
                                                                           '\n'
                                                                           'Lista estática usando '
                                                                           "`'`:\n"
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define alist '((name "
                                                                           '. "Alice") (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           'Lista dinâmica usando '
                                                                           '`` ` `` and `,`:\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define key 'name)\n"
                                                                           '(define value '
                                                                           '"Alice")\n'
                                                                           '(define alist `((,key '
                                                                           '. ,value) (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '### Acessando dados em '
                                                                           'uma lista\n'
                                                                           '\n'
                                                                           'Para recuperar um '
                                                                           'valor de uma lista, '
                                                                           'você pode usar a '
                                                                           'função `assoc`, que '
                                                                           'procura um par por sua '
                                                                           'chave.\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(assoc 'name alist)   "
                                                                           '; Returns (name . '
                                                                           '"Alice")\n'
                                                                           "(assoc 'country alist) "
                                                                           '; Returns #f (key not '
                                                                           'found)\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '### Extraindo o valor\n'
                                                                           '\n'
                                                                           'Depois de recuperar um '
                                                                           'par usando `assoc`, '
                                                                           'use `cdr` para extrair '
                                                                           'o valor:\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(cdr (assoc 'name "
                                                                           'alist))   ; Returns '
                                                                           '"Alice"\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '### Resumo dos '
                                                                           'principais recursos\n'
                                                                           '\n'
                                                                           '- **Aspas simples '
                                                                           "(`'`)**: Cria uma "
                                                                           'lista estática onde '
                                                                           'todos os elementos são '
                                                                           'dados literais.\n'
                                                                           '- **Backquote (`` ` '
                                                                           '``)**: Allows dynamic '
                                                                           'creation of alists by '
                                                                           'mixing static elements '
                                                                           'with evaluated '
                                                                           'expressions (using '
                                                                           '`,`).\n'
                                                                           '- **Notação de ponto '
                                                                           '(`.`)**: Usada para '
                                                                           'construir pares, '
                                                                           'associando uma chave a '
                                                                           'um valor em uma lista.',
                                                                  'ru': '---\n'
                                                                        'title: "Ассоциативные '
                                                                        'списки (Alists)"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        '**список ассоциаций** '
                                                                        '(или **список**)\xa0— это '
                                                                        'фундаментальная структура '
                                                                        'данных в Scheme, '
                                                                        'используемая для '
                                                                        'представления коллекций '
                                                                        'пар ключ-значение. Он '
                                                                        'реализован в виде списка '
                                                                        'пар, где каждая пара '
                                                                        'связывает ключ (обычно '
                                                                        'символ) со значением. '
                                                                        'Списки просты, гибки и '
                                                                        'хорошо подходят для '
                                                                        'наборов данных небольшого '
                                                                        'и среднего размера.\n'
                                                                        '\n'
                                                                        '### Структура списка '
                                                                        'ассоциаций\n'
                                                                        '\n'
                                                                        'Список — это список, в '
                                                                        'котором каждый элемент '
                                                                        'представляет собой '
                                                                        '**пару** (созданную с '
                                                                        'помощью `cons`). Каждая '
                                                                        'пара состоит из:\n'
                                                                        '\n'
                                                                        '- **Ключ**: первый '
                                                                        'элемент (обычно символ).\n'
                                                                        '- **Значение**: второй '
                                                                        'элемент, который может '
                                                                        'иметь любой тип данных.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        "- **Ключ**: `'name`, "
                                                                        "`'age`, `'city`\n"
                                                                        '- **Значение**: '
                                                                        '`"Alice"`, `30`, '
                                                                        '`"Paris"`\n'
                                                                        '- **Структура**: список '
                                                                        'пар:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Создание списка\n'
                                                                        '\n'
                                                                        'Вы можете создать список, '
                                                                        'создав пары вручную или '
                                                                        'программно, используя '
                                                                        '`cons`.\n'
                                                                        '\n'
                                                                        '#### Использование '
                                                                        "одинарной кавычки (`'`)\n"
                                                                        '\n'
                                                                        "Одинарная кавычка (`'`) "
                                                                        'является сокращением '
                                                                        '**цитирования**, что не '
                                                                        'позволяет Scheme оценить '
                                                                        'выражение. Это делает его '
                                                                        'идеальным для создания '
                                                                        'статических списков, в '
                                                                        'которых все ключи и '
                                                                        'значения жестко '
                                                                        'запрограммированы.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Alist manuell '
                                                                        'definieren\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Programmatisch ein '
                                                                        'neues Paar hinzufügen\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Результат**:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### Использование '
                                                                        'обратной кавычки (`` ` '
                                                                        '``) and Comma (`,`)\n'
                                                                        '\n'
                                                                        'Оператор обратной кавычки '
                                                                        '(`` ` ``) is similar to '
                                                                        'the single quote but '
                                                                        'allows you to dynamically '
                                                                        'insert evaluated '
                                                                        'expressions using the '
                                                                        'comma (`,`). Это полезно '
                                                                        'для создания списков, в '
                                                                        'которых ключи или '
                                                                        'значения вычисляются во '
                                                                        'время выполнения.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Результат**:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Пример сравнения\n'
                                                                        '\n'
                                                                        'Статический список с '
                                                                        "использованием `'`:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        'Динамический список с '
                                                                        'использованием `` ` `` '
                                                                        'and `,`:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Доступ к данным в '
                                                                        'списке\n'
                                                                        '\n'
                                                                        'Чтобы получить значение '
                                                                        'из списка, вы можете '
                                                                        'использовать функцию '
                                                                        '`assoc`, которая ищет '
                                                                        'пару по ее ключу.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Returns (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Returns #f (key not '
                                                                        'found)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Извлечение значения\n'
                                                                        '\n'
                                                                        'После того как вы '
                                                                        'получите пару с помощью '
                                                                        '`assoc`, используйте '
                                                                        '`cdr`, чтобы извлечь '
                                                                        'значение:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Returns '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Краткое описание '
                                                                        'основных функций\n'
                                                                        '\n'
                                                                        '- **Одиночная кавычка '
                                                                        "(`'`)**: создает "
                                                                        'статический список, в '
                                                                        'котором все элементы '
                                                                        'являются буквальными '
                                                                        'данными.\n'
                                                                        '- **Обратная кавычка (`` '
                                                                        '` ``)**: Allows dynamic '
                                                                        'creation of alists by '
                                                                        'mixing static elements '
                                                                        'with evaluated '
                                                                        'expressions (using `,`).\n'
                                                                        '- **Точечная нотация '
                                                                        '(`.`)**: используется для '
                                                                        'создания пар, связывающих '
                                                                        'ключ со значением в '
                                                                        'списке.',
                                                                  'sv': '---\n'
                                                                        'title: '
                                                                        '"Associationslistor '
                                                                        '(Alists)"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        'En **associationslista** '
                                                                        '(eller **alist**) är en '
                                                                        'grundläggande '
                                                                        'datastruktur i Schema som '
                                                                        'används för att '
                                                                        'representera samlingar av '
                                                                        'nyckel-värdepar. Det '
                                                                        'implementeras som en '
                                                                        'lista med par, där varje '
                                                                        'par associerar en nyckel '
                                                                        '(vanligtvis en symbol) '
                                                                        'med ett värde. Alister är '
                                                                        'enkla, flexibla och väl '
                                                                        'lämpade för små till '
                                                                        'medelstora datamängder.\n'
                                                                        '\n'
                                                                        '### Struktur för en '
                                                                        'föreningslista\n'
                                                                        '\n'
                                                                        'En alist är en lista där '
                                                                        'varje element är ett '
                                                                        '**par** (konstruerad med '
                                                                        '`cons`). Varje par består '
                                                                        'av:\n'
                                                                        '\n'
                                                                        '- **Key**: Det första '
                                                                        'elementet (vanligtvis en '
                                                                        'symbol).\n'
                                                                        '- **Värde**: Det andra '
                                                                        'elementet, som kan vara '
                                                                        'av vilken datatyp som '
                                                                        'helst.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        "- **Nyckel**: `'name`, "
                                                                        "`'age`, `'city`\n"
                                                                        '- **Värde**: `"Alice"`, '
                                                                        '`30`, `"Paris"`\n'
                                                                        '- **Struktur**: En lista '
                                                                        'med par:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Skapa en Alist\n'
                                                                        '\n'
                                                                        'Du kan skapa en lista '
                                                                        'genom att manuellt '
                                                                        'konstruera par eller '
                                                                        'genom att programmera '
                                                                        'bygga den med `cons`.\n'
                                                                        '\n'
                                                                        '#### Använda det enda '
                                                                        "citatet (`'`)\n"
                                                                        '\n'
                                                                        "Det enkla citatet (`'`) "
                                                                        'är en förkortning för '
                                                                        '**citat**, vilket hindrar '
                                                                        'Scheme från att utvärdera '
                                                                        'uttrycket. Detta gör den '
                                                                        'idealisk för att skapa '
                                                                        'statiska listor där alla '
                                                                        'nycklar och värden är '
                                                                        'hårdkodade.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Alist manuell '
                                                                        'definieren\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Programmatisch ein '
                                                                        'neues Paar hinzufügen\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Resultat**:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### Använda bakre citat '
                                                                        '(`` ` ``) and Comma '
                                                                        '(`,`)\n'
                                                                        '\n'
                                                                        'Operatorn för bakåtcitat '
                                                                        '(`` ` ``) is similar to '
                                                                        'the single quote but '
                                                                        'allows you to dynamically '
                                                                        'insert evaluated '
                                                                        'expressions using the '
                                                                        'comma (`,`). Detta är '
                                                                        'användbart för att skapa '
                                                                        'listor där nycklar eller '
                                                                        'värden beräknas under '
                                                                        'körning.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**Resultat**:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### Jämförelseexempel\n'
                                                                        '\n'
                                                                        "Statisk lista med `'`:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        'Dynamisk lista med `` ` '
                                                                        '`` and `,`:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Åtkomst till data i '
                                                                        'en lista\n'
                                                                        '\n'
                                                                        'För att hämta ett värde '
                                                                        'från en lista kan du '
                                                                        'använda '
                                                                        '`assoc`-funktionen, som '
                                                                        'slår upp ett par med sin '
                                                                        'nyckel.\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Returns (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Returns #f (key not '
                                                                        'found)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Extrahera värdet\n'
                                                                        '\n'
                                                                        'När du har hämtat ett par '
                                                                        'med `assoc`, använd `cdr` '
                                                                        'för att extrahera '
                                                                        'värdet:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Returns '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### Sammanfattning av '
                                                                        'nyckelfunktioner\n'
                                                                        '\n'
                                                                        '- **Enstaka citat '
                                                                        "(`'`)**: Skapar en "
                                                                        'statisk lista där alla '
                                                                        'element är bokstavliga '
                                                                        'data.\n'
                                                                        '- **Tillbakscitat (`` ` '
                                                                        '``)**: Allows dynamic '
                                                                        'creation of alists by '
                                                                        'mixing static elements '
                                                                        'with evaluated '
                                                                        'expressions (using `,`).\n'
                                                                        '- **Punktnotation '
                                                                        '(`.`)**: Används för att '
                                                                        'konstruera par, associera '
                                                                        'en nyckel med ett värde i '
                                                                        'en alist.',
                                                                  'th': '---\n'
                                                                        'title: "รายการเชื่อมโยง '
                                                                        '(Alists)"\n'
                                                                        'type: docs\n'
                                                                        'weight: 6\n'
                                                                        '---\n'
                                                                        '**รายการการเชื่อมโยง** '
                                                                        '(หรือ **รายการ**) '
                                                                        'เป็นโครงสร้างข้อมูลพื้นฐานในโครงการที่ใช้เพื่อแสดงคอลเลกชันของคู่คีย์-ค่า '
                                                                        'มันถูกนำไปใช้เป็นรายการคู่ '
                                                                        'โดยที่แต่ละคู่เชื่อมโยงคีย์ '
                                                                        '(โดยทั่วไปคือสัญลักษณ์) '
                                                                        'กับค่า '
                                                                        'รายการมีความเรียบง่าย '
                                                                        'ยืดหยุ่น '
                                                                        'และเหมาะสำหรับชุดข้อมูลขนาดเล็กถึงขนาดกลาง\n'
                                                                        '\n'
                                                                        '### '
                                                                        'โครงสร้างรายชื่อสมาคม\n'
                                                                        '\n'
                                                                        'อลิสต์คือรายการที่แต่ละองค์ประกอบเป็น '
                                                                        '**คู่** (สร้างด้วย '
                                                                        '`cons`) '
                                                                        'แต่ละคู่ประกอบด้วย:\n'
                                                                        '\n'
                                                                        '- **คีย์**: องค์ประกอบแรก '
                                                                        '(โดยทั่วไปจะเป็นสัญลักษณ์)\n'
                                                                        '- **ค่า**: องค์ประกอบที่ '
                                                                        '2 '
                                                                        'ซึ่งอาจเป็นข้อมูลประเภทใดก็ได้\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        "- **คีย์**: `'name`, "
                                                                        "`'age`, `'city`\n"
                                                                        '- **มูลค่า**: `"Alice"`, '
                                                                        '`30`, `"Paris"`\n'
                                                                        '- **โครงสร้าง**: '
                                                                        'รายการคู่:\n'
                                                                        '  `((name . "Alice") (age '
                                                                        '. 30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### การสร้าง Alist\n'
                                                                        '\n'
                                                                        'คุณสามารถสร้างรายการได้โดยการสร้างคู่ด้วยตนเองหรือสร้างโดยทางโปรแกรมโดยใช้ '
                                                                        '`cons`\n'
                                                                        '\n'
                                                                        '#### การใช้คำพูดเดี่ยว '
                                                                        "(`'`)\n"
                                                                        '\n'
                                                                        'เครื่องหมายคำพูดเดี่ยว '
                                                                        "(`'`) เป็นการย่อสำหรับ "
                                                                        '**quoting** ซึ่งทำให้ '
                                                                        'Scheme '
                                                                        'ไม่สามารถประเมินนิพจน์ได้ '
                                                                        'ทำให้เหมาะอย่างยิ่งสำหรับการสร้างรายการคงที่โดยที่คีย์และค่าทั้งหมดเป็นแบบฮาร์ดโค้ด\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        ';; Alist manuell '
                                                                        'definieren\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '\n'
                                                                        ';; Programmatisch ein '
                                                                        'neues Paar hinzufügen\n'
                                                                        '(define updated-alist '
                                                                        "(cons '(country . "
                                                                        '"France") alist))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**ผลลัพธ์**:\n'
                                                                        '`((country . "France") '
                                                                        '(name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '#### การใช้ Backquote (`` '
                                                                        '` ``) and Comma (`,`)\n'
                                                                        '\n'
                                                                        'ตัวดำเนินการ backquote '
                                                                        '(`` ` ``) is similar to '
                                                                        'the single quote but '
                                                                        'allows you to dynamically '
                                                                        'insert evaluated '
                                                                        'expressions using the '
                                                                        'comma (`,`) '
                                                                        'สิ่งนี้มีประโยชน์สำหรับการสร้างรายการที่มีการคำนวณคีย์หรือค่าขณะรันไทม์\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '**ผลลัพธ์**:\n'
                                                                        '`((name . "Alice") (age . '
                                                                        '30) (city . "Paris"))`\n'
                                                                        '\n'
                                                                        '### '
                                                                        'ตัวอย่างการเปรียบเทียบ\n'
                                                                        '\n'
                                                                        "รายการคงที่โดยใช้ `'`:\n"
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define alist '((name . "
                                                                        '"Alice") (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        'รายการแบบไดนามิกโดยใช้ `` '
                                                                        '` `` and `,`:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(define key 'name)\n"
                                                                        '(define value "Alice")\n'
                                                                        '(define alist `((,key . '
                                                                        ',value) (age . 30) (city '
                                                                        '. "Paris")))\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### การเข้าถึงข้อมูลใน '
                                                                        'Alist\n'
                                                                        '\n'
                                                                        'หากต้องการดึงค่าจากรายการ '
                                                                        'คุณสามารถใช้ฟังก์ชัน '
                                                                        '`assoc` '
                                                                        'ซึ่งจะค้นหาคู่ด้วยคีย์\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(assoc 'name alist)   ; "
                                                                        'Returns (name . "Alice")\n'
                                                                        "(assoc 'country alist) ; "
                                                                        'Returns #f (key not '
                                                                        'found)\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### การแยกคุณค่า\n'
                                                                        '\n'
                                                                        'เมื่อคุณดึงข้อมูลคู่โดยใช้ '
                                                                        '`assoc` ให้ใช้ `cdr` '
                                                                        'เพื่อแยกค่า:\n'
                                                                        '\n'
                                                                        '```scheme\n'
                                                                        "(cdr (assoc 'name "
                                                                        'alist))   ; Returns '
                                                                        '"Alice"\n'
                                                                        '```\n'
                                                                        '\n'
                                                                        '### '
                                                                        'สรุปคุณสมบัติที่สำคัญ\n'
                                                                        '\n'
                                                                        "- **Single Quote (`'`)**: "
                                                                        'สร้างรายการคงที่โดยที่องค์ประกอบทั้งหมดเป็นข้อมูลตามตัวอักษร\n'
                                                                        '- **ราคาย้อนกลับ (`` ` '
                                                                        '``)**: Allows dynamic '
                                                                        'creation of alists by '
                                                                        'mixing static elements '
                                                                        'with evaluated '
                                                                        'expressions (using `,`)\n'
                                                                        '- **Dot Notation (`.`)**: '
                                                                        'ใช้เพื่อสร้างคู่ '
                                                                        'เชื่อมโยงคีย์กับค่าในรายการ',
                                                                  'zh-cn': '---\n'
                                                                           'title: "关联列表（Alists）"\n'
                                                                           'type: docs\n'
                                                                           'weight: 6\n'
                                                                           '---\n'
                                                                           '**关联列表**（或**alist**）是Scheme中的一种基本数据结构，用于表示键值对的集合。它被实现为一个对的列表，其中每对将一个键（通常是一个符号）与一个值相关联。列表简单、灵活，非常适合中小型数据集。\n'
                                                                           '\n'
                                                                           '### 关联列表的结构\n'
                                                                           '\n'
                                                                           'alist '
                                                                           '是一个列表，其中每个元素都是一个**对**（使用 '
                                                                           '`cons` 构造）。每对包括：\n'
                                                                           '\n'
                                                                           '- **键**：第一个元素（通常是符号）。\n'
                                                                           '- '
                                                                           '**Value**：第二个元素，可以是任何数据类型。\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define alist '((name "
                                                                           '. "Alice") (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '- '
                                                                           "**密钥**：`'name`、`'age`、`'city`\n"
                                                                           '- '
                                                                           '**值**：`"Alice"`、`30`、`"Paris"`\n'
                                                                           '- **结构**：对列表：\n'
                                                                           '  `((name . "Alice") '
                                                                           '(age . 30) (city . '
                                                                           '"Paris"))`\n'
                                                                           '\n'
                                                                           '### 创建一个列表\n'
                                                                           '\n'
                                                                           '您可以通过手动构建对或使用 `cons` '
                                                                           '以编程方式构建来创建列表。\n'
                                                                           '\n'
                                                                           "#### 使用单引号 (`'`)\n"
                                                                           '\n'
                                                                           "单引号 (`'`) 是 "
                                                                           '**quoting** '
                                                                           '的简写，它会阻止Scheme '
                                                                           '计算表达式。这使得它非常适合创建所有键和值都被硬编码的静态列表。\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           ';; Alist manuell '
                                                                           'definieren\n'
                                                                           "(define alist '((name "
                                                                           '. "Alice") (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '\n'
                                                                           ';; Programmatisch ein '
                                                                           'neues Paar hinzufügen\n'
                                                                           '(define updated-alist '
                                                                           "(cons '(country . "
                                                                           '"France") alist))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '**结果**：\n'
                                                                           '`((country . "France") '
                                                                           '(name . "Alice") (age '
                                                                           '. 30) (city . '
                                                                           '"Paris"))`\n'
                                                                           '\n'
                                                                           '#### 使用反引号 (`` ` ``) '
                                                                           'and Comma (`,`)\n'
                                                                           '\n'
                                                                           '反引号 (`` ` ``) is '
                                                                           'similar to the single '
                                                                           'quote but allows you '
                                                                           'to dynamically insert '
                                                                           'evaluated expressions '
                                                                           'using the comma (`,`) '
                                                                           '运算符。这对于创建在运行时计算键或值的列表很有用。\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define key 'name)\n"
                                                                           '(define value '
                                                                           '"Alice")\n'
                                                                           '\n'
                                                                           '(define alist `((,key '
                                                                           '. ,value) (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '**结果**：\n'
                                                                           '`((name . "Alice") '
                                                                           '(age . 30) (city . '
                                                                           '"Paris"))`\n'
                                                                           '\n'
                                                                           '### 示例比较\n'
                                                                           '\n'
                                                                           "使用 `'` 的静态列表：\n"
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define alist '((name "
                                                                           '. "Alice") (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '使用 `` ` `` and `,` '
                                                                           '的动态列表：\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define key 'name)\n"
                                                                           '(define value '
                                                                           '"Alice")\n'
                                                                           '(define alist `((,key '
                                                                           '. ,value) (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '### 访问列表中的数据\n'
                                                                           '\n'
                                                                           '要从列表中检索值，您可以使用 `assoc` '
                                                                           '函数，该函数通过键查找一对。\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(assoc 'name alist)   "
                                                                           '; Returns (name . '
                                                                           '"Alice")\n'
                                                                           "(assoc 'country alist) "
                                                                           '; Returns #f (key not '
                                                                           'found)\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '### 提取值\n'
                                                                           '\n'
                                                                           '使用 `assoc` 检索一对后，请使用 '
                                                                           '`cdr` 提取该值：\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(cdr (assoc 'name "
                                                                           'alist))   ; Returns '
                                                                           '"Alice"\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '### 主要功能总结\n'
                                                                           '\n'
                                                                           '- **单引号 '
                                                                           "(`'`)**：创建一个静态列表，其中所有元素都是文字数据。\n"
                                                                           '- **反引号 (`` ` ``)**: '
                                                                           'Allows dynamic '
                                                                           'creation of alists by '
                                                                           'mixing static elements '
                                                                           'with evaluated '
                                                                           'expressions (using '
                                                                           '`,`)。\n'
                                                                           '- **点符号 '
                                                                           '(`.`)**：用于构造对，将键与列表中的值关联起来。',
                                                                  'zh-tw': '---\n'
                                                                           'title: "關聯列表（Alists）"\n'
                                                                           'type: docs\n'
                                                                           'weight: 6\n'
                                                                           '---\n'
                                                                           '**關聯清單**（或**alist**）是Scheme中的基本資料結構，用於表示鍵值對的集合。它被實現為一個對的列表，其中每對將一個鍵（通常是一個符號）與一個值相關聯。清單簡單、靈活，非常適合中小型資料集。\n'
                                                                           '\n'
                                                                           '### 關聯清單的結構\n'
                                                                           '\n'
                                                                           'alist '
                                                                           '是一個列表，其中每個元素都是一個**對**（使用 '
                                                                           '`cons` 構造）。每對包括：\n'
                                                                           '\n'
                                                                           '- **鍵**：第一個元素（通常是符號）。\n'
                                                                           '- '
                                                                           '**Value**：第二個元素，可以是任何資料型態。\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define alist '((name "
                                                                           '. "Alice") (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '- '
                                                                           "**金鑰**：`'name`、`'age`、`'city`\n"
                                                                           '- '
                                                                           '**值**：`"Alice"`、`30`、`"Paris"`\n'
                                                                           '- **結構**：對列表：\n'
                                                                           '  `((name . "Alice") '
                                                                           '(age . 30) (city . '
                                                                           '"Paris"))`\n'
                                                                           '\n'
                                                                           '### 建立一個列表\n'
                                                                           '\n'
                                                                           '您可以透過手動建立對或使用 `cons` '
                                                                           '以程式設計方式建立來建立清單。\n'
                                                                           '\n'
                                                                           "#### 使用單引號 (`'`)\n"
                                                                           '\n'
                                                                           "單引號 (`'`) 是 "
                                                                           '**quoting** '
                                                                           '的簡寫，它會阻止Scheme '
                                                                           '計算表達式。這使得它非常適合創建所有鍵和值都被硬編碼的靜態列表。\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           ';; Alist manuell '
                                                                           'definieren\n'
                                                                           "(define alist '((name "
                                                                           '. "Alice") (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '\n'
                                                                           ';; Programmatisch ein '
                                                                           'neues Paar hinzufügen\n'
                                                                           '(define updated-alist '
                                                                           "(cons '(country . "
                                                                           '"France") alist))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '**結果**：\n'
                                                                           '`((country . "France") '
                                                                           '(name . "Alice") (age '
                                                                           '. 30) (city . '
                                                                           '"Paris"))`\n'
                                                                           '\n'
                                                                           '#### 使用反引號 (`` ` ``) '
                                                                           'and Comma (`,`)\n'
                                                                           '\n'
                                                                           '反引號 (`` ` ``) is '
                                                                           'similar to the single '
                                                                           'quote but allows you '
                                                                           'to dynamically insert '
                                                                           'evaluated expressions '
                                                                           'using the comma (`,`) '
                                                                           '運算子。這對於建立在運行時計算鍵或值的清單很有用。\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define key 'name)\n"
                                                                           '(define value '
                                                                           '"Alice")\n'
                                                                           '\n'
                                                                           '(define alist `((,key '
                                                                           '. ,value) (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '**結果**：\n'
                                                                           '`((name . "Alice") '
                                                                           '(age . 30) (city . '
                                                                           '"Paris"))`\n'
                                                                           '\n'
                                                                           '### 範例比較\n'
                                                                           '\n'
                                                                           "使用 `'` 的靜態清單：\n"
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define alist '((name "
                                                                           '. "Alice") (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '使用 `` ` `` and `,` '
                                                                           '的動態清單：\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(define key 'name)\n"
                                                                           '(define value '
                                                                           '"Alice")\n'
                                                                           '(define alist `((,key '
                                                                           '. ,value) (age . 30) '
                                                                           '(city . "Paris")))\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '### 存取清單中的數據\n'
                                                                           '\n'
                                                                           '若要從清單中檢索值，您可以使用 '
                                                                           '`assoc` '
                                                                           '函數，該函數透過鍵找到一對。\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(assoc 'name alist)   "
                                                                           '; Returns (name . '
                                                                           '"Alice")\n'
                                                                           "(assoc 'country alist) "
                                                                           '; Returns #f (key not '
                                                                           'found)\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '### 提取值\n'
                                                                           '\n'
                                                                           '使用 `assoc` 檢索一對後，請使用 '
                                                                           '`cdr` 提取該值：\n'
                                                                           '\n'
                                                                           '```scheme\n'
                                                                           "(cdr (assoc 'name "
                                                                           'alist))   ; Returns '
                                                                           '"Alice"\n'
                                                                           '```\n'
                                                                           '\n'
                                                                           '### 主要功能總結\n'
                                                                           '\n'
                                                                           '- **單引號 '
                                                                           "(`'`)**：建立一個靜態列表，其中所有元素都是文字資料。\n"
                                                                           '- **反引號 (`` ` ``)**: '
                                                                           'Allows dynamic '
                                                                           'creation of alists by '
                                                                           'mixing static elements '
                                                                           'with evaluated '
                                                                           'expressions (using '
                                                                           '`,`)。\n'
                                                                           '- **點符號 '
                                                                           '(`.`)**：用於建構對，將鍵與列表中的值關聯起來。'},
 'content/hub/scripting/fundamentals/Data Structures/lists.md': {'de': '---\n'
                                                                       'title: "Listen"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'In Scheme ist eine '
                                                                       '**Liste** eine '
                                                                       'grundlegende '
                                                                       'Datenstruktur, die zum '
                                                                       'Gruppieren von Werten '
                                                                       'verwendet wird. Listen '
                                                                       'sind geordnete Sammlungen '
                                                                       'von Elementen, wobei jedes '
                                                                       'Element einen beliebigen '
                                                                       'Typ haben kann, '
                                                                       'einschließlich einer '
                                                                       'anderen Liste. Listen '
                                                                       'werden in Scheme häufig '
                                                                       'sowohl zur '
                                                                       'Datenspeicherung als auch '
                                                                       'zur Programmstruktur '
                                                                       'verwendet.\n'
                                                                       '\n'
                                                                       '### Beispiel 1: Einfache '
                                                                       'Liste\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Erstellt eine Liste mit '
                                                                       'drei Elementen: `1`, `2` '
                                                                       'und `3`.\n'
                                                                       '\n'
                                                                       'Ergebnis: **`(1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Zugriff auf '
                                                                       'Listenelemente\n'
                                                                       '\n'
                                                                       'Auf Elemente in einer '
                                                                       'Liste wird mit den '
                                                                       'Prozeduren `car` und `cdr` '
                                                                       'zugegriffen:\n'
                                                                       '\n'
                                                                       '- `car` ruft das erste '
                                                                       'Element einer Liste ab.\n'
                                                                       '- `cdr` ruft den Rest der '
                                                                       'Liste ab (alles außer dem '
                                                                       'ersten Element).\n'
                                                                       '\n'
                                                                       '#### Beispiele\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Ergebnis:\n'
                                                                       '\n'
                                                                       '- `(car my-list)` gibt `1` '
                                                                       'zurück\n'
                                                                       '- `(cdr my-list)` gibt `(2 '
                                                                       '3)` zurück\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Einfache Rekursion: '
                                                                       'Durch eine Liste '
                                                                       'iterieren\n'
                                                                       '\n'
                                                                       'Durch den rekursiven '
                                                                       'Aufruf von `car` auf dem '
                                                                       '`cdr` einer Liste können '
                                                                       'Sie jedes Element einzeln '
                                                                       'verarbeiten, bis die Liste '
                                                                       'durchlaufen ist. Dies '
                                                                       'bildet die Grundlage '
                                                                       'vieler '
                                                                       'Listenverarbeitungsalgorithmen.\n'
                                                                       '\n'
                                                                       '#### Beispiel: Jedes '
                                                                       'Element einer Liste '
                                                                       'drucken\n'
                                                                       '\n'
                                                                       'Hier ist eine einfache '
                                                                       'rekursive Funktion zum '
                                                                       'Drucken jedes Elements in '
                                                                       'einer Liste:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **Basisfall:** Wenn die '
                                                                       'Liste leer ist (`null? '
                                                                       'lst`), stoppen Sie die '
                                                                       'Rekursion.\n'
                                                                       '- **Rekursiver Fall:** '
                                                                       'Drucken Sie das erste '
                                                                       'Element (`car lst`) und '
                                                                       'rufen Sie dann die '
                                                                       'Funktion für den Rest der '
                                                                       'Liste auf (`cdr lst`).\n'
                                                                       '\n'
                                                                       '#### Beispielverwendung\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Ausgabe:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       'Ergebnis: „erledigt“\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Wie es funktioniert\n'
                                                                       '\n'
                                                                       '1. Die Funktion ruft mit '
                                                                       '`car` das erste Element '
                                                                       'der Liste ab und '
                                                                       'verarbeitet es.\n'
                                                                       '2. Anschließend ruft es '
                                                                       'sich selbst mit dem Rest '
                                                                       'der Liste auf (`cdr`).\n'
                                                                       '3. Dieser Vorgang '
                                                                       'wiederholt sich, bis die '
                                                                       'Liste leer ist (`null? '
                                                                       'lst`).\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Beispiel 2: Gemischte '
                                                                       'Typen\n'
                                                                       '\n'
                                                                       'Listen können Elemente '
                                                                       'unterschiedlichen Typs '
                                                                       'enthalten, darunter '
                                                                       'Zeichenfolgen, boolesche '
                                                                       'Werte, Zahlen, andere '
                                                                       'Listen oder sogar das '
                                                                       'Ergebnis von Ausdrücken:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Dadurch wird eine Liste '
                                                                       'erstellt mit:\n'
                                                                       '  - Eine Zahl (`42`)\n'
                                                                       '  - Eine Zeichenfolge '
                                                                       '(`"hello"`)\n'
                                                                       '  – Ein boolescher Wert '
                                                                       '(`#t`)\n'
                                                                       '  - Eine weitere Liste '
                                                                       '(`(1 2)`)\n'
                                                                       '  – Das Ergebnis eines '
                                                                       'Ausdrucks (`(+ 3 4)`, der '
                                                                       'zu `7` ausgewertet wird)\n'
                                                                       '\n'
                                                                       'Ergebnis: **`(42 "hello" '
                                                                       '#t (1 2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Diese Beispiele '
                                                                       'veranschaulichen die '
                                                                       'Vielseitigkeit von Listen '
                                                                       'in Scheme und machen sie '
                                                                       'zu einem leistungsstarken '
                                                                       'Werkzeug zum Organisieren '
                                                                       'und Bearbeiten von Daten.\n'
                                                                       '\n'
                                                                       '### Listen erstellen\n'
                                                                       '\n'
                                                                       'Die Prozedur `cons` wird '
                                                                       'verwendet, um eine neue '
                                                                       'Liste zu erstellen, indem '
                                                                       'ein Element mit einer '
                                                                       'vorhandenen Liste '
                                                                       'kombiniert wird.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Beispiel\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Fügt `0` am Anfang der '
                                                                       'Liste `(1 2 3)` hinzu.\n'
                                                                       '\n'
                                                                       'Ergebnis: **`(0 1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Nach Listen suchen\n'
                                                                       '\n'
                                                                       'Die Prozedur `list?` '
                                                                       'prüft, ob ein gegebener '
                                                                       'Wert eine Liste ist.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Beispiel: Liste?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Ergebnis:\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))` '
                                                                       'gibt `#t` zurück (wahr)\n'
                                                                       '- `(list? 42)` gibt `#f` '
                                                                       'zurück (falsch)\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Operationen auf '
                                                                       'Listen\n'
                                                                       '\n'
                                                                       'Scheme bietet mehrere '
                                                                       'integrierte Verfahren zum '
                                                                       'Arbeiten mit Listen, '
                                                                       'darunter:\n'
                                                                       '\n'
                                                                       '- `length`: Gibt die '
                                                                       'Anzahl der Elemente in '
                                                                       'einer Liste zurück.\n'
                                                                       '- `append`: Kombiniert '
                                                                       'zwei oder mehr Listen zu '
                                                                       'einer.\n'
                                                                       '- `reverse`: Gibt eine '
                                                                       'neue Liste mit Elementen '
                                                                       'in umgekehrter Reihenfolge '
                                                                       'zurück.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Ergebnis:\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))` '
                                                                       'gibt `3` zurück\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))` gibt `(1 2 3 '
                                                                       '4)` zurück\n'
                                                                       '- `(reverse (list 1 2 3))` '
                                                                       'gibt `(3 2 1)` zurück#### '
                                                                       'Verwendung von `list-ref`\n'
                                                                       '\n'
                                                                       'Die Prozedur `list-ref` '
                                                                       'ruft das Element an einem '
                                                                       'angegebenen Index einer '
                                                                       'Liste ab (nullbasierter '
                                                                       'Index).\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **`lst`**: Die Liste, '
                                                                       'aus der das Element '
                                                                       'abgerufen werden soll.\n'
                                                                       '- **`index`**: Ein '
                                                                       'nullbasierter Index, der '
                                                                       'angibt, welches Element '
                                                                       'zurückgegeben werden '
                                                                       'soll.\n'
                                                                       '\n'
                                                                       '##### Beispiel: '
                                                                       'Listenreferenz\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Ergebnis: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Verschachtelte Listen\n'
                                                                       '\n'
                                                                       'Listen in Scheme können '
                                                                       'andere Listen als Elemente '
                                                                       'enthalten, wodurch eine '
                                                                       'verschachtelte Struktur '
                                                                       'entsteht.\n'
                                                                       '\n'
                                                                       '#### Beispiel: Erstellen '
                                                                       'einer verschachtelten '
                                                                       'Liste\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Erstellt eine Liste mit '
                                                                       'drei Elementen, von denen '
                                                                       'jedes selbst eine Liste '
                                                                       'ist.\n'
                                                                       '\n'
                                                                       'Ergebnis: **`((1 2) (3 4) '
                                                                       '(5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Zugriff auf '
                                                                       'verschachtelte Daten\n'
                                                                       '\n'
                                                                       'Um auf Elemente innerhalb '
                                                                       'einer verschachtelten '
                                                                       'Liste zuzugreifen, können '
                                                                       'Sie Kombinationen aus '
                                                                       '`car` und `cdr` verwenden, '
                                                                       'um durch die Struktur zu '
                                                                       'navigieren.\n'
                                                                       '\n'
                                                                       '#### Beispiel: Auf '
                                                                       'Elemente zugreifen\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Erklärung\n'
                                                                       '\n'
                                                                       '1. **`car nested-list`**:\n'
                                                                       '   – Ruft das erste '
                                                                       'Element von `nested-list` '
                                                                       'ab, nämlich `(1 2)`.\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**:\n'
                                                                       '   – Ruft das erste '
                                                                       'Element von `(1 2)` ab, '
                                                                       'nämlich `1`.\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**:\n'
                                                                       '   – Ruft den Rest von `(1 '
                                                                       '2)` ab, also `(2)`.\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**:\n'
                                                                       '   – Ruft das erste '
                                                                       'Element von `(2)` ab, '
                                                                       'nämlich `2`.\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Beispiel: Zugriff auf '
                                                                       'Elemente aus anderen '
                                                                       'Unterlisten\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Dieser Ansatz ermöglicht '
                                                                       'Ihnen die systematische '
                                                                       'Navigation und den Zugriff '
                                                                       'auf bestimmte Elemente in '
                                                                       'einer verschachtelten '
                                                                       'Liste und bietet so eine '
                                                                       'leistungsstarke '
                                                                       'Flexibilität für die '
                                                                       'Arbeit mit hierarchischen '
                                                                       'Daten.\n'
                                                                       '\n'
                                                                       '### Zusammenfassung\n'
                                                                       '\n'
                                                                       '- **Listen** in Scheme '
                                                                       'sind vielseitige und '
                                                                       'wesentliche '
                                                                       'Datenstrukturen.\n'
                                                                       '- Verwenden Sie `list` zum '
                                                                       'Erstellen einer Liste, '
                                                                       '`car` und `cdr` für den '
                                                                       'Zugriff auf Elemente und '
                                                                       '`cons` zum Erstellen von '
                                                                       'Listen.\n'
                                                                       '- Integrierte Prozeduren '
                                                                       'wie `length`, `append`, '
                                                                       '`reverse` und `list-ref` '
                                                                       'machen Listenoperationen '
                                                                       'einfach und effizient.\n'
                                                                       '- Listen können '
                                                                       'verschachtelt werden, was '
                                                                       'komplexe Datenstrukturen '
                                                                       'für erweiterte '
                                                                       'Anwendungsfälle '
                                                                       'ermöglicht.',
                                                                 'es': '---\n'
                                                                       'title: "Listas"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'En Scheme, una **lista** '
                                                                       'es una estructura de datos '
                                                                       'fundamental que se utiliza '
                                                                       'para agrupar valores. Las '
                                                                       'listas son colecciones '
                                                                       'ordenadas de elementos '
                                                                       'donde cada elemento puede '
                                                                       'ser de cualquier tipo, '
                                                                       'incluida otra lista. Las '
                                                                       'listas se utilizan '
                                                                       'ampliamente en Scheme '
                                                                       'tanto para el '
                                                                       'almacenamiento de datos '
                                                                       'como para la estructura '
                                                                       'del programa.\n'
                                                                       '\n'
                                                                       '### Ejemplo 1: Lista '
                                                                       'simple\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Crea una lista de tres '
                                                                       'elementos: `1`, `2` y '
                                                                       '`3`.\n'
                                                                       '\n'
                                                                       'Resultado: **`(1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Acceso a elementos de '
                                                                       'la lista\n'
                                                                       '\n'
                                                                       'Se accede a los elementos '
                                                                       'de una lista mediante los '
                                                                       'procedimientos `car` y '
                                                                       '`cdr`:\n'
                                                                       '\n'
                                                                       '- `car` recupera el primer '
                                                                       'elemento de una lista.\n'
                                                                       '- `cdr` recupera el resto '
                                                                       'de la lista (todo excepto '
                                                                       'el primer elemento).\n'
                                                                       '\n'
                                                                       '#### Ejemplos\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultado:\n'
                                                                       '\n'
                                                                       '- `(car my-list)` devuelve '
                                                                       '`1`\n'
                                                                       '- `(cdr my-list)` devuelve '
                                                                       '`(2 3)`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Recursión simple: '
                                                                       'iteración a través de una '
                                                                       'lista\n'
                                                                       '\n'
                                                                       'Al llamar recursivamente a '
                                                                       '`car` en el `cdr` de una '
                                                                       'lista, puede procesar cada '
                                                                       'elemento uno por uno hasta '
                                                                       'recorrer la lista. Esto '
                                                                       'forma la base de muchos '
                                                                       'algoritmos de '
                                                                       'procesamiento de listas.\n'
                                                                       '\n'
                                                                       '#### Ejemplo: imprimir '
                                                                       'cada elemento de una '
                                                                       'lista\n'
                                                                       '\n'
                                                                       'Aquí hay una función '
                                                                       'recursiva simple para '
                                                                       'imprimir cada elemento en '
                                                                       'una lista:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **Caso base:** Si la '
                                                                       'lista está vacía (`null? '
                                                                       'lst`), detenga la '
                                                                       'recursividad.\n'
                                                                       '- **Caso recursivo:** '
                                                                       'Imprime el primer elemento '
                                                                       '(`car lst`), luego llama a '
                                                                       'la función en el resto de '
                                                                       'la lista (`cdr lst`).\n'
                                                                       '\n'
                                                                       '#### Ejemplo de uso\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Salida:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       'Result: "done"\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Cómo funciona\n'
                                                                       '\n'
                                                                       '1. La función recupera el '
                                                                       'primer elemento de la '
                                                                       'lista usando `car` y lo '
                                                                       'procesa.\n'
                                                                       '2. Luego se llama a sí '
                                                                       'mismo con el resto de la '
                                                                       'lista (`cdr`).\n'
                                                                       '3. Este proceso se repite '
                                                                       'hasta que la lista esté '
                                                                       'vacía (`null? lst`).\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Ejemplo 2: tipos '
                                                                       'mixtos\n'
                                                                       '\n'
                                                                       'Las listas pueden incluir '
                                                                       'elementos de diferentes '
                                                                       'tipos, incluidas cadenas, '
                                                                       'booleanos, números, otras '
                                                                       'listas o incluso el '
                                                                       'resultado de expresiones:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Esto crea una lista '
                                                                       'con:\n'
                                                                       '  - Un número (`42`)\n'
                                                                       '  - Una cadena '
                                                                       '(`"hello"`)\n'
                                                                       '  - Un booleano (`#t`)\n'
                                                                       '  - Otra lista (`(1 2)`)\n'
                                                                       '  - El resultado de una '
                                                                       'expresión (`(+ 3 4)`, que '
                                                                       'se evalúa como `7`)\n'
                                                                       '\n'
                                                                       'Resultado: **`(42 "hello" '
                                                                       '#t (1 2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Estos ejemplos demuestran '
                                                                       'la versatilidad de las '
                                                                       'listas en Scheme, lo que '
                                                                       'las convierte en una '
                                                                       'poderosa herramienta para '
                                                                       'organizar y manipular '
                                                                       'datos.\n'
                                                                       '\n'
                                                                       '### Construyendo listas\n'
                                                                       '\n'
                                                                       'El procedimiento `cons` se '
                                                                       'utiliza para construir una '
                                                                       'nueva lista combinando un '
                                                                       'elemento con una lista '
                                                                       'existente.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Ejemplo\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Agrega `0` al principio '
                                                                       'de la lista `(1 2 3)`.\n'
                                                                       '\n'
                                                                       'Resultado: **`(0 1 2 '
                                                                       '3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Comprobando listas\n'
                                                                       '\n'
                                                                       'El procedimiento `list?` '
                                                                       'comprueba si un valor '
                                                                       'determinado es una lista.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Ejemplo: ¿lista?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultado:\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))` '
                                                                       'devuelve `#t` (verdadero)\n'
                                                                       '- `(list? 42)` devuelve '
                                                                       '`#f` (falso)\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Operaciones en listas\n'
                                                                       '\n'
                                                                       'Scheme proporciona varios '
                                                                       'procedimientos integrados '
                                                                       'para trabajar con listas, '
                                                                       'que incluyen:\n'
                                                                       '\n'
                                                                       '- `length`: Devuelve el '
                                                                       'número de elementos de una '
                                                                       'lista.\n'
                                                                       '- `append`: Combina dos o '
                                                                       'más listas en una.\n'
                                                                       '- `reverse`: Devuelve una '
                                                                       'nueva lista con elementos '
                                                                       'en orden inverso.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultado:\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))` '
                                                                       'devuelve `3`\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))` devuelve `(1 '
                                                                       '2 3 4)`\n'
                                                                       '- `(reverse (list 1 2 3))` '
                                                                       'devuelve `(3 2 1)`\n'
                                                                       '\n'
                                                                       '#### Usando `list-ref`\n'
                                                                       '\n'
                                                                       'El procedimiento '
                                                                       '`list-ref` recupera el '
                                                                       'elemento en un índice '
                                                                       'específico de una lista '
                                                                       '(índice de base cero).\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **`lst`**: La lista de '
                                                                       'la cual recuperar el '
                                                                       'elemento.\n'
                                                                       '- **`index`**: un índice '
                                                                       'de base cero que indica '
                                                                       'qué elemento devolver.\n'
                                                                       '\n'
                                                                       '##### Ejemplo: lista-ref\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultado: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Listas anidadas\n'
                                                                       '\n'
                                                                       'Las listas en Scheme '
                                                                       'pueden contener otras '
                                                                       'listas como elementos, '
                                                                       'creando una estructura '
                                                                       'anidada.\n'
                                                                       '\n'
                                                                       '#### Ejemplo: creación de '
                                                                       'una lista anidada\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Crea una lista de tres '
                                                                       'elementos, cada uno de los '
                                                                       'cuales es en sí mismo una '
                                                                       'lista.\n'
                                                                       '\n'
                                                                       'Resultado: **`((1 2) (3 4) '
                                                                       '(5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Acceso a datos '
                                                                       'anidados\n'
                                                                       '\n'
                                                                       'Para acceder a elementos '
                                                                       'dentro de una lista '
                                                                       'anidada, puede usar '
                                                                       'combinaciones de `car` y '
                                                                       '`cdr` para navegar a '
                                                                       'través de la estructura.\n'
                                                                       '\n'
                                                                       '#### Ejemplo: acceso a '
                                                                       'elementos\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Explicación\n'
                                                                       '\n'
                                                                       '1. **`car nested-list`**:\n'
                                                                       '   - Recupera el primer '
                                                                       'elemento de `nested-list`, '
                                                                       'que es `(1 2)`.\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Recupera el primer '
                                                                       'elemento de `(1 2)`, que '
                                                                       'es `1`.\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Recupera el resto de '
                                                                       '`(1 2)`, que es `(2)`.\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**:\n'
                                                                       '   - Recupera el primer '
                                                                       'elemento de `(2)`, que es '
                                                                       '`2`.\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Ejemplo: acceder a '
                                                                       'elementos de otras '
                                                                       'sublistas\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Este enfoque le permite '
                                                                       'navegar y acceder '
                                                                       'sistemáticamente a '
                                                                       'elementos específicos en '
                                                                       'una lista anidada, lo que '
                                                                       'proporciona una gran '
                                                                       'flexibilidad para trabajar '
                                                                       'con datos jerárquicos.\n'
                                                                       '\n'
                                                                       '### Resumen\n'
                                                                       '\n'
                                                                       '- Las **Listas** en Scheme '
                                                                       'son estructuras de datos '
                                                                       'versátiles y esenciales.\n'
                                                                       '- Utilice `list` para '
                                                                       'crear una lista, `car` y '
                                                                       '`cdr` para acceder a '
                                                                       'elementos y `cons` para '
                                                                       'construir listas.\n'
                                                                       '- Los procedimientos '
                                                                       'integrados como `length`, '
                                                                       '`append`, `reverse` y '
                                                                       '`list-ref` hacen que las '
                                                                       'operaciones de listas sean '
                                                                       'fáciles y eficientes.\n'
                                                                       '- Las listas se pueden '
                                                                       'anidar, lo que permite '
                                                                       'estructuras de datos '
                                                                       'complejas para casos de '
                                                                       'uso avanzados.',
                                                                 'fr': '---\n'
                                                                       'title: "Listes"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'Dans Scheme, une **list** '
                                                                       'est une structure de '
                                                                       'données fondamentale '
                                                                       'utilisée pour regrouper '
                                                                       'des valeurs. Les listes '
                                                                       'sont des collections '
                                                                       "ordonnées d'éléments où "
                                                                       'chaque élément peut être '
                                                                       "de n'importe quel type, y "
                                                                       'compris une autre liste. '
                                                                       'Les listes sont largement '
                                                                       'utilisées dans Scheme à la '
                                                                       'fois pour le stockage de '
                                                                       'données et la structure du '
                                                                       'programme.\n'
                                                                       '\n'
                                                                       '### Exemple 1\xa0: Liste '
                                                                       'simple\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Crée une liste de trois '
                                                                       'éléments\xa0: `1`, `2` et '
                                                                       '`3`.\n'
                                                                       '\n'
                                                                       'Résultat\xa0: **`(1 2 '
                                                                       '3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Accéder aux éléments '
                                                                       'de la liste\n'
                                                                       '\n'
                                                                       "Les éléments d'une liste "
                                                                       "sont accessibles à l'aide "
                                                                       'des procédures `car` et '
                                                                       '`cdr`\xa0:\n'
                                                                       '\n'
                                                                       '- `car` récupère le '
                                                                       "premier élément d'une "
                                                                       'liste.\n'
                                                                       '- `cdr` récupère le reste '
                                                                       'de la liste (tout sauf le '
                                                                       'premier élément).\n'
                                                                       '\n'
                                                                       '#### Exemples\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Résultat :\n'
                                                                       '\n'
                                                                       '- `(car my-list)` renvoie '
                                                                       '`1`\n'
                                                                       '- `(cdr my-list)` renvoie '
                                                                       '`(2 3)`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Récursivité simple\xa0'
                                                                       ': parcourir une liste\n'
                                                                       '\n'
                                                                       'En appelant récursivement '
                                                                       "`car` sur le `cdr` d'une "
                                                                       'liste, vous pouvez traiter '
                                                                       'chaque élément un par un '
                                                                       "jusqu'à ce que la liste "
                                                                       'soit parcourue. Ceci '
                                                                       'constitue la base de '
                                                                       'nombreux algorithmes de '
                                                                       'traitement de listes.\n'
                                                                       '\n'
                                                                       '#### Exemple\xa0: '
                                                                       'Impression de chaque '
                                                                       "élément d'une liste\n"
                                                                       '\n'
                                                                       'Voici une fonction '
                                                                       'récursive simple pour '
                                                                       'imprimer chaque élément '
                                                                       "d'une liste\xa0:\n"
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **Cas de base\xa0:** Si '
                                                                       'la liste est vide (`null? '
                                                                       'lst`), arrêtez la '
                                                                       'récursivité.\n'
                                                                       '- **Cas récursif\xa0:** '
                                                                       'Imprimez le premier '
                                                                       'élément (`car lst`), puis '
                                                                       'appelez la fonction sur le '
                                                                       'reste de la liste (`cdr '
                                                                       'lst`).\n'
                                                                       '\n'
                                                                       '#### Exemple '
                                                                       "d'utilisation\n"
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Sortie\xa0:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       'Result: "done"\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Comment ça marche\n'
                                                                       '\n'
                                                                       '1. La fonction récupère le '
                                                                       'premier élément de la '
                                                                       "liste à l'aide de `car` et "
                                                                       'le traite.\n'
                                                                       "2. Il s'appelle ensuite "
                                                                       'avec le reste de la liste '
                                                                       '(`cdr`).\n'
                                                                       '3. Ce processus se répète '
                                                                       "jusqu'à ce que la liste "
                                                                       'soit vide (`null? lst`).\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Exemple 2\xa0: Types '
                                                                       'mixtes\n'
                                                                       '\n'
                                                                       'Les listes peuvent inclure '
                                                                       'des éléments de différents '
                                                                       'types, notamment des '
                                                                       'chaînes, des booléens, des '
                                                                       "nombres, d'autres listes "
                                                                       'ou même le résultat '
                                                                       "d'expressions\xa0:\n"
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Cela crée une liste '
                                                                       'avec\xa0:\n'
                                                                       '  - Un numéro (`42`)\n'
                                                                       '  - Une chaîne '
                                                                       '(`"hello"`)\n'
                                                                       '  - Un booléen (`#t`)\n'
                                                                       '  - Une autre liste (`(1 '
                                                                       '2)`)\n'
                                                                       "  - Le résultat d'une "
                                                                       'expression (`(+ 3 4)`, qui '
                                                                       "s'évalue à `7`)\n"
                                                                       '\n'
                                                                       'Résultat\xa0: **`(42 '
                                                                       '"hello" #t (1 2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Ces exemples démontrent la '
                                                                       'polyvalence des listes '
                                                                       'dans Scheme, ce qui en '
                                                                       'fait un outil puissant '
                                                                       'pour organiser et '
                                                                       'manipuler les données.\n'
                                                                       '\n'
                                                                       '### Construire des listes\n'
                                                                       '\n'
                                                                       'La procédure `cons` permet '
                                                                       'de construire une nouvelle '
                                                                       'liste en combinant un '
                                                                       'élément avec une liste '
                                                                       'existante.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Exemple\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Ajoute `0` au début de '
                                                                       'la liste `(1 2 3)`.\n'
                                                                       '\n'
                                                                       'Résultat\xa0: **`(0 1 2 '
                                                                       '3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Vérification des '
                                                                       'listes\n'
                                                                       '\n'
                                                                       'La procédure `list?` '
                                                                       'vérifie si une valeur '
                                                                       'donnée est une liste.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Exemple : liste ?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Résultat :\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))` '
                                                                       'renvoie `#t` (vrai)\n'
                                                                       '- `(list? 42)` renvoie '
                                                                       '`#f` (faux)\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Opérations sur les '
                                                                       'listes\n'
                                                                       '\n'
                                                                       'Scheme fournit plusieurs '
                                                                       'procédures intégrées pour '
                                                                       'travailler avec des '
                                                                       'listes, notamment\xa0:\n'
                                                                       '\n'
                                                                       '- `length` : Renvoie le '
                                                                       "nombre d'éléments dans une "
                                                                       'liste.\n'
                                                                       '- `append`\xa0: Combine '
                                                                       'deux ou plusieurs listes '
                                                                       'en une seule.\n'
                                                                       '- `reverse` : Renvoie une '
                                                                       'nouvelle liste avec les '
                                                                       "éléments dans l'ordre "
                                                                       'inverse.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Résultat :\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))` '
                                                                       'renvoie `3`\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))` renvoie `(1 2 '
                                                                       '3 4)`\n'
                                                                       '- `(reverse (list 1 2 3))` '
                                                                       'renvoie `(3 2 1)`\n'
                                                                       '\n'
                                                                       '#### Utilisation de '
                                                                       '`list-ref`\n'
                                                                       '\n'
                                                                       'La procédure `list-ref` '
                                                                       "récupère l'élément à un "
                                                                       "index spécifié d'une liste "
                                                                       '(index de base zéro).\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **`lst`** : La liste à '
                                                                       'partir de laquelle '
                                                                       "récupérer l'élément.\n"
                                                                       '- **`index`**\xa0: Un '
                                                                       'index de base zéro '
                                                                       'indiquant quel élément '
                                                                       'renvoyer.\n'
                                                                       '\n'
                                                                       '##### Exemple\xa0: '
                                                                       'list-ref\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Résultat\xa0: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Listes imbriquées\n'
                                                                       '\n'
                                                                       'Les listes dans Scheme '
                                                                       "peuvent contenir d'autres "
                                                                       'listes en tant '
                                                                       "qu'éléments, créant ainsi "
                                                                       'une structure imbriquée.\n'
                                                                       '\n'
                                                                       '#### Exemple\xa0: Création '
                                                                       "d'une liste imbriquée\n"
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Crée une liste de trois '
                                                                       'éléments, dont chacun est '
                                                                       'lui-même une liste.\n'
                                                                       '\n'
                                                                       'Résultat\xa0: **`((1 2) (3 '
                                                                       '4) (5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Accès aux données '
                                                                       'imbriquées\n'
                                                                       '\n'
                                                                       'Pour accéder aux éléments '
                                                                       "d'une liste imbriquée, "
                                                                       'vous pouvez utiliser des '
                                                                       'combinaisons de `car` et '
                                                                       '`cdr` pour naviguer dans '
                                                                       'la structure.\n'
                                                                       '\n'
                                                                       '#### Exemple\xa0: accès '
                                                                       'aux éléments\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Explication\n'
                                                                       '\n'
                                                                       '1. **`car '
                                                                       'nested-list`**\xa0:\n'
                                                                       '   - Récupère le premier '
                                                                       'élément de `nested-list`, '
                                                                       'qui est `(1 2)`.\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**\xa0:\n'
                                                                       '   - Récupère le premier '
                                                                       'élément de `(1 2)`, qui '
                                                                       'est `1`.\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**\xa0:\n'
                                                                       '   - Récupère le reste de '
                                                                       '`(1 2)`, qui est `(2)`.\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**\xa0:\n'
                                                                       '   - Récupère le premier '
                                                                       'élément de `(2)`, qui est '
                                                                       '`2`.\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Exemple\xa0: accès '
                                                                       'aux éléments à partir '
                                                                       "d'autres sous-listes\n"
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Cette approche vous permet '
                                                                       "de naviguer et d'accéder "
                                                                       'systématiquement à des '
                                                                       'éléments spécifiques dans '
                                                                       'une liste imbriquée, '
                                                                       'offrant ainsi une grande '
                                                                       'flexibilité pour '
                                                                       'travailler avec des '
                                                                       'données hiérarchiques.\n'
                                                                       '\n'
                                                                       '### Résumé\n'
                                                                       '\n'
                                                                       '- Les **Listes** dans '
                                                                       'Scheme sont des structures '
                                                                       'de données polyvalentes et '
                                                                       'essentielles.\n'
                                                                       '- Utilisez `list` pour '
                                                                       'créer une liste, `car` et '
                                                                       '`cdr` pour accéder aux '
                                                                       'éléments et `cons` pour '
                                                                       'construire des listes.\n'
                                                                       '- Les procédures intégrées '
                                                                       'telles que `length`, '
                                                                       '`append`, `reverse` et '
                                                                       '`list-ref` rendent les '
                                                                       'opérations de liste '
                                                                       'faciles et efficaces.\n'
                                                                       '- Les listes peuvent être '
                                                                       'imbriquées, permettant des '
                                                                       'structures de données '
                                                                       'complexes pour des cas '
                                                                       "d'utilisation avancés.",
                                                                 'it': '---\n'
                                                                       'title: "Elenchi"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'In Scheme, una **lista** è '
                                                                       'una struttura dati '
                                                                       'fondamentale utilizzata '
                                                                       'per raggruppare valori. '
                                                                       'Gli elenchi sono raccolte '
                                                                       'ordinate di elementi in '
                                                                       'cui ciascun elemento può '
                                                                       'essere di qualsiasi tipo, '
                                                                       'incluso un altro elenco. '
                                                                       'Gli elenchi sono '
                                                                       'ampiamente utilizzati in '
                                                                       'Scheme sia per '
                                                                       "l'archiviazione dei dati "
                                                                       'che per la struttura del '
                                                                       'programma.\n'
                                                                       '\n'
                                                                       '### Esempio 1: Elenco '
                                                                       'semplice\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Crea un elenco di tre '
                                                                       'elementi: `1`, `2` e `3`.\n'
                                                                       '\n'
                                                                       'Risultato: **`(1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Accesso agli elementi '
                                                                       "dell'elenco\n"
                                                                       '\n'
                                                                       'È possibile accedere agli '
                                                                       'elementi di un elenco '
                                                                       'utilizzando le procedure '
                                                                       '`car` e `cdr`:\n'
                                                                       '\n'
                                                                       '- `car` recupera il primo '
                                                                       'elemento di un elenco.\n'
                                                                       '- `cdr` recupera il resto '
                                                                       "dell'elenco (tutto tranne "
                                                                       'il primo elemento).\n'
                                                                       '\n'
                                                                       '#### Esempi\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Risultato:\n'
                                                                       '\n'
                                                                       '- `(car my-list)` '
                                                                       'restituisce `1`\n'
                                                                       '- `(cdr my-list)` '
                                                                       'restituisce `(2 3)`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Ricorsione semplice: '
                                                                       'scorrere una lista\n'
                                                                       '\n'
                                                                       'Chiamando ricorsivamente '
                                                                       '`car` sul `cdr` di un '
                                                                       'elenco, è possibile '
                                                                       'elaborare ciascun elemento '
                                                                       'uno per uno finché '
                                                                       "l'elenco non viene "
                                                                       'attraversato. Ciò '
                                                                       'costituisce la base di '
                                                                       'molti algoritmi di '
                                                                       'elaborazione delle liste.\n'
                                                                       '\n'
                                                                       '#### Esempio: stampa di '
                                                                       'ciascun elemento di un '
                                                                       'elenco\n'
                                                                       '\n'
                                                                       'Ecco una semplice funzione '
                                                                       'ricorsiva per stampare '
                                                                       'ogni elemento in un '
                                                                       'elenco:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **Caso base:** Se '
                                                                       "l'elenco è vuoto (`null? "
                                                                       'lst`), interrompe la '
                                                                       'ricorsione.\n'
                                                                       '- **Caso ricorsivo:** '
                                                                       'Stampa il primo elemento '
                                                                       '(`car lst`), quindi chiama '
                                                                       'la funzione sul resto '
                                                                       "dell'elenco (`cdr lst`).\n"
                                                                       '\n'
                                                                       '#### Esempio di utilizzo\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Uscita:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       'Result: "done"\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Come funziona\n'
                                                                       '\n'
                                                                       '1. La funzione recupera il '
                                                                       "primo elemento dell'elenco "
                                                                       'utilizzando `car` e lo '
                                                                       'elabora.\n'
                                                                       '2. Quindi si richiama con '
                                                                       "il resto dell'elenco "
                                                                       '(`cdr`).\n'
                                                                       '3. Questo processo si '
                                                                       "ripete finché l'elenco è "
                                                                       'vuoto (`null? lst`).\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Esempio 2: tipi misti\n'
                                                                       '\n'
                                                                       'Gli elenchi possono '
                                                                       'includere elementi di '
                                                                       'diverso tipo, tra cui '
                                                                       'stringhe, valori booleani, '
                                                                       'numeri, altri elenchi o '
                                                                       'persino il risultato di '
                                                                       'espressioni:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Questo crea un elenco '
                                                                       'con:\n'
                                                                       '  - Un numero (`42`)\n'
                                                                       '  - Una stringa '
                                                                       '(`"hello"`)\n'
                                                                       '  - Un valore booleano '
                                                                       '(`#t`)\n'
                                                                       "  - Un'altra lista (`(1 "
                                                                       '2)`)\n'
                                                                       '  - Il risultato di '
                                                                       "un'espressione (`(+ 3 4)`, "
                                                                       'che restituisce `7`)\n'
                                                                       '\n'
                                                                       'Risultato: **`(42 "hello" '
                                                                       '#t (1 2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Questi esempi dimostrano '
                                                                       'la versatilità degli '
                                                                       'elenchi in Scheme, '
                                                                       'rendendoli un potente '
                                                                       'strumento per organizzare '
                                                                       'e manipolare i dati.\n'
                                                                       '\n'
                                                                       '### Costruzione di '
                                                                       'elenchi\n'
                                                                       '\n'
                                                                       'La procedura `cons` viene '
                                                                       'utilizzata per costruire '
                                                                       'una nuova lista combinando '
                                                                       'un elemento con una lista '
                                                                       'esistente.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Esempio\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       "- Aggiunge `0` all'inizio "
                                                                       "dell'elenco `(1 2 3)`.\n"
                                                                       '\n'
                                                                       'Risultato: **`(0 1 2 '
                                                                       '3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Controllo degli '
                                                                       'elenchi\n'
                                                                       '\n'
                                                                       'La procedura `list?` '
                                                                       'controlla se un dato '
                                                                       'valore è una lista.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Esempio: elenco?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Risultato:\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))` '
                                                                       'restituisce `#t` (vero)\n'
                                                                       '- `(list? 42)` restituisce '
                                                                       '`#f` (falso)\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Operazioni sulle '
                                                                       'liste\n'
                                                                       '\n'
                                                                       'Scheme fornisce diverse '
                                                                       'procedure integrate per '
                                                                       'lavorare con gli elenchi, '
                                                                       'tra cui:\n'
                                                                       '\n'
                                                                       '- `length`: restituisce il '
                                                                       'numero di elementi in un '
                                                                       'elenco.\n'
                                                                       '- `append`: combina due o '
                                                                       'più elenchi in uno solo.\n'
                                                                       '- `reverse`: restituisce '
                                                                       'un nuovo elenco con gli '
                                                                       'elementi in ordine '
                                                                       'inverso.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Risultato:\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))` '
                                                                       'restituisce `3`\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))` restituisce '
                                                                       '`(1 2 3 4)`\n'
                                                                       '- `(reverse (list 1 2 3))` '
                                                                       'restituisce `(3 2 1)`\n'
                                                                       '\n'
                                                                       '#### Utilizzo di '
                                                                       '`list-ref`\n'
                                                                       '\n'
                                                                       'La procedura `list-ref` '
                                                                       "recupera l'elemento in un "
                                                                       'indice specificato di un '
                                                                       'elenco (indice in base '
                                                                       'zero).\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       "- **`lst`**: l'elenco da "
                                                                       'cui recuperare '
                                                                       "l'elemento.\n"
                                                                       '- **`index`**: un indice '
                                                                       'in base zero che indica '
                                                                       'quale elemento '
                                                                       'restituire.\n'
                                                                       '\n'
                                                                       '##### Esempio: rif-elenco\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Risultato: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Elenchi nidificati\n'
                                                                       '\n'
                                                                       'Gli elenchi in Scheme '
                                                                       'possono contenere altri '
                                                                       'elenchi come elementi, '
                                                                       'creando una struttura '
                                                                       'nidificata.\n'
                                                                       '\n'
                                                                       '#### Esempio: creazione di '
                                                                       'un elenco nidificato\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Crea un elenco di tre '
                                                                       'elementi, ognuno dei quali '
                                                                       'è esso stesso un elenco.\n'
                                                                       '\n'
                                                                       'Risultato: **`((1 2) (3 4) '
                                                                       '(5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Accesso ai dati '
                                                                       'annidati\n'
                                                                       '\n'
                                                                       'Per accedere agli elementi '
                                                                       "all'interno di un elenco "
                                                                       'nidificato, è possibile '
                                                                       'utilizzare le combinazioni '
                                                                       'di `car` e `cdr` per '
                                                                       'navigare attraverso la '
                                                                       'struttura.\n'
                                                                       '\n'
                                                                       '#### Esempio: accesso agli '
                                                                       'elementi\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Spiegazione\n'
                                                                       '\n'
                                                                       '1. **`car nested-list`**:\n'
                                                                       '   - Recupera il primo '
                                                                       'elemento di `nested-list`, '
                                                                       'che è `(1 2)`.\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Recupera il primo '
                                                                       'elemento di `(1 2)`, che è '
                                                                       '`1`.\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Recupera il resto di '
                                                                       '`(1 2)`, ovvero `(2)`.\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**:\n'
                                                                       '   - Recupera il primo '
                                                                       'elemento di `(2)`, che è '
                                                                       '`2`.\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Esempio: accesso agli '
                                                                       'elementi da altre '
                                                                       'sottoliste\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Questo approccio consente '
                                                                       'di navigare e accedere '
                                                                       'sistematicamente a '
                                                                       'elementi specifici in un '
                                                                       'elenco nidificato, '
                                                                       'offrendo una potente '
                                                                       'flessibilità per lavorare '
                                                                       'con dati gerarchici.\n'
                                                                       '\n'
                                                                       '### Riepilogo\n'
                                                                       '\n'
                                                                       '- Le **Elenchi** in Scheme '
                                                                       'sono strutture dati '
                                                                       'versatili ed essenziali.\n'
                                                                       '- Utilizzare `list` per '
                                                                       'creare un elenco, `car` e '
                                                                       '`cdr` per accedere agli '
                                                                       'elementi e `cons` per '
                                                                       'costruire elenchi.\n'
                                                                       '- Procedure integrate come '
                                                                       '`length`, `append`, '
                                                                       '`reverse` e `list-ref` '
                                                                       'rendono le operazioni '
                                                                       'sugli elenchi semplici ed '
                                                                       'efficienti.\n'
                                                                       '- Gli elenchi possono '
                                                                       'essere nidificati, '
                                                                       'consentendo strutture di '
                                                                       'dati complesse per casi '
                                                                       "d'uso avanzati.",
                                                                 'ja': '---\n'
                                                                       'title: "リスト"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'Scheme では、**リスト** '
                                                                       'は値をグループ化するために使用される基本的なデータ構造です。リストは要素の順序付けられたコレクションであり、各要素は別のリストを含む任意の型にすることができます。リストは、Scheme '
                                                                       'でデータ '
                                                                       'ストレージとプログラム構造の両方に広く使用されています。\n'
                                                                       '\n'
                                                                       '### 例 1: 単純なリスト\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- 3 つの要素のリストを作成します: '
                                                                       '`1`、`2`、および `3`。\n'
                                                                       '\n'
                                                                       '結果: **`(1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### リスト要素へのアクセス\n'
                                                                       '\n'
                                                                       'リスト内の要素には、`car` および `cdr` '
                                                                       'プロシージャを使用してアクセスします。\n'
                                                                       '\n'
                                                                       '- `car` '
                                                                       'は、リストの最初の要素を取得します。\n'
                                                                       '- `cdr` は、リストの残りの部分 '
                                                                       '(最初の要素を除くすべて) を取得します。\n'
                                                                       '\n'
                                                                       '#### 例\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '結果:\n'
                                                                       '\n'
                                                                       '- `(car my-list)` は `1` '
                                                                       'を返します\n'
                                                                       '- `(cdr my-list)` は `(2 '
                                                                       '3)` を返します\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### 単純な再帰: リストの反復処理\n'
                                                                       '\n'
                                                                       'リストの `cdr` で `car` '
                                                                       'を再帰的に呼び出すことにより、リストを走査するまで各要素を '
                                                                       '1 '
                                                                       'つずつ処理できます。これは、多くのリスト処理アルゴリズムの基礎を形成します。\n'
                                                                       '\n'
                                                                       '#### 例: リストの各要素の出力\n'
                                                                       '\n'
                                                                       '以下は、リスト内のすべての要素を出力する単純な再帰関数です。\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **基本ケース:** リストが空の場合 '
                                                                       '(`null? lst`)、再帰を停止します。\n'
                                                                       '- **再帰的な場合:** 最初の要素 (`car '
                                                                       'lst`) '
                                                                       'を出力し、リストの残りの関数を呼び出します '
                                                                       '(`cdr lst`)。\n'
                                                                       '\n'
                                                                       '#### 使用例\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '出力:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       '結果:「完了」\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### 仕組み\n'
                                                                       '\n'
                                                                       '1. この関数は、`car` '
                                                                       'を使用してリストの最初の要素を取得し、それを処理します。\n'
                                                                       '2. '
                                                                       '次に、リストの残りの部分を使用して自分自身を呼び出します '
                                                                       '(`cdr`)。\n'
                                                                       '3. '
                                                                       'このプロセスは、リストが空になるまで繰り返されます '
                                                                       '(`null? lst`)。\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### 例 2: 混合型\n'
                                                                       '\n'
                                                                       'リストには、文字列、ブール値、数値、他のリスト、さらには式の結果など、さまざまなタイプの要素を含めることができます。\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- これにより、以下のリストが作成されます。\n'
                                                                       '  - 数字 (`42`)\n'
                                                                       '  - 文字列 (`"hello"`)\n'
                                                                       '  - ブール値 (`#t`)\n'
                                                                       '  - 別のリスト (`(1 2)`)\n'
                                                                       '  - 式の結果 (`(+ 3 4)`、`7` '
                                                                       'と評価される)\n'
                                                                       '\n'
                                                                       '結果: **`(42 "hello" #t (1 '
                                                                       '2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'これらの例は、Scheme '
                                                                       'のリストの多用途性を示し、リストがデータの整理と操作のための強力なツールとなることを示しています。\n'
                                                                       '\n'
                                                                       '### リストの構築\n'
                                                                       '\n'
                                                                       '`cons` '
                                                                       'プロシージャは、要素を既存のリストと組み合わせて新しいリストを構築するために使用されます。\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### 例\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- `0` をリスト `(1 2 3)` '
                                                                       'の先頭に追加します。\n'
                                                                       '\n'
                                                                       '結果: **`(0 1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### リストのチェック\n'
                                                                       '\n'
                                                                       '`list?` '
                                                                       'プロシージャは、指定された値がリストであるかどうかを確認します。\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### 例: リスト?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '結果:\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))` は '
                                                                       '`#t` (true) を返します\n'
                                                                       '- `(list? 42)` は `#f` (偽) '
                                                                       'を返します\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### リストの操作\n'
                                                                       '\n'
                                                                       'Scheme '
                                                                       'には、リストを操作するための次のような組み込みプロシージャがいくつか用意されています。\n'
                                                                       '\n'
                                                                       '- `length`: '
                                                                       'リスト内の要素の数を返します。\n'
                                                                       '- `append`: 2 つ以上のリストを 1 '
                                                                       'つに結合します。\n'
                                                                       '- `reverse`: '
                                                                       '要素を逆順にした新しいリストを返します。\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '結果:\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))` '
                                                                       'は `3` を返します\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))` は `(1 2 3 4)` '
                                                                       'を返します\n'
                                                                       '- `(reverse (list 1 2 3))` '
                                                                       'は `(3 2 1)` を返します#### '
                                                                       '`list-ref` を使用する\n'
                                                                       '\n'
                                                                       '`list-ref` '
                                                                       'プロシージャは、リストの指定されたインデックス (0 '
                                                                       'から始まるインデックス) にある要素を取得します。\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **`lst`**: 要素を取得するリスト。\n'
                                                                       '- **`index`**: どの要素を返すかを示す '
                                                                       '0 から始まるインデックス。\n'
                                                                       '\n'
                                                                       '##### 例: リスト参照\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '結果: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### ネストされたリスト\n'
                                                                       '\n'
                                                                       'Scheme '
                                                                       'のリストには他のリストを要素として含めることができ、入れ子構造を作成します。\n'
                                                                       '\n'
                                                                       '#### 例: ネストされたリストの作成\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- 3 '
                                                                       'つの要素のリストを作成します。各要素はそれ自体がリストです。\n'
                                                                       '\n'
                                                                       '結果: **`((1 2) (3 4) '
                                                                       '(5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### ネストされたデータへのアクセス\n'
                                                                       '\n'
                                                                       'ネストされたリスト内の要素にアクセスするには、`car` '
                                                                       'と `cdr` '
                                                                       'の組み合わせを使用して構造内を移動できます。\n'
                                                                       '\n'
                                                                       '#### 例: 要素へのアクセス\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### 説明\n'
                                                                       '\n'
                                                                       '1. **`car nested-list`**:\n'
                                                                       '   - `nested-list` の最初の要素 '
                                                                       '(`(1 2)`) を取得します。\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - `(1 2)` の最初の要素 (`1`) '
                                                                       'を取得します。\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - `(1 2)` の残り、つまり `(2)` '
                                                                       'を取得します。\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**:\n'
                                                                       '   - `(2)` の最初の要素 (`2`) '
                                                                       'を取得します。\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### 例: '
                                                                       '他のサブリストからの要素へのアクセス\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'このアプローチにより、ネストされたリスト内の特定の要素に体系的に移動してアクセスできるため、階層データを操作するための強力な柔軟性が得られます。\n'
                                                                       '\n'
                                                                       '### 概要\n'
                                                                       '\n'
                                                                       '- Scheme の **リスト** '
                                                                       'は多用途で不可欠なデータ構造です。\n'
                                                                       '- `list` '
                                                                       'を使用してリストを作成し、`car` および '
                                                                       '`cdr` を使用して要素にアクセスし、`cons` '
                                                                       'を使用してリストを構築します。\n'
                                                                       '- '
                                                                       '`length`、`append`、`reverse`、`list-ref` '
                                                                       'などの組み込みプロシージャにより、リスト操作が簡単かつ効率的になります。\n'
                                                                       '- '
                                                                       'リストはネストできるため、高度なユースケース向けに複雑なデータ構造が可能になります。',
                                                                 'ko': '---\n'
                                                                       'title: "리스트"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'Scheme에서 **목록**은 값을 그룹화하는 '
                                                                       '데 사용되는 기본 데이터 구조입니다. 목록은 각 '
                                                                       '요소가 다른 목록을 포함하여 모든 유형일 수 '
                                                                       '있는 순서가 지정된 요소 모음입니다. 목록은 '
                                                                       '데이터 저장 및 프로그램 구조 모두를 위해 '
                                                                       'Scheme에서 널리 사용됩니다.\n'
                                                                       '\n'
                                                                       '### 예시 1: 단순 목록\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- `1`, `2` 및 `3`의 세 가지 요소 '
                                                                       '목록을 생성합니다.\n'
                                                                       '\n'
                                                                       '결과: **`(1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### 목록 요소에 액세스하기\n'
                                                                       '\n'
                                                                       '목록의 요소는 `car` 및 `cdr` '
                                                                       '프로시저를 사용하여 액세스됩니다.\n'
                                                                       '\n'
                                                                       '- `car`은 목록의 첫 번째 요소를 '
                                                                       '검색합니다.\n'
                                                                       '- `cdr`은 목록의 나머지 부분(첫 번째 '
                                                                       '요소를 제외한 모든 항목)을 검색합니다.\n'
                                                                       '\n'
                                                                       '#### 예\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '결과:\n'
                                                                       '\n'
                                                                       '- `(car my-list)`은 `1`을 '
                                                                       '반환합니다.\n'
                                                                       '- `(cdr my-list)`은 `(2 '
                                                                       '3)`을 반환합니다.\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### 단순 재귀: 목록 반복\n'
                                                                       '\n'
                                                                       '목록의 `cdr`에서 `car`을 재귀적으로 '
                                                                       '호출하면 목록을 순회할 때까지 각 요소를 하나씩 '
                                                                       '처리할 수 있습니다. 이는 많은 목록 처리 '
                                                                       '알고리즘의 기초를 형성합니다.\n'
                                                                       '\n'
                                                                       '#### 예: 목록의 각 요소 인쇄\n'
                                                                       '\n'
                                                                       '다음은 목록의 모든 요소를 인쇄하는 간단한 재귀 '
                                                                       '함수입니다.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **기본 사례:** 목록이 비어 있는 '
                                                                       '경우(`null? lst`) 재귀를 '
                                                                       '중지합니다.\n'
                                                                       '- **재귀 사례:** 첫 번째 요소(`car '
                                                                       'lst`)를 인쇄한 다음 목록의 나머지 '
                                                                       '부분(`cdr lst`)에서 함수를 '
                                                                       '호출합니다.\n'
                                                                       '\n'
                                                                       '#### 사용 예\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '출력:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       '결과: "완료"\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### 작동 방식\n'
                                                                       '\n'
                                                                       '1. 함수는 `car`을 사용하여 목록의 첫 '
                                                                       '번째 요소를 검색하고 처리합니다.\n'
                                                                       '2. 그런 다음 나머지 목록(`cdr`)을 '
                                                                       '사용하여 자신을 호출합니다.\n'
                                                                       '3. 이 프로세스는 목록이 비어 있을 때까지 '
                                                                       '반복됩니다(`null? lst`).\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### 예시 2: 혼합 유형\n'
                                                                       '\n'
                                                                       '목록에는 문자열, 부울, 숫자, 기타 목록 또는 '
                                                                       '표현식 결과를 비롯한 다양한 유형의 요소가 '
                                                                       '포함될 수 있습니다.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- 다음을 포함하는 목록이 생성됩니다.\n'
                                                                       '  - 숫자(`42`)\n'
                                                                       '  - 문자열(`"hello"`)\n'
                                                                       '  - 부울(`#t`)\n'
                                                                       '  - 또 다른 목록 (`(1 2)`)\n'
                                                                       '  - 표현식의 결과(`(+ 3 4)`, '
                                                                       '`7`로 평가됨)\n'
                                                                       '\n'
                                                                       '결과: **`(42 "hello" #t (1 '
                                                                       '2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '이러한 예는 Scheme의 목록이 데이터를 '
                                                                       '구성하고 조작하기 위한 강력한 도구가 된다는 '
                                                                       '점을 보여줍니다.\n'
                                                                       '\n'
                                                                       '### 목록 구성\n'
                                                                       '\n'
                                                                       '`cons` 프로시저는 요소를 기존 목록과 '
                                                                       '결합하여 새 목록을 구성하는 데 사용됩니다.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### 예\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- `(1 2 3)` 목록의 시작 부분에 '
                                                                       '`0`을 추가합니다.\n'
                                                                       '\n'
                                                                       '결과: **`(0 1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### 목록 확인 중\n'
                                                                       '\n'
                                                                       '`list?` 프로시저는 주어진 값이 목록인지 '
                                                                       '확인합니다.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### 예: 목록?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '결과:\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))`은 '
                                                                       '`#t`을 반환합니다(true).\n'
                                                                       '- `(list? 42)`은 `#f`을 '
                                                                       '반환합니다(거짓).\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### 목록 작업\n'
                                                                       '\n'
                                                                       'Scheme은 다음을 포함하여 목록 작업을 위한 '
                                                                       '몇 가지 내장 프로시저를 제공합니다.\n'
                                                                       '\n'
                                                                       '- `length`: 목록의 요소 수를 '
                                                                       '반환합니다.\n'
                                                                       '- `append`: 두 개 이상의 목록을 '
                                                                       '하나로 결합합니다.\n'
                                                                       '- `reverse`: 요소가 역순으로 포함된 '
                                                                       '새 목록을 반환합니다.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '결과:\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))`은 '
                                                                       '`3`을 반환합니다.\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))`은 `(1 2 3 4)`을 '
                                                                       '반환합니다.\n'
                                                                       '- `(reverse (list 1 2 '
                                                                       '3))`은 `(3 2 1)`을 '
                                                                       '반환합니다.#### `list-ref` 사용\n'
                                                                       '\n'
                                                                       '`list-ref` 프로시저는 목록의 지정된 '
                                                                       '인덱스(0부터 시작하는 인덱스)에 있는 요소를 '
                                                                       '검색합니다.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **`lst`**: 요소를 검색할 '
                                                                       '목록입니다.\n'
                                                                       '- **`index`**: 반환할 요소를 '
                                                                       '나타내는 0부터 시작하는 인덱스입니다.\n'
                                                                       '\n'
                                                                       '##### 예: 목록-ref\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '결과: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### 중첩 목록\n'
                                                                       '\n'
                                                                       '구성표의 목록은 다른 목록을 요소로 포함하여 '
                                                                       '중첩 구조를 만들 수 있습니다.\n'
                                                                       '\n'
                                                                       '#### 예: 중첩 목록 만들기\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- 각 요소 자체가 목록인 세 가지 요소의 '
                                                                       '목록을 만듭니다.\n'
                                                                       '\n'
                                                                       '결과: **`((1 2) (3 4) '
                                                                       '(5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### 중첩된 데이터에 액세스\n'
                                                                       '\n'
                                                                       '중첩 목록 내의 요소에 액세스하려면 `car` '
                                                                       '및 `cdr` 조합을 사용하여 구조를 탐색할 수 '
                                                                       '있습니다.\n'
                                                                       '\n'
                                                                       '#### 예: 요소에 액세스하기\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### 설명\n'
                                                                       '\n'
                                                                       '1. **`car nested-list`**:\n'
                                                                       '   - `nested-list`의 첫 번째 '
                                                                       '요소인 `(1 2)`을 검색합니다.\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - `(1 2)`의 첫 번째 요소인 '
                                                                       '`1`을 검색합니다.\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - `(1 2)`의 나머지 부분인 '
                                                                       '`(2)`을 검색합니다.\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**:\n'
                                                                       '   - `(2)`의 첫 번째 요소인 `2`을 '
                                                                       '검색합니다.\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### 예: 다른 하위 목록의 요소에 액세스\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '이 접근 방식을 사용하면 중첩 목록의 특정 '
                                                                       '요소를 체계적으로 탐색하고 액세스할 수 있으므로 '
                                                                       '계층적 데이터 작업에 강력한 유연성을 '
                                                                       '제공합니다.\n'
                                                                       '\n'
                                                                       '### 요약\n'
                                                                       '\n'
                                                                       '- Scheme의 **리스트**는 다양하고 '
                                                                       '필수적인 데이터 구조입니다.\n'
                                                                       '- `list`을 사용하여 목록을 생성하고, '
                                                                       '`car` 및 `cdr`을 사용하여 요소에 '
                                                                       '접근하고, `cons`을 사용하여 목록을 '
                                                                       '구성합니다.\n'
                                                                       '- `length`, `append`, '
                                                                       '`reverse` 및 `list-ref`과 같은 '
                                                                       '내장 프로시저를 통해 목록 작업을 쉽고 '
                                                                       '효율적으로 수행할 수 있습니다.\n'
                                                                       '- 목록을 중첩할 수 있어 고급 사용 사례를 '
                                                                       '위한 복잡한 데이터 구조가 가능합니다.',
                                                                 'nl': '---\n'
                                                                       'title: "Lijsten"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'In Scheme is een **lijst** '
                                                                       'een fundamentele '
                                                                       'gegevensstructuur die '
                                                                       'wordt gebruikt om waarden '
                                                                       'te groeperen. Lijsten zijn '
                                                                       'geordende verzamelingen '
                                                                       'elementen waarbij elk '
                                                                       'element van elk type kan '
                                                                       'zijn, inclusief een andere '
                                                                       'lijst. Lijsten worden in '
                                                                       'Scheme veel gebruikt voor '
                                                                       'zowel gegevensopslag als '
                                                                       'programmastructuur.\n'
                                                                       '\n'
                                                                       '### Voorbeeld 1: '
                                                                       'Eenvoudige lijst\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Creëert een lijst met '
                                                                       'drie elementen: `1`, `2` '
                                                                       'en `3`.\n'
                                                                       '\n'
                                                                       'Resultaat: **`(1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Lijstelementen '
                                                                       'openen\n'
                                                                       '\n'
                                                                       'Elementen in een lijst '
                                                                       'zijn toegankelijk via de '
                                                                       'procedures `car` en '
                                                                       '`cdr`:\n'
                                                                       '\n'
                                                                       '- `car` haalt het eerste '
                                                                       'element van een lijst op.\n'
                                                                       '- `cdr` haalt de rest van '
                                                                       'de lijst op (alles behalve '
                                                                       'het eerste element).\n'
                                                                       '\n'
                                                                       '#### Voorbeelden\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultaat:\n'
                                                                       '\n'
                                                                       '- `(car my-list)` '
                                                                       'retourneert `1`\n'
                                                                       '- `(cdr my-list)` '
                                                                       'retourneert `(2 3)`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Eenvoudige recursie: '
                                                                       'itereren door een lijst\n'
                                                                       '\n'
                                                                       'Door `car` recursief aan '
                                                                       'te roepen op de `cdr` van '
                                                                       'een lijst, kunt u elk '
                                                                       'element één voor één '
                                                                       'verwerken totdat de lijst '
                                                                       'wordt doorlopen. Dit vormt '
                                                                       'de basis van veel '
                                                                       'algoritmen voor '
                                                                       'lijstverwerking.\n'
                                                                       '\n'
                                                                       '#### Voorbeeld: elk '
                                                                       'element van een lijst '
                                                                       'afdrukken\n'
                                                                       '\n'
                                                                       'Hier is een eenvoudige '
                                                                       'recursieve functie om elk '
                                                                       'element in een lijst af te '
                                                                       'drukken:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **Basisscenario:** Als '
                                                                       'de lijst leeg is (`null? '
                                                                       'lst`), stop dan de '
                                                                       'recursie.\n'
                                                                       '- **Recursief '
                                                                       'hoofdlettergebruik:** Druk '
                                                                       'het eerste element af '
                                                                       '(`car lst`) en roep '
                                                                       'vervolgens de functie op '
                                                                       'in de rest van de lijst '
                                                                       '(`cdr lst`).\n'
                                                                       '\n'
                                                                       '#### Voorbeeldgebruik\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Uitgang:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       'Resultaat: "klaar"\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Hoe het werkt\n'
                                                                       '\n'
                                                                       '1. De functie haalt het '
                                                                       'eerste element van de '
                                                                       'lijst op met `car` en '
                                                                       'verwerkt dit.\n'
                                                                       '2. Vervolgens roept het '
                                                                       'zichzelf aan met de rest '
                                                                       'van de lijst (`cdr`).\n'
                                                                       '3. Dit proces herhaalt '
                                                                       'zich totdat de lijst leeg '
                                                                       'is (`null? lst`).\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Voorbeeld 2: Gemengde '
                                                                       'typen\n'
                                                                       '\n'
                                                                       'Lijsten kunnen elementen '
                                                                       'van verschillende typen '
                                                                       'bevatten, waaronder '
                                                                       'tekenreeksen, booleans, '
                                                                       'getallen, andere lijsten '
                                                                       'of zelfs het resultaat van '
                                                                       'expressies:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Hierdoor ontstaat een '
                                                                       'lijst met:\n'
                                                                       '  - Een nummer (`42`)\n'
                                                                       '  - Een string '
                                                                       '(`"hello"`)\n'
                                                                       '  - Een boolean (`#t`)\n'
                                                                       '  - Nog een lijst (`(1 '
                                                                       '2)`)\n'
                                                                       '  - Het resultaat van een '
                                                                       'uitdrukking (`(+ 3 4)`, '
                                                                       'die resulteert in `7`)\n'
                                                                       '\n'
                                                                       'Resultaat: **`(42 "hello" '
                                                                       '#t (1 2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Deze voorbeelden '
                                                                       'demonstreren de '
                                                                       'veelzijdigheid van lijsten '
                                                                       'in Scheme, waardoor ze een '
                                                                       'krachtig hulpmiddel zijn '
                                                                       'voor het organiseren en '
                                                                       'manipuleren van gegevens.\n'
                                                                       '\n'
                                                                       '### Lijsten samenstellen\n'
                                                                       '\n'
                                                                       'De `cons` procedure wordt '
                                                                       'gebruikt om een nieuwe '
                                                                       'lijst samen te stellen '
                                                                       'door een element te '
                                                                       'combineren met een '
                                                                       'bestaande lijst.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Voorbeeld\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Voegt `0` toe aan het '
                                                                       'begin van de lijst `(1 2 '
                                                                       '3)`.\n'
                                                                       '\n'
                                                                       'Resultaat: **`(0 1 2 '
                                                                       '3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Controleren op '
                                                                       'lijsten\n'
                                                                       '\n'
                                                                       'De `list?` procedure '
                                                                       'controleert of een '
                                                                       'bepaalde waarde een lijst '
                                                                       'is.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Voorbeeld: lijst?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultaat:\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))` '
                                                                       'retourneert `#t` (waar)\n'
                                                                       '- `(list? 42)` retourneert '
                                                                       '`#f` (onwaar)\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Bewerkingen op '
                                                                       'lijsten\n'
                                                                       '\n'
                                                                       'Scheme biedt verschillende '
                                                                       'ingebouwde procedures voor '
                                                                       'het werken met lijsten, '
                                                                       'waaronder:\n'
                                                                       '\n'
                                                                       '- `length`: Geeft het '
                                                                       'aantal elementen in een '
                                                                       'lijst terug.\n'
                                                                       '- `append`: Combineert '
                                                                       'twee of meer lijsten in '
                                                                       'één.\n'
                                                                       '- `reverse`: Geeft een '
                                                                       'nieuwe lijst terug met '
                                                                       'elementen in omgekeerde '
                                                                       'volgorde.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultaat:\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))` '
                                                                       'retourneert `3`\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))` retourneert '
                                                                       '`(1 2 3 4)`\n'
                                                                       '- `(reverse (list 1 2 3))` '
                                                                       'retourneert `(3 2 1)`\n'
                                                                       '\n'
                                                                       '#### `list-ref` gebruiken\n'
                                                                       '\n'
                                                                       'De procedure `list-ref` '
                                                                       'haalt het element op bij '
                                                                       'een gespecificeerde index '
                                                                       'van een lijst (op nul '
                                                                       'gebaseerde index).\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **`lst`**: De lijst '
                                                                       'waaruit het element moet '
                                                                       'worden opgehaald.\n'
                                                                       '- **`index`**: een op nul '
                                                                       'gebaseerde index die '
                                                                       'aangeeft welk element moet '
                                                                       'worden geretourneerd.\n'
                                                                       '\n'
                                                                       '##### Voorbeeld: lijstref\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultaat: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Geneste lijsten\n'
                                                                       '\n'
                                                                       'Lijsten in Schema kunnen '
                                                                       'andere lijsten als '
                                                                       'elementen bevatten, '
                                                                       'waardoor een geneste '
                                                                       'structuur ontstaat.\n'
                                                                       '\n'
                                                                       '#### Voorbeeld: een '
                                                                       'geneste lijst maken\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Creëert een lijst van '
                                                                       'drie elementen, waarvan '
                                                                       'elk zelf een lijst is.\n'
                                                                       '\n'
                                                                       'Resultaat: **`((1 2) (3 4) '
                                                                       '(5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Toegang tot geneste '
                                                                       'gegevens\n'
                                                                       '\n'
                                                                       'Om toegang te krijgen tot '
                                                                       'elementen binnen een '
                                                                       'geneste lijst, kunt u '
                                                                       'combinaties van `car` en '
                                                                       '`cdr` gebruiken om door de '
                                                                       'structuur te navigeren.\n'
                                                                       '\n'
                                                                       '#### Voorbeeld: toegang '
                                                                       'tot elementen\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Uitleg\n'
                                                                       '\n'
                                                                       '1. **`car nested-list`**:\n'
                                                                       '   - Haalt het eerste '
                                                                       'element van `nested-list` '
                                                                       'op, namelijk `(1 2)`.\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Haalt het eerste '
                                                                       'element van `(1 2)` op, '
                                                                       'namelijk `1`.\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Haalt de rest van `(1 '
                                                                       '2)` op, wat `(2)` is.\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**:\n'
                                                                       '   - Haalt het eerste '
                                                                       'element van `(2)` op, '
                                                                       'namelijk `2`.\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Voorbeeld: toegang '
                                                                       'krijgen tot elementen uit '
                                                                       'andere sublijsten\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Met deze aanpak kunt u '
                                                                       'systematisch navigeren en '
                                                                       'toegang krijgen tot '
                                                                       'specifieke elementen in '
                                                                       'een geneste lijst, wat een '
                                                                       'krachtige flexibiliteit '
                                                                       'biedt bij het werken met '
                                                                       'hiërarchische gegevens.\n'
                                                                       '\n'
                                                                       '### Samenvatting\n'
                                                                       '\n'
                                                                       '- **Lijsten** in Scheme '
                                                                       'zijn veelzijdige en '
                                                                       'essentiële '
                                                                       'datastructuren.\n'
                                                                       '- Gebruik `list` om een '
                                                                       '\u200b\u200blijst te '
                                                                       'maken, `car` en `cdr` om '
                                                                       'toegang te krijgen tot '
                                                                       'elementen, en `cons` om '
                                                                       'lijsten samen te stellen.\n'
                                                                       '- Ingebouwde procedures '
                                                                       'zoals `length`, `append`, '
                                                                       '`reverse` en `list-ref` '
                                                                       'maken lijstbewerkingen '
                                                                       'eenvoudig en efficiënt.\n'
                                                                       '- Lijsten kunnen worden '
                                                                       'genest, waardoor complexe '
                                                                       'datastructuren voor '
                                                                       'geavanceerde '
                                                                       "gebruiksscenario's "
                                                                       'mogelijk worden.',
                                                                 'pl': '---\n'
                                                                       'title: "Listy"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'W schemacie **lista** jest '
                                                                       'podstawową strukturą '
                                                                       'danych używaną do '
                                                                       'grupowania wartości. Listy '
                                                                       'to uporządkowane zbiory '
                                                                       'elementów, z których każdy '
                                                                       'może być dowolnego typu, '
                                                                       'łącznie z inną listą. '
                                                                       'Listy są szeroko stosowane '
                                                                       'w schemacie zarówno do '
                                                                       'przechowywania danych, jak '
                                                                       'i struktury programu.\n'
                                                                       '\n'
                                                                       '### Przykład 1: Prosta '
                                                                       'lista\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Tworzy listę trzech '
                                                                       'elementów: `1`, `2` i '
                                                                       '`3`.\n'
                                                                       '\n'
                                                                       'Wynik: **`(1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Dostęp do elementów '
                                                                       'listy\n'
                                                                       '\n'
                                                                       'Dostęp do elementów listy '
                                                                       'uzyskuje się za pomocą '
                                                                       'procedur `car` i `cdr`:\n'
                                                                       '\n'
                                                                       '- `car` pobiera pierwszy '
                                                                       'element listy.\n'
                                                                       '- `cdr` pobiera resztę '
                                                                       'listy (wszystko oprócz '
                                                                       'pierwszego elementu).\n'
                                                                       '\n'
                                                                       '#### Przykłady\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Wynik:\n'
                                                                       '\n'
                                                                       '- `(car my-list)` zwraca '
                                                                       '`1`\n'
                                                                       '- `(cdr my-list)` zwraca '
                                                                       '`(2 3)`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Prosta rekurencja: '
                                                                       'iteracja po liście\n'
                                                                       '\n'
                                                                       'Wywołując rekurencyjnie '
                                                                       '`car` na `cdr` listy, '
                                                                       'możesz przetwarzać każdy '
                                                                       'element jeden po drugim, '
                                                                       'aż do przejścia przez '
                                                                       'listę. Stanowi to podstawę '
                                                                       'wielu algorytmów '
                                                                       'przetwarzania list.\n'
                                                                       '\n'
                                                                       '#### Przykład: drukowanie '
                                                                       'każdego elementu listy\n'
                                                                       '\n'
                                                                       'Oto prosta funkcja '
                                                                       'rekurencyjna umożliwiająca '
                                                                       'wydrukowanie każdego '
                                                                       'elementu listy:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **Przypadek '
                                                                       'podstawowy:** Jeśli lista '
                                                                       'jest pusta (`null? lst`), '
                                                                       'zatrzymaj rekursję.\n'
                                                                       '- **Przypadek '
                                                                       'rekurencyjny:** Wydrukuj '
                                                                       'pierwszy element (`car '
                                                                       'lst`), a następnie wywołaj '
                                                                       'funkcję na pozostałej '
                                                                       'części listy (`cdr lst`).\n'
                                                                       '\n'
                                                                       '#### Przykładowe użycie\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Dane wyjściowe:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       'Wynik: „gotowe”\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Jak to działa\n'
                                                                       '\n'
                                                                       '1. Funkcja pobiera '
                                                                       'pierwszy element listy za '
                                                                       'pomocą `car` i przetwarza '
                                                                       'go.\n'
                                                                       '2. Następnie wywołuje '
                                                                       'siebie wraz z resztą listy '
                                                                       '(`cdr`).\n'
                                                                       '3. Ten proces powtarza '
                                                                       'się, aż lista będzie pusta '
                                                                       '(`null? lst`).\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Przykład 2: Typy '
                                                                       'mieszane\n'
                                                                       '\n'
                                                                       'Listy mogą zawierać '
                                                                       'elementy różnych typów, w '
                                                                       'tym ciągi znaków, wartości '
                                                                       'logiczne, liczby, inne '
                                                                       'listy, a nawet wyniki '
                                                                       'wyrażeń:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Spowoduje to utworzenie '
                                                                       'listy zawierającej:\n'
                                                                       '  - Liczba (`42`)\n'
                                                                       '  - Ciąg (`"hello"`)\n'
                                                                       '  - Wartość logiczna '
                                                                       '(`#t`)\n'
                                                                       '  - Kolejna lista (`(1 '
                                                                       '2)`)\n'
                                                                       '  - Wynik wyrażenia (`(+ 3 '
                                                                       '4)`, którego wynikiem jest '
                                                                       '`7`)\n'
                                                                       '\n'
                                                                       'Wynik: **`(42 "hello" #t '
                                                                       '(1 2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Te przykłady pokazują '
                                                                       'wszechstronność list w '
                                                                       'Scheme, co czyni je '
                                                                       'potężnym narzędziem do '
                                                                       'organizowania danych i '
                                                                       'manipulowania nimi.\n'
                                                                       '\n'
                                                                       '### Konstruowanie list\n'
                                                                       '\n'
                                                                       'Procedura `cons` służy do '
                                                                       'konstruowania nowej listy '
                                                                       'poprzez połączenie '
                                                                       'elementu z istniejącą '
                                                                       'listą.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Przykład\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Dodaje `0` na początek '
                                                                       'listy `(1 2 3)`.\n'
                                                                       '\n'
                                                                       'Wynik: **`(0 1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Sprawdzanie list\n'
                                                                       '\n'
                                                                       'Procedura `list?` '
                                                                       'sprawdza, czy dana wartość '
                                                                       'jest listą.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Przykład: lista?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Wynik:\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))` '
                                                                       'zwraca `#t` (true)\n'
                                                                       '- `(list? 42)` zwraca `#f` '
                                                                       '(fałsz)\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Operacje na listach\n'
                                                                       '\n'
                                                                       'Scheme udostępnia kilka '
                                                                       'wbudowanych procedur pracy '
                                                                       'z listami, w tym:\n'
                                                                       '\n'
                                                                       '- `length`: Zwraca liczbę '
                                                                       'elementów na liście.\n'
                                                                       '- `append`: Łączy dwie lub '
                                                                       'więcej list w jedną.\n'
                                                                       '- `reverse`: Zwraca nową '
                                                                       'listę z elementami w '
                                                                       'odwrotnej kolejności.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Wynik:\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))` '
                                                                       'zwraca `3`\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))` zwraca `(1 2 '
                                                                       '3 4)`\n'
                                                                       '- `(reverse (list 1 2 3))` '
                                                                       'zwraca `(3 2 1)`\n'
                                                                       '\n'
                                                                       '#### Korzystanie z '
                                                                       '`list-ref`\n'
                                                                       '\n'
                                                                       'Procedura `list-ref` '
                                                                       'pobiera element o '
                                                                       'określonym indeksie listy '
                                                                       '(indeks liczony od zera).\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **`lst`**: Lista, z '
                                                                       'której chcesz pobrać '
                                                                       'element.\n'
                                                                       '- **`index`**: Indeks od '
                                                                       'zera wskazujący, który '
                                                                       'element ma zostać '
                                                                       'zwrócony.\n'
                                                                       '\n'
                                                                       '##### Przykład: lista-ref\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Wynik: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Listy zagnieżdżone\n'
                                                                       '\n'
                                                                       'Listy w schemacie mogą '
                                                                       'zawierać inne listy jako '
                                                                       'elementy, tworząc '
                                                                       'zagnieżdżoną strukturę.\n'
                                                                       '\n'
                                                                       '#### Przykład: tworzenie '
                                                                       'listy zagnieżdżonej\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Tworzy listę trzech '
                                                                       'elementów, z których każdy '
                                                                       'sam jest listą.\n'
                                                                       '\n'
                                                                       'Wynik: **`((1 2) (3 4) '
                                                                       '(5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Dostęp do danych '
                                                                       'zagnieżdżonych\n'
                                                                       '\n'
                                                                       'Aby uzyskać dostęp do '
                                                                       'elementów na zagnieżdżonej '
                                                                       'liście, możesz użyć '
                                                                       'kombinacji `car` i `cdr`, '
                                                                       'aby poruszać się po '
                                                                       'strukturze.\n'
                                                                       '\n'
                                                                       '#### Przykład: uzyskiwanie '
                                                                       'dostępu do elementów\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Wyjaśnienie\n'
                                                                       '\n'
                                                                       '1. **`car nested-list`**:\n'
                                                                       '   - Pobiera pierwszy '
                                                                       'element `nested-list`, '
                                                                       'którym jest `(1 2)`.\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Pobiera pierwszy '
                                                                       'element `(1 2)`, którym '
                                                                       'jest `1`.\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Pobiera resztę `(1 '
                                                                       '2)`, czyli `(2)`.\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**:\n'
                                                                       '   - Pobiera pierwszy '
                                                                       'element `(2)`, którym jest '
                                                                       '`2`.\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Przykład: uzyskiwanie '
                                                                       'dostępu do elementów z '
                                                                       'innych podlist\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Takie podejście umożliwia '
                                                                       'systematyczne nawigowanie '
                                                                       'i uzyskiwanie dostępu do '
                                                                       'określonych elementów na '
                                                                       'zagnieżdżonej liście, '
                                                                       'zapewniając dużą '
                                                                       'elastyczność pracy z '
                                                                       'danymi hierarchicznymi.\n'
                                                                       '\n'
                                                                       '### Podsumowanie\n'
                                                                       '\n'
                                                                       '- **Listy** w schemacie to '
                                                                       'wszechstronne i niezbędne '
                                                                       'struktury danych.\n'
                                                                       '- Użyj `list`, aby '
                                                                       'utworzyć listę, `car` i '
                                                                       '`cdr`, aby uzyskać dostęp '
                                                                       'do elementów, oraz `cons`, '
                                                                       'aby skonstruować listy.\n'
                                                                       '- Wbudowane procedury, '
                                                                       'takie jak `length`, '
                                                                       '`append`, `reverse` i '
                                                                       '`list-ref` sprawiają, że '
                                                                       'operacje na listach są '
                                                                       'łatwe i wydajne.\n'
                                                                       '- Listy można zagnieżdżać, '
                                                                       'co umożliwia tworzenie '
                                                                       'złożonych struktur danych '
                                                                       'w zaawansowanych '
                                                                       'przypadkach.',
                                                                 'pt-br': '---\n'
                                                                          'title: "Listas"\n'
                                                                          'type: docs\n'
                                                                          'weight: 4\n'
                                                                          '---\n'
                                                                          'No Scheme, uma '
                                                                          '**lista** é uma '
                                                                          'estrutura de dados '
                                                                          'fundamental usada para '
                                                                          'agrupar valores. Listas '
                                                                          'são coleções ordenadas '
                                                                          'de elementos onde cada '
                                                                          'elemento pode ser de '
                                                                          'qualquer tipo, '
                                                                          'incluindo outra lista. '
                                                                          'As listas são '
                                                                          'amplamente utilizadas '
                                                                          'no Scheme tanto para '
                                                                          'armazenamento de dados '
                                                                          'quanto para estrutura '
                                                                          'de programa.\n'
                                                                          '\n'
                                                                          '### Exemplo 1: Lista '
                                                                          'Simples\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list 1 2 3)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- Cria uma lista de '
                                                                          'três elementos: `1`, '
                                                                          '`2` e `3`.\n'
                                                                          '\n'
                                                                          'Resultado: **`(1 2 '
                                                                          '3)`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### Acessando '
                                                                          'Elementos da Lista\n'
                                                                          '\n'
                                                                          'Os elementos de uma '
                                                                          'lista são acessados '
                                                                          'usando os procedimentos '
                                                                          '`car` e `cdr`:\n'
                                                                          '\n'
                                                                          '- `car` recupera o '
                                                                          'primeiro elemento de '
                                                                          'uma lista.\n'
                                                                          '- `cdr` recupera o '
                                                                          'resto da lista (tudo '
                                                                          'exceto o primeiro '
                                                                          'elemento).\n'
                                                                          '\n'
                                                                          '#### Exemplos\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(define my-list (list 1 '
                                                                          '2 3))\n'
                                                                          '(car my-list)  ; Ruft '
                                                                          'das erste Element ab\n'
                                                                          '(cdr my-list)  ; Ruft '
                                                                          'den Rest der Liste ab\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          'Resultado:\n'
                                                                          '\n'
                                                                          '- `(car my-list)` '
                                                                          'retorna `1`\n'
                                                                          '- `(cdr my-list)` '
                                                                          'retorna `(2 3)`\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### Recursão simples: '
                                                                          'iterando por meio de '
                                                                          'uma lista\n'
                                                                          '\n'
                                                                          'Chamando recursivamente '
                                                                          '`car` no `cdr` de uma '
                                                                          'lista, você pode '
                                                                          'processar cada elemento '
                                                                          'um por um até que a '
                                                                          'lista seja percorrida. '
                                                                          'This forms the basis of '
                                                                          'many list-processing '
                                                                          'algorithms.\n'
                                                                          '\n'
                                                                          '#### Exemplo: '
                                                                          'Imprimindo cada '
                                                                          'elemento de uma lista\n'
                                                                          '\n'
                                                                          'Aqui está uma função '
                                                                          'recursiva simples para '
                                                                          'imprimir todos os '
                                                                          'elementos de uma '
                                                                          'lista:\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(define (print-elements '
                                                                          'lst)\n'
                                                                          '  (if (null? lst)\n'
                                                                          '    (lumi-message '
                                                                          '"done")\n'
                                                                          '    (begin\n'
                                                                          '      (lumi-message '
                                                                          '(number->string (car '
                                                                          'lst))) ;; Erstes '
                                                                          'Element ausgeben\n'
                                                                          '      (print-elements '
                                                                          '(cdr '
                                                                          'lst)))))             ;; '
                                                                          'Rest der Liste '
                                                                          'verarbeiten\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- **Caso base:** Se a '
                                                                          'lista estiver vazia '
                                                                          '(`null? lst`), pare a '
                                                                          'recursão.\n'
                                                                          '- **Caso recursivo:** '
                                                                          'Imprima o primeiro '
                                                                          'elemento (`car lst`) e '
                                                                          'depois chame a função '
                                                                          'no restante da lista '
                                                                          '(`cdr lst`).\n'
                                                                          '\n'
                                                                          '#### Exemplo de uso\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(print-elements (list 1 '
                                                                          '2 3))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          'Saída:\n'
                                                                          '\n'
                                                                          '-`"1"`\n'
                                                                          '- `"2"`\n'
                                                                          '- `"3"`\n'
                                                                          '\n'
                                                                          'Resultado: "concluído"\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### Como funciona\n'
                                                                          '\n'
                                                                          '1. A função recupera o '
                                                                          'primeiro elemento da '
                                                                          'lista usando `car` e o '
                                                                          'processa.\n'
                                                                          '2. Em seguida, ele '
                                                                          'chama a si mesmo com o '
                                                                          'restante da lista '
                                                                          '(`cdr`).\n'
                                                                          '3. Este processo se '
                                                                          'repete até que a lista '
                                                                          'fique vazia (`null? '
                                                                          'lst`).\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### Exemplo 2: Tipos '
                                                                          'mistos\n'
                                                                          '\n'
                                                                          'As listas podem incluir '
                                                                          'elementos de diferentes '
                                                                          'tipos, incluindo '
                                                                          'strings, booleanos, '
                                                                          'números, outras listas '
                                                                          'ou até mesmo o '
                                                                          'resultado de '
                                                                          'expressões:\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list 42 "hello" #t '
                                                                          '(list 1 2) (+ 3 4))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- Isso cria uma lista '
                                                                          'com:\n'
                                                                          '  - Um número (`42`)\n'
                                                                          '  - Uma string '
                                                                          '(`"hello"`)\n'
                                                                          '  - Um booleano '
                                                                          '(@LUMI_TOKEN_40@@)\n'
                                                                          '  - Outra lista (`(1 '
                                                                          '2)`)\n'
                                                                          '  - O resultado de uma '
                                                                          'expressão (`(+ 3 4)`, '
                                                                          'que é avaliada como '
                                                                          '`7`)\n'
                                                                          '\n'
                                                                          'Resultado: **`(42 '
                                                                          '"hello" #t (1 2) 7)`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          'Esses exemplos '
                                                                          'demonstram a '
                                                                          'versatilidade das '
                                                                          'listas no Scheme, '
                                                                          'tornando-as uma '
                                                                          'ferramenta poderosa '
                                                                          'para organizar e '
                                                                          'manipular dados.\n'
                                                                          '\n'
                                                                          '### Construindo Listas\n'
                                                                          '\n'
                                                                          'O procedimento `cons` é '
                                                                          'usado para construir '
                                                                          'uma nova lista '
                                                                          'combinando um elemento '
                                                                          'com uma lista '
                                                                          'existente.\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(cons new-element '
                                                                          'existing-list)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '#### Exemplo\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(cons 0 (list 1 2 3))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- Adiciona `0` ao '
                                                                          'início da lista `(1 2 '
                                                                          '3)`.\n'
                                                                          '\n'
                                                                          'Resultado: **`(0 1 2 '
                                                                          '3)`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### Verificando listas\n'
                                                                          '\n'
                                                                          'O procedimento `list?` '
                                                                          'verifica se um '
                                                                          'determinado valor é uma '
                                                                          'lista.\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list? value)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '#### Exemplo: lista?\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list? (list 1 2 3))  ; '
                                                                          'Prüft, ob (list 1 2 3) '
                                                                          'eine Liste ist\n'
                                                                          '(list? 42)            ; '
                                                                          'Prüft, ob 42 eine Liste '
                                                                          'ist\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          'Resultado:\n'
                                                                          '\n'
                                                                          '- `(list? (list 1 2 '
                                                                          '3))` retorna `#t` '
                                                                          '(verdadeiro)\n'
                                                                          '- `(list? 42)` retorna '
                                                                          '`#f` (falso)\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### Operações em '
                                                                          'listas\n'
                                                                          '\n'
                                                                          'O Scheme fornece vários '
                                                                          'procedimentos '
                                                                          'integrados para '
                                                                          'trabalhar com listas, '
                                                                          'incluindo:\n'
                                                                          '\n'
                                                                          '- `length`: Retorna o '
                                                                          'número de elementos de '
                                                                          'uma lista.\n'
                                                                          '- `append`: Combina '
                                                                          'duas ou mais listas em '
                                                                          'uma.\n'
                                                                          '- `reverse`: Retorna '
                                                                          'uma nova lista com '
                                                                          'elementos em ordem '
                                                                          'inversa.\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(length (list 1 2 '
                                                                          '3))          ; Gibt 3 '
                                                                          'zurück\n'
                                                                          '(append (list 1 2) '
                                                                          '(list 3 4)) ; Gibt (1 2 '
                                                                          '3 4) zurück\n'
                                                                          '(reverse (list 1 2 '
                                                                          '3))         ; Gibt (3 2 '
                                                                          '1) zurück\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          'Resultado:\n'
                                                                          '\n'
                                                                          '- `(length (list 1 2 '
                                                                          '3))` retorna `3`\n'
                                                                          '- `(append (list 1 2) '
                                                                          '(list 3 4))` retorna '
                                                                          '`(1 2 3 4)`\n'
                                                                          '- `(reverse (list 1 2 '
                                                                          '3))` retorna `(3 2 1)`\n'
                                                                          '\n'
                                                                          '#### Usando `list-ref`\n'
                                                                          '\n'
                                                                          'O procedimento '
                                                                          '`list-ref` recupera o '
                                                                          'elemento em um índice '
                                                                          'especificado de uma '
                                                                          'lista (índice baseado '
                                                                          'em zero).\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list-ref lst index)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- **`lst`**: A lista da '
                                                                          'qual recuperar o '
                                                                          'elemento.\n'
                                                                          '- **`index`**: Um '
                                                                          'índice baseado em zero '
                                                                          'indicando qual elemento '
                                                                          'retornar.\n'
                                                                          '\n'
                                                                          '##### Exemplo: '
                                                                          'ref-lista\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list-ref (list 10 20 '
                                                                          '30 40) 2)  ; Ruft das '
                                                                          'Element an Index 2 ab\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          'Resultado: `30`\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### Listas aninhadas\n'
                                                                          '\n'
                                                                          'As listas no esquema '
                                                                          'podem conter outras '
                                                                          'listas como elementos, '
                                                                          'criando uma estrutura '
                                                                          'aninhada.\n'
                                                                          '\n'
                                                                          '#### Exemplo: Criando '
                                                                          'uma lista aninhada\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(define nested-list '
                                                                          '(list (list 1 2) (list '
                                                                          '3 4) (list 5)))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- Cria uma lista de '
                                                                          'três elementos, cada um '
                                                                          'dos quais é uma lista.\n'
                                                                          '\n'
                                                                          'Resultado: **`((1 2) (3 '
                                                                          '4) (5))`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### Acessando dados '
                                                                          'aninhados\n'
                                                                          '\n'
                                                                          'Para acessar elementos '
                                                                          'em uma lista aninhada, '
                                                                          'você pode usar '
                                                                          'combinações de `car` e '
                                                                          '`cdr` para navegar pela '
                                                                          'estrutura.\n'
                                                                          '\n'
                                                                          '#### Exemplo: Acessando '
                                                                          'Elementos\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(car '
                                                                          'nested-list)              '
                                                                          '; Ruft das erste '
                                                                          'Element ab: (1 2)\n'
                                                                          '(car (car '
                                                                          'nested-list))        ; '
                                                                          'Ruft das erste Element '
                                                                          'ab of the first '
                                                                          'sublist: 1\n'
                                                                          '(cdr (car '
                                                                          'nested-list))        ; '
                                                                          'Ruft den Rest der '
                                                                          'ersten Teilliste ab: '
                                                                          '(2)\n'
                                                                          '(car (cdr (car '
                                                                          'nested-list)))  ; Ruft '
                                                                          'das zweite Element der '
                                                                          'ersten Teilliste ab: 2\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### Explicação\n'
                                                                          '\n'
                                                                          '1. **`car '
                                                                          'nested-list`**:\n'
                                                                          '   - Recupera o '
                                                                          'primeiro elemento de '
                                                                          '`nested-list`, que é '
                                                                          '`(1 2)`.\n'
                                                                          '\n'
                                                                          '2. **`car (car '
                                                                          'nested-list)`**:\n'
                                                                          '   - Recupera o '
                                                                          'primeiro elemento de '
                                                                          '`(1 2)`, que é `1`.\n'
                                                                          '\n'
                                                                          '3. **`cdr (car '
                                                                          'nested-list)`**:\n'
                                                                          '   - Recupera o resto '
                                                                          'de `(1 2)`, que é '
                                                                          '`(2)`.\n'
                                                                          '\n'
                                                                          '4. **`car (cdr (car '
                                                                          'nested-list))`**:\n'
                                                                          '   - Recupera o '
                                                                          'primeiro elemento de '
                                                                          '`(2)`, que é `2`.\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### Exemplo: acessando '
                                                                          'elementos de outras '
                                                                          'sublistas\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(car (cdr '
                                                                          'nested-list))        ; '
                                                                          'Ruft die zweite '
                                                                          'Teilliste ab: (3 4)\n'
                                                                          '(car (car (cdr '
                                                                          'nested-list)))  ; Ruft '
                                                                          'das erste Element ab of '
                                                                          'the second sublist: 3\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          'Essa abordagem permite '
                                                                          'navegar e acessar '
                                                                          'sistematicamente '
                                                                          'elementos específicos '
                                                                          'em uma lista aninhada, '
                                                                          'proporcionando '
                                                                          'flexibilidade poderosa '
                                                                          'para trabalhar com '
                                                                          'dados hierárquicos.\n'
                                                                          '\n'
                                                                          '### Resumo\n'
                                                                          '\n'
                                                                          '- **Listas** em Scheme '
                                                                          'são estruturas de dados '
                                                                          'versáteis e '
                                                                          'essenciais.\n'
                                                                          '- Use `list` para criar '
                                                                          'uma lista, `car` e '
                                                                          '`cdr` para acessar '
                                                                          'elementos e `cons` para '
                                                                          'construir listas.\n'
                                                                          '- Procedimentos '
                                                                          'integrados como '
                                                                          '`length`, `append`, '
                                                                          '`reverse` e `list-ref` '
                                                                          'tornam as operações de '
                                                                          'lista fáceis e '
                                                                          'eficientes.\n'
                                                                          '- As listas podem ser '
                                                                          'aninhadas, permitindo '
                                                                          'estruturas de dados '
                                                                          'complexas para casos de '
                                                                          'uso avançados.',
                                                                 'ru': '---\n'
                                                                       'title: "Списки"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'В Scheme **список**\xa0— '
                                                                       'это фундаментальная '
                                                                       'структура данных, '
                                                                       'используемая для '
                                                                       'группировки значений. '
                                                                       'Списки — это упорядоченные '
                                                                       'коллекции элементов, где '
                                                                       'каждый элемент может быть '
                                                                       'любого типа, включая '
                                                                       'другой список. Списки '
                                                                       'широко используются в '
                                                                       'Scheme как для хранения '
                                                                       'данных, так и для '
                                                                       'структуры программы.\n'
                                                                       '\n'
                                                                       '### Example 1: Simple '
                                                                       'List\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Создает список из трех '
                                                                       'элементов: `1`, `2` и '
                                                                       '`3`.\n'
                                                                       '\n'
                                                                       'Результат: **`(1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Доступ к элементам '
                                                                       'списка\n'
                                                                       '\n'
                                                                       'Доступ к элементам списка '
                                                                       'осуществляется с помощью '
                                                                       'процедур `car` и `cdr`:\n'
                                                                       '\n'
                                                                       '- `car` извлекает первый '
                                                                       'элемент списка.\n'
                                                                       '- `cdr` извлекает '
                                                                       'остальную часть списка '
                                                                       '(все, кроме первого '
                                                                       'элемента).\n'
                                                                       '\n'
                                                                       '#### Примеры\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Результат:\n'
                                                                       '\n'
                                                                       '- `(car my-list)` '
                                                                       'возвращает `1`\n'
                                                                       '- `(cdr my-list)` '
                                                                       'возвращает `(2 3)`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Простая рекурсия: '
                                                                       'обход списка\n'
                                                                       '\n'
                                                                       'Рекурсивно вызывая `car` '
                                                                       'для `cdr` списка, вы '
                                                                       'можете обрабатывать каждый '
                                                                       'элемент один за другим, '
                                                                       'пока список не будет '
                                                                       'пройден. Это составляет '
                                                                       'основу многих алгоритмов '
                                                                       'обработки списков.\n'
                                                                       '\n'
                                                                       '#### Пример: печать '
                                                                       'каждого элемента списка\n'
                                                                       '\n'
                                                                       'Вот простая рекурсивная '
                                                                       'функция для печати каждого '
                                                                       'элемента списка:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **Базовый случай:** Если '
                                                                       'список пуст (`null? lst`), '
                                                                       'остановите рекурсию.\n'
                                                                       '- **Рекурсивный случай:** '
                                                                       'Распечатайте первый '
                                                                       'элемент (`car lst`), затем '
                                                                       'вызовите функцию для '
                                                                       'остальной части списка '
                                                                       '(`cdr lst`).\n'
                                                                       '\n'
                                                                       '#### Пример использования\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Выход:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       'Результат: «готово»\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Как это работает\n'
                                                                       '\n'
                                                                       '1. Функция извлекает '
                                                                       'первый элемент списка с '
                                                                       'помощью `car` и '
                                                                       'обрабатывает его.\n'
                                                                       '2. Затем он вызывает себя '
                                                                       'вместе с остальной частью '
                                                                       'списка (`cdr`).\n'
                                                                       '3. Этот процесс '
                                                                       'повторяется до тех пор, '
                                                                       'пока список не станет '
                                                                       'пустым (`null? lst`).\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Пример 2: смешанные '
                                                                       'типы\n'
                                                                       '\n'
                                                                       'Списки могут включать '
                                                                       'элементы разных типов, '
                                                                       'включая строки, логические '
                                                                       'значения, числа, другие '
                                                                       'списки или даже результаты '
                                                                       'выражений:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Это создает список с:\n'
                                                                       '  - Номер (`42`)\n'
                                                                       '  - Строка (`"hello"`)\n'
                                                                       '  - Логическое значение '
                                                                       '(`#t`)\n'
                                                                       '  - Еще один список (`(1 '
                                                                       '2)`)\n'
                                                                       '  - Результат выражения '
                                                                       '(`(+ 3 4)`, которое имеет '
                                                                       'значение `7`)\n'
                                                                       '\n'
                                                                       'Результат: **`(42 "hello" '
                                                                       '#t (1 2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Эти примеры демонстрируют '
                                                                       'универсальность списков в '
                                                                       'Scheme, что делает их '
                                                                       'мощным инструментом для '
                                                                       'организации данных и '
                                                                       'управления ими.\n'
                                                                       '\n'
                                                                       '### Создание списков\n'
                                                                       '\n'
                                                                       'Процедура `cons` '
                                                                       'используется для создания '
                                                                       'нового списка путем '
                                                                       'объединения элемента с '
                                                                       'существующим списком.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Пример\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Добавляет `0` в начало '
                                                                       'списка `(1 2 3)`.\n'
                                                                       '\n'
                                                                       'Результат: **`(0 1 2 '
                                                                       '3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Проверка списков\n'
                                                                       '\n'
                                                                       'Процедура `list?` '
                                                                       'проверяет, является ли '
                                                                       'данное значение списком.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Пример: список?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Результат:\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))` '
                                                                       'возвращает `#t` (истина)\n'
                                                                       '- `(list? 42)` возвращает '
                                                                       '`#f` (ложь)\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Операции со списками\n'
                                                                       '\n'
                                                                       'Scheme предоставляет '
                                                                       'несколько встроенных '
                                                                       'процедур для работы со '
                                                                       'списками, в том числе:\n'
                                                                       '\n'
                                                                       '- `length`: возвращает '
                                                                       'количество элементов в '
                                                                       'списке.\n'
                                                                       '- `append`: объединяет два '
                                                                       'или более списков в один.\n'
                                                                       '- `reverse`: возвращает '
                                                                       'новый список с элементами '
                                                                       'в обратном порядке.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Результат:\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))` '
                                                                       'возвращает `3`\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))` возвращает '
                                                                       '`(1 2 3 4)`\n'
                                                                       '- `(reverse (list 1 2 3))` '
                                                                       'возвращает `(3 2 1)`\n'
                                                                       '\n'
                                                                       '#### Использование '
                                                                       '`list-ref`\n'
                                                                       '\n'
                                                                       'Процедура `list-ref` '
                                                                       'извлекает элемент по '
                                                                       'указанному индексу списка '
                                                                       '(индекс, начинающийся с '
                                                                       'нуля).\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **`lst`**: список, из '
                                                                       'которого можно получить '
                                                                       'элемент.\n'
                                                                       '- **`index`**: индекс, '
                                                                       'отсчитываемый от нуля, '
                                                                       'указывающий, какой элемент '
                                                                       'нужно вернуть.\n'
                                                                       '\n'
                                                                       '##### Пример: ссылка на '
                                                                       'список\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Результат: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Вложенные списки\n'
                                                                       '\n'
                                                                       'Списки в Scheme могут '
                                                                       'содержать другие списки в '
                                                                       'качестве элементов, '
                                                                       'создавая вложенную '
                                                                       'структуру.\n'
                                                                       '\n'
                                                                       '#### Пример: создание '
                                                                       'вложенного списка\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Создает список из трех '
                                                                       'элементов, каждый из '
                                                                       'которых сам по себе '
                                                                       'является списком.\n'
                                                                       '\n'
                                                                       'Результат: **`((1 2) (3 4) '
                                                                       '(5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Доступ к вложенным '
                                                                       'данным\n'
                                                                       '\n'
                                                                       'Для доступа к элементам '
                                                                       'вложенного списка вы '
                                                                       'можете использовать '
                                                                       'комбинации `car` и `cdr` '
                                                                       'для навигации по '
                                                                       'структуре.\n'
                                                                       '\n'
                                                                       '#### Пример: доступ к '
                                                                       'элементам\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Объяснение\n'
                                                                       '\n'
                                                                       '1. **`car nested-list`**:\n'
                                                                       '   - Извлекает первый '
                                                                       'элемент `nested-list`, то '
                                                                       'есть `(1 2)`.\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Получает первый '
                                                                       'элемент `(1 2)`, то есть '
                                                                       '`1`.\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Получает остальную '
                                                                       'часть `(1 2)`, то есть '
                                                                       '`(2)`.\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**:\n'
                                                                       '   - Получает первый '
                                                                       'элемент `(2)`, то есть '
                                                                       '`2`.\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Пример: доступ к '
                                                                       'элементам из других '
                                                                       'подсписков\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Такой подход позволяет '
                                                                       'систематически '
                                                                       'перемещаться и получать '
                                                                       'доступ к определенным '
                                                                       'элементам во вложенном '
                                                                       'списке, обеспечивая '
                                                                       'высокую гибкость при '
                                                                       'работе с иерархическими '
                                                                       'данными.\n'
                                                                       '\n'
                                                                       '### Резюме\n'
                                                                       '\n'
                                                                       '- **Списки** в Scheme\xa0— '
                                                                       'это универсальные и важные '
                                                                       'структуры данных.\n'
                                                                       '- Используйте `list` для '
                                                                       'создания списка, `car` и '
                                                                       '`cdr` для доступа к '
                                                                       'элементам и `cons` для '
                                                                       'создания списков.\n'
                                                                       '- Встроенные процедуры, '
                                                                       'такие как `length`, '
                                                                       '`append`, `reverse` и '
                                                                       '`list-ref`, делают '
                                                                       'операции со списками '
                                                                       'простыми и эффективными.\n'
                                                                       '- Списки могут быть '
                                                                       'вложенными, что позволяет '
                                                                       'использовать сложные '
                                                                       'структуры данных для '
                                                                       'расширенных вариантов '
                                                                       'использования.',
                                                                 'sv': '---\n'
                                                                       'title: "Listor"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'I Schema är en **lista** '
                                                                       'en grundläggande '
                                                                       'datastruktur som används '
                                                                       'för att gruppera värden. '
                                                                       'Listor är ordnade '
                                                                       'samlingar av element där '
                                                                       'varje element kan vara av '
                                                                       'vilken typ som helst, '
                                                                       'inklusive en annan lista. '
                                                                       'Listor används ofta i '
                                                                       'Scheme för både '
                                                                       'datalagring och '
                                                                       'programstruktur.\n'
                                                                       '\n'
                                                                       '### Exempel 1: Enkel '
                                                                       'lista\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Skapar en lista med tre '
                                                                       'element: `1`, `2` och '
                                                                       '`3`.\n'
                                                                       '\n'
                                                                       'Resultat: **`(1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Åtkomst till '
                                                                       'listelement\n'
                                                                       '\n'
                                                                       'Element i en lista nås med '
                                                                       'hjälp av procedurerna '
                                                                       '`car` och `cdr`:\n'
                                                                       '\n'
                                                                       '- `car` hämtar det första '
                                                                       'elementet i en lista.\n'
                                                                       '- `cdr` hämtar resten av '
                                                                       'listan (allt utom det '
                                                                       'första elementet).\n'
                                                                       '\n'
                                                                       '#### Exempel\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultat:\n'
                                                                       '\n'
                                                                       '- `(car my-list)` '
                                                                       'returnerar `1`\n'
                                                                       '- `(cdr my-list)` '
                                                                       'returnerar `(2 3)`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Enkel rekursion: '
                                                                       'Iteration genom en lista\n'
                                                                       '\n'
                                                                       'Genom att rekursivt anropa '
                                                                       '`car` på `cdr` i en lista, '
                                                                       'kan du bearbeta varje '
                                                                       'element ett efter ett '
                                                                       'tills listan har '
                                                                       'passerats. Detta utgör '
                                                                       'grunden för många '
                                                                       'listbearbetningsalgoritmer.\n'
                                                                       '\n'
                                                                       '#### Exempel: Skriva ut '
                                                                       'varje element i en lista\n'
                                                                       '\n'
                                                                       'Här är en enkel rekursiv '
                                                                       'funktion för att skriva ut '
                                                                       'varje element i en lista:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **Grundfall:** Om listan '
                                                                       'är tom (`null? lst`), '
                                                                       'stoppa rekursion.\n'
                                                                       '- **Rekursiv skiftläge:** '
                                                                       'Skriv ut det första '
                                                                       'elementet (`car lst`), '
                                                                       'anropa sedan funktionen på '
                                                                       'resten av listan (`cdr '
                                                                       'lst`).\n'
                                                                       '\n'
                                                                       '#### Exempel på '
                                                                       'användning\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Utdata:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       'Resultat: "klar"\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Hur det fungerar\n'
                                                                       '\n'
                                                                       '1. Funktionen hämtar det '
                                                                       'första elementet i listan '
                                                                       'med `car` och bearbetar '
                                                                       'det.\n'
                                                                       '2. Den anropar sig sedan '
                                                                       'med resten av listan '
                                                                       '(`cdr`).\n'
                                                                       '3. Denna process upprepas '
                                                                       'tills listan är tom '
                                                                       '(`null? lst`).\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Exempel 2: Blandade '
                                                                       'typer\n'
                                                                       '\n'
                                                                       'Listor kan innehålla '
                                                                       'element av olika typer, '
                                                                       'inklusive strängar, '
                                                                       'booleaner, siffror, andra '
                                                                       'listor eller till och med '
                                                                       'resultatet av uttryck:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Detta skapar en lista '
                                                                       'med:\n'
                                                                       '  - Ett nummer (`42`)\n'
                                                                       '  - En sträng (`"hello"`)\n'
                                                                       '  - En boolesk (`#t`)\n'
                                                                       '  - En annan lista (`(1 '
                                                                       '2)`)\n'
                                                                       '  - Resultatet av ett '
                                                                       'uttryck (`(+ 3 4)`, som '
                                                                       'utvärderas till `7`)\n'
                                                                       '\n'
                                                                       'Resultat: **`(42 "hello" '
                                                                       '#t (1 2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Dessa exempel visar '
                                                                       'mångsidigheten hos listor '
                                                                       'i Scheme, vilket gör dem '
                                                                       'till ett kraftfullt '
                                                                       'verktyg för att organisera '
                                                                       'och manipulera data.\n'
                                                                       '\n'
                                                                       '### Konstruera listor\n'
                                                                       '\n'
                                                                       '`cons`-proceduren används '
                                                                       'för att konstruera en ny '
                                                                       'lista genom att kombinera '
                                                                       'ett element med en '
                                                                       'befintlig lista.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Exempel\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Lägger till `0` i början '
                                                                       'av listan `(1 2 3)`.\n'
                                                                       '\n'
                                                                       'Resultat: **`(0 1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Söker efter listor\n'
                                                                       '\n'
                                                                       '`list?` proceduren '
                                                                       'kontrollerar om ett givet '
                                                                       'värde är en lista.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### Exempel: lista?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultat:\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))` '
                                                                       'returnerar `#t` (sant)\n'
                                                                       '- `(list? 42)` returnerar '
                                                                       '`#f` (falskt)\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Operationer på listor\n'
                                                                       '\n'
                                                                       'Schema tillhandahåller '
                                                                       'flera inbyggda procedurer '
                                                                       'för att arbeta med listor, '
                                                                       'inklusive:\n'
                                                                       '\n'
                                                                       '- `length`: Returnerar '
                                                                       'antalet element i en '
                                                                       'lista.\n'
                                                                       '- `append`: Kombinerar två '
                                                                       'eller flera listor till '
                                                                       'en.\n'
                                                                       '- `reverse`: Returnerar en '
                                                                       'ny lista med element i '
                                                                       'omvänd ordning.\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultat:\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))` '
                                                                       'returnerar `3`\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))` returnerar '
                                                                       '`(1 2 3 4)`\n'
                                                                       '- `(reverse (list 1 2 3))` '
                                                                       'returnerar `(3 2 1)`\n'
                                                                       '\n'
                                                                       '#### Använda `list-ref`\n'
                                                                       '\n'
                                                                       '`list-ref`-proceduren '
                                                                       'hämtar elementet vid ett '
                                                                       'specificerat index i en '
                                                                       'lista (nollbaserat '
                                                                       'index).\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **`lst`**: Listan från '
                                                                       'vilken elementet ska '
                                                                       'hämtas.\n'
                                                                       '- **`index`**: Ett '
                                                                       'nollbaserat index som '
                                                                       'anger vilket element som '
                                                                       'ska returneras.\n'
                                                                       '\n'
                                                                       '##### Exempel: list-ref\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'Resultat: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### Kapslade listor\n'
                                                                       '\n'
                                                                       'Listor i Schema kan '
                                                                       'innehålla andra listor som '
                                                                       'element, vilket skapar en '
                                                                       'kapslad struktur.\n'
                                                                       '\n'
                                                                       '#### Exempel: Skapa en '
                                                                       'kapslad lista\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- Skapar en lista med tre '
                                                                       'element, som var och en är '
                                                                       'en lista.\n'
                                                                       '\n'
                                                                       'Resultat: **`((1 2) (3 4) '
                                                                       '(5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Åtkomst till kapslade '
                                                                       'data\n'
                                                                       '\n'
                                                                       'För att komma åt element i '
                                                                       'en kapslad lista kan du '
                                                                       'använda kombinationer av '
                                                                       '`car` och `cdr` för att '
                                                                       'navigera genom '
                                                                       'strukturen.\n'
                                                                       '\n'
                                                                       '#### Exempel: Åtkomst till '
                                                                       'element\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Förklaring\n'
                                                                       '\n'
                                                                       '1. **`car nested-list`**:\n'
                                                                       '   - Hämtar det första '
                                                                       'elementet i `nested-list`, '
                                                                       'vilket är `(1 2)`.\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Hämtar det första '
                                                                       'elementet i `(1 2)`, '
                                                                       'vilket är `1`.\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - Hämtar resten av `(1 '
                                                                       '2)`, vilket är `(2)`.\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**:\n'
                                                                       '   - Hämtar det första '
                                                                       'elementet i `(2)`, vilket '
                                                                       'är `2`.\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### Exempel: Åtkomst till '
                                                                       'element från andra '
                                                                       'underlistor\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'Detta tillvägagångssätt '
                                                                       'låter dig systematiskt '
                                                                       'navigera och komma åt '
                                                                       'specifika element i en '
                                                                       'kapslad lista, vilket ger '
                                                                       'kraftfull flexibilitet för '
                                                                       'att arbeta med hierarkiska '
                                                                       'data.\n'
                                                                       '\n'
                                                                       '### Sammanfattning\n'
                                                                       '\n'
                                                                       '- **Listor** i Scheme är '
                                                                       'mångsidiga och viktiga '
                                                                       'datastrukturer.\n'
                                                                       '- Använd `list` för att '
                                                                       'skapa en lista, `car` och '
                                                                       '`cdr` för att komma åt '
                                                                       'element och `cons` för att '
                                                                       'konstruera listor.\n'
                                                                       '- Inbyggda procedurer som '
                                                                       '`length`, `append`, '
                                                                       '`reverse` och `list-ref` '
                                                                       'gör listoperationer enkel '
                                                                       'och effektiv.\n'
                                                                       '- Listor kan kapslas, '
                                                                       'vilket möjliggör komplexa '
                                                                       'datastrukturer för '
                                                                       'avancerade '
                                                                       'användningsfall.',
                                                                 'th': '---\n'
                                                                       'title: "รายการ"\n'
                                                                       'type: docs\n'
                                                                       'weight: 4\n'
                                                                       '---\n'
                                                                       'ใน Scheme **รายการ** '
                                                                       'คือโครงสร้างข้อมูลพื้นฐานที่ใช้ในการจัดกลุ่มค่า '
                                                                       'รายการคือการเรียงลำดับคอลเลกชันขององค์ประกอบ '
                                                                       'โดยแต่ละองค์ประกอบสามารถเป็นประเภทใดก็ได้ '
                                                                       'รวมถึงรายการอื่นด้วย '
                                                                       'รายการมีการใช้กันอย่างแพร่หลายใน '
                                                                       'Scheme '
                                                                       'สำหรับทั้งการจัดเก็บข้อมูลและโครงสร้างของโปรแกรม\n'
                                                                       '\n'
                                                                       '### ตัวอย่างที่ 1: '
                                                                       'รายการอย่างง่าย\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 1 2 3)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- '
                                                                       'สร้างรายการองค์ประกอบสามรายการ: '
                                                                       '`1`, `2` และ `3`\n'
                                                                       '\n'
                                                                       'ผลลัพธ์: **`(1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### '
                                                                       'การเข้าถึงองค์ประกอบรายการ\n'
                                                                       '\n'
                                                                       'เข้าถึงองค์ประกอบในรายการได้โดยใช้ขั้นตอน '
                                                                       '`car` และ `cdr`:\n'
                                                                       '\n'
                                                                       '- `car` '
                                                                       'ดึงข้อมูลองค์ประกอบแรกของรายการ\n'
                                                                       '- `cdr` '
                                                                       'ดึงข้อมูลส่วนที่เหลือของรายการ '
                                                                       '(ทุกอย่างยกเว้นองค์ประกอบแรก)\n'
                                                                       '\n'
                                                                       '#### ตัวอย่าง\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define my-list (list 1 2 '
                                                                       '3))\n'
                                                                       '(car my-list)  ; Ruft das '
                                                                       'erste Element ab\n'
                                                                       '(cdr my-list)  ; Ruft den '
                                                                       'Rest der Liste ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'ผลลัพธ์:\n'
                                                                       '\n'
                                                                       '- `(car my-list)` กลับมา '
                                                                       '`1`\n'
                                                                       '- `(cdr my-list)` กลับมา '
                                                                       '`(2 3)`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### การเรียกซ้ำอย่างง่าย: '
                                                                       'การวนซ้ำผ่านรายการ\n'
                                                                       '\n'
                                                                       'ด้วยการเรียก `car` '
                                                                       'แบบวนซ้ำบน `cdr` ของรายการ '
                                                                       'คุณสามารถประมวลผลแต่ละองค์ประกอบได้ทีละรายการจนกว่ารายการจะถูกสำรวจ '
                                                                       'นี่เป็นพื้นฐานของอัลกอริธึมการประมวลผลรายการจำนวนมาก\n'
                                                                       '\n'
                                                                       '#### ตัวอย่าง: '
                                                                       'การพิมพ์แต่ละองค์ประกอบของรายการ\n'
                                                                       '\n'
                                                                       'ต่อไปนี้เป็นฟังก์ชันแบบเรียกซ้ำอย่างง่ายในการพิมพ์ทุกองค์ประกอบในรายการ:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define (print-elements '
                                                                       'lst)\n'
                                                                       '  (if (null? lst)\n'
                                                                       '    (lumi-message "done")\n'
                                                                       '    (begin\n'
                                                                       '      (lumi-message '
                                                                       '(number->string (car '
                                                                       'lst))) ;; Erstes Element '
                                                                       'ausgeben\n'
                                                                       '      (print-elements (cdr '
                                                                       'lst)))))             ;; '
                                                                       'Rest der Liste '
                                                                       'verarbeiten\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **กรณีพื้นฐาน:** '
                                                                       'หากรายการว่างเปล่า (`null? '
                                                                       'lst`) ให้หยุดการเรียกซ้ำ\n'
                                                                       '- **กรณีแบบเรียกซ้ำ:** '
                                                                       'พิมพ์องค์ประกอบแรก (`car '
                                                                       'lst`) '
                                                                       'จากนั้นเรียกใช้ฟังก์ชันในส่วนที่เหลือของรายการ '
                                                                       '(`cdr lst`)\n'
                                                                       '\n'
                                                                       '#### ตัวอย่างการใช้งาน\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(print-elements (list 1 2 '
                                                                       '3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'เอาท์พุท:\n'
                                                                       '\n'
                                                                       '- `"1"`\n'
                                                                       '- `"2"`\n'
                                                                       '- `"3"`\n'
                                                                       '\n'
                                                                       'ผลลัพธ์: "เสร็จสิ้น"\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### มันทำงานอย่างไร\n'
                                                                       '\n'
                                                                       '1. '
                                                                       'ฟังก์ชันดึงข้อมูลองค์ประกอบแรกของรายการโดยใช้ '
                                                                       '`car` '
                                                                       'และประมวลผลองค์ประกอบดังกล่าว\n'
                                                                       '2. '
                                                                       'จากนั้นจะเรียกตัวเองพร้อมกับรายการที่เหลือ '
                                                                       '(`cdr`)\n'
                                                                       '3. '
                                                                       'กระบวนการนี้จะทำซ้ำจนกว่ารายการจะว่างเปล่า '
                                                                       '(`null? lst`)\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### ตัวอย่างที่ 2: '
                                                                       'ประเภทผสม\n'
                                                                       '\n'
                                                                       'รายการอาจมีองค์ประกอบประเภทต่างๆ '
                                                                       'รวมถึงสตริง บูลีน ตัวเลข '
                                                                       'รายการอื่นๆ '
                                                                       'หรือแม้แต่ผลลัพธ์ของนิพจน์:\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list 42 "hello" #t (list '
                                                                       '1 2) (+ 3 4))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- '
                                                                       'สิ่งนี้จะสร้างรายการด้วย:\n'
                                                                       '  - ตัวเลข (`42`)\n'
                                                                       '  - สตริง (`"hello"`)\n'
                                                                       '  - บูลีน (`#t`)\n'
                                                                       '  - อีกรายการ (`(1 2)`)\n'
                                                                       '  - ผลลัพธ์ของนิพจน์ (`(+ '
                                                                       '3 4)` ซึ่งประเมินเป็น '
                                                                       '`7`)\n'
                                                                       '\n'
                                                                       'ผลลัพธ์: **`(42 "hello" #t '
                                                                       '(1 2) 7)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'ตัวอย่างเหล่านี้แสดงให้เห็นถึงความเก่งกาจของรายการใน '
                                                                       'Scheme '
                                                                       'ทำให้เป็นเครื่องมือที่มีประสิทธิภาพในการจัดระเบียบและจัดการข้อมูล\n'
                                                                       '\n'
                                                                       '### รายการการก่อสร้าง\n'
                                                                       '\n'
                                                                       'กระบวนการ `cons` '
                                                                       'ใช้เพื่อสร้างรายการใหม่โดยการรวมองค์ประกอบเข้ากับรายการที่มีอยู่\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons new-element '
                                                                       'existing-list)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### ตัวอย่าง\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(cons 0 (list 1 2 3))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- เพิ่ม `0` '
                                                                       'ที่จุดเริ่มต้นของรายการ '
                                                                       '`(1 2 3)`\n'
                                                                       '\n'
                                                                       'ผลลัพธ์: **`(0 1 2 3)`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### กำลังตรวจสอบรายการ\n'
                                                                       '\n'
                                                                       'กระบวนการ `list?` '
                                                                       'จะตรวจสอบว่าค่าที่กำหนดเป็นรายการหรือไม่\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? value)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '#### ตัวอย่าง: รายการ?\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list? (list 1 2 3))  ; '
                                                                       'Prüft, ob (list 1 2 3) '
                                                                       'eine Liste ist\n'
                                                                       '(list? 42)            ; '
                                                                       'Prüft, ob 42 eine Liste '
                                                                       'ist\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'ผลลัพธ์:\n'
                                                                       '\n'
                                                                       '- `(list? (list 1 2 3))` '
                                                                       'ส่งกลับ `#t` (จริง)\n'
                                                                       '- `(list? 42)` ส่งคืน `#f` '
                                                                       '(เท็จ)\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### การดำเนินงานในรายการ\n'
                                                                       '\n'
                                                                       'Scheme '
                                                                       'มีขั้นตอนในตัวหลายอย่างสำหรับการทำงานกับรายการ '
                                                                       'ได้แก่:\n'
                                                                       '\n'
                                                                       '- `length`: '
                                                                       'ส่งกลับจำนวนองค์ประกอบในรายการ\n'
                                                                       '- `append`: '
                                                                       'รวมสองรายการขึ้นไปเป็นรายการเดียว\n'
                                                                       '- `reverse`: '
                                                                       'ส่งคืนรายการใหม่ที่มีองค์ประกอบในลำดับย้อนกลับ\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(length (list 1 2 '
                                                                       '3))          ; Gibt 3 '
                                                                       'zurück\n'
                                                                       '(append (list 1 2) (list 3 '
                                                                       '4)) ; Gibt (1 2 3 4) '
                                                                       'zurück\n'
                                                                       '(reverse (list 1 2 '
                                                                       '3))         ; Gibt (3 2 1) '
                                                                       'zurück\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'ผลลัพธ์:\n'
                                                                       '\n'
                                                                       '- `(length (list 1 2 3))` '
                                                                       'กลับมา `3`\n'
                                                                       '- `(append (list 1 2) '
                                                                       '(list 3 4))` กลับมา `(1 2 '
                                                                       '3 4)`\n'
                                                                       '- `(reverse (list 1 2 3))` '
                                                                       'กลับมา `(3 2 1)`\n'
                                                                       '\n'
                                                                       '#### การใช้ `list-ref`\n'
                                                                       '\n'
                                                                       'กระบวนการ `list-ref` '
                                                                       'จะดึงข้อมูลองค์ประกอบที่ดัชนีที่ระบุของรายการ '
                                                                       '(ดัชนีแบบศูนย์)\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref lst index)\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- **`lst`**: '
                                                                       'รายการที่จะดึงข้อมูลองค์ประกอบ\n'
                                                                       '- **`index`**: '
                                                                       'ดัชนีแบบศูนย์ซึ่งระบุองค์ประกอบที่จะส่งคืน\n'
                                                                       '\n'
                                                                       '##### ตัวอย่าง: list-ref\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(list-ref (list 10 20 30 '
                                                                       '40) 2)  ; Ruft das Element '
                                                                       'an Index 2 ab\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       'ผลลัพธ์: `30`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '### รายการที่ซ้อนกัน\n'
                                                                       '\n'
                                                                       'รายการใน Scheme '
                                                                       'สามารถมีรายการอื่นเป็นองค์ประกอบ '
                                                                       'ซึ่งสร้างโครงสร้างที่ซ้อนกัน\n'
                                                                       '\n'
                                                                       '#### ตัวอย่าง: '
                                                                       'การสร้างรายการที่ซ้อนกัน\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(define nested-list (list '
                                                                       '(list 1 2) (list 3 4) '
                                                                       '(list 5)))\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '- '
                                                                       'สร้างรายการองค์ประกอบสามรายการ '
                                                                       'ซึ่งแต่ละองค์ประกอบก็เป็นรายการของตัวเอง\n'
                                                                       '\n'
                                                                       'ผลลัพธ์: **`((1 2) (3 4) '
                                                                       '(5))`**\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### '
                                                                       'การเข้าถึงข้อมูลที่ซ้อนกัน\n'
                                                                       '\n'
                                                                       'หากต้องการเข้าถึงองค์ประกอบภายในรายการที่ซ้อนกัน '
                                                                       'คุณสามารถใช้ `car` และ '
                                                                       '`cdr` '
                                                                       'ร่วมกันเพื่อนำทางผ่านโครงสร้างได้\n'
                                                                       '\n'
                                                                       '#### ตัวอย่าง: '
                                                                       'การเข้าถึงองค์ประกอบ\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car '
                                                                       'nested-list)              '
                                                                       '; Ruft das erste Element '
                                                                       'ab: (1 2)\n'
                                                                       '(car (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft das erste Element ab '
                                                                       'of the first sublist: 1\n'
                                                                       '(cdr (car '
                                                                       'nested-list))        ; '
                                                                       'Ruft den Rest der ersten '
                                                                       'Teilliste ab: (2)\n'
                                                                       '(car (cdr (car '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'zweite Element der ersten '
                                                                       'Teilliste ab: 2\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### คำอธิบาย\n'
                                                                       '\n'
                                                                       '1. **`car nested-list`**:\n'
                                                                       '   - '
                                                                       'ดึงข้อมูลองค์ประกอบแรกของ '
                                                                       '`nested-list` ซึ่งก็คือ '
                                                                       '`(1 2)`\n'
                                                                       '\n'
                                                                       '2. **`car (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - '
                                                                       'ดึงข้อมูลองค์ประกอบแรกของ '
                                                                       '`(1 2)` ซึ่งก็คือ `1`\n'
                                                                       '\n'
                                                                       '3. **`cdr (car '
                                                                       'nested-list)`**:\n'
                                                                       '   - '
                                                                       'ดึงข้อมูลส่วนที่เหลือของ '
                                                                       '`(1 2)` ซึ่งก็คือ `(2)`\n'
                                                                       '\n'
                                                                       '4. **`car (cdr (car '
                                                                       'nested-list))`**:\n'
                                                                       '   - '
                                                                       'ดึงข้อมูลองค์ประกอบแรกของ '
                                                                       '`(2)` ซึ่งก็คือ `2`\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       '#### ตัวอย่าง: '
                                                                       'การเข้าถึงองค์ประกอบจากรายการย่อยอื่น\n'
                                                                       '\n'
                                                                       '```scheme\n'
                                                                       '(car (cdr '
                                                                       'nested-list))        ; '
                                                                       'Ruft die zweite Teilliste '
                                                                       'ab: (3 4)\n'
                                                                       '(car (car (cdr '
                                                                       'nested-list)))  ; Ruft das '
                                                                       'erste Element ab of the '
                                                                       'second sublist: 3\n'
                                                                       '```\n'
                                                                       '\n'
                                                                       '---\n'
                                                                       '\n'
                                                                       'แนวทางนี้ช่วยให้คุณสามารถนำทางและเข้าถึงองค์ประกอบเฉพาะในรายการที่ซ้อนกันได้อย่างเป็นระบบ '
                                                                       'ซึ่งให้ความยืดหยุ่นที่มีประสิทธิภาพในการทำงานกับข้อมูลแบบลำดับชั้น\n'
                                                                       '\n'
                                                                       '### สรุป\n'
                                                                       '\n'
                                                                       '- **รายการ** ใน Scheme '
                                                                       'เป็นโครงสร้างข้อมูลที่หลากหลายและจำเป็น\n'
                                                                       '- ใช้ `list` '
                                                                       'เพื่อสร้างรายการ `car` และ '
                                                                       '`cdr` '
                                                                       'เพื่อเข้าถึงองค์ประกอบ '
                                                                       'และใช้ `cons` '
                                                                       'เพื่อสร้างรายการ\n'
                                                                       '- ขั้นตอนในตัว เช่น '
                                                                       '`length`, `append`, '
                                                                       '`reverse` และ `list-ref` '
                                                                       'ทำให้การดำเนินการรายการง่ายและมีประสิทธิภาพ\n'
                                                                       '- รายการสามารถซ้อนกันได้ '
                                                                       'ช่วยให้ใช้โครงสร้างข้อมูลที่ซับซ้อนสำหรับกรณีการใช้งานขั้นสูง',
                                                                 'zh-cn': '---\n'
                                                                          'title: "列表"\n'
                                                                          'type: docs\n'
                                                                          'weight: 4\n'
                                                                          '---\n'
                                                                          '在Scheme中，**列表**是用于对值进行分组的基本数据结构。列表是元素的有序集合，其中每个元素可以是任何类型，包括另一个列表。列表在Scheme中广泛用于数据存储和程序结构。\n'
                                                                          '\n'
                                                                          '### 示例 1：简单列表\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list 1 2 3)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- 创建包含三个元素的列表：`1`、`2` 和 '
                                                                          '`3`。\n'
                                                                          '\n'
                                                                          '结果：**`(1 2 3)`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 访问列表元素\n'
                                                                          '\n'
                                                                          '使用 `car` 和 `cdr` '
                                                                          '过程访问列表中的元素：\n'
                                                                          '\n'
                                                                          '- `car` 检索列表的第一个元素。\n'
                                                                          '- `cdr` '
                                                                          '检索列表的其余部分（除第一个元素之外的所有内容）。\n'
                                                                          '\n'
                                                                          '#### 示例\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(define my-list (list 1 '
                                                                          '2 3))\n'
                                                                          '(car my-list)  ; Ruft '
                                                                          'das erste Element ab\n'
                                                                          '(cdr my-list)  ; Ruft '
                                                                          'den Rest der Liste ab\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '结果：\n'
                                                                          '\n'
                                                                          '- `(car my-list)` '
                                                                          '返回`1`\n'
                                                                          '- `(cdr my-list)` 返回`(2 '
                                                                          '3)`\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 简单递归：遍历列表\n'
                                                                          '\n'
                                                                          '通过对列表的`cdr`递归调用`car`，可以逐一处理每个元素，直到遍历完列表。这构成了许多列表处理算法的基础。\n'
                                                                          '\n'
                                                                          '#### 示例：打印列表的每个元素\n'
                                                                          '\n'
                                                                          '这是一个简单的递归函数，用于打印列表中的每个元素：\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(define (print-elements '
                                                                          'lst)\n'
                                                                          '  (if (null? lst)\n'
                                                                          '    (lumi-message '
                                                                          '"done")\n'
                                                                          '    (begin\n'
                                                                          '      (lumi-message '
                                                                          '(number->string (car '
                                                                          'lst))) ;; Erstes '
                                                                          'Element ausgeben\n'
                                                                          '      (print-elements '
                                                                          '(cdr '
                                                                          'lst)))))             ;; '
                                                                          'Rest der Liste '
                                                                          'verarbeiten\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- **基本情况：** 如果列表为空 '
                                                                          '(`null? lst`)，则停止递归。\n'
                                                                          '- **递归情况：** 打印第一个元素 '
                                                                          '(`car lst`)，然后调用列表其余部分 '
                                                                          '(`cdr lst`) 上的函数。\n'
                                                                          '\n'
                                                                          '#### 用法示例\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(print-elements (list 1 '
                                                                          '2 3))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '输出：\n'
                                                                          '\n'
                                                                          '-`"1"`\n'
                                                                          '- `"2"`\n'
                                                                          '- `"3"`\n'
                                                                          '\n'
                                                                          '结果：“完成”\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 它是如何工作的\n'
                                                                          '\n'
                                                                          '1. 该函数使用 `car` '
                                                                          '检索列表的第一个元素并对其进行处理。\n'
                                                                          '2. 然后它用列表的其余部分调用自身 '
                                                                          '(`cdr`)。\n'
                                                                          '3. 重复此过程，直到列表为空 (`null? '
                                                                          'lst`)。\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### 示例 2：混合类型\n'
                                                                          '\n'
                                                                          '列表可以包含不同类型的元素，包括字符串、布尔值、数字、其他列表，甚至表达式的结果：\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list 42 "hello" #t '
                                                                          '(list 1 2) (+ 3 4))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- 这将创建一个列表：\n'
                                                                          '  - 一个数字 (`42`)\n'
                                                                          '  - 字符串 (`"hello"`)\n'
                                                                          '  - 布尔值 (`#t`)\n'
                                                                          '  - 另一个列表 (`(1 2)`)\n'
                                                                          '  - 表达式的结果（`(+ 3 '
                                                                          '4)`，其计算结果为`7`）\n'
                                                                          '\n'
                                                                          '结果：**`(42 "hello" #t (1 '
                                                                          '2) 7)`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '这些例子展示了Scheme中列表的多功能性，使它们成为组织和操作数据的强大工具。\n'
                                                                          '\n'
                                                                          '### 构建列表\n'
                                                                          '\n'
                                                                          '`cons` '
                                                                          '过程用于通过将元素与现有列表组合来构造新列表。\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(cons new-element '
                                                                          'existing-list)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '#### 示例\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(cons 0 (list 1 2 3))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- 将`0` 添加到列表`(1 2 3)` '
                                                                          '的开头。\n'
                                                                          '\n'
                                                                          '结果：**`(0 1 2 3)`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### 检查列表\n'
                                                                          '\n'
                                                                          '`list?` 过程检查给定值是否是列表。\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list? value)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '#### 示例：列表？\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list? (list 1 2 3))  ; '
                                                                          'Prüft, ob (list 1 2 3) '
                                                                          'eine Liste ist\n'
                                                                          '(list? 42)            ; '
                                                                          'Prüft, ob 42 eine Liste '
                                                                          'ist\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '结果：\n'
                                                                          '\n'
                                                                          '- `(list? (list 1 2 '
                                                                          '3))` 返回`#t`（真）\n'
                                                                          '- `(list? 42)` 返回`#f` '
                                                                          '(假)\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### 列表操作\n'
                                                                          '\n'
                                                                          'Scheme '
                                                                          '提供了几个用于处理列表的内置过程，包括：\n'
                                                                          '\n'
                                                                          '- `length`：返回列表中的元素数量。\n'
                                                                          '- '
                                                                          '`append`：将两个或多个列表合并为一个。\n'
                                                                          '- '
                                                                          '`reverse`：返回一个新列表，其中元素按相反顺序排列。\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(length (list 1 2 '
                                                                          '3))          ; Gibt 3 '
                                                                          'zurück\n'
                                                                          '(append (list 1 2) '
                                                                          '(list 3 4)) ; Gibt (1 2 '
                                                                          '3 4) zurück\n'
                                                                          '(reverse (list 1 2 '
                                                                          '3))         ; Gibt (3 2 '
                                                                          '1) zurück\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '结果：\n'
                                                                          '\n'
                                                                          '- `(length (list 1 2 '
                                                                          '3))` 返回`3`\n'
                                                                          '- `(append (list 1 2) '
                                                                          '(list 3 4))` 返回`(1 2 3 '
                                                                          '4)`\n'
                                                                          '- `(reverse (list 1 2 '
                                                                          '3))` 返回`(3 2 1)`\n'
                                                                          '\n'
                                                                          '#### 使用`list-ref`\n'
                                                                          '\n'
                                                                          '`list-ref` '
                                                                          '过程检索列表指定索引处的元素（从零开始的索引）。\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list-ref lst index)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- **`lst`**：从中检索元素的列表。\n'
                                                                          '- '
                                                                          '**`index`**：从零开始的索引，指示要返回哪个元素。\n'
                                                                          '\n'
                                                                          '##### 示例：列表引用\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list-ref (list 10 20 '
                                                                          '30 40) 2)  ; Ruft das '
                                                                          'Element an Index 2 ab\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '结果：`30`\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### 嵌套列表\n'
                                                                          '\n'
                                                                          'Scheme '
                                                                          '中的列表可以包含其他列表作为元素，从而创建嵌套结构。\n'
                                                                          '\n'
                                                                          '#### 示例：创建嵌套列表\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(define nested-list '
                                                                          '(list (list 1 2) (list '
                                                                          '3 4) (list 5)))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- '
                                                                          '创建一个包含三个元素的列表，每个元素本身就是一个列表。\n'
                                                                          '\n'
                                                                          '结果：**`((1 2) (3 4) '
                                                                          '(5))`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 访问嵌套数据\n'
                                                                          '\n'
                                                                          '要访问嵌套列表中的元素，您可以使用 `car` '
                                                                          '和 `cdr` 的组合来浏览结构。\n'
                                                                          '\n'
                                                                          '#### 示例：访问元素\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(car '
                                                                          'nested-list)              '
                                                                          '; Ruft das erste '
                                                                          'Element ab: (1 2)\n'
                                                                          '(car (car '
                                                                          'nested-list))        ; '
                                                                          'Ruft das erste Element '
                                                                          'ab of the first '
                                                                          'sublist: 1\n'
                                                                          '(cdr (car '
                                                                          'nested-list))        ; '
                                                                          'Ruft den Rest der '
                                                                          'ersten Teilliste ab: '
                                                                          '(2)\n'
                                                                          '(car (cdr (car '
                                                                          'nested-list)))  ; Ruft '
                                                                          'das zweite Element der '
                                                                          'ersten Teilliste ab: 2\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 解释\n'
                                                                          '\n'
                                                                          '1. **`car '
                                                                          'nested-list`**：\n'
                                                                          '   - 检索`nested-list` '
                                                                          '的第一个元素，即`(1 2)`。\n'
                                                                          '\n'
                                                                          '2. **`car (car '
                                                                          'nested-list)`**：\n'
                                                                          '   - 检索`(1 2)` '
                                                                          '的第一个元素，即`1`。\n'
                                                                          '\n'
                                                                          '3. **`cdr (car '
                                                                          'nested-list)`**：\n'
                                                                          '   - 检索`(1 2)` '
                                                                          '的其余部分，即`(2)`。\n'
                                                                          '\n'
                                                                          '4. **`car (cdr (car '
                                                                          'nested-list))`**：\n'
                                                                          '   - 检索`(2)` '
                                                                          '的第一个元素，即`2`。\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 示例：访问其他子列表中的元素\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(car (cdr '
                                                                          'nested-list))        ; '
                                                                          'Ruft die zweite '
                                                                          'Teilliste ab: (3 4)\n'
                                                                          '(car (car (cdr '
                                                                          'nested-list)))  ; Ruft '
                                                                          'das erste Element ab of '
                                                                          'the second sublist: 3\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '这种方法允许您系统地导航和访问嵌套列表中的特定元素，为处理分层数据提供强大的灵活性。\n'
                                                                          '\n'
                                                                          '### 总结\n'
                                                                          '\n'
                                                                          '-Scheme '
                                                                          '中的**列表**是通用且重要的数据结构。\n'
                                                                          '- 使用`list` 创建列表，使用`car` '
                                                                          '和`cdr` 访问元素，使用`cons` '
                                                                          '构建列表。\n'
                                                                          '- '
                                                                          '`length`、`append`、`reverse` '
                                                                          '和 `list-ref` '
                                                                          '等内置程序使列表操作变得简单高效。\n'
                                                                          '- '
                                                                          '列表可以嵌套，从而为高级用例启用复杂的数据结构。',
                                                                 'zh-tw': '---\n'
                                                                          'title: "列表"\n'
                                                                          'type: docs\n'
                                                                          'weight: 4\n'
                                                                          '---\n'
                                                                          '在Scheme中，**列表**是用於將值分組的基本資料結構。列表是元素的有序集合，其中每個元素可以是任何類型，包括另一個列表。列表在Scheme中廣泛用於資料儲存和程式結構。\n'
                                                                          '\n'
                                                                          '### 範例 1：簡單列表\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list 1 2 3)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- 建立包含三個元素的清單：`1`、`2` 和 '
                                                                          '`3`。\n'
                                                                          '\n'
                                                                          '結果：**`(1 2 3)`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 存取清單元素\n'
                                                                          '\n'
                                                                          '使用 `car` 和 `cdr` '
                                                                          '程序存取清單中的元素：\n'
                                                                          '\n'
                                                                          '- `car` 檢索清單的第一個元素。\n'
                                                                          '- `cdr` '
                                                                          '檢索清單的其餘部分（除第一個元素之外的所有內容）。\n'
                                                                          '\n'
                                                                          '#### 範例\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(define my-list (list 1 '
                                                                          '2 3))\n'
                                                                          '(car my-list)  ; Ruft '
                                                                          'das erste Element ab\n'
                                                                          '(cdr my-list)  ; Ruft '
                                                                          'den Rest der Liste ab\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '結果：\n'
                                                                          '\n'
                                                                          '- `(car my-list)` '
                                                                          '返回`1`\n'
                                                                          '- `(cdr my-list)` 返回`(2 '
                                                                          '3)`\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 簡單遞歸：遍歷列表\n'
                                                                          '\n'
                                                                          '透過對列表的`cdr`遞歸呼叫`car`，可以逐一處理每個元素，直到遍歷完列表。這構成了許多列表處理演算法的基礎。\n'
                                                                          '\n'
                                                                          '#### 範例：列印清單的每個元素\n'
                                                                          '\n'
                                                                          '這是一個簡單的遞歸函數，用於列印清單中的每個元素：\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(define (print-elements '
                                                                          'lst)\n'
                                                                          '  (if (null? lst)\n'
                                                                          '    (lumi-message '
                                                                          '"done")\n'
                                                                          '    (begin\n'
                                                                          '      (lumi-message '
                                                                          '(number->string (car '
                                                                          'lst))) ;; Erstes '
                                                                          'Element ausgeben\n'
                                                                          '      (print-elements '
                                                                          '(cdr '
                                                                          'lst)))))             ;; '
                                                                          'Rest der Liste '
                                                                          'verarbeiten\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- **基本情況：** 若清單為空 '
                                                                          '(`null? lst`)，則停止遞迴。\n'
                                                                          '- **遞歸情況：** 列印第一個元素 '
                                                                          '(`car lst`)，然後呼叫清單其餘部分 '
                                                                          '(`cdr lst`) 上的函數。\n'
                                                                          '\n'
                                                                          '#### 用法範例\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(print-elements (list 1 '
                                                                          '2 3))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '輸出：\n'
                                                                          '\n'
                                                                          '-`"1"`\n'
                                                                          '- `"2"`\n'
                                                                          '- `"3"`\n'
                                                                          '\n'
                                                                          '結果：“完成”\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 它是如何運作的\n'
                                                                          '\n'
                                                                          '1. 此函數使用 `car` '
                                                                          '檢索列表的第一個元素並對其進行處理。\n'
                                                                          '2. 然後它用列表的其餘部分呼叫自身 '
                                                                          '(`cdr`)。\n'
                                                                          '3. 重複此過程，直到清單為空 (`null? '
                                                                          'lst`)。\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### 範例 2：混合型別\n'
                                                                          '\n'
                                                                          '列表可以包含不同類型的元素，包括字串、布林值、數字、其他列表，甚至是表達式的結果：\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list 42 "hello" #t '
                                                                          '(list 1 2) (+ 3 4))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- 這將建立一個清單：\n'
                                                                          '  - 一個數字 (`42`)\n'
                                                                          '  - 字串 (`"hello"`)\n'
                                                                          '  - 布林值 (`#t`)\n'
                                                                          '  - 另一個清單 (`(1 2)`)\n'
                                                                          '  - 表達式的結果（`(+ 3 '
                                                                          '4)`，其計算結果為`7`）\n'
                                                                          '\n'
                                                                          '結果：**`(42 "hello" #t (1 '
                                                                          '2) 7)`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '這些範例展示了Scheme中清單的多功能性，使它們成為組織和操作資料的強大工具。\n'
                                                                          '\n'
                                                                          '### 建置列表\n'
                                                                          '\n'
                                                                          '`cons` '
                                                                          '流程用於透過將元素與現有清單組合來建構新清單。\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(cons new-element '
                                                                          'existing-list)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '#### 範例\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(cons 0 (list 1 2 3))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- 將 `0` 加到列表`(1 2 3)` '
                                                                          '的開頭。\n'
                                                                          '\n'
                                                                          '結果：**`(0 1 2 3)`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### 檢查列表\n'
                                                                          '\n'
                                                                          '`list?` 過程檢查給定值是否為列表。\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list? value)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '#### 範例：列表？\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list? (list 1 2 3))  ; '
                                                                          'Prüft, ob (list 1 2 3) '
                                                                          'eine Liste ist\n'
                                                                          '(list? 42)            ; '
                                                                          'Prüft, ob 42 eine Liste '
                                                                          'ist\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '結果：\n'
                                                                          '\n'
                                                                          '- `(list? (list 1 2 '
                                                                          '3))` 返回`#t`（真）\n'
                                                                          '- `(list? 42)` 返回`#f` '
                                                                          '(假)\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### 清單操作\n'
                                                                          '\n'
                                                                          'Scheme '
                                                                          '提供了幾個用於處理清單的內建流程，包括：\n'
                                                                          '\n'
                                                                          '- `length`：傳回清單中的元素數量。\n'
                                                                          '- '
                                                                          '`append`：將兩個或多個清單合併為一個。\n'
                                                                          '- '
                                                                          '`reverse`：傳回一個新列表，其中元素以相反順序排列。\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(length (list 1 2 '
                                                                          '3))          ; Gibt 3 '
                                                                          'zurück\n'
                                                                          '(append (list 1 2) '
                                                                          '(list 3 4)) ; Gibt (1 2 '
                                                                          '3 4) zurück\n'
                                                                          '(reverse (list 1 2 '
                                                                          '3))         ; Gibt (3 2 '
                                                                          '1) zurück\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '結果：\n'
                                                                          '\n'
                                                                          '- `(length (list 1 2 '
                                                                          '3))` 返回`3`\n'
                                                                          '- `(append (list 1 2) '
                                                                          '(list 3 4))` 返回`(1 2 3 '
                                                                          '4)`\n'
                                                                          '- `(reverse (list 1 2 '
                                                                          '3))` 返回`(3 2 1)`\n'
                                                                          '\n'
                                                                          '#### 使用`list-ref`\n'
                                                                          '\n'
                                                                          '`list-ref` '
                                                                          '程序檢索清單指定索引處的元素（從零開始的索引）。\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list-ref lst index)\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- **`lst`**：從中檢索元素的清單。\n'
                                                                          '- '
                                                                          '**`index`**：從零開始的索引，指示要傳回哪個元素。\n'
                                                                          '\n'
                                                                          '##### 範例：清單引用\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(list-ref (list 10 20 '
                                                                          '30 40) 2)  ; Ruft das '
                                                                          'Element an Index 2 ab\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '結果：`30`\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '### 嵌套列表\n'
                                                                          '\n'
                                                                          'Scheme '
                                                                          '中的清單可以包含其他清單作為元素，從而建立嵌套結構。\n'
                                                                          '\n'
                                                                          '#### 範例：建立巢狀列表\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(define nested-list '
                                                                          '(list (list 1 2) (list '
                                                                          '3 4) (list 5)))\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '- '
                                                                          '建立一個包含三個元素的列表，每個元素本身就是一個列表。\n'
                                                                          '\n'
                                                                          '結果：**`((1 2) (3 4) '
                                                                          '(5))`**\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 存取嵌套數據\n'
                                                                          '\n'
                                                                          '若要存取巢狀清單中的元素，您可以使用 '
                                                                          '`car` 和 `cdr` '
                                                                          '的組合來瀏覽結構。\n'
                                                                          '\n'
                                                                          '#### 範例：存取元素\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(car '
                                                                          'nested-list)              '
                                                                          '; Ruft das erste '
                                                                          'Element ab: (1 2)\n'
                                                                          '(car (car '
                                                                          'nested-list))        ; '
                                                                          'Ruft das erste Element '
                                                                          'ab of the first '
                                                                          'sublist: 1\n'
                                                                          '(cdr (car '
                                                                          'nested-list))        ; '
                                                                          'Ruft den Rest der '
                                                                          'ersten Teilliste ab: '
                                                                          '(2)\n'
                                                                          '(car (cdr (car '
                                                                          'nested-list)))  ; Ruft '
                                                                          'das zweite Element der '
                                                                          'ersten Teilliste ab: 2\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 解釋\n'
                                                                          '\n'
                                                                          '1. **`car '
                                                                          'nested-list`**：\n'
                                                                          '   - 檢索`nested-list` '
                                                                          '的第一個元素，即`(1 2)`。\n'
                                                                          '\n'
                                                                          '2. **`car (car '
                                                                          'nested-list)`**：\n'
                                                                          '   - 檢索`(1 2)` '
                                                                          '的第一個元素，即`1`。\n'
                                                                          '\n'
                                                                          '3. **`cdr (car '
                                                                          'nested-list)`**：\n'
                                                                          '   - 檢索`(1 2)` '
                                                                          '的其餘部分，即`(2)`。\n'
                                                                          '\n'
                                                                          '4. **`car (cdr (car '
                                                                          'nested-list))`**：\n'
                                                                          '   - 檢索`(2)` '
                                                                          '的第一個元素，即`2`。\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '#### 範例：存取其他子清單中的元素\n'
                                                                          '\n'
                                                                          '```scheme\n'
                                                                          '(car (cdr '
                                                                          'nested-list))        ; '
                                                                          'Ruft die zweite '
                                                                          'Teilliste ab: (3 4)\n'
                                                                          '(car (car (cdr '
                                                                          'nested-list)))  ; Ruft '
                                                                          'das erste Element ab of '
                                                                          'the second sublist: 3\n'
                                                                          '```\n'
                                                                          '\n'
                                                                          '---\n'
                                                                          '\n'
                                                                          '這種方法可讓您有系統地導航和存取嵌套清單中的特定元素，為處理分層資料提供強大的靈活性。\n'
                                                                          '\n'
                                                                          '### 總結\n'
                                                                          '\n'
                                                                          '-Scheme '
                                                                          '中的**列表**是通用且重要的資料結構。\n'
                                                                          '- 使用`list` 建立列表，使用`car` '
                                                                          '和`cdr` 存取元素，使用`cons` '
                                                                          '建立列表。\n'
                                                                          '- '
                                                                          '`length`、`append`、`reverse` '
                                                                          '和 `list-ref` '
                                                                          '等內建程式可讓清單操作簡單且有效率。\n'
                                                                          '- '
                                                                          '清單可以嵌套，從而為高級用例啟用複雜的資料結構。'},
 'content/hub/scripting/fundamentals/Data Structures/vectors.md': {'de': '---\n'
                                                                         'title: "Vektoren"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'In Scheme ist ein Vektor '
                                                                         'eine weitere '
                                                                         'grundlegende '
                                                                         'Datenstruktur, die zum '
                                                                         'Gruppieren von Werten '
                                                                         'verwendet wird. Im '
                                                                         'Gegensatz zu Listen sind '
                                                                         'Vektoren indizierte '
                                                                         'Elementsammlungen fester '
                                                                         'Größe, die einen '
                                                                         'schnelleren '
                                                                         'Direktzugriff und '
                                                                         'schnellere '
                                                                         'Aktualisierungen '
                                                                         'ermöglichen. Jedes '
                                                                         'Element in einem Vektor '
                                                                         'kann von beliebigem Typ '
                                                                         'sein, einschließlich '
                                                                         'eines anderen Vektors. '
                                                                         'Vektoren werden durch # '
                                                                         'gefolgt von Klammern '
                                                                         'dargestellt. `#(1 2 3)`\n'
                                                                         '\n'
                                                                         'Obwohl Vektoren und '
                                                                         'Listen ähnlich aussehen '
                                                                         'mögen, dienen sie in der '
                                                                         'Scheme-Programmierung '
                                                                         'unterschiedlichen '
                                                                         'Zwecken:\n'
                                                                         '\n'
                                                                         '- Listen werden häufiger '
                                                                         'für rekursive '
                                                                         'Operationen und '
                                                                         'dynamische Strukturen '
                                                                         'verwendet, da ihre '
                                                                         'Linked-Node-Implementierung '
                                                                         'eine effiziente '
                                                                         'Manipulation ihres '
                                                                         'Anfangs und Durchlaufs '
                                                                         'durch rekursive '
                                                                         'Zerlegung ermöglicht.\n'
                                                                         '\n'
                                                                         '- Vektoren hingegen sind '
                                                                         'für Szenarien optimiert, '
                                                                         'in denen wahlfreier '
                                                                         'Zugriff auf Elemente '
                                                                         'oder Aktualisierungen '
                                                                         'bei bestimmten Indizes '
                                                                         'erforderlich sind, '
                                                                         'wodurch sie besser für '
                                                                         'Anwendungsfälle wie '
                                                                         'Nachschlagetabellen, '
                                                                         'Konfigurationen mit '
                                                                         'fester Größe oder '
                                                                         'leistungskritische '
                                                                         'indizierte Vorgänge '
                                                                         'geeignet sind.\n'
                                                                         '\n'
                                                                         'Im Wesentlichen sind '
                                                                         'Listen die natürliche '
                                                                         'Wahl für rekursive '
                                                                         'Algorithmen und Daten '
                                                                         'mit dynamischer Größe, '
                                                                         'während Vektoren '
                                                                         'glänzen, wenn es auf '
                                                                         'feste Größe oder '
                                                                         'indizierte '
                                                                         'Zugriffsmuster ankommt.\n'
                                                                         '\n'
                                                                         '### Einfache Vektoren\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- Erstellt einen Vektor '
                                                                         'aus drei Elementen: `1`, '
                                                                         '`2` und `3`.\n'
                                                                         '\n'
                                                                         'Ergebnis: **`#(1 2 '
                                                                         '3)`**\n'
                                                                         '\n'
                                                                         '#### Zugriff auf '
                                                                         'Vektorelemente\n'
                                                                         '\n'
                                                                         'Auf Elemente in einem '
                                                                         'Vektor wird mit der '
                                                                         'Prozedur `vector-ref` '
                                                                         'zugegriffen. Sie ruft '
                                                                         'das Element an einem '
                                                                         'angegebenen Index ab '
                                                                         '(beginnend bei `0`).\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### Iteration: '
                                                                         'Verarbeiten jedes '
                                                                         'Elements in einem '
                                                                         'Vektor\n'
                                                                         '\n'
                                                                         'Sie können einen Vektor '
                                                                         'mithilfe einer Schleife '
                                                                         'oder Rekursion '
                                                                         'durchlaufen. Das Schema '
                                                                         'stellt `vector-length` '
                                                                         'zur Verfügung, um die '
                                                                         'Größe eines Vektors zu '
                                                                         'bestimmen. Hier ist eine '
                                                                         'einfache Schleife, um '
                                                                         'jedes Element in einem '
                                                                         'Vektor zu drucken:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **Basisfall:** Wenn '
                                                                         'der Index `i` die Länge '
                                                                         'des Vektors erreicht, '
                                                                         'stoppen Sie die '
                                                                         'Schleife.\n'
                                                                         '- **Rekursiver Fall:** '
                                                                         'Drucken Sie das Element '
                                                                         'am Index `i` und erhöhen '
                                                                         'Sie dann `i`.\n'
                                                                         '\n'
                                                                         '#### Beispielverwendung\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Ergebnis:\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         'Ergebnis: „erledigt“\n'
                                                                         '\n'
                                                                         '### Gemischte Vektoren\n'
                                                                         '\n'
                                                                         'Vektoren können Elemente '
                                                                         'unterschiedlichen Typs '
                                                                         'enthalten, darunter '
                                                                         'Zeichenfolgen, boolesche '
                                                                         'Werte, Zahlen, andere '
                                                                         'Vektoren oder sogar das '
                                                                         'Ergebnis von '
                                                                         'Ausdrücken:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Dadurch entsteht ein '
                                                                         'Vektor mit:\n'
                                                                         '  - Eine Zahl (`42`)\n'
                                                                         '  - Eine Zeichenfolge '
                                                                         '(`"hello"`)\n'
                                                                         '  – Ein boolescher Wert '
                                                                         '(`#t`)\n'
                                                                         '  - Ein weiterer Vektor '
                                                                         '(`#(1 2)`)\n'
                                                                         '  – Das Ergebnis eines '
                                                                         'Ausdrucks (`(+ 3 4)`, '
                                                                         'der zu `7` ausgewertet '
                                                                         'wird)\n'
                                                                         '\n'
                                                                         'Ergebnis: **`#(42 '
                                                                         '"hello" #t #(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### Vektoren '
                                                                         'konstruieren\n'
                                                                         '\n'
                                                                         'Vektoren werden mit '
                                                                         '`vector` oder mit '
                                                                         '`make-vector` erstellt, '
                                                                         'um einen Vektor mit '
                                                                         'fester Größe und einem '
                                                                         'Anfangswert zu '
                                                                         'erstellen.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Erstellt einen Vektor '
                                                                         'der Größe `5`, wobei '
                                                                         'alle Elemente auf `0` '
                                                                         'initialisiert sind.\n'
                                                                         '\n'
                                                                         'Ergebnis: `#(0 0 0 0 '
                                                                         '0)`\n'
                                                                         '\n'
                                                                         '### Vektoren '
                                                                         'aktualisieren\n'
                                                                         '\n'
                                                                         'Die Prozedur '
                                                                         '`vector-set!` '
                                                                         'aktualisiert ein Element '
                                                                         'in einem Vektor an einem '
                                                                         'angegebenen Index.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Ergebnis: `#(1 42 3)`\n'
                                                                         '\n'
                                                                         '### Nach Vektoren '
                                                                         'suchen\n'
                                                                         '\n'
                                                                         'Die Prozedur `vector?` '
                                                                         'prüft, ob ein gegebener '
                                                                         'Wert ein Vektor ist.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Ergebnis:\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))` gibt `#t` zurück '
                                                                         '(wahr)\n'
                                                                         '- `(vector? 42)` gibt '
                                                                         '`#f` zurück (falsch)\n'
                                                                         '\n'
                                                                         '### Vektoren und '
                                                                         'Pass-by-Reference-VerhaltenIn '
                                                                         'Scheme sind Vektoren '
                                                                         'veränderbar und werden '
                                                                         'als Referenz übergeben. '
                                                                         'Das heißt, wenn Sie '
                                                                         'einen Vektor an eine '
                                                                         'Funktion übergeben, kann '
                                                                         'die Funktion den '
                                                                         'ursprünglichen Vektor '
                                                                         'direkt ändern. Alle am '
                                                                         'Vektor innerhalb der '
                                                                         'Funktion vorgenommenen '
                                                                         'Änderungen werden auch '
                                                                         'außerhalb der Funktion '
                                                                         'widergespiegelt. Dieses '
                                                                         'Verhalten ist nützlich '
                                                                         'für die effiziente '
                                                                         'gemeinsame Nutzung und '
                                                                         'Aktualisierung von Daten '
                                                                         'über mehrere Funktionen '
                                                                         'hinweg, erfordert aber '
                                                                         'auch Vorsicht, um '
                                                                         'unbeabsichtigte '
                                                                         'Nebenwirkungen zu '
                                                                         'vermeiden.\n'
                                                                         '\n'
                                                                         '#### Beispiel: Ändern '
                                                                         'eines Vektors in einer '
                                                                         'Funktion\n'
                                                                         '\n'
                                                                         'Hier ist ein Beispiel, '
                                                                         'das zeigt, wie Vektoren '
                                                                         'als Referenz übergeben '
                                                                         'und geändert werden:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Ergebnis: `#(10 99 30)`\n'
                                                                         '\n'
                                                                         '#### '
                                                                         'Schritt-für-Schritt-Erklärung\n'
                                                                         '\n'
                                                                         '1. **Erstellen Sie einen '
                                                                         'Vektor:** `my-vector` '
                                                                         'wird mit den Werten '
                                                                         '`10`, `20` und `30` '
                                                                         'initialisiert.\n'
                                                                         '2. **Übergabe an eine '
                                                                         'Funktion:** `my-vector` '
                                                                         'wird zusammen mit dem '
                                                                         'Index und dem neuen zu '
                                                                         'aktualisierenden Wert an '
                                                                         '`modify-vector` '
                                                                         'übergeben.\n'
                                                                         '3. **In Funktion '
                                                                         'ändern:** Die Prozedur '
                                                                         '`vector-set!` '
                                                                         'aktualisiert den Wert am '
                                                                         'angegebenen Index direkt '
                                                                         'im Originalvektor.\n'
                                                                         '4. **Änderungen '
                                                                         'widerspiegeln:** Da '
                                                                         'Vektoren als Referenz '
                                                                         'übergeben werden, werden '
                                                                         'innerhalb der Funktion '
                                                                         'vorgenommene Änderungen '
                                                                         'im ursprünglichen Vektor '
                                                                         'widergespiegelt.\n'
                                                                         '\n'
                                                                         '#### Implikationen von '
                                                                         'Pass-by-Reference\n'
                                                                         '\n'
                                                                         '- **Leistung:** Die '
                                                                         'Übergabe von Vektoren '
                                                                         'als Referenz ist '
                                                                         'effizient, da dadurch '
                                                                         'das Kopieren großer '
                                                                         'Strukturen vermieden '
                                                                         'wird.\n'
                                                                         '- **Nebenwirkungen:** '
                                                                         'Seien Sie vorsichtig, '
                                                                         'wenn Sie Vektoren '
                                                                         'funktionsübergreifend '
                                                                         'teilen, um '
                                                                         'unbeabsichtigte '
                                                                         'Änderungen an gemeinsam '
                                                                         'genutzten Daten zu '
                                                                         'vermeiden.\n'
                                                                         '\n'
                                                                         '### Operationen auf '
                                                                         'Vektoren\n'
                                                                         '\n'
                                                                         'Scheme bietet mehrere '
                                                                         'integrierte Verfahren '
                                                                         'zum Arbeiten mit '
                                                                         'Vektoren, darunter:\n'
                                                                         '\n'
                                                                         '- `vector-length`: Gibt '
                                                                         'die Anzahl der Elemente '
                                                                         'in einem Vektor zurück.\n'
                                                                         '- `vector->list`: '
                                                                         'Konvertiert einen Vektor '
                                                                         'in eine Liste.\n'
                                                                         '- `list->vector`: '
                                                                         'Konvertiert eine Liste '
                                                                         'in einen Vektor.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Ergebnis:\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))` gibt '
                                                                         '`3` zurück\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))` gibt `(1 2 3)` '
                                                                         'zurück\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))` gibt `#(1 2 3)` '
                                                                         'zurück\n'
                                                                         '\n'
                                                                         '### Verschachtelte '
                                                                         'Vektoren\n'
                                                                         '\n'
                                                                         'Vektoren in Scheme '
                                                                         'können andere Vektoren '
                                                                         'als Elemente enthalten, '
                                                                         'wodurch eine '
                                                                         'verschachtelte Struktur '
                                                                         'entsteht.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Erstellt einen Vektor '
                                                                         'aus drei Elementen, von '
                                                                         'denen jedes selbst ein '
                                                                         'Vektor ist.\n'
                                                                         '\n'
                                                                         'Ergebnis: **`#(#(1 2) '
                                                                         '#(3 4) #(5))`**\n'
                                                                         '\n'
                                                                         '#### Zugriff auf '
                                                                         'verschachtelte Daten\n'
                                                                         '\n'
                                                                         'Um auf Elemente '
                                                                         'innerhalb eines '
                                                                         'verschachtelten Vektors '
                                                                         'zuzugreifen, verwenden '
                                                                         'Sie mehrmals '
                                                                         '`vector-ref`, um durch '
                                                                         'die Struktur zu '
                                                                         'navigieren.\n'
                                                                         '\n'
                                                                         '#### Beispiel: Auf '
                                                                         'Elemente zugreifen\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### Zusammenfassung\n'
                                                                         '\n'
                                                                         '- **Vektoren** in Scheme '
                                                                         'sind indizierte '
                                                                         'Datenstrukturen fester '
                                                                         'Größe.\n'
                                                                         '- Verwenden Sie `vector` '
                                                                         'zum Erstellen eines '
                                                                         'Vektors, `vector-ref` '
                                                                         'zum Zugriff auf Elemente '
                                                                         'und `vector-set!` zum '
                                                                         'Aktualisieren von '
                                                                         'Elementen.\n'
                                                                         '- Integrierte Prozeduren '
                                                                         'wie `vector-length`, '
                                                                         '`vector->list` und '
                                                                         '`list->vector` '
                                                                         'ermöglichen flexible '
                                                                         'Abläufe.\n'
                                                                         '- Verschachtelte '
                                                                         'Vektoren ermöglichen '
                                                                         'komplexe, hierarchische '
                                                                         'Datenstrukturen.',
                                                                   'es': '---\n'
                                                                         'title: "Vectores"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'En Scheme, un vector es '
                                                                         'otra estructura de datos '
                                                                         'fundamental que se '
                                                                         'utiliza para agrupar '
                                                                         'valores. A diferencia de '
                                                                         'las listas, los vectores '
                                                                         'son colecciones de '
                                                                         'elementos indexados y de '
                                                                         'tamaño fijo, que '
                                                                         'proporcionan '
                                                                         'actualizaciones y acceso '
                                                                         'aleatorio más rápido. '
                                                                         'Cada elemento de un '
                                                                         'vector puede ser de '
                                                                         'cualquier tipo, incluido '
                                                                         'otro vector. Los '
                                                                         'vectores se representan '
                                                                         'usando # seguido de '
                                                                         'paréntesis. `#(1 2 3)`\n'
                                                                         '\n'
                                                                         'Si bien los vectores y '
                                                                         'las listas pueden '
                                                                         'parecer similares, '
                                                                         'tienen diferentes '
                                                                         'propósitos en la '
                                                                         'programación de '
                                                                         'esquemas:\n'
                                                                         '\n'
                                                                         '- Las listas se utilizan '
                                                                         'más comúnmente para '
                                                                         'operaciones recursivas y '
                                                                         'estructuras dinámicas, '
                                                                         'ya que su implementación '
                                                                         'de nodo vinculado '
                                                                         'permite una manipulación '
                                                                         'eficiente de su inicio y '
                                                                         'recorrido mediante '
                                                                         'descomposición '
                                                                         'recursiva.\n'
                                                                         '\n'
                                                                         '- Los vectores, por otro '
                                                                         'lado, están optimizados '
                                                                         'para escenarios donde se '
                                                                         'requiere acceso '
                                                                         'aleatorio a elementos o '
                                                                         'actualizaciones en '
                                                                         'índices específicos, lo '
                                                                         'que los hace más '
                                                                         'adecuados para casos de '
                                                                         'uso como tablas de '
                                                                         'búsqueda, '
                                                                         'configuraciones de '
                                                                         'tamaño fijo u '
                                                                         'operaciones indexadas '
                                                                         'críticas para el '
                                                                         'rendimiento.\n'
                                                                         '\n'
                                                                         'En esencia, las listas '
                                                                         'son la elección natural '
                                                                         'para algoritmos '
                                                                         'recursivos y datos de '
                                                                         'tamaño dinámico, '
                                                                         'mientras que los '
                                                                         'vectores brillan cuando '
                                                                         'los patrones de acceso '
                                                                         'indexados o de tamaño '
                                                                         'fijo son primordiales.\n'
                                                                         '\n'
                                                                         '### Vectores simples\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- Crea un vector de tres '
                                                                         'elementos: `1`, `2` y '
                                                                         '`3`.\n'
                                                                         '\n'
                                                                         'Resultado: **`#(1 2 '
                                                                         '3)`**\n'
                                                                         '\n'
                                                                         '#### Accediendo a '
                                                                         'elementos vectoriales\n'
                                                                         '\n'
                                                                         'Se accede a los '
                                                                         'elementos de un vector '
                                                                         'mediante el '
                                                                         'procedimiento '
                                                                         '`vector-ref`, que '
                                                                         'recupera el elemento en '
                                                                         'un índice específico '
                                                                         '(comenzando desde `0`).\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### Iteración: '
                                                                         'procesamiento de cada '
                                                                         'elemento en un vector\n'
                                                                         '\n'
                                                                         'Puedes iterar a través '
                                                                         'de un vector usando un '
                                                                         'bucle o recursividad. '
                                                                         'Scheme proporciona '
                                                                         '`vector-length` para '
                                                                         'determinar el tamaño de '
                                                                         'un vector. Aquí hay un '
                                                                         'bucle simple para '
                                                                         'imprimir cada elemento '
                                                                         'en un vector:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **Caso base:** Si el '
                                                                         'índice `i` alcanza la '
                                                                         'longitud del vector, '
                                                                         'detenga el ciclo.\n'
                                                                         '- **Caso recursivo:** '
                                                                         'Imprime el elemento en '
                                                                         'el índice `i`, luego '
                                                                         'incrementa `i`.\n'
                                                                         '\n'
                                                                         '#### Ejemplo de uso\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultado:\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         'Result: "done"\n'
                                                                         '\n'
                                                                         '### Vectores mixtos\n'
                                                                         '\n'
                                                                         'Los vectores pueden '
                                                                         'incluir elementos de '
                                                                         'diferentes tipos, '
                                                                         'incluidas cadenas, '
                                                                         'booleanos, números, '
                                                                         'otros vectores o incluso '
                                                                         'el resultado de '
                                                                         'expresiones:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Esto crea un vector '
                                                                         'con:\n'
                                                                         '  - Un número (`42`)\n'
                                                                         '  - Una cadena '
                                                                         '(`"hello"`)\n'
                                                                         '  - Un booleano (`#t`)\n'
                                                                         '  - Otro vector (`#(1 '
                                                                         '2)`)\n'
                                                                         '  - El resultado de una '
                                                                         'expresión (`(+ 3 4)`, '
                                                                         'que se evalúa como `7`)\n'
                                                                         '\n'
                                                                         'Resultado: **`#(42 '
                                                                         '"hello" #t #(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### Construyendo '
                                                                         'vectores\n'
                                                                         '\n'
                                                                         'Los vectores se crean '
                                                                         'usando `vector`, o '
                                                                         'usando `make-vector` '
                                                                         'para crear un vector de '
                                                                         'un tamaño fijo con un '
                                                                         'valor inicial.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Crea un vector de tamaño '
                                                                         '`5` con todos los '
                                                                         'elementos inicializados '
                                                                         'en `0`.\n'
                                                                         '\n'
                                                                         'Resultado: `#(0 0 0 0 '
                                                                         '0)`\n'
                                                                         '\n'
                                                                         '### Actualizando '
                                                                         'vectores\n'
                                                                         '\n'
                                                                         'El procedimiento '
                                                                         '`vector-set!` actualiza '
                                                                         'un elemento en un vector '
                                                                         'en un índice '
                                                                         'específico.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultado: `#(1 42 3)`\n'
                                                                         '\n'
                                                                         '### Comprobando '
                                                                         'vectores\n'
                                                                         '\n'
                                                                         'El procedimiento '
                                                                         '`vector?` comprueba si '
                                                                         'un valor dado es un '
                                                                         'vector.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultado:\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))` devuelve `#t` '
                                                                         '(verdadero)\n'
                                                                         '- `(vector? 42)` '
                                                                         'devuelve `#f` (falso)\n'
                                                                         '\n'
                                                                         '### Vectores y '
                                                                         'comportamiento de paso '
                                                                         'por referenciaEn Scheme, '
                                                                         'los vectores son '
                                                                         'mutables y se pasan por '
                                                                         'referencia. Esto '
                                                                         'significa que cuando '
                                                                         'pasas un vector a una '
                                                                         'función, la función '
                                                                         'puede modificar el '
                                                                         'vector original '
                                                                         'directamente. Cualquier '
                                                                         'cambio realizado en el '
                                                                         'vector dentro de la '
                                                                         'función también se '
                                                                         'reflejará fuera de la '
                                                                         'función. Este '
                                                                         'comportamiento es útil '
                                                                         'para compartir y '
                                                                         'actualizar datos de '
                                                                         'manera eficiente entre '
                                                                         'múltiples funciones, '
                                                                         'pero también requiere '
                                                                         'precaución para evitar '
                                                                         'efectos secundarios no '
                                                                         'deseados.\n'
                                                                         '\n'
                                                                         '#### Ejemplo: Modificar '
                                                                         'un vector en una '
                                                                         'función\n'
                                                                         '\n'
                                                                         'Aquí hay un ejemplo que '
                                                                         'demuestra cómo los '
                                                                         'vectores se pasan por '
                                                                         'referencia y se '
                                                                         'modifican:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultado: `#(10 99 '
                                                                         '30)`\n'
                                                                         '\n'
                                                                         '#### Explicación paso a '
                                                                         'paso\n'
                                                                         '\n'
                                                                         '1. **Crear un vector:** '
                                                                         '`my-vector` se '
                                                                         'inicializa con los '
                                                                         'valores `10`, `20` y '
                                                                         '`30`.\n'
                                                                         '2. **Pasar a una '
                                                                         'función:** `my-vector` '
                                                                         'se pasa a '
                                                                         '`modify-vector` junto '
                                                                         'con el índice y el nuevo '
                                                                         'valor a actualizar.\n'
                                                                         '3. **Modificar en '
                                                                         'función:** El '
                                                                         'procedimiento '
                                                                         '`vector-set!` actualiza '
                                                                         'el valor en el índice '
                                                                         'especificado '
                                                                         'directamente en el '
                                                                         'vector original.\n'
                                                                         '4. **Reflejar cambios:** '
                                                                         'Dado que los vectores se '
                                                                         'pasan por referencia, '
                                                                         'los cambios realizados '
                                                                         'dentro de la función se '
                                                                         'reflejan en el vector '
                                                                         'original.\n'
                                                                         '\n'
                                                                         '#### Implicaciones del '
                                                                         'paso por referencia\n'
                                                                         '\n'
                                                                         '- **Rendimiento:** Pasar '
                                                                         'vectores por referencia '
                                                                         'es eficiente porque '
                                                                         'evita copiar estructuras '
                                                                         'grandes.\n'
                                                                         '- **Efectos '
                                                                         'secundarios:** Tenga '
                                                                         'cuidado al compartir '
                                                                         'vectores entre funciones '
                                                                         'para evitar '
                                                                         'modificaciones no '
                                                                         'deseadas en los datos '
                                                                         'compartidos.\n'
                                                                         '\n'
                                                                         '### Operaciones sobre '
                                                                         'vectores\n'
                                                                         '\n'
                                                                         'Scheme proporciona '
                                                                         'varios procedimientos '
                                                                         'integrados para trabajar '
                                                                         'con vectores, que '
                                                                         'incluyen:\n'
                                                                         '\n'
                                                                         '- `vector-length`: '
                                                                         'Devuelve el número de '
                                                                         'elementos de un vector.\n'
                                                                         '- `vector->list`: '
                                                                         'Convierte un vector en '
                                                                         'una lista.\n'
                                                                         '- `list->vector`: '
                                                                         'Convierte una lista en '
                                                                         'un vector.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultado:\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))` '
                                                                         'devuelve `3`\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))` devuelve `(1 2 '
                                                                         '3)`\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))` devuelve `#(1 2 '
                                                                         '3)`\n'
                                                                         '\n'
                                                                         '### Vectores anidados\n'
                                                                         '\n'
                                                                         'Los vectores en Scheme '
                                                                         'pueden contener otros '
                                                                         'vectores como elementos, '
                                                                         'creando una estructura '
                                                                         'anidada.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Crea un vector de tres '
                                                                         'elementos, cada uno de '
                                                                         'los cuales es en sí '
                                                                         'mismo un vector.\n'
                                                                         '\n'
                                                                         'Resultado: **`#(#(1 2) '
                                                                         '#(3 4) #(5))`**\n'
                                                                         '\n'
                                                                         '#### Acceso a datos '
                                                                         'anidados\n'
                                                                         '\n'
                                                                         'Para acceder a elementos '
                                                                         'dentro de un vector '
                                                                         'anidado, use '
                                                                         '`vector-ref` varias '
                                                                         'veces para navegar a '
                                                                         'través de la '
                                                                         'estructura.\n'
                                                                         '\n'
                                                                         '#### Ejemplo: acceso a '
                                                                         'elementos\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### Resumen\n'
                                                                         '\n'
                                                                         '- Los **Vectores** en '
                                                                         'Scheme son estructuras '
                                                                         'de datos indexados de '
                                                                         'tamaño fijo.\n'
                                                                         '- Utilice `vector` para '
                                                                         'crear un vector, '
                                                                         '`vector-ref` para '
                                                                         'acceder a elementos y '
                                                                         '`vector-set!` para '
                                                                         'actualizar elementos.\n'
                                                                         '- Los procedimientos '
                                                                         'integrados como '
                                                                         '`vector-length`, '
                                                                         '`vector->list` y '
                                                                         '`list->vector` permiten '
                                                                         'operaciones flexibles.\n'
                                                                         '- Los vectores anidados '
                                                                         'permiten estructuras de '
                                                                         'datos jerárquicas y '
                                                                         'complejas.',
                                                                   'fr': '---\n'
                                                                         'title: "Vecteurs"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'Dans Scheme, un vecteur '
                                                                         'est une autre structure '
                                                                         'de données fondamentale '
                                                                         'utilisée pour regrouper '
                                                                         'des valeurs. '
                                                                         'Contrairement aux '
                                                                         'listes, les vecteurs '
                                                                         'sont des collections '
                                                                         'd’éléments indexés de '
                                                                         'taille fixe, offrant un '
                                                                         'accès aléatoire et des '
                                                                         'mises à jour plus '
                                                                         'rapides. Chaque élément '
                                                                         "d'un vecteur peut être "
                                                                         "de n'importe quel type, "
                                                                         'y compris un autre '
                                                                         'vecteur. Les vecteurs '
                                                                         'sont représentés par # '
                                                                         'suivi de parenthèses. '
                                                                         '`#(1 2 3)`\n'
                                                                         '\n'
                                                                         'Bien que les vecteurs et '
                                                                         'les listes puissent '
                                                                         'sembler similaires, ils '
                                                                         'remplissent des '
                                                                         'objectifs différents '
                                                                         'dans la programmation '
                                                                         'Scheme\xa0:\n'
                                                                         '\n'
                                                                         '- Les listes sont plus '
                                                                         'couramment utilisées '
                                                                         'pour les opérations '
                                                                         'récursives et les '
                                                                         'structures dynamiques, '
                                                                         'car leur implémentation '
                                                                         'de nœuds liés permet une '
                                                                         'manipulation efficace de '
                                                                         'leur début et de leur '
                                                                         'parcours via une '
                                                                         'décomposition '
                                                                         'récursive.\n'
                                                                         '\n'
                                                                         '- Les vecteurs, en '
                                                                         'revanche, sont optimisés '
                                                                         'pour les scénarios dans '
                                                                         'lesquels un accès '
                                                                         'aléatoire à des éléments '
                                                                         'ou des mises à jour '
                                                                         "d'index spécifiques sont "
                                                                         'requis, ce qui les rend '
                                                                         'plus adaptés aux cas '
                                                                         "d'utilisation tels que "
                                                                         'les tables de recherche, '
                                                                         'les configurations de '
                                                                         'taille fixe ou les '
                                                                         'opérations indexées '
                                                                         'critiques en termes de '
                                                                         'performances.\n'
                                                                         '\n'
                                                                         'Essentiellement, les '
                                                                         'listes constituent le '
                                                                         'choix naturel pour les '
                                                                         'algorithmes récursifs et '
                                                                         'les données de taille '
                                                                         'dynamique, tandis que '
                                                                         'les vecteurs brillent '
                                                                         'lorsque les modèles '
                                                                         "d'accès de taille fixe "
                                                                         'ou indexés sont '
                                                                         'primordiaux.\n'
                                                                         '\n'
                                                                         '### Vecteurs simples\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- Crée un vecteur de '
                                                                         'trois éléments\xa0: `1`, '
                                                                         '`2` et `3`.\n'
                                                                         '\n'
                                                                         'Résultat\xa0: **`#(1 2 '
                                                                         '3)`**\n'
                                                                         '\n'
                                                                         '#### Accès aux éléments '
                                                                         'vectoriels\n'
                                                                         '\n'
                                                                         "Les éléments d'un "
                                                                         'vecteur sont accessibles '
                                                                         "à l'aide de la procédure "
                                                                         '`vector-ref`, elle '
                                                                         "récupère l'élément à un "
                                                                         'index spécifié (à partir '
                                                                         'de `0`).\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### Itération\xa0: '
                                                                         'traitement de chaque '
                                                                         'élément dans un vecteur\n'
                                                                         '\n'
                                                                         'Vous pouvez parcourir un '
                                                                         'vecteur à l’aide d’une '
                                                                         'boucle ou d’une '
                                                                         'récursion. Scheme '
                                                                         'fournit `vector-length` '
                                                                         'pour déterminer la '
                                                                         "taille d'un vecteur. "
                                                                         'Voici une boucle simple '
                                                                         'pour imprimer chaque '
                                                                         "élément d'un vecteur\xa0"
                                                                         ':\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **Cas de base\xa0:** '
                                                                         "Si l'index `i` atteint "
                                                                         'la longueur du vecteur, '
                                                                         'arrêtez la boucle.\n'
                                                                         '- **Cas récursif\xa0:** '
                                                                         "Imprimez l'élément à "
                                                                         "l'index `i`, puis "
                                                                         'incrémentez `i`.\n'
                                                                         '\n'
                                                                         '#### Exemple '
                                                                         "d'utilisation\n"
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Résultat :\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         'Result: "done"\n'
                                                                         '\n'
                                                                         '### Vecteurs mixtes\n'
                                                                         '\n'
                                                                         'Les vecteurs peuvent '
                                                                         'inclure des éléments de '
                                                                         'différents types, '
                                                                         'notamment des chaînes, '
                                                                         'des booléens, des '
                                                                         "nombres, d'autres "
                                                                         'vecteurs ou même le '
                                                                         'résultat '
                                                                         "d'expressions\xa0:\n"
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Cela crée un vecteur '
                                                                         'avec\xa0:\n'
                                                                         '  - Un numéro (`42`)\n'
                                                                         '  - Une chaîne '
                                                                         '(`"hello"`)\n'
                                                                         '  - Un booléen (`#t`)\n'
                                                                         '  - Un autre vecteur '
                                                                         '(`#(1 2)`)\n'
                                                                         "  - Le résultat d'une "
                                                                         'expression (`(+ 3 4)`, '
                                                                         "qui s'évalue à `7`)\n"
                                                                         '\n'
                                                                         'Résultat\xa0: **`#(42 '
                                                                         '"hello" #t #(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### Construire des '
                                                                         'vecteurs\n'
                                                                         '\n'
                                                                         'Les vecteurs sont créés '
                                                                         'en utilisant `vector`, '
                                                                         'ou en utilisant '
                                                                         '`make-vector` pour créer '
                                                                         'un vecteur de taille '
                                                                         'fixe avec une valeur '
                                                                         'initiale.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Crée un vecteur de '
                                                                         'taille `5` avec tous les '
                                                                         'éléments initialisés à '
                                                                         '`0`.\n'
                                                                         '\n'
                                                                         'Résultat\xa0: `#(0 0 0 0 '
                                                                         '0)`\n'
                                                                         '\n'
                                                                         '### Mise à jour des '
                                                                         'vecteurs\n'
                                                                         '\n'
                                                                         'La procédure '
                                                                         '`vector-set!` met à jour '
                                                                         'un élément dans un '
                                                                         'vecteur à un index '
                                                                         'spécifié.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Résultat\xa0: `#(1 42 '
                                                                         '3)`\n'
                                                                         '\n'
                                                                         '### Vérification des '
                                                                         'vecteurs\n'
                                                                         '\n'
                                                                         'La procédure `vector?` '
                                                                         'vérifie si une valeur '
                                                                         'donnée est un vecteur.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Résultat :\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))` renvoie `#t` '
                                                                         '(vrai)\n'
                                                                         '- `(vector? 42)` renvoie '
                                                                         '`#f` (faux)\n'
                                                                         '\n'
                                                                         '### Vecteurs et '
                                                                         'comportement de passage '
                                                                         'par référence\n'
                                                                         '\n'
                                                                         'Dans Scheme, les '
                                                                         'vecteurs sont mutables '
                                                                         'et transmis par '
                                                                         'référence. Cela signifie '
                                                                         'que lorsque vous '
                                                                         'transmettez un vecteur à '
                                                                         'une fonction, la '
                                                                         'fonction peut modifier '
                                                                         'directement le vecteur '
                                                                         "d'origine. Toute "
                                                                         'modification apportée au '
                                                                         'vecteur à l’intérieur de '
                                                                         'la fonction sera '
                                                                         'également reflétée à '
                                                                         'l’extérieur de la '
                                                                         'fonction. Ce '
                                                                         'comportement est utile '
                                                                         'pour partager et mettre '
                                                                         'à jour efficacement les '
                                                                         'données entre plusieurs '
                                                                         'fonctions, mais il '
                                                                         'nécessite également de '
                                                                         'la prudence pour éviter '
                                                                         'les effets secondaires '
                                                                         'involontaires.\n'
                                                                         '\n'
                                                                         '#### Exemple : '
                                                                         "Modification d'un "
                                                                         'vecteur dans une '
                                                                         'fonction\n'
                                                                         '\n'
                                                                         'Voici un exemple '
                                                                         'illustrant comment les '
                                                                         'vecteurs sont passés par '
                                                                         'référence et modifiés\xa0'
                                                                         ':\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Résultat\xa0: `#(10 99 '
                                                                         '30)`\n'
                                                                         '\n'
                                                                         '#### Explication étape '
                                                                         'par étape\n'
                                                                         '\n'
                                                                         '1. **Créer un vecteur\xa0'
                                                                         ':** `my-vector` est '
                                                                         'initialisé avec les '
                                                                         'valeurs `10`, `20` et '
                                                                         '`30`.\n'
                                                                         '2. **Passer à une '
                                                                         'fonction\xa0:** '
                                                                         '`my-vector` est transmis '
                                                                         'à `modify-vector` avec '
                                                                         "l'index et la nouvelle "
                                                                         'valeur à mettre à jour.\n'
                                                                         '3. **Modifier dans la '
                                                                         'fonction\xa0:** La '
                                                                         'procédure `vector-set!` '
                                                                         'met à jour la valeur à '
                                                                         "l'index spécifié "
                                                                         'directement dans le '
                                                                         "vecteur d'origine.\n"
                                                                         '4. **Refléter les '
                                                                         'modifications\xa0:** '
                                                                         'Étant donné que les '
                                                                         'vecteurs sont transmis '
                                                                         'par référence, les '
                                                                         'modifications apportées '
                                                                         'au sein de la fonction '
                                                                         'sont reflétées dans le '
                                                                         "vecteur d'origine.\n"
                                                                         '\n'
                                                                         '#### Implications du '
                                                                         'passage par référence\n'
                                                                         '\n'
                                                                         '- **Performance\xa0:** '
                                                                         'Le passage de vecteurs '
                                                                         'par référence est '
                                                                         'efficace car cela évite '
                                                                         'de copier de grandes '
                                                                         'structures.\n'
                                                                         '- **Effets '
                                                                         'secondaires\xa0:** Soyez '
                                                                         'prudent lorsque vous '
                                                                         'partagez des vecteurs '
                                                                         'entre fonctions afin '
                                                                         "d'éviter des "
                                                                         'modifications '
                                                                         'involontaires des '
                                                                         'données partagées.\n'
                                                                         '\n'
                                                                         '### Opérations sur les '
                                                                         'vecteurs\n'
                                                                         '\n'
                                                                         'Scheme fournit plusieurs '
                                                                         'procédures intégrées '
                                                                         'pour travailler avec des '
                                                                         'vecteurs, notamment\xa0'
                                                                         ':\n'
                                                                         '\n'
                                                                         '- `vector-length` : '
                                                                         'Renvoie le nombre '
                                                                         "d'éléments dans un "
                                                                         'vecteur.\n'
                                                                         '- `vector->list` : '
                                                                         'Convertit un vecteur en '
                                                                         'liste.\n'
                                                                         '- `list->vector` : '
                                                                         'Convertit une liste en '
                                                                         'vecteur.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Résultat :\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))` renvoie '
                                                                         '`3`\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))` renvoie `(1 2 '
                                                                         '3)`\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))` renvoie `#(1 2 '
                                                                         '3)`\n'
                                                                         '\n'
                                                                         '### Vecteurs imbriqués\n'
                                                                         '\n'
                                                                         'Les vecteurs dans Scheme '
                                                                         'peuvent contenir '
                                                                         "d'autres vecteurs en "
                                                                         "tant qu'éléments, créant "
                                                                         'ainsi une structure '
                                                                         'imbriquée.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Crée un vecteur de trois '
                                                                         'éléments, chacun étant '
                                                                         'lui-même un vecteur.\n'
                                                                         '\n'
                                                                         'Résultat\xa0: **`#(#(1 '
                                                                         '2) #(3 4) #(5))`**\n'
                                                                         '\n'
                                                                         '#### Accès aux données '
                                                                         'imbriquées\n'
                                                                         '\n'
                                                                         'Pour accéder aux '
                                                                         "éléments d'un vecteur "
                                                                         'imbriqué, utilisez '
                                                                         '`vector-ref` plusieurs '
                                                                         'fois pour naviguer dans '
                                                                         'la structure.\n'
                                                                         '\n'
                                                                         '#### Exemple\xa0: accès '
                                                                         'aux éléments\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### Résumé\n'
                                                                         '\n'
                                                                         '- Les **Vecteurs** dans '
                                                                         'Scheme sont des '
                                                                         'structures de données '
                                                                         'indexées de taille '
                                                                         'fixe.\n'
                                                                         '- Utilisez `vector` pour '
                                                                         'créer un vecteur, '
                                                                         '`vector-ref` pour '
                                                                         'accéder aux éléments et '
                                                                         '`vector-set!` pour '
                                                                         'mettre à jour les '
                                                                         'éléments.\n'
                                                                         '- Les procédures '
                                                                         'intégrées telles que '
                                                                         '`vector-length`, '
                                                                         '`vector->list` et '
                                                                         '`list->vector` '
                                                                         'permettent des '
                                                                         'opérations flexibles.\n'
                                                                         '- Les vecteurs imbriqués '
                                                                         'permettent des '
                                                                         'structures de données '
                                                                         'complexes et '
                                                                         'hiérarchiques.',
                                                                   'it': '---\n'
                                                                         'title: "Vettori"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'In Scheme, un vettore è '
                                                                         "un'altra struttura dati "
                                                                         'fondamentale utilizzata '
                                                                         'per raggruppare valori. '
                                                                         'A differenza degli '
                                                                         'elenchi, i vettori sono '
                                                                         'raccolte di elementi '
                                                                         'indicizzati e di '
                                                                         'dimensione fissa, che '
                                                                         'forniscono accesso '
                                                                         'casuale e aggiornamenti '
                                                                         'più rapidi. Ogni '
                                                                         'elemento in un vettore '
                                                                         'può essere di qualsiasi '
                                                                         'tipo, incluso un altro '
                                                                         'vettore. I vettori sono '
                                                                         'rappresentati '
                                                                         'utilizzando # seguito da '
                                                                         'parentesi. `#(1 2 3)`\n'
                                                                         '\n'
                                                                         'Anche se i vettori e gli '
                                                                         'elenchi possono sembrare '
                                                                         'simili, hanno scopi '
                                                                         'diversi nella '
                                                                         'programmazione di '
                                                                         'Scheme:\n'
                                                                         '\n'
                                                                         '- Le liste sono più '
                                                                         'comunemente usate per '
                                                                         'operazioni ricorsive e '
                                                                         'strutture dinamiche, '
                                                                         'poiché la loro '
                                                                         'implementazione a nodo '
                                                                         'collegato consente una '
                                                                         'manipolazione efficiente '
                                                                         'del loro inizio e del '
                                                                         'loro attraversamento '
                                                                         'attraverso la '
                                                                         'scomposizione '
                                                                         'ricorsiva.\n'
                                                                         '\n'
                                                                         "- I vettori, d'altro "
                                                                         'canto, sono ottimizzati '
                                                                         'per scenari in cui è '
                                                                         "richiesto l'accesso "
                                                                         'casuale a elementi o '
                                                                         'aggiornamenti a indici '
                                                                         'specifici, rendendoli '
                                                                         "più adatti a casi d'uso "
                                                                         'come tabelle di ricerca, '
                                                                         'configurazioni a '
                                                                         'dimensione fissa o '
                                                                         'operazioni indicizzate '
                                                                         'critiche per le '
                                                                         'prestazioni.\n'
                                                                         '\n'
                                                                         'In sostanza, le liste '
                                                                         'sono la scelta naturale '
                                                                         'per algoritmi ricorsivi '
                                                                         'e dati di dimensione '
                                                                         'dinamica, mentre i '
                                                                         'vettori brillano quando '
                                                                         'i modelli di accesso a '
                                                                         'dimensione fissa o '
                                                                         'indicizzati sono '
                                                                         'fondamentali.\n'
                                                                         '\n'
                                                                         '### Vettori semplici\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- Crea un vettore di tre '
                                                                         'elementi: `1`, `2` e '
                                                                         '`3`.\n'
                                                                         '\n'
                                                                         'Risultato: **`#(1 2 '
                                                                         '3)`**\n'
                                                                         '\n'
                                                                         '#### Accesso agli '
                                                                         'elementi vettoriali\n'
                                                                         '\n'
                                                                         'È possibile accedere '
                                                                         'agli elementi in un '
                                                                         'vettore utilizzando la '
                                                                         'procedura `vector-ref`, '
                                                                         "che recupera l'elemento "
                                                                         'in un indice specificato '
                                                                         '(a partire da `0`).\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### Iterazione: '
                                                                         'elaborazione di ciascun '
                                                                         'elemento in un vettore\n'
                                                                         '\n'
                                                                         'È possibile scorrere un '
                                                                         'vettore utilizzando un '
                                                                         'ciclo o la ricorsione. '
                                                                         'Lo schema fornisce '
                                                                         '`vector-length` per '
                                                                         'determinare la '
                                                                         'dimensione di un '
                                                                         'vettore. Ecco un '
                                                                         'semplice ciclo per '
                                                                         'stampare ogni elemento '
                                                                         'in un vettore:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **Caso base:** Se '
                                                                         "l'indice `i` raggiunge "
                                                                         'la lunghezza del '
                                                                         'vettore, interrompe il '
                                                                         'ciclo.\n'
                                                                         '- **Caso ricorsivo:** '
                                                                         "stampa l'elemento "
                                                                         "all'indice `i`, quindi "
                                                                         'incrementa `i`.\n'
                                                                         '\n'
                                                                         '#### Esempio di '
                                                                         'utilizzo\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Risultato:\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         'Result: "done"\n'
                                                                         '\n'
                                                                         '### Vettori misti\n'
                                                                         '\n'
                                                                         'I vettori possono '
                                                                         'includere elementi di '
                                                                         'diverso tipo, tra cui '
                                                                         'stringhe, booleani, '
                                                                         'numeri, altri vettori o '
                                                                         'persino il risultato di '
                                                                         'espressioni:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Questo crea un vettore '
                                                                         'con:\n'
                                                                         '  - Un numero (`42`)\n'
                                                                         '  - Una stringa '
                                                                         '(`"hello"`)\n'
                                                                         '  - Un valore booleano '
                                                                         '(`#t`)\n'
                                                                         '  - Un altro vettore '
                                                                         '(`#(1 2)`)\n'
                                                                         '  - Il risultato di '
                                                                         "un'espressione (`(+ 3 "
                                                                         '4)`, che restituisce '
                                                                         '`7`)\n'
                                                                         '\n'
                                                                         'Risultato: **`#(42 '
                                                                         '"hello" #t #(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### Costruire vettori\n'
                                                                         '\n'
                                                                         'I vettori vengono creati '
                                                                         'utilizzando `vector` '
                                                                         'oppure utilizzando '
                                                                         '`make-vector` per creare '
                                                                         'un vettore di dimensione '
                                                                         'fissa con un valore '
                                                                         'iniziale.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Crea un vettore di '
                                                                         'dimensione `5` con tutti '
                                                                         'gli elementi '
                                                                         'inizializzati su `0`.\n'
                                                                         '\n'
                                                                         'Risultato: `#(0 0 0 0 '
                                                                         '0)`\n'
                                                                         '\n'
                                                                         '### Aggiornamento dei '
                                                                         'vettori\n'
                                                                         '\n'
                                                                         'La procedura '
                                                                         '`vector-set!` aggiorna '
                                                                         'un elemento in un '
                                                                         'vettore in un indice '
                                                                         'specificato.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Risultato: `#(1 42 3)`\n'
                                                                         '\n'
                                                                         '### Controllo dei '
                                                                         'vettori\n'
                                                                         '\n'
                                                                         'La procedura `vector?` '
                                                                         'controlla se un dato '
                                                                         'valore è un vettore.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Risultato:\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))` restituisce `#t` '
                                                                         '(vero)\n'
                                                                         '- `(vector? 42)` '
                                                                         'restituisce `#f` '
                                                                         '(falso)\n'
                                                                         '\n'
                                                                         '### Vettori e '
                                                                         'comportamento di '
                                                                         'passaggio per '
                                                                         'riferimentoIn Scheme, i '
                                                                         'vettori sono mutabili e '
                                                                         'passati per riferimento. '
                                                                         'Ciò significa che quando '
                                                                         'passi un vettore a una '
                                                                         'funzione, la funzione '
                                                                         'può modificare '
                                                                         'direttamente il vettore '
                                                                         'originale. Qualsiasi '
                                                                         'modifica apportata al '
                                                                         "vettore all'interno "
                                                                         'della funzione si '
                                                                         'rifletterà anche '
                                                                         "all'esterno della "
                                                                         'funzione. Questo '
                                                                         'comportamento è utile '
                                                                         'per condividere e '
                                                                         'aggiornare in modo '
                                                                         'efficiente i dati tra '
                                                                         'più funzioni, ma '
                                                                         'richiede anche cautela '
                                                                         'per evitare effetti '
                                                                         'collaterali '
                                                                         'indesiderati.\n'
                                                                         '\n'
                                                                         '#### Esempio: modifica '
                                                                         'di un vettore in una '
                                                                         'funzione\n'
                                                                         '\n'
                                                                         'Ecco un esempio che '
                                                                         'dimostra come i vettori '
                                                                         'vengono passati per '
                                                                         'riferimento e '
                                                                         'modificati:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Risultato: `#(10 99 '
                                                                         '30)`\n'
                                                                         '\n'
                                                                         '#### Spiegazione passo '
                                                                         'passo\n'
                                                                         '\n'
                                                                         '1. **Crea un vettore:** '
                                                                         '`my-vector` viene '
                                                                         'inizializzato con i '
                                                                         'valori `10`, `20` e '
                                                                         '`30`.\n'
                                                                         '2. **Passa a una '
                                                                         'funzione:** `my-vector` '
                                                                         'viene passato a '
                                                                         '`modify-vector` insieme '
                                                                         "all'indice e al nuovo "
                                                                         'valore da aggiornare.\n'
                                                                         '3. **Modifica nella '
                                                                         'funzione:** La procedura '
                                                                         '`vector-set!` aggiorna '
                                                                         "il valore nell'indice "
                                                                         'specificato direttamente '
                                                                         'nel vettore originale.\n'
                                                                         '4. **Riflette '
                                                                         'modifiche:** poiché i '
                                                                         'vettori vengono passati '
                                                                         'per riferimento, le '
                                                                         'modifiche apportate '
                                                                         "all'interno della "
                                                                         'funzione si riflettono '
                                                                         'nel vettore originale.\n'
                                                                         '\n'
                                                                         '#### Implicazioni del '
                                                                         'passaggio per '
                                                                         'riferimento\n'
                                                                         '\n'
                                                                         '- **Prestazioni:** Il '
                                                                         'passaggio di vettori per '
                                                                         'riferimento è efficiente '
                                                                         'perché evita di copiare '
                                                                         'strutture di grandi '
                                                                         'dimensioni.\n'
                                                                         '- **Effetti '
                                                                         'collaterali:** prestare '
                                                                         'attenzione quando si '
                                                                         'condividono vettori tra '
                                                                         'funzioni per evitare '
                                                                         'modifiche involontarie '
                                                                         'ai dati condivisi.\n'
                                                                         '\n'
                                                                         '### Operazioni sui '
                                                                         'vettori\n'
                                                                         '\n'
                                                                         'Scheme fornisce diverse '
                                                                         'procedure integrate per '
                                                                         'lavorare con i vettori, '
                                                                         'tra cui:\n'
                                                                         '\n'
                                                                         '- `vector-length`: '
                                                                         'restituisce il numero di '
                                                                         'elementi in un vettore.\n'
                                                                         '- `vector->list`: '
                                                                         'converte un vettore in '
                                                                         'un elenco.\n'
                                                                         '- `list->vector`: '
                                                                         'converte un elenco in un '
                                                                         'vettore.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Risultato:\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))` '
                                                                         'restituisce `3`\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))` restituisce `(1 '
                                                                         '2 3)`\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))` restituisce `#(1 '
                                                                         '2 3)`\n'
                                                                         '\n'
                                                                         '### Vettori nidificati\n'
                                                                         '\n'
                                                                         'I vettori in Scheme '
                                                                         'possono contenere altri '
                                                                         'vettori come elementi, '
                                                                         'creando una struttura '
                                                                         'nidificata.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Crea un vettore di tre '
                                                                         'elementi, ognuno dei '
                                                                         'quali è a sua volta un '
                                                                         'vettore.\n'
                                                                         '\n'
                                                                         'Risultato: **`#(#(1 2) '
                                                                         '#(3 4) #(5))`**\n'
                                                                         '\n'
                                                                         '#### Accesso ai dati '
                                                                         'annidati\n'
                                                                         '\n'
                                                                         'Per accedere agli '
                                                                         "elementi all'interno di "
                                                                         'un vettore nidificato, '
                                                                         'utilizzare `vector-ref` '
                                                                         'più volte per navigare '
                                                                         'nella struttura.\n'
                                                                         '\n'
                                                                         '#### Esempio: accesso '
                                                                         'agli elementi\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### Riepilogo\n'
                                                                         '\n'
                                                                         '- I **Vettori** nello '
                                                                         'Schema sono strutture '
                                                                         'dati indicizzate a '
                                                                         'dimensione fissa.\n'
                                                                         '- Utilizzare `vector` '
                                                                         'per creare un vettore, '
                                                                         '`vector-ref` per '
                                                                         'accedere agli elementi e '
                                                                         '`vector-set!` per '
                                                                         'aggiornare gli '
                                                                         'elementi.\n'
                                                                         '- Le procedure integrate '
                                                                         'come `vector-length`, '
                                                                         '`vector->list` e '
                                                                         '`list->vector` '
                                                                         'consentono operazioni '
                                                                         'flessibili.\n'
                                                                         '- I vettori nidificati '
                                                                         'consentono strutture di '
                                                                         'dati complesse e '
                                                                         'gerarchiche.',
                                                                   'ja': '---\n'
                                                                         'title: "ベクター"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'Scheme '
                                                                         'では、ベクトルは値をグループ化するために使用されるもう '
                                                                         '1 '
                                                                         'つの基本的なデータ構造です。リストとは異なり、ベクトルは固定サイズのインデックス付き要素コレクションであり、より高速なランダム '
                                                                         'アクセスと更新を提供します。ベクトル内の各要素は、別のベクトルを含め、任意のタイプにすることができます。ベクトルは、# '
                                                                         'に続く括弧を使用して表されます。 `#(1 2 '
                                                                         '3)`\n'
                                                                         '\n'
                                                                         'ベクトルとリストは似ているように見えますが、Scheme '
                                                                         'プログラミングでは異なる目的を果たします。\n'
                                                                         '\n'
                                                                         '- '
                                                                         'リストは、リンクされたノードの実装により、再帰的分解を通じてリストの開始とトラバースを効率的に操作できるため、再帰的操作や動的構造によく使用されます。\n'
                                                                         '\n'
                                                                         '- 一方、ベクターは、要素へのランダム '
                                                                         'アクセスや特定のインデックスでの更新が必要なシナリオ向けに最適化されており、ルックアップ '
                                                                         'テーブル、固定サイズの構成、またはパフォーマンスが重要なインデックス操作などのユースケースにより適しています。\n'
                                                                         '\n'
                                                                         '基本的に、再帰アルゴリズムや動的サイズのデータ\u200b\u200bにはリストが自然な選択ですが、固定サイズまたはインデックス付きのアクセス '
                                                                         'パターンが最も重要な場合にはベクトルが最適です。\n'
                                                                         '\n'
                                                                         '### 単純なベクトル\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- `1`、`2`、`3` の 3 '
                                                                         'つの要素からなるベクトルを作成します。\n'
                                                                         '\n'
                                                                         '結果: **`#(1 2 3)`**\n'
                                                                         '\n'
                                                                         '#### ベクトル要素へのアクセス\n'
                                                                         '\n'
                                                                         'ベクトル内の要素には `vector-ref` '
                                                                         'プロシージャを使用してアクセスし、指定されたインデックス '
                                                                         '(`0` から始まる) で要素を取得します。\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### 反復: ベクトル内の各要素の処理\n'
                                                                         '\n'
                                                                         'ループまたは再帰を使用してベクトルを反復処理できます。スキームは、ベクトルのサイズを決定する '
                                                                         '`vector-length` '
                                                                         'を提供します。以下は、ベクター内のすべての要素を出力する単純なループです。\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **基本ケース:** インデックス `i` '
                                                                         'がベクトルの長さに達すると、ループを停止します。\n'
                                                                         '- **再帰的な場合:** インデックス `i` '
                                                                         'の要素を出力し、`i` '
                                                                         'をインクリメントします。\n'
                                                                         '\n'
                                                                         '#### 使用例\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '結果:\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         '結果:「完了」\n'
                                                                         '\n'
                                                                         '### 混合ベクトル\n'
                                                                         '\n'
                                                                         'ベクトルには、文字列、ブール値、数値、他のベクトル、さらには式の結果など、さまざまなタイプの要素を含めることができます。\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'これにより、次のベクトルが作成されます。\n'
                                                                         '  - 数字 (`42`)\n'
                                                                         '  - A string '
                                                                         '(`"hello"`)\n'
                                                                         '  - ブール値 (`#t`)\n'
                                                                         '  - 別ベクトル (`#(1 2)`)\n'
                                                                         '  - 式の結果 (`(+ 3 4)`、`7` '
                                                                         'と評価される)\n'
                                                                         '\n'
                                                                         '結果: **`#(42 "hello" #t '
                                                                         '#(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### ベクトルの構築\n'
                                                                         '\n'
                                                                         'ベクトルは `vector` '
                                                                         'を使用して作成されるか、`make-vector` '
                                                                         'を使用して初期値を持つ固定サイズのベクトルを作成します。\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'すべての要素が `0` に初期化された、サイズ '
                                                                         '`5` のベクトルを作成します。\n'
                                                                         '\n'
                                                                         '結果: `#(0 0 0 0 0)`\n'
                                                                         '\n'
                                                                         '### ベクターの更新\n'
                                                                         '\n'
                                                                         '`vector-set!` '
                                                                         'プロシージャは、指定されたインデックスにあるベクトル内の要素を更新します。\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '結果: `#(1 42 3)`\n'
                                                                         '\n'
                                                                         '### ベクトルのチェック\n'
                                                                         '\n'
                                                                         '`vector?` '
                                                                         'プロシージャは、指定された値がベクトルであるかどうかをチェックします。\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '結果:\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))` は `#t` (true) '
                                                                         'を返します\n'
                                                                         '- `(vector? 42)` は `#f` '
                                                                         '(偽) を返します\n'
                                                                         '\n'
                                                                         '### ベクトルと参照渡しの動作Scheme '
                                                                         'では、ベクトルは変更可能であり、参照によって渡されます。これは、ベクトルを関数に渡すと、関数が元のベクトルを直接変更できることを意味します。関数内でベクトルに加えられた変更は、関数の外部にも反映されます。この動作は、複数の機能間でデータを効率的に共有および更新するのに役立ちますが、意図しない副作用を避けるために注意も必要です。\n'
                                                                         '\n'
                                                                         '#### 例: 関数内のベクトルの変更\n'
                                                                         '\n'
                                                                         '以下は、ベクトルが参照によって渡され、変更される方法を示す例です。\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '結果: `#(10 99 30)`\n'
                                                                         '\n'
                                                                         '#### 段階的な説明\n'
                                                                         '\n'
                                                                         '1. **ベクターの作成:** '
                                                                         '`my-vector` は、値 '
                                                                         '`10`、`20`、および `30` '
                                                                         'で初期化されます。\n'
                                                                         '2. **関数に渡す:** '
                                                                         '`my-vector` '
                                                                         'は、インデックスと更新する新しい値とともに '
                                                                         '`modify-vector` に渡されます。\n'
                                                                         '3. **関数内の変更:** '
                                                                         '`vector-set!` '
                                                                         'プロシージャは、元のベクトル内の指定されたインデックスの値を直接更新します。\n'
                                                                         '4. **変更の反映:** '
                                                                         'ベクトルは参照によって渡されるため、関数内で行われた変更は元のベクトルに反映されます。\n'
                                                                         '\n'
                                                                         '#### 参照渡しの影響\n'
                                                                         '\n'
                                                                         '- **パフォーマンス:** '
                                                                         '参照によるベクトルの受け渡しは、大きな構造のコピーを回避できるため効率的です。\n'
                                                                         '- **副作用:** '
                                                                         '関数間でベクトルを共有する場合は、共有データへの意図しない変更を避けるために注意してください。\n'
                                                                         '\n'
                                                                         '### ベクトルの演算\n'
                                                                         '\n'
                                                                         'Scheme '
                                                                         'には、ベクトルを操作するための次のような組み込みプロシージャがいくつか用意されています。\n'
                                                                         '\n'
                                                                         '- `vector-length`: '
                                                                         'ベクトル内の要素の数を返します。\n'
                                                                         '- `vector->list`: '
                                                                         'ベクトルをリストに変換します。\n'
                                                                         '- `list->vector`: '
                                                                         'リストをベクトルに変換します。\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '結果:\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))` は `3` '
                                                                         'を返します\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))` は `(1 2 3)` '
                                                                         'を返します\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))` は `#(1 2 3)` '
                                                                         'を返します\n'
                                                                         '\n'
                                                                         '### 入れ子になったベクトル\n'
                                                                         '\n'
                                                                         'Scheme '
                                                                         '内のベクトルには、他のベクトルを要素として含めることができ、入れ子構造を作成します。\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '3 '
                                                                         'つの要素からなるベクトルを作成します。各要素はそれ自体ベクトルです。\n'
                                                                         '\n'
                                                                         '結果: **`#(#(1 2) #(3 4) '
                                                                         '#(5))`**\n'
                                                                         '\n'
                                                                         '#### ネストされたデータへのアクセス\n'
                                                                         '\n'
                                                                         'ネストされたベクトル内の要素にアクセスするには、`vector-ref` '
                                                                         'を複数回使用して構造内を移動します。\n'
                                                                         '\n'
                                                                         '#### 例: 要素へのアクセス\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### 概要\n'
                                                                         '\n'
                                                                         '- Scheme の **Vector** '
                                                                         'は、固定サイズのインデックス付きデータ構造です。\n'
                                                                         '- `vector` '
                                                                         'を使用してベクターを作成し、`vector-ref` '
                                                                         'を使用して要素にアクセスし、`vector-set!` '
                                                                         'を使用して要素を更新します。\n'
                                                                         '- '
                                                                         '`vector-length`、`vector->list`、`list->vector` '
                                                                         'などの組み込みプロシージャにより、柔軟な運用が可能です。\n'
                                                                         '- '
                                                                         'ネストされたベクトルにより、複雑な階層データ構造が可能になります。',
                                                                   'ko': '---\n'
                                                                         'title: "벡터"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'Scheme에서 벡터는 값을 그룹화하는 데 '
                                                                         '사용되는 또 다른 기본 데이터 구조입니다. '
                                                                         '목록과 달리 벡터는 고정 크기의 인덱스 요소 '
                                                                         '컬렉션으로, 더 빠른 임의 액세스 및 '
                                                                         '업데이트를 제공합니다. 벡터의 각 요소는 '
                                                                         '다른 벡터를 포함하여 모든 유형이 될 수 '
                                                                         '있습니다. 벡터는 # 다음에 괄호를 사용하여 '
                                                                         '표시됩니다. `#(1 2 3)`\n'
                                                                         '\n'
                                                                         '벡터와 목록은 유사해 보일 수 있지만 '
                                                                         'Scheme 프로그래밍에서는 서로 다른 '
                                                                         '목적으로 사용됩니다.\n'
                                                                         '\n'
                                                                         '- 목록은 연결된 노드 구현을 통해 재귀 '
                                                                         '분해를 통해 시작 및 순회를 효율적으로 '
                                                                         '조작할 수 있으므로 재귀 작업 및 동적 '
                                                                         '구조에 더 일반적으로 사용됩니다.\n'
                                                                         '\n'
                                                                         '- 반면 벡터는 특정 인덱스의 요소 또는 '
                                                                         '업데이트에 대한 무작위 액세스가 필요한 '
                                                                         '시나리오에 최적화되어 조회 테이블, 고정 '
                                                                         '크기 구성 또는 성능이 중요한 인덱싱 작업과 '
                                                                         '같은 사용 사례에 더 적합합니다.\n'
                                                                         '\n'
                                                                         '본질적으로 목록은 재귀 알고리즘과 동적 크기 '
                                                                         '데이터에 대한 자연스러운 선택인 반면, '
                                                                         '벡터는 고정 크기 또는 인덱스 액세스 패턴이 '
                                                                         '가장 중요한 경우에 빛을 발합니다.\n'
                                                                         '\n'
                                                                         '### 간단한 벡터\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- `1`, `2` 및 `3`의 세 가지 '
                                                                         '요소로 구성된 벡터를 생성합니다.\n'
                                                                         '\n'
                                                                         '결과: **`#(1 2 3)`**\n'
                                                                         '\n'
                                                                         '#### 벡터 요소에 액세스하기\n'
                                                                         '\n'
                                                                         '벡터의 요소는 `vector-ref` '
                                                                         '프로시저를 사용하여 액세스되며 지정된 '
                                                                         '인덱스(`0`에서 시작)에서 요소를 '
                                                                         '검색합니다.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### 반복: 벡터의 각 요소 처리\n'
                                                                         '\n'
                                                                         '루프나 재귀를 사용하여 벡터를 반복할 수 '
                                                                         '있습니다. 체계는 벡터의 크기를 결정하기 '
                                                                         '위해 `vector-length`을 '
                                                                         '제공합니다. 다음은 벡터의 모든 요소를 '
                                                                         '인쇄하는 간단한 루프입니다.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **기본 사례:** `i` 인덱스가 벡터 '
                                                                         '길이에 도달하면 루프를 중지합니다.\n'
                                                                         '- **재귀 사례:** `i` 인덱스의 '
                                                                         '요소를 인쇄한 다음 `i`을 증가시킵니다.\n'
                                                                         '\n'
                                                                         '#### 사용 예\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '결과:\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         '결과: "완료"\n'
                                                                         '\n'
                                                                         '### 혼합 벡터\n'
                                                                         '\n'
                                                                         '벡터에는 문자열, 부울, 숫자, 기타 벡터 '
                                                                         '또는 표현식 결과를 비롯한 다양한 유형의 '
                                                                         '요소가 포함될 수 있습니다.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '그러면 다음을 사용하여 벡터가 생성됩니다.\n'
                                                                         '  - 숫자(`42`)\n'
                                                                         '  - 문자열(`"hello"`)\n'
                                                                         '  - 부울(`#t`)\n'
                                                                         '  - 또 다른 벡터(`#(1 2)`)\n'
                                                                         '  - 표현식의 결과(`(+ 3 4)`, '
                                                                         '`7`로 평가됨)\n'
                                                                         '\n'
                                                                         '결과: **`#(42 "hello" #t '
                                                                         '#(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### 벡터 구성하기\n'
                                                                         '\n'
                                                                         '벡터는 `vector`을 사용하여 생성되거나 '
                                                                         '`make-vector`을 사용하여 초기 '
                                                                         '값으로 고정된 크기의 벡터를 생성합니다.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '`0`으로 초기화된 모든 요소를 사용하여 '
                                                                         '`5` 크기의 벡터를 생성합니다.\n'
                                                                         '\n'
                                                                         '결과: `#(0 0 0 0 0)`\n'
                                                                         '\n'
                                                                         '### 벡터 업데이트 중\n'
                                                                         '\n'
                                                                         '`vector-set!` 프로시저는 지정된 '
                                                                         '인덱스에 있는 벡터의 요소를 '
                                                                         '업데이트합니다.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '결과: `#(1 42 3)`\n'
                                                                         '\n'
                                                                         '### 벡터 확인 중\n'
                                                                         '\n'
                                                                         '`vector?` 프로시저는 주어진 값이 '
                                                                         '벡터인지 확인합니다.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '결과:\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))`은 `#t`을 '
                                                                         '반환합니다(true).\n'
                                                                         '- `(vector? 42)`은 `#f`을 '
                                                                         '반환합니다(거짓).\n'
                                                                         '\n'
                                                                         '### 벡터와 참조에 의한 전달 '
                                                                         '동작Scheme에서 벡터는 변경 가능하며 '
                                                                         '참조로 전달됩니다. 이는 벡터를 함수에 '
                                                                         '전달하면 함수가 원래 벡터를 직접 수정할 수 '
                                                                         '있음을 의미합니다. 함수 내부의 벡터에 대한 '
                                                                         '모든 변경 사항은 함수 외부에도 반영됩니다. '
                                                                         '이 동작은 여러 기능에서 데이터를 효율적으로 '
                                                                         '공유하고 업데이트하는 데 유용하지만 의도하지 '
                                                                         '않은 부작용을 방지하려면 주의도 '
                                                                         '필요합니다.\n'
                                                                         '\n'
                                                                         '#### 예: 함수에서 벡터 수정\n'
                                                                         '\n'
                                                                         '다음은 벡터가 참조로 전달되고 수정되는 '
                                                                         '방법을 보여주는 예입니다.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '결과: `#(10 99 30)`\n'
                                                                         '\n'
                                                                         '#### 단계별 설명\n'
                                                                         '\n'
                                                                         '1. **벡터 생성:** '
                                                                         '`my-vector`은 `10`, `20` '
                                                                         '및 `30` 값으로 초기화됩니다.\n'
                                                                         '2. **함수에 전달:** '
                                                                         '`my-vector`은 업데이트할 인덱스 및 '
                                                                         '새 값과 함께 `modify-vector`에 '
                                                                         '전달됩니다.\n'
                                                                         '3. **함수 수정:** '
                                                                         '`vector-set!` 프로시저는 원본 '
                                                                         '벡터에서 직접 지정된 인덱스의 값을 '
                                                                         '업데이트합니다.\n'
                                                                         '4. **변경 사항 반영:** 벡터는 참조로 '
                                                                         '전달되므로 함수 내에서 변경된 내용이 원본 '
                                                                         '벡터에 반영됩니다.\n'
                                                                         '\n'
                                                                         '#### 참조에 의한 전달의 의미\n'
                                                                         '\n'
                                                                         '- **성능:** 참조로 벡터를 전달하는 '
                                                                         '것은 큰 구조를 복사하는 것을 방지하므로 '
                                                                         '효율적입니다.\n'
                                                                         '- **부작용:** 공유 데이터에 대한 '
                                                                         '의도하지 않은 수정을 방지하려면 기능 간에 '
                                                                         '벡터를 공유할 때 주의하십시오.\n'
                                                                         '\n'
                                                                         '### 벡터 연산\n'
                                                                         '\n'
                                                                         'Scheme은 다음을 포함하여 벡터 작업을 '
                                                                         '위한 여러 내장 프로시저를 제공합니다.\n'
                                                                         '\n'
                                                                         '- `vector-length`: 벡터의 '
                                                                         '요소 수를 반환합니다.\n'
                                                                         '- `vector->list`: 벡터를 '
                                                                         '목록으로 변환합니다.\n'
                                                                         '- `list->vector`: 목록을 '
                                                                         '벡터로 변환합니다.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '결과:\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))`은 `3`을 '
                                                                         '반환합니다.\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))`은 `(1 2 3)`을 '
                                                                         '반환합니다.\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))`은 `#(1 2 3)`을 '
                                                                         '반환합니다.\n'
                                                                         '\n'
                                                                         '### 중첩 벡터\n'
                                                                         '\n'
                                                                         'Scheme의 벡터는 다른 벡터를 요소로 '
                                                                         '포함하여 중첩 구조를 만들 수 있습니다.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '각 요소 자체가 벡터인 세 요소의 벡터를 '
                                                                         '만듭니다.\n'
                                                                         '\n'
                                                                         '결과: **`#(#(1 2) #(3 4) '
                                                                         '#(5))`**\n'
                                                                         '\n'
                                                                         '#### 중첩된 데이터에 액세스\n'
                                                                         '\n'
                                                                         '중첩된 벡터 내의 요소에 액세스하려면 '
                                                                         '`vector-ref`을 여러 번 사용하여 '
                                                                         '구조를 탐색하세요.\n'
                                                                         '\n'
                                                                         '#### 예: 요소에 액세스하기\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### 요약\n'
                                                                         '\n'
                                                                         '- Scheme의 **벡터**는 고정 크기의 '
                                                                         '인덱스 데이터 구조입니다.\n'
                                                                         '- `vector`을 사용하여 벡터를 '
                                                                         '생성하고, `vector-ref`을 사용하여 '
                                                                         '요소에 액세스하고, '
                                                                         '`vector-set!`을 사용하여 요소를 '
                                                                         '업데이트합니다.\n'
                                                                         '- `vector-length`, '
                                                                         '`vector->list` 및 '
                                                                         '`list->vector`과 같은 내장 '
                                                                         '프로시저를 통해 유연한 작업이 가능합니다.\n'
                                                                         '- 중첩된 벡터는 복잡한 계층적 데이터 '
                                                                         '구조를 허용합니다.',
                                                                   'nl': '---\n'
                                                                         'title: "Vectoren"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'In Scheme is een vector '
                                                                         'een andere fundamentele '
                                                                         'gegevensstructuur die '
                                                                         'wordt gebruikt om '
                                                                         'waarden te groeperen. In '
                                                                         'tegenstelling tot '
                                                                         'lijsten zijn vectoren '
                                                                         'geïndexeerde '
                                                                         'verzamelingen van '
                                                                         'elementen met een vaste '
                                                                         'grootte, waardoor '
                                                                         'snellere willekeurige '
                                                                         'toegang en updates '
                                                                         'mogelijk zijn. Elk '
                                                                         'element in een vector '
                                                                         'kan van elk type zijn, '
                                                                         'inclusief een andere '
                                                                         'vector. Vectoren worden '
                                                                         'weergegeven met # '
                                                                         'gevolgd door haakjes. '
                                                                         '`#(1 2 3)`\n'
                                                                         '\n'
                                                                         'Hoewel vectoren en '
                                                                         'lijsten op elkaar '
                                                                         'lijken, dienen ze '
                                                                         'verschillende doeleinden '
                                                                         'bij het programmeren van '
                                                                         "schema's:\n"
                                                                         '\n'
                                                                         '- Lijsten worden vaker '
                                                                         'gebruikt voor recursieve '
                                                                         'bewerkingen en '
                                                                         'dynamische structuren, '
                                                                         'omdat hun implementatie '
                                                                         'met gekoppelde '
                                                                         'knooppunten een '
                                                                         'efficiënte manipulatie '
                                                                         'van het begin en de '
                                                                         'doorloop ervan door '
                                                                         'middel van recursieve '
                                                                         'ontbinding mogelijk '
                                                                         'maakt.\n'
                                                                         '\n'
                                                                         '- Vectoren zijn '
                                                                         'daarentegen '
                                                                         'geoptimaliseerd voor '
                                                                         "scenario's waarin "
                                                                         'willekeurige toegang tot '
                                                                         'elementen of updates op '
                                                                         'specifieke indices '
                                                                         'vereist is, waardoor ze '
                                                                         'geschikter zijn voor '
                                                                         "gebruiksscenario's zoals "
                                                                         'opzoektabellen, '
                                                                         'configuraties met een '
                                                                         'vaste grootte of '
                                                                         'prestatiekritische '
                                                                         'geïndexeerde '
                                                                         'bewerkingen.\n'
                                                                         '\n'
                                                                         'In wezen zijn lijsten de '
                                                                         'logische keuze voor '
                                                                         'recursieve algoritmen en '
                                                                         'gegevens met een '
                                                                         'dynamische grootte, '
                                                                         'terwijl vectoren '
                                                                         'uitblinken wanneer '
                                                                         'toegangspatronen met een '
                                                                         'vaste grootte of '
                                                                         'geïndexeerde waarden van '
                                                                         'het grootste belang '
                                                                         'zijn.\n'
                                                                         '\n'
                                                                         '### Eenvoudige vectoren\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- Creëert een vector van '
                                                                         'drie elementen: `1`, `2` '
                                                                         'en `3`.\n'
                                                                         '\n'
                                                                         'Resultaat: **`#(1 2 '
                                                                         '3)`**\n'
                                                                         '\n'
                                                                         '#### Toegang tot '
                                                                         'vectorelementen\n'
                                                                         '\n'
                                                                         'Elementen in een vector '
                                                                         'worden benaderd met '
                                                                         'behulp van de '
                                                                         '`vector-ref` procedure, '
                                                                         'deze haalt het element '
                                                                         'op bij een '
                                                                         'gespecificeerde index '
                                                                         '(beginnend bij `0`).\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### Iteratie: elk '
                                                                         'element in een vector '
                                                                         'verwerken\n'
                                                                         '\n'
                                                                         'U kunt een vector '
                                                                         'herhalen met behulp van '
                                                                         'een lus of recursie. '
                                                                         'Schema biedt '
                                                                         '`vector-length` om de '
                                                                         'grootte van een vector '
                                                                         'te bepalen. Hier is een '
                                                                         'eenvoudige lus om elk '
                                                                         'element in een vector af '
                                                                         'te drukken:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **Basisscenario:** Als '
                                                                         'de index `i` de lengte '
                                                                         'van de vector bereikt, '
                                                                         'stop dan de lus.\n'
                                                                         '- **Recursief '
                                                                         'hoofdlettergebruik:** '
                                                                         'Druk het element af op '
                                                                         'index `i` en verhoog '
                                                                         'vervolgens `i`.\n'
                                                                         '\n'
                                                                         '#### Voorbeeldgebruik\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultaat:\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         'Resultaat: "klaar"\n'
                                                                         '\n'
                                                                         '### Gemengde vectoren\n'
                                                                         '\n'
                                                                         'Vectoren kunnen '
                                                                         'elementen van '
                                                                         'verschillende typen '
                                                                         'bevatten, waaronder '
                                                                         'tekenreeksen, booleans, '
                                                                         'getallen, andere '
                                                                         'vectoren of zelfs het '
                                                                         'resultaat van '
                                                                         'uitdrukkingen:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Hierdoor ontstaat een '
                                                                         'vector met:\n'
                                                                         '  - Een nummer (`42`)\n'
                                                                         '  - Een string '
                                                                         '(`"hello"`)\n'
                                                                         '  - Een Booleaanse '
                                                                         '(`#t`)\n'
                                                                         '  - Nog een vector (`#(1 '
                                                                         '2)`)\n'
                                                                         '  - Het resultaat van '
                                                                         'een uitdrukking (`(+ 3 '
                                                                         '4)`, die resulteert in '
                                                                         '`7`)\n'
                                                                         '\n'
                                                                         'Resultaat: **`#(42 '
                                                                         '"hello" #t #(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### Vectoren '
                                                                         'construeren\n'
                                                                         '\n'
                                                                         'Vectoren worden gemaakt '
                                                                         'met `vector`, of door '
                                                                         '`make-vector` te '
                                                                         'gebruiken om een vector '
                                                                         'van een vaste grootte '
                                                                         'met een initiële waarde '
                                                                         'te maken.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Creëert een vector met '
                                                                         'de grootte `5` waarbij '
                                                                         'alle elementen zijn '
                                                                         'geïnitialiseerd naar '
                                                                         '`0`.\n'
                                                                         '\n'
                                                                         'Resultaat: `#(0 0 0 0 '
                                                                         '0)`\n'
                                                                         '\n'
                                                                         '### Vectoren bijwerken\n'
                                                                         '\n'
                                                                         'De `vector-set!` '
                                                                         'procedure werkt een '
                                                                         'element in een vector '
                                                                         'bij op een '
                                                                         'gespecificeerde index.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultaat: `#(1 42 3)`\n'
                                                                         '\n'
                                                                         '### Controleren op '
                                                                         'vectoren\n'
                                                                         '\n'
                                                                         'De `vector?` procedure '
                                                                         'controleert of een '
                                                                         'gegeven waarde een '
                                                                         'vector is.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultaat:\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))` retourneert `#t` '
                                                                         '(waar)\n'
                                                                         '- `(vector? 42)` '
                                                                         'retourneert `#f` '
                                                                         '(onwaar)\n'
                                                                         '\n'
                                                                         '### Vectoren en '
                                                                         'pass-by-referentiegedragIn '
                                                                         'Schema zijn vectoren '
                                                                         'veranderlijk en worden '
                                                                         'ze door verwijzing '
                                                                         'doorgegeven. Dit '
                                                                         'betekent dat wanneer u '
                                                                         'een vector aan een '
                                                                         'functie doorgeeft, de '
                                                                         'functie de originele '
                                                                         'vector rechtstreeks kan '
                                                                         'wijzigen. Alle '
                                                                         'wijzigingen die binnen '
                                                                         'de functie aan de vector '
                                                                         'worden aangebracht, '
                                                                         'worden ook buiten de '
                                                                         'functie weerspiegeld. '
                                                                         'Dit gedrag is handig '
                                                                         'voor het efficiënt delen '
                                                                         'en bijwerken van '
                                                                         'gegevens over meerdere '
                                                                         'functies, maar vereist '
                                                                         'ook voorzichtigheid om '
                                                                         'onbedoelde bijwerkingen '
                                                                         'te voorkomen.\n'
                                                                         '\n'
                                                                         '#### Voorbeeld: een '
                                                                         'vector in een functie '
                                                                         'wijzigen\n'
                                                                         '\n'
                                                                         'Hier is een voorbeeld '
                                                                         'dat laat zien hoe '
                                                                         'vectoren ter referentie '
                                                                         'worden doorgegeven en '
                                                                         'gewijzigd:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultaat: `#(10 99 '
                                                                         '30)`\n'
                                                                         '\n'
                                                                         '#### Stap-voor-stap '
                                                                         'uitleg\n'
                                                                         '\n'
                                                                         '1. **Maak een vector:** '
                                                                         '`my-vector` wordt '
                                                                         'geïnitialiseerd met de '
                                                                         'waarden `10`, `20` en '
                                                                         '`30`.\n'
                                                                         '2. **Doorgeven aan een '
                                                                         'functie:** `my-vector` '
                                                                         'wordt doorgegeven aan '
                                                                         '`modify-vector` samen '
                                                                         'met de index en de '
                                                                         'nieuwe waarde die moet '
                                                                         'worden bijgewerkt.\n'
                                                                         '3. **Wijzigen in '
                                                                         'functie:** De '
                                                                         '`vector-set!` procedure '
                                                                         'werkt de waarde bij de '
                                                                         'opgegeven index '
                                                                         'rechtstreeks in de '
                                                                         'originele vector bij.\n'
                                                                         '4. **Wijzigingen '
                                                                         'weerspiegelen:** Omdat '
                                                                         'vectoren door middel van '
                                                                         'referentie worden '
                                                                         'doorgegeven, worden '
                                                                         'wijzigingen die binnen '
                                                                         'de functie worden '
                                                                         'aangebracht, '
                                                                         'weerspiegeld in de '
                                                                         'originele vector.\n'
                                                                         '\n'
                                                                         '#### Implicaties van '
                                                                         'pass-by-referentie\n'
                                                                         '\n'
                                                                         '- **Prestaties:** Het '
                                                                         'doorgeven van vectoren '
                                                                         'via referentie is '
                                                                         'efficiënt omdat het '
                                                                         'kopiëren van grote '
                                                                         'structuren wordt '
                                                                         'vermeden.\n'
                                                                         '- **Bijwerkingen:** Wees '
                                                                         'voorzichtig bij het '
                                                                         'delen van vectoren '
                                                                         'tussen functies om '
                                                                         'onbedoelde wijzigingen '
                                                                         'in gedeelde gegevens te '
                                                                         'voorkomen.\n'
                                                                         '\n'
                                                                         '### Bewerkingen op '
                                                                         'vectoren\n'
                                                                         '\n'
                                                                         'Scheme biedt '
                                                                         'verschillende ingebouwde '
                                                                         'procedures voor het '
                                                                         'werken met vectoren, '
                                                                         'waaronder:\n'
                                                                         '\n'
                                                                         '- `vector-length`: Geeft '
                                                                         'het aantal elementen in '
                                                                         'een vector terug.\n'
                                                                         '- `vector->list`: '
                                                                         'Converteert een vector '
                                                                         'naar een lijst.\n'
                                                                         '- `list->vector`: '
                                                                         'Converteert een lijst '
                                                                         'naar een vector.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultaat:\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))` '
                                                                         'retourneert `3`\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))` retourneert `(1 '
                                                                         '2 3)`\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))` retourneert `#(1 '
                                                                         '2 3)`\n'
                                                                         '\n'
                                                                         '### Geneste vectoren\n'
                                                                         '\n'
                                                                         'Vectoren in Schema '
                                                                         'kunnen andere vectoren '
                                                                         'als elementen bevatten, '
                                                                         'waardoor een geneste '
                                                                         'structuur ontstaat.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Creëert een vector van '
                                                                         'drie elementen, die elk '
                                                                         'zelf een vector zijn.\n'
                                                                         '\n'
                                                                         'Resultaat: **`#(#(1 2) '
                                                                         '#(3 4) #(5))`**\n'
                                                                         '\n'
                                                                         '#### Toegang tot geneste '
                                                                         'gegevens\n'
                                                                         '\n'
                                                                         'Om toegang te krijgen '
                                                                         'tot elementen binnen een '
                                                                         'geneste vector, gebruikt '
                                                                         'u `vector-ref` meerdere '
                                                                         'keren om door de '
                                                                         'structuur te navigeren.\n'
                                                                         '\n'
                                                                         '#### Voorbeeld: toegang '
                                                                         'tot elementen\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### Samenvatting\n'
                                                                         '\n'
                                                                         '- **Vectoren** in Scheme '
                                                                         'zijn geïndexeerde '
                                                                         'datastructuren met een '
                                                                         'vaste grootte.\n'
                                                                         '- Gebruik `vector` om '
                                                                         'een \u200b\u200bvector '
                                                                         'te maken, `vector-ref` '
                                                                         'om toegang te krijgen '
                                                                         'tot elementen, en '
                                                                         '`vector-set!` om '
                                                                         'elementen bij te '
                                                                         'werken.\n'
                                                                         '- Ingebouwde procedures '
                                                                         'zoals `vector-length`, '
                                                                         '`vector->list` en '
                                                                         '`list->vector` maken '
                                                                         'flexibele bewerkingen '
                                                                         'mogelijk.\n'
                                                                         '- Geneste vectoren maken '
                                                                         'complexe, hiërarchische '
                                                                         'datastructuren mogelijk.',
                                                                   'pl': '---\n'
                                                                         'title: "Wektory"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'W schemacie wektor jest '
                                                                         'kolejną podstawową '
                                                                         'strukturą danych używaną '
                                                                         'do grupowania wartości. '
                                                                         'W przeciwieństwie do '
                                                                         'list, wektory to '
                                                                         'indeksowane zbiory '
                                                                         'elementów o stałym '
                                                                         'rozmiarze, zapewniające '
                                                                         'szybszy losowy dostęp i '
                                                                         'aktualizacje. Każdy '
                                                                         'element wektora może być '
                                                                         'dowolnego typu, łącznie '
                                                                         'z innym wektorem. '
                                                                         'Wektory są '
                                                                         'reprezentowane za pomocą '
                                                                         '#, po którym następują '
                                                                         'nawiasy. `#(1 2 3)`\n'
                                                                         '\n'
                                                                         'Chociaż wektory i listy '
                                                                         'mogą wyglądać podobnie, '
                                                                         'w programowaniu '
                                                                         'schematów służą różnym '
                                                                         'celom:\n'
                                                                         '\n'
                                                                         '- Listy są częściej '
                                                                         'używane w operacjach '
                                                                         'rekurencyjnych i '
                                                                         'strukturach '
                                                                         'dynamicznych, ponieważ '
                                                                         'ich implementacja w '
                                                                         'postaci połączonych '
                                                                         'węzłów umożliwia '
                                                                         'efektywną manipulację '
                                                                         'ich początkiem i '
                                                                         'przejściem poprzez '
                                                                         'dekompozycję '
                                                                         'rekurencyjną.\n'
                                                                         '\n'
                                                                         '- Z drugiej strony '
                                                                         'wektory są '
                                                                         'zoptymalizowane pod '
                                                                         'kątem scenariuszy, w '
                                                                         'których wymagany jest '
                                                                         'losowy dostęp do '
                                                                         'elementów lub '
                                                                         'aktualizacji w '
                                                                         'określonych indeksach, '
                                                                         'dzięki czemu są bardziej '
                                                                         'odpowiednie do '
                                                                         'przypadków użycia, '
                                                                         'takich jak tabele '
                                                                         'przeglądowe, '
                                                                         'konfiguracje o stałym '
                                                                         'rozmiarze lub operacje '
                                                                         'indeksowane o krytycznym '
                                                                         'znaczeniu dla '
                                                                         'wydajności.\n'
                                                                         '\n'
                                                                         'Zasadniczo listy są '
                                                                         'naturalnym wyborem w '
                                                                         'przypadku algorytmów '
                                                                         'rekurencyjnych i danych '
                                                                         'o dynamicznie zmienianym '
                                                                         'rozmiarze, natomiast '
                                                                         'wektory wyróżniają się, '
                                                                         'gdy najważniejsze są '
                                                                         'wzorce dostępu o stałym '
                                                                         'rozmiarze lub '
                                                                         'indeksowane.\n'
                                                                         '\n'
                                                                         '### Proste wektory\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- Tworzy wektor '
                                                                         'składający się z trzech '
                                                                         'elementów: `1`, `2` i '
                                                                         '`3`.\n'
                                                                         '\n'
                                                                         'Wynik: **`#(1 2 3)`**\n'
                                                                         '\n'
                                                                         '#### Dostęp do elementów '
                                                                         'wektorowych\n'
                                                                         '\n'
                                                                         'Dostęp do elementów '
                                                                         'wektora uzyskuje się za '
                                                                         'pomocą procedury '
                                                                         '`vector-ref`, która '
                                                                         'pobiera element o '
                                                                         'określonym indeksie '
                                                                         '(zaczynając od `0`).\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### Iteracja: '
                                                                         'przetwarzanie każdego '
                                                                         'elementu w wektorze\n'
                                                                         '\n'
                                                                         'Możesz iterować po '
                                                                         'wektorze za pomocą pętli '
                                                                         'lub rekurencji. Schemat '
                                                                         'zapewnia `vector-length` '
                                                                         'w celu określenia '
                                                                         'rozmiaru wektora. Oto '
                                                                         'prosta pętla do '
                                                                         'wydrukowania każdego '
                                                                         'elementu wektora:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **Przypadek '
                                                                         'podstawowy:** Jeśli '
                                                                         'indeks `i` osiągnie '
                                                                         'długość wektora, '
                                                                         'zatrzymaj pętlę.\n'
                                                                         '- **Przypadek '
                                                                         'rekurencyjny:** Wydrukuj '
                                                                         'element o indeksie `i`, '
                                                                         'a następnie zwiększ '
                                                                         '`i`.\n'
                                                                         '\n'
                                                                         '#### Przykładowe użycie\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Wynik:\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         'Wynik: „gotowe”\n'
                                                                         '\n'
                                                                         '### Mieszane wektory\n'
                                                                         '\n'
                                                                         'Wektory mogą zawierać '
                                                                         'elementy różnych typów, '
                                                                         'w tym ciągi znaków, '
                                                                         'wartości logiczne, '
                                                                         'liczby, inne wektory, a '
                                                                         'nawet wyniki wyrażeń:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Tworzy to wektor z:\n'
                                                                         '  - Liczba (`42`)\n'
                                                                         '  - Ciąg (`"hello"`)\n'
                                                                         '  - Wartość logiczna '
                                                                         '(`#t`)\n'
                                                                         '  - Kolejny wektor (`#(1 '
                                                                         '2)`)\n'
                                                                         '  - Wynik wyrażenia (`(+ '
                                                                         '3 4)`, którego wynikiem '
                                                                         'jest `7`)\n'
                                                                         '\n'
                                                                         'Wynik: **`#(42 "hello" '
                                                                         '#t #(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### Konstruowanie '
                                                                         'wektorów\n'
                                                                         '\n'
                                                                         'Wektory są tworzone przy '
                                                                         'użyciu `vector` lub przy '
                                                                         'użyciu `make-vector` w '
                                                                         'celu utworzenia wektora '
                                                                         'o stałym rozmiarze i '
                                                                         'wartości początkowej.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Tworzy wektor o '
                                                                         'rozmiarze `5` ze '
                                                                         'wszystkimi elementami '
                                                                         'inicjalizowanymi na '
                                                                         '`0`.\n'
                                                                         '\n'
                                                                         'Wynik: `#(0 0 0 0 0)`\n'
                                                                         '\n'
                                                                         '### Aktualizacja '
                                                                         'wektorów\n'
                                                                         '\n'
                                                                         'Procedura `vector-set!` '
                                                                         'aktualizuje element '
                                                                         'wektora o określonym '
                                                                         'indeksie.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Wynik: `#(1 42 3)`\n'
                                                                         '\n'
                                                                         '### Sprawdzanie '
                                                                         'wektorów\n'
                                                                         '\n'
                                                                         'Procedura `vector?` '
                                                                         'sprawdza, czy dana '
                                                                         'wartość jest wektorem.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Wynik:\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))` zwraca `#t` (true)\n'
                                                                         '- `(vector? 42)` zwraca '
                                                                         '`#f` (fałsz)\n'
                                                                         '\n'
                                                                         '### Wektory i zachowanie '
                                                                         'podczas przekazywania '
                                                                         'przez referencjeNa '
                                                                         'schemacie wektory można '
                                                                         'modyfikować i '
                                                                         'przekazywać przez '
                                                                         'odniesienie. Oznacza to, '
                                                                         'że gdy przekazujesz '
                                                                         'wektor do funkcji, '
                                                                         'funkcja może '
                                                                         'bezpośrednio modyfikować '
                                                                         'oryginalny wektor. '
                                                                         'Wszelkie zmiany dokonane '
                                                                         'w wektorze wewnątrz '
                                                                         'funkcji zostaną '
                                                                         'odzwierciedlone również '
                                                                         'poza funkcją. To '
                                                                         'zachowanie jest '
                                                                         'przydatne do wydajnego '
                                                                         'udostępniania i '
                                                                         'aktualizowania danych w '
                                                                         'wielu funkcjach, ale '
                                                                         'wymaga również '
                                                                         'ostrożności, aby uniknąć '
                                                                         'niezamierzonych skutków '
                                                                         'ubocznych.\n'
                                                                         '\n'
                                                                         '#### Przykład: '
                                                                         'modyfikowanie wektora w '
                                                                         'funkcji\n'
                                                                         '\n'
                                                                         'Oto przykład pokazujący, '
                                                                         'jak wektory są '
                                                                         'przekazywane przez '
                                                                         'referencję i '
                                                                         'modyfikowane:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Wynik: `#(10 99 30)`\n'
                                                                         '\n'
                                                                         '#### Wyjaśnienie krok po '
                                                                         'kroku\n'
                                                                         '\n'
                                                                         '1. **Utwórz wektor:** '
                                                                         '`my-vector` jest '
                                                                         'inicjowany wartościami '
                                                                         '`10`, `20` i `30`.\n'
                                                                         '2. **Przejście do '
                                                                         'funkcji:** `my-vector` '
                                                                         'jest przekazywane do '
                                                                         '`modify-vector` wraz z '
                                                                         'indeksem i nową '
                                                                         'wartością do '
                                                                         'aktualizacji.\n'
                                                                         '3. **Modyfikuj w '
                                                                         'funkcji:** Procedura '
                                                                         '`vector-set!` '
                                                                         'aktualizuje wartość pod '
                                                                         'określonym indeksem '
                                                                         'bezpośrednio w '
                                                                         'oryginalnym wektorze.\n'
                                                                         '4. **Odzwierciedlaj '
                                                                         'zmiany:** Ponieważ '
                                                                         'wektory są przekazywane '
                                                                         'przez odniesienie, '
                                                                         'zmiany dokonane w '
                                                                         'funkcji są '
                                                                         'odzwierciedlane w '
                                                                         'oryginalnym wektorze.\n'
                                                                         '\n'
                                                                         '#### Konsekwencje '
                                                                         'przekazywania przez '
                                                                         'odwołanie\n'
                                                                         '\n'
                                                                         '- **Wydajność:** '
                                                                         'Przekazywanie wektorów '
                                                                         'przez referencje jest '
                                                                         'wydajne, ponieważ '
                                                                         'pozwala uniknąć '
                                                                         'kopiowania dużych '
                                                                         'struktur.\n'
                                                                         '- **Skutki uboczne:** '
                                                                         'Zachowaj ostrożność '
                                                                         'podczas udostępniania '
                                                                         'wektorów między '
                                                                         'funkcjami, aby uniknąć '
                                                                         'niezamierzonych '
                                                                         'modyfikacji '
                                                                         'udostępnianych danych.\n'
                                                                         '\n'
                                                                         '### Operacje na '
                                                                         'wektorach\n'
                                                                         '\n'
                                                                         'Scheme udostępnia kilka '
                                                                         'wbudowanych procedur do '
                                                                         'pracy z wektorami, w '
                                                                         'tym:\n'
                                                                         '\n'
                                                                         '- `vector-length`: '
                                                                         'Zwraca liczbę elementów '
                                                                         'wektora.\n'
                                                                         '- `vector->list`: '
                                                                         'Konwertuje wektor na '
                                                                         'listę.\n'
                                                                         '- `list->vector`: '
                                                                         'Konwertuje listę na '
                                                                         'wektor.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Wynik:\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))` zwraca '
                                                                         '`3`\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))` zwraca `(1 2 '
                                                                         '3)`\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))` zwraca `#(1 2 '
                                                                         '3)`\n'
                                                                         '\n'
                                                                         '### Zagnieżdżone '
                                                                         'wektory\n'
                                                                         '\n'
                                                                         'Wektory na schemacie '
                                                                         'mogą zawierać inne '
                                                                         'wektory jako elementy, '
                                                                         'tworząc strukturę '
                                                                         'zagnieżdżoną.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Tworzy wektor składający '
                                                                         'się z trzech elementów, '
                                                                         'z których każdy sam jest '
                                                                         'wektorem.\n'
                                                                         '\n'
                                                                         'Wynik: **`#(#(1 2) #(3 '
                                                                         '4) #(5))`**\n'
                                                                         '\n'
                                                                         '#### Dostęp do danych '
                                                                         'zagnieżdżonych\n'
                                                                         '\n'
                                                                         'Aby uzyskać dostęp do '
                                                                         'elementów w '
                                                                         'zagnieżdżonym wektorze, '
                                                                         'użyj `vector-ref` '
                                                                         'wielokrotnie, aby '
                                                                         'poruszać się po '
                                                                         'strukturze.\n'
                                                                         '\n'
                                                                         '#### Przykład: '
                                                                         'uzyskiwanie dostępu do '
                                                                         'elementów\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### Podsumowanie\n'
                                                                         '\n'
                                                                         '- **Wektory** na '
                                                                         'schemacie to indeksowane '
                                                                         'struktury danych o '
                                                                         'stałym rozmiarze.\n'
                                                                         '- Użyj `vector`, aby '
                                                                         'utworzyć wektor, '
                                                                         '`vector-ref`, aby '
                                                                         'uzyskać dostęp do '
                                                                         'elementów i '
                                                                         '`vector-set!`, aby '
                                                                         'zaktualizować elementy.\n'
                                                                         '- Wbudowane procedury, '
                                                                         'takie jak '
                                                                         '`vector-length`, '
                                                                         '`vector->list` i '
                                                                         '`list->vector` '
                                                                         'umożliwiają elastyczne '
                                                                         'operacje.\n'
                                                                         '- Zagnieżdżone wektory '
                                                                         'pozwalają na tworzenie '
                                                                         'złożonych, '
                                                                         'hierarchicznych struktur '
                                                                         'danych.',
                                                                   'pt-br': '---\n'
                                                                            'title: "Vetores"\n'
                                                                            'type: docs\n'
                                                                            'weight: 5\n'
                                                                            '---\n'
                                                                            'No Scheme, um vetor é '
                                                                            'outra estrutura de '
                                                                            'dados fundamental '
                                                                            'usada para agrupar '
                                                                            'valores. Ao contrário '
                                                                            'das listas, os '
                                                                            'vetores são coleções '
                                                                            'de elementos '
                                                                            'indexados de tamanho '
                                                                            'fixo, fornecendo '
                                                                            'acesso aleatório e '
                                                                            'atualizações mais '
                                                                            'rápidas. Cada '
                                                                            'elemento de um vetor '
                                                                            'pode ser de qualquer '
                                                                            'tipo, incluindo outro '
                                                                            'vetor. Os vetores são '
                                                                            'representados usando '
                                                                            '# seguido de '
                                                                            'parênteses. `#(1 2 '
                                                                            '3)`\n'
                                                                            '\n'
                                                                            'Embora vetores e '
                                                                            'listas possam parecer '
                                                                            'semelhantes, eles '
                                                                            'servem a propósitos '
                                                                            'diferentes na '
                                                                            'programação de '
                                                                            'esquemas:\n'
                                                                            '\n'
                                                                            '- As listas são mais '
                                                                            'comumente usadas para '
                                                                            'operações recursivas '
                                                                            'e estruturas '
                                                                            'dinâmicas, pois sua '
                                                                            'implementação de nós '
                                                                            'vinculados permite a '
                                                                            'manipulação eficiente '
                                                                            'de seu início e '
                                                                            'travessia por meio de '
                                                                            'decomposição '
                                                                            'recursiva.\n'
                                                                            '\n'
                                                                            '- Os vetores, por '
                                                                            'outro lado, são '
                                                                            'otimizados para '
                                                                            'cenários em que é '
                                                                            'necessário acesso '
                                                                            'aleatório a elementos '
                                                                            'ou atualizações em '
                                                                            'índices específicos, '
                                                                            'tornando-os mais '
                                                                            'adequados para casos '
                                                                            'de uso como tabelas '
                                                                            'de pesquisa, '
                                                                            'configurações de '
                                                                            'tamanho fixo ou '
                                                                            'operações indexadas '
                                                                            'de desempenho '
                                                                            'crítico.\n'
                                                                            '\n'
                                                                            'Em essência, as '
                                                                            'listas são a escolha '
                                                                            'natural para '
                                                                            'algoritmos recursivos '
                                                                            'e dados de tamanho '
                                                                            'dinâmico, enquanto os '
                                                                            'vetores brilham '
                                                                            'quando padrões de '
                                                                            'acesso de tamanho '
                                                                            'fixo ou indexados são '
                                                                            'fundamentais.\n'
                                                                            '\n'
                                                                            '### Vetores Simples\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector 1 2 3)\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '- Cria um vetor de '
                                                                            'três elementos: `1`, '
                                                                            '`2` e `3`.\n'
                                                                            '\n'
                                                                            'Resultado: **`#(1 2 '
                                                                            '3)`**\n'
                                                                            '\n'
                                                                            '#### Acessando '
                                                                            'elementos vetoriais\n'
                                                                            '\n'
                                                                            'Os elementos em um '
                                                                            'vetor são acessados '
                                                                            'usando o procedimento '
                                                                            '`vector-ref`, que '
                                                                            'recupera o elemento '
                                                                            'em um índice '
                                                                            'especificado '
                                                                            '(começando em `0`).\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define my-vector '
                                                                            '(vector 1 2 3))\n'
                                                                            '(vector-ref my-vector '
                                                                            '0)  ; Ruft das '
                                                                            'Element an Index 0 '
                                                                            'ab\n'
                                                                            '(vector-ref my-vector '
                                                                            '1)  ; Ruft das '
                                                                            'Element an Index 1 '
                                                                            'ab\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '#### Iteração: '
                                                                            'Processando cada '
                                                                            'elemento em um vetor\n'
                                                                            '\n'
                                                                            'Você pode iterar '
                                                                            'através de um vetor '
                                                                            'usando um loop ou '
                                                                            'recursão. O esquema '
                                                                            'fornece '
                                                                            '`vector-length` para '
                                                                            'determinar o tamanho '
                                                                            'de um vetor. Aqui '
                                                                            'está um loop simples '
                                                                            'para imprimir todos '
                                                                            'os elementos de um '
                                                                            'vetor:\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define '
                                                                            '(print-elements vec)\n'
                                                                            '  (let loop ((i 0))\n'
                                                                            '    (if (< i '
                                                                            '(vector-length vec))\n'
                                                                            '      (begin\n'
                                                                            '        (lumi-message '
                                                                            '(number->string '
                                                                            '(vector-ref vec i))) '
                                                                            '; Element ausgeben\n'
                                                                            '        (loop (+ i '
                                                                            '1)))                                    '
                                                                            '; Nächsten Index '
                                                                            'verarbeiten\n'
                                                                            '      (lumi-message '
                                                                            '"done"))))                             '
                                                                            '; Schleife beenden\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '- **Caso Base:** Se o '
                                                                            'índice `i` atingir o '
                                                                            'comprimento do vetor, '
                                                                            'pare o loop.\n'
                                                                            '- **Caso recursivo:** '
                                                                            'Imprima o elemento no '
                                                                            'índice `i` e aumente '
                                                                            '`i`.\n'
                                                                            '\n'
                                                                            '#### Exemplo de uso\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(print-elements '
                                                                            '(vector 1 2 3))\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            'Resultado:\n'
                                                                            '\n'
                                                                            '- `"1"`\n'
                                                                            '- `"2"`\n'
                                                                            '- `"3"`\n'
                                                                            '\n'
                                                                            'Resultado: '
                                                                            '"concluído"\n'
                                                                            '\n'
                                                                            '### Vetores mistos\n'
                                                                            '\n'
                                                                            'Os vetores podem '
                                                                            'incluir elementos de '
                                                                            'diferentes tipos, '
                                                                            'incluindo strings, '
                                                                            'booleanos, números, '
                                                                            'outros vetores ou até '
                                                                            'mesmo o resultado de '
                                                                            'expressões:\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector 42 "hello" #t '
                                                                            '(vector 1 2) (+ 3 '
                                                                            '4))\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            'Isso cria um vetor '
                                                                            'com:\n'
                                                                            '  - Um número '
                                                                            '(@LUMI_TOKEN_26@@)\n'
                                                                            '  - Uma string '
                                                                            '(`"hello"`)\n'
                                                                            '  - Um booleano '
                                                                            '(@LUMI_TOKEN_28@@)\n'
                                                                            '  - Outro vetor '
                                                                            '(@LUMI_TOKEN_29@@)\n'
                                                                            '  - O resultado de '
                                                                            'uma expressão (`(+ 3 '
                                                                            '4)`, que é avaliada '
                                                                            'como `7`)\n'
                                                                            '\n'
                                                                            'Resultado: **`#(42 '
                                                                            '"hello" #t #(1 2) '
                                                                            '7)`**\n'
                                                                            '\n'
                                                                            '### Construindo '
                                                                            'Vetores\n'
                                                                            '\n'
                                                                            'Os vetores são '
                                                                            'criados usando '
                                                                            '`vector` ou usando '
                                                                            '`make-vector` para '
                                                                            'criar um vetor de '
                                                                            'tamanho fixo com um '
                                                                            'valor inicial.\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(make-vector 5 0)\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            'Cria um vetor de '
                                                                            'tamanho `5` com todos '
                                                                            'os elementos '
                                                                            'inicializados como '
                                                                            '`0`.\n'
                                                                            '\n'
                                                                            'Resultado: `#(0 0 0 0 '
                                                                            '0)`\n'
                                                                            '\n'
                                                                            '### Atualizando '
                                                                            'vetores\n'
                                                                            '\n'
                                                                            'O procedimento '
                                                                            '`vector-set!` '
                                                                            'atualiza um elemento '
                                                                            'em um vetor em um '
                                                                            'índice especificado.\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define my-vector '
                                                                            '(vector 1 2 3))\n'
                                                                            '(vector-set! '
                                                                            'my-vector 1 42)  ; '
                                                                            'Setzt das zweite '
                                                                            'Element auf 42\n'
                                                                            'my-vector\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            'Resultado: `#(1 42 '
                                                                            '3)`\n'
                                                                            '\n'
                                                                            '### Verificando '
                                                                            'vetores\n'
                                                                            '\n'
                                                                            'O procedimento '
                                                                            '`vector?` verifica se '
                                                                            'um determinado valor '
                                                                            'é um vetor.\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector? (vector 1 2 '
                                                                            '3))  ; Prüft, ob #(1 '
                                                                            '2 3) ein Vektor ist\n'
                                                                            '(vector? '
                                                                            '42)              ; '
                                                                            'Prüft, ob 42 ein '
                                                                            'Vektor ist\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            'Resultado:\n'
                                                                            '\n'
                                                                            '- `(vector? (vector 1 '
                                                                            '2 3))` retorna `#t` '
                                                                            '(verdadeiro)\n'
                                                                            '- `(vector? 42)` '
                                                                            'retorna `#f` (falso)\n'
                                                                            '\n'
                                                                            '### Vetores e '
                                                                            'comportamento de '
                                                                            'passagem por '
                                                                            'referênciaNo Scheme, '
                                                                            'os vetores são '
                                                                            'mutáveis '
                                                                            '\u200b\u200be '
                                                                            'passados '
                                                                            '\u200b\u200bpor '
                                                                            'referência. Isso '
                                                                            'significa que quando '
                                                                            'você passa um vetor '
                                                                            'para uma função, a '
                                                                            'função pode modificar '
                                                                            'diretamente o vetor '
                                                                            'original. Quaisquer '
                                                                            'alterações feitas no '
                                                                            'vetor dentro da '
                                                                            'função também serão '
                                                                            'refletidas fora da '
                                                                            'função. Esse '
                                                                            'comportamento é útil '
                                                                            'para compartilhar e '
                                                                            'atualizar dados com '
                                                                            'eficiência em '
                                                                            'diversas funções, mas '
                                                                            'também requer cautela '
                                                                            'para evitar efeitos '
                                                                            'colaterais '
                                                                            'indesejados.\n'
                                                                            '\n'
                                                                            '#### Exemplo: '
                                                                            'Modificando um vetor '
                                                                            'em uma função\n'
                                                                            '\n'
                                                                            'Aqui está um exemplo '
                                                                            'que demonstra como os '
                                                                            'vetores são passados '
                                                                            'por referência e '
                                                                            'modificados:\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define '
                                                                            '(modify-vector vec '
                                                                            'index new-value)\n'
                                                                            '  (vector-set! vec '
                                                                            'index new-value))  ; '
                                                                            'Aktualisiert den '
                                                                            'Vektor am angegebenen '
                                                                            'Index\n'
                                                                            '\n'
                                                                            '(define my-vector '
                                                                            '(vector 10 20 30))\n'
                                                                            '(modify-vector '
                                                                            'my-vector 1 '
                                                                            '99)         ; Ändert '
                                                                            'das zweite Element '
                                                                            'auf 99\n'
                                                                            'my-vector                              '
                                                                            '; Der ursprüngliche '
                                                                            'Vektor ist jetzt '
                                                                            'aktualisiert\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            'Resultado: `#(10 99 '
                                                                            '30)`\n'
                                                                            '\n'
                                                                            '#### Explicação passo '
                                                                            'a passo\n'
                                                                            '\n'
                                                                            '1. **Crie um vetor:** '
                                                                            '`my-vector` é '
                                                                            'inicializado com os '
                                                                            'valores `10`, `20` e '
                                                                            '`30`.\n'
                                                                            '2. **Passar para uma '
                                                                            'função:** `my-vector` '
                                                                            'é passado para '
                                                                            '`modify-vector` junto '
                                                                            'com o índice e o novo '
                                                                            'valor a ser '
                                                                            'atualizado.\n'
                                                                            '3. **Modificar na '
                                                                            'função:** O '
                                                                            'procedimento '
                                                                            '`vector-set!` '
                                                                            'atualiza o valor no '
                                                                            'índice especificado '
                                                                            'diretamente no vetor '
                                                                            'original.\n'
                                                                            '4. **Refletir '
                                                                            'alterações:** Como os '
                                                                            'vetores são passados '
                                                                            '\u200b\u200bpor '
                                                                            'referência, as '
                                                                            'alterações feitas na '
                                                                            'função são refletidas '
                                                                            'no vetor original.\n'
                                                                            '\n'
                                                                            '#### Implicações da '
                                                                            'passagem por '
                                                                            'referência\n'
                                                                            '\n'
                                                                            '- **Desempenho:** A '
                                                                            'passagem de vetores '
                                                                            'por referência é '
                                                                            'eficiente porque '
                                                                            'evita a cópia de '
                                                                            'grandes estruturas.\n'
                                                                            '- **Efeitos '
                                                                            'colaterais:** Tenha '
                                                                            'cuidado ao '
                                                                            'compartilhar vetores '
                                                                            'entre funções para '
                                                                            'evitar modificações '
                                                                            'não intencionais nos '
                                                                            'dados '
                                                                            'compartilhados.\n'
                                                                            '\n'
                                                                            '### Operações em '
                                                                            'vetores\n'
                                                                            '\n'
                                                                            'O Scheme fornece '
                                                                            'vários procedimentos '
                                                                            'integrados para '
                                                                            'trabalhar com '
                                                                            'vetores, incluindo:\n'
                                                                            '\n'
                                                                            '- `vector-length`: '
                                                                            'Retorna o número de '
                                                                            'elementos em um '
                                                                            'vetor.\n'
                                                                            '- `vector->list`: '
                                                                            'Converte um vetor em '
                                                                            'uma lista.\n'
                                                                            '- `list->vector`: '
                                                                            'Converte uma lista em '
                                                                            'um vetor.\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector-length '
                                                                            '(vector 1 2 '
                                                                            '3))         ; Gibt 3 '
                                                                            'zurück\n'
                                                                            '(vector->list (vector '
                                                                            '1 2 3))          ; '
                                                                            'Wandelt Vektor in '
                                                                            'Liste um: (1 2 3)\n'
                                                                            '(list->vector (list 1 '
                                                                            '2 3))            ; '
                                                                            'Wandelt Liste in '
                                                                            'Vektor um: #(1 2 3)\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            'Resultado:\n'
                                                                            '\n'
                                                                            '- `(vector-length '
                                                                            '(vector 1 2 3))` '
                                                                            'retorna `3`\n'
                                                                            '- `(vector->list '
                                                                            '(vector 1 2 3))` '
                                                                            'retorna `(1 2 3)`\n'
                                                                            '- `(list->vector '
                                                                            '(list 1 2 3))` '
                                                                            'retorna `#(1 2 3)`\n'
                                                                            '\n'
                                                                            '### Vetores '
                                                                            'aninhados\n'
                                                                            '\n'
                                                                            'Os vetores no esquema '
                                                                            'podem conter outros '
                                                                            'vetores como '
                                                                            'elementos, criando '
                                                                            'uma estrutura '
                                                                            'aninhada.\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define nested-vector '
                                                                            '(vector (vector 1 2) '
                                                                            '(vector 3 4) (vector '
                                                                            '5)))\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            'Cria um vetor de três '
                                                                            'elementos, cada um '
                                                                            'dos quais é um '
                                                                            'vetor.\n'
                                                                            '\n'
                                                                            'Resultado: **`#(#(1 '
                                                                            '2) #(3 4) #(5))`**\n'
                                                                            '\n'
                                                                            '#### Acessando dados '
                                                                            'aninhados\n'
                                                                            '\n'
                                                                            'Para acessar '
                                                                            'elementos dentro de '
                                                                            'um vetor aninhado, '
                                                                            'use `vector-ref` '
                                                                            'várias vezes para '
                                                                            'navegar pela '
                                                                            'estrutura.\n'
                                                                            '\n'
                                                                            '#### Exemplo: '
                                                                            'Acessando Elementos\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector-ref '
                                                                            'nested-vector '
                                                                            '0)              ; '
                                                                            'Ruft das erste '
                                                                            'Element ab: #(1 2)\n'
                                                                            '(vector-ref '
                                                                            '(vector-ref '
                                                                            'nested-vector 0) 1) ; '
                                                                            'Ruft das zweite '
                                                                            'Element des ersten '
                                                                            'Vektors ab: 2\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '### Resumo\n'
                                                                            '\n'
                                                                            '- **Vetores** em '
                                                                            'Scheme são estruturas '
                                                                            'de dados indexadas de '
                                                                            'tamanho fixo.\n'
                                                                            '- Use `vector` para '
                                                                            'criar um vetor, '
                                                                            '`vector-ref` para '
                                                                            'acessar elementos e '
                                                                            '`vector-set!` para '
                                                                            'atualizar elementos.\n'
                                                                            '- Procedimentos '
                                                                            'integrados como '
                                                                            '`vector-length`, '
                                                                            '`vector->list` e '
                                                                            '`list->vector` '
                                                                            'permitem operações '
                                                                            'flexíveis.\n'
                                                                            '- Vetores aninhados '
                                                                            'permitem estruturas '
                                                                            'de dados hierárquicas '
                                                                            'e complexas.',
                                                                   'ru': '---\n'
                                                                         'title: "Векторы"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'В схеме вектор — это еще '
                                                                         'одна фундаментальная '
                                                                         'структура данных, '
                                                                         'используемая для '
                                                                         'группировки значений. В '
                                                                         'отличие от списков, '
                                                                         'векторы представляют '
                                                                         'собой индексированные '
                                                                         'коллекции элементов '
                                                                         'фиксированного размера, '
                                                                         'обеспечивающие более '
                                                                         'быстрый произвольный '
                                                                         'доступ и обновления. '
                                                                         'Каждый элемент вектора '
                                                                         'может быть любого типа, '
                                                                         'включая другой вектор. '
                                                                         'Векторы обозначаются '
                                                                         'знаком #, за которым '
                                                                         'следуют круглые скобки. '
                                                                         '`#(1 2 3)`\n'
                                                                         '\n'
                                                                         'Хотя векторы и списки '
                                                                         'могут показаться '
                                                                         'похожими, в '
                                                                         'программировании на '
                                                                         'Scheme они служат разным '
                                                                         'целям:\n'
                                                                         '\n'
                                                                         '- Списки чаще '
                                                                         'используются для '
                                                                         'рекурсивных операций и '
                                                                         'динамических структур, '
                                                                         'поскольку их реализация '
                                                                         'со связанными узлами '
                                                                         'позволяет эффективно '
                                                                         'манипулировать их '
                                                                         'началом и обходом '
                                                                         'посредством рекурсивной '
                                                                         'декомпозиции.\n'
                                                                         '\n'
                                                                         'С другой стороны, '
                                                                         'векторы оптимизированы '
                                                                         'для сценариев, в которых '
                                                                         'требуется произвольный '
                                                                         'доступ к элементам или '
                                                                         'обновления определенных '
                                                                         'индексов, что делает их '
                                                                         'более подходящими для '
                                                                         'таких случаев '
                                                                         'использования, как '
                                                                         'таблицы поиска, '
                                                                         'конфигурации '
                                                                         'фиксированного размера '
                                                                         'или индексированные '
                                                                         'операции, критичные к '
                                                                         'производительности.\n'
                                                                         '\n'
                                                                         'По сути, списки являются '
                                                                         'естественным выбором для '
                                                                         'рекурсивных алгоритмов и '
                                                                         'данных динамического '
                                                                         'размера, в то время как '
                                                                         'векторы прекрасно '
                                                                         'подходят, когда '
                                                                         'первостепенное значение '
                                                                         'имеют шаблоны доступа '
                                                                         'фиксированного размера '
                                                                         'или индексированные.\n'
                                                                         '\n'
                                                                         '### Простые векторы\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- Создает вектор из трех '
                                                                         'элементов: `1`, `2` и '
                                                                         '`3`.\n'
                                                                         '\n'
                                                                         'Результат: **`#(1 2 '
                                                                         '3)`**\n'
                                                                         '\n'
                                                                         '#### Доступ к векторным '
                                                                         'элементам\n'
                                                                         '\n'
                                                                         'Доступ к элементам '
                                                                         'вектора осуществляется с '
                                                                         'помощью процедуры '
                                                                         '`vector-ref`, она '
                                                                         'извлекает элемент по '
                                                                         'указанному индексу '
                                                                         '(начиная с `0`).\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### Итерация: обработка '
                                                                         'каждого элемента '
                                                                         'вектора\n'
                                                                         '\n'
                                                                         'Вы можете перебирать '
                                                                         'вектор, используя цикл '
                                                                         'или рекурсию. Схема '
                                                                         'предоставляет '
                                                                         '`vector-length` для '
                                                                         'определения размера '
                                                                         'вектора. Вот простой '
                                                                         'цикл для печати каждого '
                                                                         'элемента вектора:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **Базовый случай:** '
                                                                         'Если индекс `i` '
                                                                         'достигает длины вектора, '
                                                                         'остановите цикл.\n'
                                                                         '- **Рекурсивный '
                                                                         'случай:** Распечатайте '
                                                                         'элемент с индексом `i`, '
                                                                         'затем увеличьте `i`.\n'
                                                                         '\n'
                                                                         '#### Пример '
                                                                         'использования\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Результат:\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         'Результат: «готово»\n'
                                                                         '\n'
                                                                         '### Смешанные векторы\n'
                                                                         '\n'
                                                                         'Векторы могут включать '
                                                                         'элементы разных типов, '
                                                                         'включая строки, '
                                                                         'логические значения, '
                                                                         'числа, другие векторы '
                                                                         'или даже результаты '
                                                                         'выражений:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Это создает вектор с:\n'
                                                                         '  - Номер (`42`)\n'
                                                                         '  - Строка (`"hello"`)\n'
                                                                         '  - Логическое значение '
                                                                         '(`#t`)\n'
                                                                         '  - Другой вектор (`#(1 '
                                                                         '2)`)\n'
                                                                         '  - Результат выражения '
                                                                         '(`(+ 3 4)`, которое '
                                                                         'оценивается как `7`)\n'
                                                                         '\n'
                                                                         'Результат: **`#(42 '
                                                                         '"hello" #t #(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### Построение векторов\n'
                                                                         '\n'
                                                                         'Векторы создаются с '
                                                                         'помощью `vector` или с '
                                                                         'помощью `make-vector` '
                                                                         'для создания вектора '
                                                                         'фиксированного размера с '
                                                                         'начальным значением.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Создает вектор размера '
                                                                         '`5` со всеми элементами, '
                                                                         'инициализированными как '
                                                                         '`0`.\n'
                                                                         '\n'
                                                                         'Результат: `#(0 0 0 0 '
                                                                         '0)`\n'
                                                                         '\n'
                                                                         '### Обновление векторов\n'
                                                                         '\n'
                                                                         'Процедура `vector-set!` '
                                                                         'обновляет элемент '
                                                                         'вектора по указанному '
                                                                         'индексу.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Результат: `#(1 42 3)`\n'
                                                                         '\n'
                                                                         '### Проверка векторов\n'
                                                                         '\n'
                                                                         'Процедура `vector?` '
                                                                         'проверяет, является ли '
                                                                         'данное значение '
                                                                         'вектором.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Результат:\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))` возвращает `#t` '
                                                                         '(истина)\n'
                                                                         '- `(vector? 42)` '
                                                                         'возвращает `#f` (ложь)\n'
                                                                         '\n'
                                                                         '### Векторы и передача '
                                                                         'по ссылкеВ Scheme '
                                                                         'векторы изменяемы и '
                                                                         'передаются по ссылке. '
                                                                         'Это означает, что когда '
                                                                         'вы передаете вектор '
                                                                         'функции, функция может '
                                                                         'напрямую изменить '
                                                                         'исходный вектор. Любые '
                                                                         'изменения, внесенные в '
                                                                         'вектор внутри функции, '
                                                                         'будут отражены и за ее '
                                                                         'пределами. Такое '
                                                                         'поведение полезно для '
                                                                         'эффективного обмена и '
                                                                         'обновления данных в '
                                                                         'нескольких функциях, но '
                                                                         'оно также требует '
                                                                         'осторожности, чтобы '
                                                                         'избежать непредвиденных '
                                                                         'побочных эффектов.\n'
                                                                         '\n'
                                                                         '#### Пример: изменение '
                                                                         'вектора в функции\n'
                                                                         '\n'
                                                                         'Вот пример, '
                                                                         'демонстрирующий, как '
                                                                         'векторы передаются по '
                                                                         'ссылке и изменяются:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Результат: `#(10 99 '
                                                                         '30)`\n'
                                                                         '\n'
                                                                         '#### Пошаговое '
                                                                         'объяснение\n'
                                                                         '\n'
                                                                         '1. **Создайте вектор:** '
                                                                         '`my-vector` '
                                                                         'инициализируется '
                                                                         'значениями `10`, `20` и '
                                                                         '`30`.\n'
                                                                         '2. **Передача функции:** '
                                                                         '`my-vector` передается '
                                                                         '`modify-vector` вместе с '
                                                                         'индексом и новым '
                                                                         'значением для '
                                                                         'обновления.\n'
                                                                         '3. **Изменить в '
                                                                         'функции:** Процедура '
                                                                         '`vector-set!` обновляет '
                                                                         'значение по указанному '
                                                                         'индексу непосредственно '
                                                                         'в исходном векторе.\n'
                                                                         '4. **Отражение '
                                                                         'изменений.** Поскольку '
                                                                         'векторы передаются по '
                                                                         'ссылке, изменения, '
                                                                         'внесенные внутри '
                                                                         'функции, отражаются в '
                                                                         'исходном векторе.\n'
                                                                         '\n'
                                                                         '#### Последствия '
                                                                         'передачи по ссылке\n'
                                                                         '\n'
                                                                         '- '
                                                                         '**Производительность**. '
                                                                         'Передача векторов по '
                                                                         'ссылке эффективна, '
                                                                         'поскольку позволяет '
                                                                         'избежать копирования '
                                                                         'больших структур.\n'
                                                                         '- **Побочные эффекты:** '
                                                                         'Будьте осторожны при '
                                                                         'совместном использовании '
                                                                         'векторов между '
                                                                         'функциями, чтобы '
                                                                         'избежать '
                                                                         'непреднамеренного '
                                                                         'изменения общих данных.\n'
                                                                         '\n'
                                                                         '### Операции с '
                                                                         'векторами\n'
                                                                         '\n'
                                                                         'Scheme предоставляет '
                                                                         'несколько встроенных '
                                                                         'процедур для работы с '
                                                                         'векторами, в том числе:\n'
                                                                         '\n'
                                                                         '- `vector-length`: '
                                                                         'возвращает количество '
                                                                         'элементов в векторе.\n'
                                                                         '- `vector->list`: '
                                                                         'преобразует вектор в '
                                                                         'список.\n'
                                                                         '- `list->vector`: '
                                                                         'преобразует список в '
                                                                         'вектор.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Результат:\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))` '
                                                                         'возвращает `3`\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))` возвращает `(1 '
                                                                         '2 3)`\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))` возвращает `#(1 2 '
                                                                         '3)`\n'
                                                                         '\n'
                                                                         '### Вложенные векторы\n'
                                                                         '\n'
                                                                         'Векторы в Scheme могут '
                                                                         'содержать другие векторы '
                                                                         'в качестве элементов, '
                                                                         'создавая вложенную '
                                                                         'структуру.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Создает вектор из трех '
                                                                         'элементов, каждый из '
                                                                         'которых сам является '
                                                                         'вектором.\n'
                                                                         '\n'
                                                                         'Результат: **`#(#(1 2) '
                                                                         '#(3 4) #(5))`**\n'
                                                                         '\n'
                                                                         '#### Доступ к вложенным '
                                                                         'данным\n'
                                                                         '\n'
                                                                         'Чтобы получить доступ к '
                                                                         'элементам внутри '
                                                                         'вложенного вектора, '
                                                                         'используйте `vector-ref` '
                                                                         'несколько раз для '
                                                                         'навигации по структуре.\n'
                                                                         '\n'
                                                                         '#### Пример: доступ к '
                                                                         'элементам\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### Резюме\n'
                                                                         '\n'
                                                                         '- **Векторы** в Scheme '
                                                                         'представляют собой '
                                                                         'индексированные '
                                                                         'структуры данных '
                                                                         'фиксированного размера.\n'
                                                                         '- Используйте `vector` '
                                                                         'для создания вектора, '
                                                                         '`vector-ref` для доступа '
                                                                         'к элементам и '
                                                                         '`vector-set!` для '
                                                                         'обновления элементов.\n'
                                                                         '- Встроенные процедуры, '
                                                                         'такие как '
                                                                         '`vector-length`, '
                                                                         '`vector->list` и '
                                                                         '`list->vector`, '
                                                                         'обеспечивают гибкость '
                                                                         'операций.\n'
                                                                         '- Вложенные векторы '
                                                                         'позволяют создавать '
                                                                         'сложные иерархические '
                                                                         'структуры данных.',
                                                                   'sv': '---\n'
                                                                         'title: "Vektorer"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'I Schema är en vektor en '
                                                                         'annan grundläggande '
                                                                         'datastruktur som används '
                                                                         'för att gruppera värden. '
                                                                         'Till skillnad från '
                                                                         'listor är vektorer '
                                                                         'indexerade samlingar av '
                                                                         'element med fast '
                                                                         'storlek, vilket ger '
                                                                         'snabbare slumpmässig '
                                                                         'åtkomst och '
                                                                         'uppdateringar. Varje '
                                                                         'element i en vektor kan '
                                                                         'vara av vilken typ som '
                                                                         'helst, inklusive en '
                                                                         'annan vektor. Vektorer '
                                                                         'representeras med # '
                                                                         'följt av parentes. `#(1 '
                                                                         '2 3)`\n'
                                                                         '\n'
                                                                         'Även om vektorer och '
                                                                         'listor kan se likadana '
                                                                         'ut, tjänar de olika '
                                                                         'syften i '
                                                                         'schemaprogrammering:\n'
                                                                         '\n'
                                                                         '- Listor används oftare '
                                                                         'för rekursiva '
                                                                         'operationer och '
                                                                         'dynamiska strukturer, '
                                                                         'eftersom deras länkade '
                                                                         'nodimplementering '
                                                                         'möjliggör effektiv '
                                                                         'manipulation av deras '
                                                                         'början och genomgång '
                                                                         'genom rekursiv '
                                                                         'nedbrytning.\n'
                                                                         '\n'
                                                                         '- Vektorer, å andra '
                                                                         'sidan, är optimerade för '
                                                                         'scenarier där '
                                                                         'slumpmässig tillgång '
                                                                         'till element eller '
                                                                         'uppdateringar vid '
                                                                         'specifika index krävs, '
                                                                         'vilket gör dem mer '
                                                                         'lämpade för '
                                                                         'användningsfall som '
                                                                         'uppslagstabeller, '
                                                                         'konfigurationer med fast '
                                                                         'storlek eller '
                                                                         'prestandakritiska '
                                                                         'indexerade operationer.\n'
                                                                         '\n'
                                                                         'I grund och botten är '
                                                                         'listor det naturliga '
                                                                         'valet för rekursiva '
                                                                         'algoritmer och dynamisk '
                                                                         'storlek data, medan '
                                                                         'vektorer lyser när fast '
                                                                         'storlek eller indexerade '
                                                                         'åtkomstmönster är av '
                                                                         'största vikt.\n'
                                                                         '\n'
                                                                         '### Enkla vektorer\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- Skapar en vektor med '
                                                                         'tre element: `1`, `2` '
                                                                         'och `3`.\n'
                                                                         '\n'
                                                                         'Resultat: **`#(1 2 '
                                                                         '3)`**\n'
                                                                         '\n'
                                                                         '#### Åtkomst till '
                                                                         'vektorelement\n'
                                                                         '\n'
                                                                         'Element i en vektor nås '
                                                                         'med hjälp av proceduren '
                                                                         '`vector-ref`, den hämtar '
                                                                         'elementet vid ett '
                                                                         'specificerat index (med '
                                                                         'början från `0`).\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### Iteration: '
                                                                         'Bearbetning av varje '
                                                                         'element i en vektor\n'
                                                                         '\n'
                                                                         'Du kan iterera genom en '
                                                                         'vektor med en loop eller '
                                                                         'rekursion. Schema '
                                                                         'tillhandahåller '
                                                                         '`vector-length` för att '
                                                                         'bestämma storleken på en '
                                                                         'vektor. Här är en enkel '
                                                                         'slinga för att skriva ut '
                                                                         'varje element i en '
                                                                         'vektor:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **Basfall:** Om '
                                                                         'indexet `i` når vektorns '
                                                                         'längd, stoppa slingan.\n'
                                                                         '- **Rekursivt '
                                                                         'skiftläge:** Skriv ut '
                                                                         'elementet på index `i`, '
                                                                         'öka sedan `i`.\n'
                                                                         '\n'
                                                                         '#### Exempel på '
                                                                         'användning\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultat:\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         'Resultat: "klar"\n'
                                                                         '\n'
                                                                         '### Blandade vektorer\n'
                                                                         '\n'
                                                                         'Vektorer kan innehålla '
                                                                         'element av olika typer, '
                                                                         'inklusive strängar, '
                                                                         'booleaner, tal, andra '
                                                                         'vektorer eller till och '
                                                                         'med resultatet av '
                                                                         'uttryck:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Detta skapar en vektor '
                                                                         'med:\n'
                                                                         '  - Ett nummer (`42`)\n'
                                                                         '  - En sträng '
                                                                         '(`"hello"`)\n'
                                                                         '  - En boolesk (`#t`)\n'
                                                                         '  - En annan vektor '
                                                                         '(`#(1 2)`)\n'
                                                                         '  - Resultatet av ett '
                                                                         'uttryck (`(+ 3 4)`, som '
                                                                         'utvärderas till `7`)\n'
                                                                         '\n'
                                                                         'Resultat: **`#(42 '
                                                                         '"hello" #t #(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### Konstruera vektorer\n'
                                                                         '\n'
                                                                         'Vektorer skapas med '
                                                                         '`vector`, eller genom '
                                                                         'att använda '
                                                                         '`make-vector` för att '
                                                                         'skapa en vektor med en '
                                                                         'fast storlek med ett '
                                                                         'initialt värde.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Skapar en vektor med '
                                                                         'storlek `5` med alla '
                                                                         'element initialiserade '
                                                                         'till `0`.\n'
                                                                         '\n'
                                                                         'Resultat: `#(0 0 0 0 '
                                                                         '0)`\n'
                                                                         '\n'
                                                                         '### Uppdaterar vektorer\n'
                                                                         '\n'
                                                                         '`vector-set!`-proceduren '
                                                                         'uppdaterar ett element i '
                                                                         'en vektor vid ett '
                                                                         'specificerat index.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultat: `#(1 42 3)`\n'
                                                                         '\n'
                                                                         '### Söker efter '
                                                                         'vektorer\n'
                                                                         '\n'
                                                                         '`vector?`-proceduren '
                                                                         'kontrollerar om ett '
                                                                         'givet värde är en '
                                                                         'vektor.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultat:\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))` returnerar `#t` '
                                                                         '(sant)\n'
                                                                         '- `(vector? 42)` '
                                                                         'returnerar `#f` '
                                                                         '(falskt)\n'
                                                                         '\n'
                                                                         '### Vektorer och '
                                                                         'passerande '
                                                                         'referensbeteendeI Schema '
                                                                         'är vektorer föränderliga '
                                                                         'och skickas med '
                                                                         'referens. Detta innebär '
                                                                         'att när du skickar en '
                                                                         'vektor till en funktion '
                                                                         'kan funktionen modifiera '
                                                                         'den ursprungliga vektorn '
                                                                         'direkt. Alla ändringar '
                                                                         'som görs i vektorn inuti '
                                                                         'funktionen kommer att '
                                                                         'reflekteras utanför '
                                                                         'funktionen. Detta '
                                                                         'beteende är användbart '
                                                                         'för att effektivt dela '
                                                                         'och uppdatera data över '
                                                                         'flera funktioner, men '
                                                                         'det kräver också '
                                                                         'försiktighet för att '
                                                                         'undvika oavsiktliga '
                                                                         'biverkningar.\n'
                                                                         '\n'
                                                                         '#### Exempel: Modifiera '
                                                                         'en vektor i en funktion\n'
                                                                         '\n'
                                                                         'Här är ett exempel som '
                                                                         'visar hur vektorer '
                                                                         'skickas med referens och '
                                                                         'modifieras:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultat: `#(10 99 30)`\n'
                                                                         '\n'
                                                                         '#### '
                                                                         'Steg-för-steg-förklaring\n'
                                                                         '\n'
                                                                         '1. **Skapa en vektor:** '
                                                                         '`my-vector` initieras '
                                                                         'med värdena `10`, `20` '
                                                                         'och `30`.\n'
                                                                         '2. **Överför till en '
                                                                         'funktion:** `my-vector` '
                                                                         'skickas till '
                                                                         '`modify-vector` '
                                                                         'tillsammans med indexet '
                                                                         'och det nya värdet som '
                                                                         'ska uppdateras.\n'
                                                                         '3. **Ändra i funktion:** '
                                                                         '`vector-set!`-proceduren '
                                                                         'uppdaterar värdet vid '
                                                                         'det angivna indexet '
                                                                         'direkt i den '
                                                                         'ursprungliga vektorn.\n'
                                                                         '4. **Reflektera '
                                                                         'ändringar:** Eftersom '
                                                                         'vektorer skickas med '
                                                                         'referens, återspeglas '
                                                                         'ändringar som görs i '
                                                                         'funktionen i den '
                                                                         'ursprungliga vektorn.\n'
                                                                         '\n'
                                                                         '#### Implikationer av '
                                                                         'Pass-by-Reference\n'
                                                                         '\n'
                                                                         '- **Prestanda:** Att '
                                                                         'skicka vektorer genom '
                                                                         'referens är effektivt '
                                                                         'eftersom det undviker '
                                                                         'att kopiera stora '
                                                                         'strukturer.\n'
                                                                         '- **Biverkningar:** Var '
                                                                         'försiktig när du delar '
                                                                         'vektorer mellan '
                                                                         'funktioner för att '
                                                                         'undvika oavsiktliga '
                                                                         'ändringar av delad '
                                                                         'data.\n'
                                                                         '\n'
                                                                         '### Operationer på '
                                                                         'vektorer\n'
                                                                         '\n'
                                                                         'Schema tillhandahåller '
                                                                         'flera inbyggda '
                                                                         'procedurer för att '
                                                                         'arbeta med vektorer, '
                                                                         'inklusive:\n'
                                                                         '\n'
                                                                         '- `vector-length`: '
                                                                         'Returnerar antalet '
                                                                         'element i en vektor.\n'
                                                                         '- `vector->list`: '
                                                                         'Konverterar en vektor '
                                                                         'till en lista.\n'
                                                                         '- `list->vector`: '
                                                                         'Konverterar en lista '
                                                                         'till en vektor.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Resultat:\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))` '
                                                                         'returnerar `3`\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))` returnerar `(1 '
                                                                         '2 3)`\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))` returnerar `#(1 2 '
                                                                         '3)`\n'
                                                                         '\n'
                                                                         '### Kapslade vektorer\n'
                                                                         '\n'
                                                                         'Vektorer i Scheme kan '
                                                                         'innehålla andra vektorer '
                                                                         'som element, vilket '
                                                                         'skapar en kapslad '
                                                                         'struktur.\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'Skapar en vektor med tre '
                                                                         'element, som vart och '
                                                                         'ett i sig är en vektor.\n'
                                                                         '\n'
                                                                         'Resultat: **`#(#(1 2) '
                                                                         '#(3 4) #(5))`**\n'
                                                                         '\n'
                                                                         '#### Åtkomst till '
                                                                         'kapslade data\n'
                                                                         '\n'
                                                                         'För att komma åt element '
                                                                         'inom en kapslad vektor, '
                                                                         'använd `vector-ref` '
                                                                         'flera gånger för att '
                                                                         'navigera genom '
                                                                         'strukturen.\n'
                                                                         '\n'
                                                                         '#### Exempel: Åtkomst '
                                                                         'till element\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### Sammanfattning\n'
                                                                         '\n'
                                                                         '- **Vektorer** i Scheme '
                                                                         'är indexerade '
                                                                         'datastrukturer med fast '
                                                                         'storlek.\n'
                                                                         '- Använd `vector` för '
                                                                         'att skapa en vektor, '
                                                                         '`vector-ref` för att '
                                                                         'komma åt element och '
                                                                         '`vector-set!` för att '
                                                                         'uppdatera element.\n'
                                                                         '- Inbyggda procedurer '
                                                                         'som `vector-length`, '
                                                                         '`vector->list` och '
                                                                         '`list->vector` möjliggör '
                                                                         'flexibla operationer.\n'
                                                                         '- Kapslade vektorer '
                                                                         'möjliggör komplexa, '
                                                                         'hierarkiska '
                                                                         'datastrukturer.',
                                                                   'th': '---\n'
                                                                         'title: "เวกเตอร์"\n'
                                                                         'type: docs\n'
                                                                         'weight: 5\n'
                                                                         '---\n'
                                                                         'ใน Scheme '
                                                                         'เวกเตอร์เป็นอีกหนึ่งโครงสร้างข้อมูลพื้นฐานที่ใช้ในการจัดกลุ่มค่า '
                                                                         'ต่างจากรายการตรงที่เวกเตอร์จะมีขนาดคงที่ '
                                                                         'คอลเลกชันขององค์ประกอบที่จัดทำดัชนีแล้ว '
                                                                         'ช่วยให้เข้าถึงและอัปเดตแบบสุ่มได้รวดเร็วยิ่งขึ้น '
                                                                         'แต่ละองค์ประกอบในเวกเตอร์สามารถเป็นประเภทใดก็ได้ '
                                                                         'รวมถึงเวกเตอร์อื่นด้วย '
                                                                         'เวกเตอร์แสดงโดยใช้ # '
                                                                         'ตามด้วยวงเล็บ `#(1 2 '
                                                                         '3)`\n'
                                                                         '\n'
                                                                         'แม้ว่าเวกเตอร์และรายการอาจดูคล้ายกัน '
                                                                         'แต่ก็มีจุดประสงค์ที่แตกต่างกันในการเขียนโปรแกรม '
                                                                         'Scheme:\n'
                                                                         '\n'
                                                                         '- '
                                                                         'รายการมักใช้สำหรับการดำเนินการแบบเรียกซ้ำและโครงสร้างไดนามิก '
                                                                         'เนื่องจากการใช้งานโหนดที่เชื่อมโยงช่วยให้การจัดการจุดเริ่มต้นและการสำรวจเส้นทางมีประสิทธิภาพผ่านการสลายตัวแบบเรียกซ้ำ\n'
                                                                         '\n'
                                                                         '- ในทางกลับกัน เวกเตอร์ '
                                                                         'ได้รับการปรับให้เหมาะสมสำหรับสถานการณ์ที่จำเป็นต้องมีการเข้าถึงองค์ประกอบแบบสุ่มหรือการอัพเดตที่ดัชนีเฉพาะ '
                                                                         'ทำให้เหมาะสมมากขึ้นสำหรับกรณีการใช้งาน '
                                                                         'เช่น ตารางการค้นหา '
                                                                         'การกำหนดค่าขนาดคงที่ '
                                                                         'หรือการดำเนินการจัดทำดัชนีที่มีความสำคัญต่อประสิทธิภาพ\n'
                                                                         '\n'
                                                                         'โดยพื้นฐานแล้ว '
                                                                         'รายการต่างๆ '
                                                                         'เป็นตัวเลือกที่เป็นธรรมชาติสำหรับอัลกอริธึมแบบเรียกซ้ำและข้อมูลที่มีขนาดไดนามิก '
                                                                         'ในขณะที่เวกเตอร์จะโดดเด่นเมื่อรูปแบบการเข้าถึงที่มีขนาดคงที่หรือจัดทำดัชนีเป็นสิ่งสำคัญยิ่ง\n'
                                                                         '\n'
                                                                         '### เวกเตอร์อย่างง่าย\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 1 2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- '
                                                                         'สร้างเวกเตอร์ของสามองค์ประกอบ: '
                                                                         '`1`, `2` และ `3`\n'
                                                                         '\n'
                                                                         'ผลลัพธ์: **`#(1 2 3)`**\n'
                                                                         '\n'
                                                                         '#### '
                                                                         'การเข้าถึงองค์ประกอบเวกเตอร์\n'
                                                                         '\n'
                                                                         'เข้าถึงองค์ประกอบในเวกเตอร์ได้โดยใช้ขั้นตอน '
                                                                         '`vector-ref` '
                                                                         'โดยจะดึงข้อมูลองค์ประกอบจากดัชนีที่ระบุ '
                                                                         '(เริ่มจาก `0`)\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-ref my-vector '
                                                                         '0)  ; Ruft das Element '
                                                                         'an Index 0 ab\n'
                                                                         '(vector-ref my-vector '
                                                                         '1)  ; Ruft das Element '
                                                                         'an Index 1 ab\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '#### การวนซ้ำ: '
                                                                         'การประมวลผลแต่ละองค์ประกอบในเวกเตอร์\n'
                                                                         '\n'
                                                                         'คุณสามารถวนซ้ำผ่านเวกเตอร์โดยใช้การวนซ้ำหรือการเรียกซ้ำ '
                                                                         'Scheme จัดเตรียม '
                                                                         '`vector-length` '
                                                                         'เพื่อกำหนดขนาดของเวกเตอร์ '
                                                                         'ต่อไปนี้เป็นวิธีง่ายๆ '
                                                                         'ในการพิมพ์ทุกองค์ประกอบในเวกเตอร์:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (print-elements '
                                                                         'vec)\n'
                                                                         '  (let loop ((i 0))\n'
                                                                         '    (if (< i '
                                                                         '(vector-length vec))\n'
                                                                         '      (begin\n'
                                                                         '        (lumi-message '
                                                                         '(number->string '
                                                                         '(vector-ref vec i))) ; '
                                                                         'Element ausgeben\n'
                                                                         '        (loop (+ i '
                                                                         '1)))                                    '
                                                                         '; Nächsten Index '
                                                                         'verarbeiten\n'
                                                                         '      (lumi-message '
                                                                         '"done"))))                             '
                                                                         '; Schleife beenden\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '- **กรณีฐาน:** หากดัชนี '
                                                                         '`i` '
                                                                         'ถึงความยาวของเวกเตอร์ '
                                                                         'ให้หยุดการวนซ้ำ\n'
                                                                         '- **กรณีแบบเรียกซ้ำ:** '
                                                                         'พิมพ์องค์ประกอบที่ดัชนี '
                                                                         '`i` จากนั้นเพิ่มค่า `i`\n'
                                                                         '\n'
                                                                         '#### ตัวอย่างการใช้งาน\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(print-elements (vector '
                                                                         '1 2 3))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'ผลลัพธ์:\n'
                                                                         '\n'
                                                                         '- `"1"`\n'
                                                                         '- `"2"`\n'
                                                                         '- `"3"`\n'
                                                                         '\n'
                                                                         'ผลลัพธ์: "เสร็จสิ้น"\n'
                                                                         '\n'
                                                                         '### เวกเตอร์ผสม\n'
                                                                         '\n'
                                                                         'เวกเตอร์สามารถรวมองค์ประกอบประเภทต่างๆ '
                                                                         'ได้ รวมถึงสตริง บูลีน '
                                                                         'ตัวเลข เวกเตอร์อื่นๆ '
                                                                         'หรือแม้แต่ผลลัพธ์ของนิพจน์:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector 42 "hello" #t '
                                                                         '(vector 1 2) (+ 3 4))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'สิ่งนี้จะสร้างเวกเตอร์ด้วย:\n'
                                                                         '  - ตัวเลข (`42`)\n'
                                                                         '  - สตริง (`"hello"`)\n'
                                                                         '  - บูลีน (`#t`)\n'
                                                                         '  - เวกเตอร์อีกอัน (`#(1 '
                                                                         '2)`)\n'
                                                                         '  - ผลลัพธ์ของนิพจน์ '
                                                                         '(`(+ 3 4)` '
                                                                         'ซึ่งประเมินเป็น `7`)\n'
                                                                         '\n'
                                                                         'ผลลัพธ์: **`#(42 "hello" '
                                                                         '#t #(1 2) 7)`**\n'
                                                                         '\n'
                                                                         '### การสร้างเวกเตอร์\n'
                                                                         '\n'
                                                                         'เวกเตอร์ถูกสร้างขึ้นโดยใช้ '
                                                                         '`vector` หรือโดยใช้ '
                                                                         '`make-vector` '
                                                                         'เพื่อสร้างเวกเตอร์ที่มีขนาดคงที่พร้อมค่าเริ่มต้น\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(make-vector 5 0)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'สร้างเวกเตอร์ขนาด `5` '
                                                                         'โดยมีองค์ประกอบทั้งหมดเริ่มต้นเป็น '
                                                                         '`0`\n'
                                                                         '\n'
                                                                         'ผลลัพธ์: `#(0 0 0 0 0)`\n'
                                                                         '\n'
                                                                         '### การอัปเดตเวกเตอร์\n'
                                                                         '\n'
                                                                         'ขั้นตอน `vector-set!` '
                                                                         'จะอัปเดตองค์ประกอบในเวกเตอร์ที่ดัชนีที่ระบุ\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define my-vector '
                                                                         '(vector 1 2 3))\n'
                                                                         '(vector-set! my-vector 1 '
                                                                         '42)  ; Setzt das zweite '
                                                                         'Element auf 42\n'
                                                                         'my-vector\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'ผลลัพธ์: `#(1 42 3)`\n'
                                                                         '\n'
                                                                         '### '
                                                                         'กำลังตรวจสอบเวกเตอร์\n'
                                                                         '\n'
                                                                         'กระบวนการ `vector?` '
                                                                         'จะตรวจสอบว่าค่าที่กำหนดเป็นเวกเตอร์หรือไม่\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector? (vector 1 2 '
                                                                         '3))  ; Prüft, ob #(1 2 '
                                                                         '3) ein Vektor ist\n'
                                                                         '(vector? '
                                                                         '42)              ; '
                                                                         'Prüft, ob 42 ein Vektor '
                                                                         'ist\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'ผลลัพธ์:\n'
                                                                         '\n'
                                                                         '- `(vector? (vector 1 2 '
                                                                         '3))` ส่งกลับ `#t` '
                                                                         '(จริง)\n'
                                                                         '- `(vector? 42)` ส่งคืน '
                                                                         '`#f` (เท็จ)\n'
                                                                         '\n'
                                                                         '### '
                                                                         'เวกเตอร์และพฤติกรรมการอ้างอิงใน '
                                                                         'Scheme '
                                                                         'เวกเตอร์ไม่แน่นอนและส่งผ่านโดยการอ้างอิง '
                                                                         'ซึ่งหมายความว่าเมื่อคุณส่งเวกเตอร์ไปยังฟังก์ชัน '
                                                                         'ฟังก์ชันจะสามารถแก้ไขเวกเตอร์ดั้งเดิมได้โดยตรง '
                                                                         'การเปลี่ยนแปลงใดๆ '
                                                                         'ที่ทำกับเวกเตอร์ภายในฟังก์ชันจะมีผลภายนอกฟังก์ชันด้วย '
                                                                         'ลักษณะการทำงานนี้มีประโยชน์สำหรับการแบ่งปันและอัปเดตข้อมูลข้ามฟังก์ชันต่างๆ '
                                                                         'ได้อย่างมีประสิทธิภาพ '
                                                                         'แต่ยังต้องใช้ความระมัดระวังเพื่อหลีกเลี่ยงผลข้างเคียงที่ไม่ได้ตั้งใจ\n'
                                                                         '\n'
                                                                         '#### ตัวอย่าง: '
                                                                         'การแก้ไขเวกเตอร์ในฟังก์ชัน\n'
                                                                         '\n'
                                                                         'นี่คือตัวอย่างที่แสดงให้เห็นว่าเวกเตอร์ถูกส่งผ่านโดยการอ้างอิงและแก้ไขอย่างไร:\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define (modify-vector '
                                                                         'vec index new-value)\n'
                                                                         '  (vector-set! vec index '
                                                                         'new-value))  ; '
                                                                         'Aktualisiert den Vektor '
                                                                         'am angegebenen Index\n'
                                                                         '\n'
                                                                         '(define my-vector '
                                                                         '(vector 10 20 30))\n'
                                                                         '(modify-vector my-vector '
                                                                         '1 99)         ; Ändert '
                                                                         'das zweite Element auf '
                                                                         '99\n'
                                                                         'my-vector                              '
                                                                         '; Der ursprüngliche '
                                                                         'Vektor ist jetzt '
                                                                         'aktualisiert\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'ผลลัพธ์: `#(10 99 30)`\n'
                                                                         '\n'
                                                                         '#### '
                                                                         'คำอธิบายทีละขั้นตอน\n'
                                                                         '\n'
                                                                         '1. **สร้างเวกเตอร์:** '
                                                                         '`my-vector` '
                                                                         'เริ่มต้นได้ด้วยค่า `10`, '
                                                                         '`20` และ `30`\n'
                                                                         '2. '
                                                                         '**ส่งผ่านไปยังฟังก์ชัน:** '
                                                                         '`my-vector` '
                                                                         'ถูกส่งผ่านไปยัง '
                                                                         '`modify-vector` '
                                                                         'พร้อมด้วยดัชนีและค่าใหม่ที่จะอัปเดต\n'
                                                                         '3. **แก้ไขในฟังก์ชัน:** '
                                                                         'ขั้นตอน `vector-set!` '
                                                                         'จะอัปเดตค่าที่ดัชนีที่ระบุโดยตรงในเวกเตอร์ดั้งเดิม\n'
                                                                         '4. '
                                                                         '**สะท้อนการเปลี่ยนแปลง:** '
                                                                         'เนื่องจากเวกเตอร์ถูกส่งผ่านโดยการอ้างอิง '
                                                                         'การเปลี่ยนแปลงที่ทำภายในฟังก์ชันจึงสะท้อนให้เห็นในเวกเตอร์ดั้งเดิม\n'
                                                                         '\n'
                                                                         '#### '
                                                                         'ผลกระทบของการอ้างอิงแบบผ่าน\n'
                                                                         '\n'
                                                                         '- **ประสิทธิภาพ:** '
                                                                         'การส่งผ่านเวกเตอร์โดยการอ้างอิงมีประสิทธิภาพเนื่องจากจะหลีกเลี่ยงการคัดลอกโครงสร้างขนาดใหญ่\n'
                                                                         '- **ผลข้างเคียง:** '
                                                                         'โปรดใช้ความระมัดระวังเมื่อแชร์เวกเตอร์ข้ามฟังก์ชันต่างๆ '
                                                                         'เพื่อหลีกเลี่ยงการแก้ไขข้อมูลที่แชร์โดยไม่ได้ตั้งใจ\n'
                                                                         '\n'
                                                                         '### '
                                                                         'การดำเนินการกับเวกเตอร์\n'
                                                                         '\n'
                                                                         'Scheme '
                                                                         'มีขั้นตอนในตัวหลายอย่างสำหรับการทำงานกับเวกเตอร์ '
                                                                         'รวมไปถึง:\n'
                                                                         '\n'
                                                                         '- `vector-length`: '
                                                                         'ส่งกลับจำนวนองค์ประกอบในเวกเตอร์\n'
                                                                         '- `vector->list`: '
                                                                         'แปลงเวกเตอร์ให้เป็นรายการ\n'
                                                                         '- `list->vector`: '
                                                                         'แปลงรายการให้เป็นเวกเตอร์\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-length (vector 1 '
                                                                         '2 3))         ; Gibt 3 '
                                                                         'zurück\n'
                                                                         '(vector->list (vector 1 '
                                                                         '2 3))          ; Wandelt '
                                                                         'Vektor in Liste um: (1 2 '
                                                                         '3)\n'
                                                                         '(list->vector (list 1 2 '
                                                                         '3))            ; Wandelt '
                                                                         'Liste in Vektor um: #(1 '
                                                                         '2 3)\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'ผลลัพธ์:\n'
                                                                         '\n'
                                                                         '- `(vector-length '
                                                                         '(vector 1 2 3))` กลับมา '
                                                                         '`3`\n'
                                                                         '- `(vector->list (vector '
                                                                         '1 2 3))` กลับมา `(1 2 '
                                                                         '3)`\n'
                                                                         '- `(list->vector (list 1 '
                                                                         '2 3))` กลับมา `#(1 2 '
                                                                         '3)`\n'
                                                                         '\n'
                                                                         '### เวกเตอร์ที่ซ้อนกัน\n'
                                                                         '\n'
                                                                         'เวกเตอร์ใน Scheme '
                                                                         'สามารถมีเวกเตอร์อื่นเป็นองค์ประกอบ '
                                                                         'ทำให้เกิดโครงสร้างที่ซ้อนกัน\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(define nested-vector '
                                                                         '(vector (vector 1 2) '
                                                                         '(vector 3 4) (vector '
                                                                         '5)))\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         'สร้างเวกเตอร์ที่มีองค์ประกอบ '
                                                                         '3 ส่วน '
                                                                         'ซึ่งแต่ละองค์ประกอบก็เป็นเวกเตอร์ในตัวมันเอง\n'
                                                                         '\n'
                                                                         'ผลลัพธ์: **`#(#(1 2) #(3 '
                                                                         '4) #(5))`**\n'
                                                                         '\n'
                                                                         '#### '
                                                                         'การเข้าถึงข้อมูลที่ซ้อนกัน\n'
                                                                         '\n'
                                                                         'หากต้องการเข้าถึงองค์ประกอบภายในเวกเตอร์ที่ซ้อนกัน '
                                                                         'ให้ใช้ `vector-ref` '
                                                                         'หลายครั้งเพื่อเลื่อนดูโครงสร้าง\n'
                                                                         '\n'
                                                                         '#### ตัวอย่าง: '
                                                                         'การเข้าถึงองค์ประกอบ\n'
                                                                         '\n'
                                                                         '```scheme\n'
                                                                         '(vector-ref '
                                                                         'nested-vector '
                                                                         '0)              ; Ruft '
                                                                         'das erste Element ab: '
                                                                         '#(1 2)\n'
                                                                         '(vector-ref (vector-ref '
                                                                         'nested-vector 0) 1) ; '
                                                                         'Ruft das zweite Element '
                                                                         'des ersten Vektors ab: '
                                                                         '2\n'
                                                                         '```\n'
                                                                         '\n'
                                                                         '### สรุป\n'
                                                                         '\n'
                                                                         '- **เวกเตอร์** ใน Scheme '
                                                                         'มีขนาดคงที่ '
                                                                         'โครงสร้างข้อมูลที่จัดทำดัชนีไว้\n'
                                                                         '- ใช้ `vector` '
                                                                         'เพื่อสร้างเวกเตอร์ '
                                                                         '`vector-ref` '
                                                                         'เพื่อเข้าถึงองค์ประกอบ '
                                                                         'และ `vector-set!` '
                                                                         'เพื่ออัปเดตองค์ประกอบ\n'
                                                                         '- ขั้นตอนในตัว เช่น '
                                                                         '`vector-length`, '
                                                                         '`vector->list` และ '
                                                                         '`list->vector` '
                                                                         'ช่วยให้การดำเนินงานมีความยืดหยุ่น\n'
                                                                         '- '
                                                                         'เวกเตอร์ที่ซ้อนกันทำให้เกิดโครงสร้างข้อมูลที่ซับซ้อนและเป็นลำดับชั้น',
                                                                   'zh-cn': '---\n'
                                                                            'title: "向量"\n'
                                                                            'type: docs\n'
                                                                            'weight: 5\n'
                                                                            '---\n'
                                                                            '在Scheme中，向量是另一种用于对值进行分组的基本数据结构。与列表不同，向量是固定大小的索引元素集合，提供更快的随机访问和更新。向量中的每个元素可以是任何类型，包括另一个向量。向量使用 '
                                                                            '# 后跟括号来表示。 `#(1 2 '
                                                                            '3)`\n'
                                                                            '\n'
                                                                            '虽然向量和列表可能看起来相似，但它们在方案编程中具有不同的用途：\n'
                                                                            '\n'
                                                                            '- '
                                                                            '列表更常用于递归操作和动态结构，因为它们的链接节点实现允许通过递归分解有效地操纵它们的开始和遍历。\n'
                                                                            '\n'
                                                                            '- '
                                                                            '另一方面，向量针对需要随机访问元素或更新特定索引的场景进行了优化，使它们更适合查找表、固定大小配置或性能关键的索引操作等用例。\n'
                                                                            '\n'
                                                                            '从本质上讲，列表是递归算法和动态大小数据的自然选择，而当固定大小或索引访问模式至关重要时，向量就会大放异彩。\n'
                                                                            '\n'
                                                                            '### 简单向量\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector 1 2 3)\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '- 创建包含三个元素的向量：`1`、`2` '
                                                                            '和 `3`。\n'
                                                                            '\n'
                                                                            '结果：**`#(1 2 3)`**\n'
                                                                            '\n'
                                                                            '#### 访问向量元素\n'
                                                                            '\n'
                                                                            '使用`vector-ref` '
                                                                            '过程访问向量中的元素，它检索指定索引处的元素（从`0` '
                                                                            '开始）。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define my-vector '
                                                                            '(vector 1 2 3))\n'
                                                                            '(vector-ref my-vector '
                                                                            '0)  ; Ruft das '
                                                                            'Element an Index 0 '
                                                                            'ab\n'
                                                                            '(vector-ref my-vector '
                                                                            '1)  ; Ruft das '
                                                                            'Element an Index 1 '
                                                                            'ab\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '#### 迭代：处理向量中的每个元素\n'
                                                                            '\n'
                                                                            '您可以使用循环或递归来迭代向量。 '
                                                                            'Scheme '
                                                                            '提供`vector-length` '
                                                                            '来确定向量的大小。这是一个打印向量中每个元素的简单循环：\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define '
                                                                            '(print-elements vec)\n'
                                                                            '  (let loop ((i 0))\n'
                                                                            '    (if (< i '
                                                                            '(vector-length vec))\n'
                                                                            '      (begin\n'
                                                                            '        (lumi-message '
                                                                            '(number->string '
                                                                            '(vector-ref vec i))) '
                                                                            '; Element ausgeben\n'
                                                                            '        (loop (+ i '
                                                                            '1)))                                    '
                                                                            '; Nächsten Index '
                                                                            'verarbeiten\n'
                                                                            '      (lumi-message '
                                                                            '"done"))))                             '
                                                                            '; Schleife beenden\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '- **基本情况：** 如果索引 `i` '
                                                                            '达到向量的长度，则停止循环。\n'
                                                                            '- **递归情况：** 打印索引 `i` '
                                                                            '处的元素，然后递增 `i`。\n'
                                                                            '\n'
                                                                            '#### 用法示例\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(print-elements '
                                                                            '(vector 1 2 3))\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '结果：\n'
                                                                            '\n'
                                                                            '- `"1"`\n'
                                                                            '- `"2"`\n'
                                                                            '- `"3"`\n'
                                                                            '\n'
                                                                            '结果：“完成”\n'
                                                                            '\n'
                                                                            '### 混合向量\n'
                                                                            '\n'
                                                                            '向量可以包含不同类型的元素，包括字符串、布尔值、数字、其他向量，甚至表达式的结果：\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector 42 "hello" #t '
                                                                            '(vector 1 2) (+ 3 '
                                                                            '4))\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '这将创建一个向量：\n'
                                                                            '  - 一个数字 (`42`)\n'
                                                                            '  - 字符串 (`"hello"`)\n'
                                                                            '  - 布尔值 (`#t`)\n'
                                                                            '  - 另一个向量 (`#(1 2)`)\n'
                                                                            '  - 表达式的结果（`(+ 3 '
                                                                            '4)`，其计算结果为`7`）\n'
                                                                            '\n'
                                                                            '结果：**`#(42 "hello" #t '
                                                                            '#(1 2) 7)`**\n'
                                                                            '\n'
                                                                            '### 构造向量\n'
                                                                            '\n'
                                                                            '向量是使用`vector`创建的，或者使用`make-vector`创建具有初始值的固定大小的向量。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(make-vector 5 0)\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '创建大小为`5` '
                                                                            '的向量，所有元素都初始化为`0`。\n'
                                                                            '\n'
                                                                            '结果：`#(0 0 0 0 0)`\n'
                                                                            '\n'
                                                                            '### 更新向量\n'
                                                                            '\n'
                                                                            '`vector-set!` '
                                                                            '过程更新向量中指定索引处的元素。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define my-vector '
                                                                            '(vector 1 2 3))\n'
                                                                            '(vector-set! '
                                                                            'my-vector 1 42)  ; '
                                                                            'Setzt das zweite '
                                                                            'Element auf 42\n'
                                                                            'my-vector\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '结果：`#(1 42 3)`\n'
                                                                            '\n'
                                                                            '### 检查向量\n'
                                                                            '\n'
                                                                            '`vector?` '
                                                                            '过程检查给定值是否是向量。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector? (vector 1 2 '
                                                                            '3))  ; Prüft, ob #(1 '
                                                                            '2 3) ein Vektor ist\n'
                                                                            '(vector? '
                                                                            '42)              ; '
                                                                            'Prüft, ob 42 ein '
                                                                            'Vektor ist\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '结果：\n'
                                                                            '\n'
                                                                            '- `(vector? (vector 1 '
                                                                            '2 3))` 返回`#t`（真）\n'
                                                                            '- `(vector? 42)` '
                                                                            '返回`#f` (假)\n'
                                                                            '\n'
                                                                            '### '
                                                                            '向量和引用传递行为在Scheme中，向量是可变的并且通过引用传递。这意味着当您将向量传递给函数时，该函数可以直接修改原始向量。对函数内部向量所做的任何更改也将反映在函数外部。此行为对于跨多个函数有效共享和更新数据很有用，但也需要谨慎以避免意外的副作用。\n'
                                                                            '\n'
                                                                            '#### 示例：修改函数中的向量\n'
                                                                            '\n'
                                                                            '下面的示例演示了如何通过引用传递向量并进行修改：\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define '
                                                                            '(modify-vector vec '
                                                                            'index new-value)\n'
                                                                            '  (vector-set! vec '
                                                                            'index new-value))  ; '
                                                                            'Aktualisiert den '
                                                                            'Vektor am angegebenen '
                                                                            'Index\n'
                                                                            '\n'
                                                                            '(define my-vector '
                                                                            '(vector 10 20 30))\n'
                                                                            '(modify-vector '
                                                                            'my-vector 1 '
                                                                            '99)         ; Ändert '
                                                                            'das zweite Element '
                                                                            'auf 99\n'
                                                                            'my-vector                              '
                                                                            '; Der ursprüngliche '
                                                                            'Vektor ist jetzt '
                                                                            'aktualisiert\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '结果：`#(10 99 30)`\n'
                                                                            '\n'
                                                                            '#### 分步说明\n'
                                                                            '\n'
                                                                            '1. **创建向量：** '
                                                                            '`my-vector` 使用值 '
                                                                            '`10`、`20` 和 `30` '
                                                                            '进行初始化。\n'
                                                                            '2. **传递到函数：** '
                                                                            '`my-vector` '
                                                                            '连同要更新的索引和新值一起传递到 '
                                                                            '`modify-vector`。\n'
                                                                            '3. **在函数中修改：** '
                                                                            '`vector-set!` '
                                                                            '过程直接更新原始向量中指定索引处的值。\n'
                                                                            '4. **反映更改：** '
                                                                            '由于向量是通过引用传递的，因此函数内所做的更改将反映在原始向量中。\n'
                                                                            '\n'
                                                                            '#### 引用传递的含义\n'
                                                                            '\n'
                                                                            '- **性能：** '
                                                                            '通过引用传递向量非常高效，因为它避免了复制大型结构。\n'
                                                                            '- **副作用：** '
                                                                            '跨函数共享向量时要小心，以避免对共享数据进行意外修改。\n'
                                                                            '\n'
                                                                            '### Operations on '
                                                                            'Vectors\n'
                                                                            '\n'
                                                                            'Scheme '
                                                                            '提供了几个用于处理向量的内置过程，包括：\n'
                                                                            '\n'
                                                                            '- '
                                                                            '`vector-length`：返回向量中的元素数量。\n'
                                                                            '- '
                                                                            '`vector->list`：将向量转换为列表。\n'
                                                                            '- '
                                                                            '`list->vector`：将列表转换为向量。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector-length '
                                                                            '(vector 1 2 '
                                                                            '3))         ; Gibt 3 '
                                                                            'zurück\n'
                                                                            '(vector->list (vector '
                                                                            '1 2 3))          ; '
                                                                            'Wandelt Vektor in '
                                                                            'Liste um: (1 2 3)\n'
                                                                            '(list->vector (list 1 '
                                                                            '2 3))            ; '
                                                                            'Wandelt Liste in '
                                                                            'Vektor um: #(1 2 3)\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '结果：\n'
                                                                            '\n'
                                                                            '- `(vector-length '
                                                                            '(vector 1 2 3))` '
                                                                            '返回`3`\n'
                                                                            '- `(vector->list '
                                                                            '(vector 1 2 3))` '
                                                                            '返回`(1 2 3)`\n'
                                                                            '- `(list->vector '
                                                                            '(list 1 2 3))` 返回`#(1 '
                                                                            '2 3)`\n'
                                                                            '\n'
                                                                            '### 嵌套向量\n'
                                                                            '\n'
                                                                            'Scheme '
                                                                            '中的向量可以包含其他向量作为元素，从而创建嵌套结构。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define nested-vector '
                                                                            '(vector (vector 1 2) '
                                                                            '(vector 3 4) (vector '
                                                                            '5)))\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '创建一个由三个元素组成的向量，每个元素本身就是一个向量。\n'
                                                                            '\n'
                                                                            '结果：**`#(#(1 2) #(3 4) '
                                                                            '#(5))`**\n'
                                                                            '\n'
                                                                            '#### 访问嵌套数据\n'
                                                                            '\n'
                                                                            '要访问嵌套向量内的元素，请多次使用 '
                                                                            '`vector-ref` 来浏览结构。\n'
                                                                            '\n'
                                                                            '#### 示例：访问元素\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector-ref '
                                                                            'nested-vector '
                                                                            '0)              ; '
                                                                            'Ruft das erste '
                                                                            'Element ab: #(1 2)\n'
                                                                            '(vector-ref '
                                                                            '(vector-ref '
                                                                            'nested-vector 0) 1) ; '
                                                                            'Ruft das zweite '
                                                                            'Element des ersten '
                                                                            'Vektors ab: 2\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '### 总结\n'
                                                                            '\n'
                                                                            '-Scheme '
                                                                            '中的**向量**是固定大小的索引数据结构。\n'
                                                                            '- 使用`vector` '
                                                                            '创建向量，使用`vector-ref` '
                                                                            '访问元素，使用`vector-set!` '
                                                                            '更新元素。\n'
                                                                            '- '
                                                                            '`vector-length`、`vector->list` '
                                                                            '和`list->vector` '
                                                                            '等内置过程可实现灵活的操作。\n'
                                                                            '- 嵌套向量允许复杂的分层数据结构。',
                                                                   'zh-tw': '---\n'
                                                                            'title: "向量"\n'
                                                                            'type: docs\n'
                                                                            'weight: 5\n'
                                                                            '---\n'
                                                                            '在Scheme中，向量是另一個用於將值分組的基本資料結構。與列表不同，向量是固定大小的索引元素集合，提供更快的隨機存取和更新。向量中的每個元素可以是任何類型，包括另一個向量。向量使用 '
                                                                            '# 後面跟著括號來表示。 `#(1 2 '
                                                                            '3)`\n'
                                                                            '\n'
                                                                            '雖然向量和列表可能看起來相似，但它們在方案編程中具有不同的用途：\n'
                                                                            '\n'
                                                                            '- '
                                                                            '列表更常用於遞歸操作和動態結構，因為它們的連結節點實現允許透過遞歸分解有效地操縱它們的開始和遍歷。\n'
                                                                            '\n'
                                                                            '- '
                                                                            '另一方面，向量针对需要随机访问元素或更新特定索引的场景进行了优化，使它们更适合查找表、固定大小配置或性能关键的索引操作等用例。\n'
                                                                            '\n'
                                                                            '從本質上講，清單是遞歸演算法和動態大小資料的自然選擇，而當固定大小或索引存取模式至關重要時，向量就會大放異彩。\n'
                                                                            '\n'
                                                                            '### 簡單向量\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector 1 2 3)\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '- 建立包含三個元素的向量：`1`、`2` '
                                                                            '和 `3`。\n'
                                                                            '\n'
                                                                            '結果：**`#(1 2 3)`**\n'
                                                                            '\n'
                                                                            '#### 存取向量元素\n'
                                                                            '\n'
                                                                            '使用 `vector-ref` '
                                                                            '程序存取向量中的元素，它會擷取指定索引處的元素（從`0` '
                                                                            '開始）。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define my-vector '
                                                                            '(vector 1 2 3))\n'
                                                                            '(vector-ref my-vector '
                                                                            '0)  ; Ruft das '
                                                                            'Element an Index 0 '
                                                                            'ab\n'
                                                                            '(vector-ref my-vector '
                                                                            '1)  ; Ruft das '
                                                                            'Element an Index 1 '
                                                                            'ab\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '#### 迭代：處理向量中的每個元素\n'
                                                                            '\n'
                                                                            '您可以使用循環或遞歸來迭代向量。 '
                                                                            'Scheme '
                                                                            '提供`vector-length` '
                                                                            '來決定向量的大小。這是一個列印向量中每個元素的簡單循環：\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define '
                                                                            '(print-elements vec)\n'
                                                                            '  (let loop ((i 0))\n'
                                                                            '    (if (< i '
                                                                            '(vector-length vec))\n'
                                                                            '      (begin\n'
                                                                            '        (lumi-message '
                                                                            '(number->string '
                                                                            '(vector-ref vec i))) '
                                                                            '; Element ausgeben\n'
                                                                            '        (loop (+ i '
                                                                            '1)))                                    '
                                                                            '; Nächsten Index '
                                                                            'verarbeiten\n'
                                                                            '      (lumi-message '
                                                                            '"done"))))                             '
                                                                            '; Schleife beenden\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '- **基本情況：** 如果索引 `i` '
                                                                            '達到向量的長度，則停止循環。\n'
                                                                            '- **遞迴情況：** 列印索引 `i` '
                                                                            '處的元素，然後遞增 `i`。\n'
                                                                            '\n'
                                                                            '#### 用法範例\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(print-elements '
                                                                            '(vector 1 2 3))\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '結果：\n'
                                                                            '\n'
                                                                            '- `"1"`\n'
                                                                            '- `"2"`\n'
                                                                            '- `"3"`\n'
                                                                            '\n'
                                                                            '結果：“完成”\n'
                                                                            '\n'
                                                                            '### 混合向量\n'
                                                                            '\n'
                                                                            '向量可以包含不同類型的元素，包括字串、布林值、數字、其他向量，甚至是表達式的結果：\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector 42 "hello" #t '
                                                                            '(vector 1 2) (+ 3 '
                                                                            '4))\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '這將創建一個向量：\n'
                                                                            '  - 一個數字 (`42`)\n'
                                                                            '  - 字串 (`"hello"`)\n'
                                                                            '  - 布林值 (`#t`)\n'
                                                                            '  - 另一個向量 (`#(1 2)`)\n'
                                                                            '  - 表達式的結果（`(+ 3 '
                                                                            '4)`，其計算結果為`7`）\n'
                                                                            '\n'
                                                                            '結果：**`#(42 "hello" #t '
                                                                            '#(1 2) 7)`**\n'
                                                                            '\n'
                                                                            '### 建構向量\n'
                                                                            '\n'
                                                                            '向量是使用`vector`建立的，或使用`make-vector`建立具有初始值的固定大小的向量。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(make-vector 5 0)\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '建立大小為`5` '
                                                                            '的向量，所有元素都初始化為`0`。\n'
                                                                            '\n'
                                                                            '結果：`#(0 0 0 0 0)`\n'
                                                                            '\n'
                                                                            '### 更新向量\n'
                                                                            '\n'
                                                                            '`vector-set!` '
                                                                            '程序更新向量中指定索引處的元素。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define my-vector '
                                                                            '(vector 1 2 3))\n'
                                                                            '(vector-set! '
                                                                            'my-vector 1 42)  ; '
                                                                            'Setzt das zweite '
                                                                            'Element auf 42\n'
                                                                            'my-vector\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '結果：`#(1 42 3)`\n'
                                                                            '\n'
                                                                            '### 檢查向量\n'
                                                                            '\n'
                                                                            '`vector?` '
                                                                            '過程檢查給定值是否為向量。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector? (vector 1 2 '
                                                                            '3))  ; Prüft, ob #(1 '
                                                                            '2 3) ein Vektor ist\n'
                                                                            '(vector? '
                                                                            '42)              ; '
                                                                            'Prüft, ob 42 ein '
                                                                            'Vektor ist\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '結果：\n'
                                                                            '\n'
                                                                            '- `(vector? (vector 1 '
                                                                            '2 3))` 返回`#t`（真）\n'
                                                                            '- `(vector? 42)` '
                                                                            '返回`#f` (假)\n'
                                                                            '\n'
                                                                            '### '
                                                                            '向量與引用傳遞行為在Scheme中，向量是可變的並且透過引用傳遞。這意味著當您將向量傳遞給函數時，該函數可以直接修改原始向量。對函數內部向量所做的任何更改也將反映在函數外部。此行為對於跨多個函數有效共享和更新資料很有用，但也需要謹慎以避免意外的副作用。\n'
                                                                            '\n'
                                                                            '#### 範例：修改函數中的向量\n'
                                                                            '\n'
                                                                            '下面的範例示範如何透過引用傳遞向量並進行修改：\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define '
                                                                            '(modify-vector vec '
                                                                            'index new-value)\n'
                                                                            '  (vector-set! vec '
                                                                            'index new-value))  ; '
                                                                            'Aktualisiert den '
                                                                            'Vektor am angegebenen '
                                                                            'Index\n'
                                                                            '\n'
                                                                            '(define my-vector '
                                                                            '(vector 10 20 30))\n'
                                                                            '(modify-vector '
                                                                            'my-vector 1 '
                                                                            '99)         ; Ändert '
                                                                            'das zweite Element '
                                                                            'auf 99\n'
                                                                            'my-vector                              '
                                                                            '; Der ursprüngliche '
                                                                            'Vektor ist jetzt '
                                                                            'aktualisiert\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '結果：`#(10 99 30)`\n'
                                                                            '\n'
                                                                            '#### 逐步說明\n'
                                                                            '\n'
                                                                            '1. **建立向量：** '
                                                                            '`my-vector` 使用值 '
                                                                            '`10`、`20` 和 `30` '
                                                                            '初始化。\n'
                                                                            '2. **傳遞到函數：** '
                                                                            '`my-vector` '
                                                                            '連同要更新的索引和新值一起傳遞到 '
                                                                            '`modify-vector`。\n'
                                                                            '3. **在函數中修改：** '
                                                                            '`vector-set!` '
                                                                            '程序直接更新原始向量中指定索引處的值。\n'
                                                                            '4. **反映變更：** '
                                                                            '由於向量是透過引用傳遞的，因此函數內所做的變更將反映在原始向量中。\n'
                                                                            '\n'
                                                                            '#### 引用傳遞的意義\n'
                                                                            '\n'
                                                                            '- **效能：** '
                                                                            '透過引用傳遞向量非常高效，因為它避免了複製大型結構。\n'
                                                                            '- **副作用：** '
                                                                            '跨函數共享向量時要小心，以避免對共享資料進行意外修改。\n'
                                                                            '\n'
                                                                            '### 向量運算\n'
                                                                            '\n'
                                                                            'Scheme '
                                                                            '提供了幾個用於處理向量的內建流程，包括：\n'
                                                                            '\n'
                                                                            '- '
                                                                            '`vector-length`：傳迴向量中的元素數量。\n'
                                                                            '- '
                                                                            '`vector->list`：將向量轉換為列表。\n'
                                                                            '- '
                                                                            '`list->vector`：將列表轉換為向量。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector-length '
                                                                            '(vector 1 2 '
                                                                            '3))         ; Gibt 3 '
                                                                            'zurück\n'
                                                                            '(vector->list (vector '
                                                                            '1 2 3))          ; '
                                                                            'Wandelt Vektor in '
                                                                            'Liste um: (1 2 3)\n'
                                                                            '(list->vector (list 1 '
                                                                            '2 3))            ; '
                                                                            'Wandelt Liste in '
                                                                            'Vektor um: #(1 2 3)\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '結果：\n'
                                                                            '\n'
                                                                            '- `(vector-length '
                                                                            '(vector 1 2 3))` '
                                                                            '返回`3`\n'
                                                                            '- `(vector->list '
                                                                            '(vector 1 2 3))` '
                                                                            '返回`(1 2 3)`\n'
                                                                            '- `(list->vector '
                                                                            '(list 1 2 3))` 返回`#(1 '
                                                                            '2 3)`\n'
                                                                            '\n'
                                                                            '### 巢狀向量\n'
                                                                            '\n'
                                                                            'Scheme '
                                                                            '中的向量可以包含其他向量作為元素，從而建立巢狀結構。\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(define nested-vector '
                                                                            '(vector (vector 1 2) '
                                                                            '(vector 3 4) (vector '
                                                                            '5)))\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '創建一個由三個元素組成的向量，每個元素本身就是一個向量。\n'
                                                                            '\n'
                                                                            '結果：**`#(#(1 2) #(3 4) '
                                                                            '#(5))`**\n'
                                                                            '\n'
                                                                            '#### 存取嵌套數據\n'
                                                                            '\n'
                                                                            '若要存取巢狀向量內的元素，請多次使用 '
                                                                            '`vector-ref` 來瀏覽結構。\n'
                                                                            '\n'
                                                                            '#### 範例：存取元素\n'
                                                                            '\n'
                                                                            '```scheme\n'
                                                                            '(vector-ref '
                                                                            'nested-vector '
                                                                            '0)              ; '
                                                                            'Ruft das erste '
                                                                            'Element ab: #(1 2)\n'
                                                                            '(vector-ref '
                                                                            '(vector-ref '
                                                                            'nested-vector 0) 1) ; '
                                                                            'Ruft das zweite '
                                                                            'Element des ersten '
                                                                            'Vektors ab: 2\n'
                                                                            '```\n'
                                                                            '\n'
                                                                            '### 總結\n'
                                                                            '\n'
                                                                            '-Scheme '
                                                                            '中的**向量**是固定大小的索引資料結構。\n'
                                                                            '- 使用`vector` 建立向量，使用 '
                                                                            '`vector-ref` '
                                                                            '存取元素，使用`vector-set!` '
                                                                            '更新元素。\n'
                                                                            '- '
                                                                            '`vector-length`、`vector->list` '
                                                                            '和`list->vector` '
                                                                            '等內建過程可實現靈活的操作。\n'
                                                                            '- 巢狀向量允許複雜的分層資料結構。'}}


def split_front_matter(text: str) -> tuple[str, str]:
    if not text.startswith("---"):
        return "", text
    end = text.find("\n---", 3)
    if end == -1:
        return "", text
    end += 4
    if end < len(text) and text[end] == "\n":
        end += 1
    return text[:end], text[end:]


def extract_front_matter_field(front: str, key: str) -> str:
    match = re.search(rf"(?m){re.escape(key)}:\s*(.+)$", front)
    return match.group(1).strip().strip('"') if match else ""


def build_front_matter(source_rel: str, translated: str) -> str:
    src_path = SITE_ROOT / source_rel
    src_front, _ = split_front_matter(src_path.read_text(encoding="utf-8"))
    tr_front, _ = split_front_matter(translated)

    title = extract_front_matter_field(tr_front, "title") or extract_front_matter_field(src_front, "title")
    lines = ["---", f'title: "{title}"']

    for key in ("type", "weight", "toc"):
        value = extract_front_matter_field(tr_front, key) or extract_front_matter_field(src_front, key)
        if value:
            if key in ("weight", "toc"):
                lines.append(f"{key}: {value}")
            else:
                lines.append(f'{key}: "{value}"')

    sha = SOURCE_HASHES[source_rel]
    lines.extend(
        [
            "translation_provenance: ai-reviewed",
            "translation_lock: true",
            f"translation_source_sha256: {sha}",
            "---",
        ]
    )
    return "\n".join(lines) + "\n"


def write_translation(source_rel: str, lang: str, body: str) -> None:
    src_path = SITE_ROOT / source_rel
    stem = src_path.with_suffix("")
    out_path = Path(str(stem) + f".{lang}.md")
    front = build_front_matter(source_rel, body)
    _, tr_body = split_front_matter(body)
    out_path.write_text(front + tr_body, encoding="utf-8")


def main() -> None:
    count = 0
    for source_rel, lang_map in TRANSLATIONS.items():
        for lang, content in lang_map.items():
            write_translation(source_rel, lang, content)
            count += 1
    print(f"Wrote {count} translation files")


if __name__ == "__main__":
    main()
